        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // Selection Box
    if (mouseDownPos) {
        const currentWorld = { 
            x: mousePos.x + state.camera.x, 
            y: mousePos.y + state.camera.y 
        };
        const startWorld = {
            x: mouseDownPos.x + state.camera.x,
            y: mouseDownPos.y + state.camera.y
        };

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorld.x - startWorld.x, 
            currentWorld.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);
    }

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    // Keyboard Pan
    const keySpeed = 20;
    if (keysPressed.current.has('ArrowLeft') || keysPressed.current.has('KeyA')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight') || keysPressed.current.has('KeyD')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp') || keysPressed.current.has('KeyW')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown') || keysPressed.current.has('KeyS')) gameStateRef.current.camera.y += keySpeed;

    // Edge Pan (Only if not dragging)
    if (!isDraggingCamera.current) {
        if (mousePos.x < margin) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
          }
          return;
      }
      setMouseDownPos({ x: e.clientX, y: e.clientY });
    } else if (e.button === 2) { // Right Click
      e.preventDefault();
      const pos = getWorldPos(e);
      const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
         const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
         return dist < ent.radius + 5;
      });

      gameStateRef.current.selection.forEach(id => {
        const unit = gameStateRef.current.entities.get(id);
        if (unit && unit.owner === Owner.PLAYER) {
           if (clickedEntity) {
               if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                   unit.state = 'GATHERING';
                   unit.targetId = clickedEntity.id;
                   unit.targetPosition = null;
               } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                   unit.state = 'ATTACKING';
                   unit.targetId = clickedEntity.id;
                   unit.targetPosition = null;
               } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                   // Workers attack if told to
                   unit.state = 'ATTACKING';
                   unit.targetId = clickedEntity.id;
               }
           } else {
               unit.state = 'MOVING';
               unit.targetPosition = pos;
               unit.targetId = null;
           }
        }
      });
      setCommandMode(null);
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    setMousePos({ x: e.clientX, y: e.clientY });

    // Handle Drag Pan
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;

        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;

        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 0 && mouseDownPos) {
         const start = mouseDownPos;
         const end = { x: e.clientX, y: e.clientY };

         const cam = gameStateRef.current.camera;
         const worldStart = { x: start.x + cam.x, y: start.y + cam.y };
         const worldEnd = { x: end.x + cam.x, y: end.y + cam.y };

         const minX = Math.min(worldStart.x, worldEnd.x);
         const maxX = Math.max(worldStart.x, worldEnd.x);
         const minY = Math.min(worldStart.y, worldEnd.y);
         const maxY = Math.max(worldStart.y, worldEnd.y);

         const isClick = (maxX - minX < 5) && (maxY - minY < 5);
         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             // Can select Enemy/Neutral if single click
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - worldStart.x;
                 const dy = ent.position.y - worldStart.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 10) {
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         // Smart selection: if mixed, select units only
         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         setMouseDownPos(null);
     }
  };

  const handleMouseLeave = () => {
     setMouseDownPos(null);
     isDraggingCamera.current = false;
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2 } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity } from '../services/gameLogic';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State
  const [mouseDownPos, setMouseDownPos] = useState<Vector2 | null>(null);
  // Fix: Initialize mousePos to center to prevent initial top-left drift
  const [mousePos, setMousePos] = useState<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          // Camera Move from Minimap
          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                      }
                  }
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => keysPressed.current.add(e.code);
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, []);

  const getWorldPos = (e: React.MouseEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left + gameStateRef.current.camera.x;
    const y = e.clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else {
        // Color based on owner
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // Selection Box
    if (mouseDownPos) {
        const currentWorld = { 
            x: mousePos.x + state.camera.x, 
            y: mousePos.y + state.camera.y 
        };
        const startWorld = {
            x: mouseDownPos.x + state.camera.x,
            y: mouseDownPos.y + state.camera.y
        };

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorld.x - startWorld.x, 
            currentWorld.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);
    }

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    // Keyboard Pan
    const keySpeed = 20;
    if (keysPressed.current.has('ArrowLeft') || keysPressed.current.has('KeyA')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight') || keysPressed.current.has('KeyD')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp') || keysPressed.current.has('KeyW')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown') || keysPressed.current.has('KeyS')) gameStateRef.current.camera.y += keySpeed;

    // Edge Pan (Only if not dragging)
    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { // Right Click - Prepare for Drag or Command
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        // Don't execute command yet
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
          }
          return;
      }
      setMouseDownPos({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    setMousePos({ x: e.clientX, y: e.clientY });

    // Middle Mouse Drag Pan
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    // Right Mouse Drag Pan
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { // Right Click Up
         e.preventDefault();
         if (!isRightDragging.current) {
             // Not a drag, so it's a Command Click
             const pos = getWorldPos(e);
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 5;
             });

             gameStateRef.current.selection.forEach(id => {
                const unit = gameStateRef.current.entities.get(id);
                if (unit && unit.owner === Owner.PLAYER) {
                   if (clickedEntity) {
                       if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                           unit.state = 'GATHERING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                       }
                   } else {
                       unit.state = 'MOVING';
                       unit.targetPosition = pos;
                       unit.targetId = null;
                   }
                }
             });
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownPos) {
         const start = mouseDownPos;
         const end = { x: e.clientX, y: e.clientY };

         const cam = gameStateRef.current.camera;
         const worldStart = { x: start.x + cam.x, y: start.y + cam.y };
         const worldEnd = { x: end.x + cam.x, y: end.y + cam.y };

         const minX = Math.min(worldStart.x, worldEnd.x);
         const maxX = Math.max(worldStart.x, worldEnd.x);
         const minY = Math.min(worldStart.y, worldEnd.y);
         const maxY = Math.max(worldStart.y, worldEnd.y);

         const isClick = (maxX - minX < 5) && (maxY - minY < 5);
         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             // Can select Enemy/Neutral if single click
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - worldStart.x;
                 const dy = ent.position.y - worldStart.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 10) {
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         // Smart selection: if mixed, select units only
         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         setMouseDownPos(null);
     }
  };

  const handleMouseLeave = () => {
     setMouseDownPos(null);
     isDraggingCamera.current = false;
     isRightDragging.current = false;
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

import React from 'react';
import { Entity, EntityType, GameState, Owner } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';

interface Props {
  gameState: GameState;
  selectedEntities: Entity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];

  // Determine available commands based on selection
  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);

  const canBuild = allWorkers && selectedEntities.length === 1; // Only 1 worker can open build menu for now

  const handleMinimapClick = (e: React.MouseEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const xPct = (e.clientX - rect.left) / rect.width;
      const yPct = (e.clientY - rect.top) / rect.height;

      const targetX = xPct * GAME_WIDTH;
      const targetY = yPct * GAME_HEIGHT;

      // Center camera on click
      const centerX = targetX - (window.innerWidth / 2);
      const centerY = targetY - (window.innerHeight / 2);

      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
      }));
  };

  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between">
      {/* Top Bar */}
      <div className="bg-gray-900 bg-opacity-90 text-white p-2 flex gap-8 border-b border-gray-700 pointer-events-auto select-none">
         <div className="font-bold text-yellow-400">Minerals: {Math.floor(resources)}</div>
         <div className={supply.used > supply.max ? "text-red-500" : "text-green-400"}>
             Supply: {supply.used}/{supply.max}
         </div>
         <div className="text-gray-400">Time: {Math.floor(gameState.gameTime / 60)}s</div>
         {gameState.victory && (
             <div className="ml-auto font-bold text-2xl text-yellow-500 animate-pulse">
                 {gameState.victory === Owner.PLAYER ? "VICTORY!" : "DEFEAT"}
             </div>
         )}
      </div>

      {/* Bottom Panel */}
      <div className="h-48 bg-gray-900 border-t border-gray-700 flex pointer-events-auto select-none">
          {/* Minimap */}
          <div 
              className="w-48 bg-black border-r border-gray-700 relative overflow-hidden cursor-move"
              onMouseDown={handleMinimapClick} // Simple click to jump, could be drag later
          >
             {/* Simple Minimap Rendering */}
             {(Array.from(gameState.entities.values()) as Entity[]).map(e => (
                 <div key={e.id} 
                      className={`absolute w-1 h-1 rounded-full ${
                          e.owner === Owner.PLAYER ? 'bg-blue-500' : 
                          e.owner === Owner.AI ? 'bg-red-500' : 'bg-teal-500'
                      }`}
                      style={{ 
                          left: `${(e.position.x / GAME_WIDTH) * 100}%`, 
                          top: `${(e.position.y / GAME_HEIGHT) * 100}%` 
                      }} 
                 />
             ))}
             {/* Camera Rect */}
             <div className="absolute border border-white pointer-events-none"
                  style={{
                      left: `${(gameState.camera.x / GAME_WIDTH) * 100}%`,
                      top: `${(gameState.camera.y / GAME_HEIGHT) * 100}%`,
                      width: `${(window.innerWidth / GAME_WIDTH) * 100}%`,
                      height: `${(window.innerHeight / GAME_HEIGHT) * 100}%`,
                  }}
             />
          </div>

          {/* Unit Info */}
          <div className="flex-1 p-4 border-r border-gray-700 flex flex-wrap gap-2 overflow-auto">
             {selectedEntities.length === 0 && <span className="text-gray-500">No selection</span>}
             {selectedEntities.length > 0 && selectedEntities.length < 12 && selectedEntities.map(e => (
                 <div key={e.id} className="w-16 h-16 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-xs text-white">
                     <div className={`w-3 h-3 rounded-full mb-1 ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                     <span>{e.type}</span>
                     <div className="w-full h-1 bg-red-900 mt-1">
                         <div className="h-full bg-green-500" style={{ width: `${(e.hp / e.maxHp) * 100}%`}} />
                     </div>
                 </div>
             ))}
             {selectedEntities.length >= 12 && (
                 <div className="text-white p-4">
                     Selected: {selectedEntities.length} Units
                 </div>
             )}
          </div>

          {/* Command Card */}
          <div className="w-64 bg-gray-800 p-2 grid grid-cols-3 gap-2">
              {/* Build Commands */}
              {canBuild && (
                  <>
                    <CommandButton 
                        label="Depot (100)" 
                        hotkey="S" 
                        cost={100} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} 
                    />
                    <CommandButton 
                        label="Barracks (150)" 
                        hotkey="B" 
                        cost={150} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} 
                    />
                  </>
              )}

              {/* Train Commands */}
              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Worker (50)" 
                      hotkey="W" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.WORKER].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {singleSelection?.type === EntityType.BARRACKS && (
                  <CommandButton 
                      label="Marine (50)" 
                      hotkey="M" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.MARINE)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.MARINE].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
          </div>
      </div>
    </div>
  );
};

const CommandButton = ({ label, hotkey, cost, currentResources, onClick, progress, maxProgress, queue }: any) => {
    const disabled = currentResources < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`relative bg-gray-700 border border-gray-500 text-white text-xs p-1 hover:bg-gray-600 active:bg-gray-500 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center justify-center h-20`}
        >
            <span className="font-bold text-yellow-300 mb-1">{hotkey}</span>
            <span className="text-center">{label}</span>
            {queue > 0 && <span className="absolute top-0 right-0 bg-blue-600 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center">{queue}</span>}
            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-black">
                    <div className="h-full bg-white" style={{ width: `${(progress / maxProgress) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2 } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity } from '../services/gameLogic';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State via Refs to avoid stale closures in the game loop
  const mouseDownPosRef = useRef<Vector2 | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Sync commandMode to a ref if needed, or rely on useEffect restart. 
  // Since we rely on useEffect deps for commandMode, the loop recreates, which is fine for infrequent changes.
  // But to be safe and cleaner, let's just use the prop directly in the closures which are recreated.

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          // Camera Move from Minimap
          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                      }
                  }
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => keysPressed.current.add(e.code);
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, []);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else {
        // Color based on owner
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // Selection Box
    if (mouseDownPosRef.current) {
        const currentWorld = { 
            x: mousePos.x + state.camera.x, 
            y: mousePos.y + state.camera.y 
        };
        const startWorld = {
            x: mouseDownPosRef.current.x + state.camera.x,
            y: mouseDownPosRef.current.y + state.camera.y
        };

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorld.x - startWorld.x, 
            currentWorld.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);
    }

    const mousePos = mousePosRef.current;

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    // Keyboard Pan
    const keySpeed = 20;
    if (keysPressed.current.has('ArrowLeft') || keysPressed.current.has('KeyA')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight') || keysPressed.current.has('KeyD')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp') || keysPressed.current.has('KeyW')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown') || keysPressed.current.has('KeyS')) gameStateRef.current.camera.y += keySpeed;

    // Edge Pan (Only if not dragging)
    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); // commandMode dependency restarts loop when mode changes (acceptable)

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { // Right Click - Prepare for Drag or Command
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
          }
          return;
      }
      mouseDownPosRef.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    // Middle Mouse Drag Pan
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    // Right Mouse Drag Pan
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { // Right Click Up
         e.preventDefault();
         if (!isRightDragging.current) {
             // Not a drag, so it's a Command Click
             const pos = getWorldPos(e.clientX, e.clientY);
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 5;
             });

             gameStateRef.current.selection.forEach(id => {
                const unit = gameStateRef.current.entities.get(id);
                if (unit && unit.owner === Owner.PLAYER) {
                   if (clickedEntity) {
                       if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                           unit.state = 'GATHERING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                       }
                   } else {
                       unit.state = 'MOVING';
                       unit.targetPosition = pos;
                       unit.targetId = null;
                   }
                }
             });
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownPosRef.current) {
         const start = mouseDownPosRef.current;
         const end = { x: e.clientX, y: e.clientY };

         const cam = gameStateRef.current.camera;
         const worldStart = { x: start.x + cam.x, y: start.y + cam.y };
         const worldEnd = { x: end.x + cam.x, y: end.y + cam.y };

         const minX = Math.min(worldStart.x, worldEnd.x);
         const maxX = Math.max(worldStart.x, worldEnd.x);
         const minY = Math.min(worldStart.y, worldEnd.y);
         const maxY = Math.max(worldStart.y, worldEnd.y);

         const isClick = (maxX - minX < 5) && (maxY - minY < 5);
         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             // Can select Enemy/Neutral if single click
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - worldStart.x;
                 const dy = ent.position.y - worldStart.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 10) {
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         // Smart selection: if mixed, select units only
         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownPosRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownPosRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     // Stop edge panning when mouse leaves
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2 } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: type === EntityType.MINERAL ? 1500 : 0,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: 100, // Buildings start built unless specified otherwise
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

export const initGame = (): GameState => {
  const entities = new Map<string, Entity>();

  // Helper to add entity
  const add = (e: Entity) => entities.set(e.id, e);

  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };
  add(createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos));
  // Player Workers
  for (let i = 0; i < 4; i++) {
    add(createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 })); // Spawned slightly above
  }
  // Player Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; // Semi-circle
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  // AI Workers
  for (let i = 0; i < 4; i++) {
    add(createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 }));
  }
  // AI Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; // Opposite semi-circle
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  return {
    entities,
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: 1400 }, // Start near player
    gameTime: 0,
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; // Buildings don't get pushed
  if (STATS[entity.type].speed === 0) return; // Static units don't move

  entities.forEach(other => {
    if (entity.id === other.id) return;
    if (STATS[other.type].speed === 0 && other.constructionProgress! >= 100) {
        // Hard collision with buildings
        // Simplified: handled by navigation usually, but basic push-out here
    }

    const dist = getDistance(entity.position, other.position);
    const minDist = entity.radius + other.radius;

    if (dist < minDist && dist > 0) {
      const push = (minDist - dist) / 2;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      entity.position.x += Math.cos(angle) * push * 0.1; // Soft push
      entity.position.y += Math.sin(angle) * push * 0.1;
    }
  });
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return; // Skip neutrals for supply calculations

    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  // Limit max supply to 200
  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    // 1. Building Construction / Production
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; // Can't do anything while building
    }

    // 2. Unit Production (Buildings training units)
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          // Spawn Unit
          const stats = STATS[unitType];
          // Check supply again before spawning
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             // Spawn logic: Player spawns 'Above' (negative Y offset), AI 'Below' (positive Y offset)
             // This keeps units towards the center of map usually and visible
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // If AI, give basic attack move command immediately to rally point (center map)
             if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             // Supply blocked, pause production
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    if (entity.state === 'IDLE') {
        // Auto-attack check
        if (stats.damage > 0) {
            let target: Entity | null = null;
            let minDist = stats.range + 50; // Acquisition range slightly larger

            entities.forEach(e => {
                if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0) {
                    const d = getDistance(entity.position, e.position);
                    if (d < minDist) {
                        minDist = d;
                        target = e;
                    }
                }
            });

            if (target) {
                entity.targetId = (target as Entity).id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 5) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // If target dead or lost, look for new one or stop
        if (!target || target.hp <= 0) {
           if (entity.targetPosition) {
             entity.state = 'MOVING'; // Resume move command (Attack-Move logic simplified)
           } else {
             entity.state = 'IDLE';
           }
           entity.targetId = null;
        } else {
           const dist = getDistance(entity.position, target.position);
           if (dist <= stats.range) {
              // Attack
              if (entity.cooldown <= 0) {
                  // Projectile logic could go here, for now instant hit
                  target.hp -= stats.damage;
                  entity.cooldown = stats.attackSpeed;
                  // Aggro logic: target attacks back if idle
                  if (target.state === 'IDLE' && STATS[target.type].damage > 0) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              // Move into range
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            // Find new resource
            const newRes = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
            if (newRes) {
                entity.targetId = newRes.id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            const dist = getDistance(entity.position, target.position);
            if (dist <= 10) {
                entity.cooldown++; // Using cooldown as gather timer
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id); // Depleted
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    // Find nearest base
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
            // Base destroyed? Find another
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; // No bases left
        } else {
            const dist = getDistance(entity.position, base.position);
            if (dist < base.radius + entity.radius + 5) {
                // Deposit
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                // Return to mining
                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        newEntities.delete(entity.id);
    }

    // Resolve physics
    resolveCollisions(entity, entities);

  });

  // --- SIMPLE AI ---
  // Only run AI logic every 60 frames roughly to save perf, or just run lightweight checks
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) playerBuildings++;
      if (e.owner === Owner.AI && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; // Simplified win con
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    gameTime: state.gameTime + 1,
    victory
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  // 1. Train Workers
  if (workers.length < 12 && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  // 2. Manage Workers (Idle Check)
  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // 3. Build Supply Depots
  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      // Find a worker to build
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          // Build near base
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          // Instant placement for AI simplicity (create entity immediately with construction progress 0)
          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  // 4. Build Barracks
  if (barracks.length < 3 && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  // 5. Train Army
  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  // 6. Attack
  if (army.length > 10) {
      // Find enemy base
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      const targetPos = enemyBase ? enemyBase.position : { x: 200, y: 1800 }; // Fallback to player start

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2 } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity } from '../services/gameLogic';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State via Refs
  // Stores both screen position and the WORLD position at the time of the click
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                      }
                  }
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => keysPressed.current.add(e.code);
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, []);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else {
        // Color based on owner
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // Selection Box Drawing
    if (mouseDownStateRef.current) {
        // Calculate current world pos (accounting for camera movement)
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorldPos.x - startWorld.x, 
            currentWorldPos.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);
    }

    const mousePos = mousePosRef.current;

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    // Keyboard Pan
    const keySpeed = 20;
    if (keysPressed.current.has('ArrowLeft') || keysPressed.current.has('KeyA')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight') || keysPressed.current.has('KeyD')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp') || keysPressed.current.has('KeyW')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown') || keysPressed.current.has('KeyS')) gameStateRef.current.camera.y += keySpeed;

    // Edge Pan (Only if not dragging)
    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { // Right Click
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
          }
          return;
      }

      // Store BOTH Screen and World position for consistent dragging
      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    // Middle Mouse Drag Pan
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    // Right Mouse Drag Pan
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { // Right Click Up
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             // Larger tolerance for clicking units
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 15; // Increased tolerance
             });

             gameStateRef.current.selection.forEach(id => {
                const unit = gameStateRef.current.entities.get(id);
                if (unit && unit.owner === Owner.PLAYER) {
                   if (clickedEntity) {
                       if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                           unit.state = 'GATHERING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                       }
                   } else {
                       unit.state = 'MOVING';
                       unit.targetPosition = pos;
                       unit.targetId = null;
                   }
                }
             });
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);

         const isClick = (screenDiffX < 5 && screenDiffY < 5);

         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         // Use the world position from when the mouse was pressed down for the start of the box
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             // Can select Enemy/Neutral if single click
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { // Increased hit tolerance
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     // Stop edge panning when mouse leaves
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI',
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Entity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
}

export interface GameState {
  entities: Map<string, Entity>;
  effects: Effect[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
  };
  selection: string[]; // IDs of selected entities
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  speed: number;
  attackSpeed: number; // Frames between attacks
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: type === EntityType.MINERAL ? 1500 : 0,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: type === EntityType.MOUNTAIN ? 100 : 100,
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

export const initGame = (): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  // Helper to add entity
  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---

  // Create Mountains (Chokepoints)
  // Diagonal barrier with a gap in the middle
  const centerX = GAME_WIDTH / 2;
  const centerY = GAME_HEIGHT / 2;

  for(let i = 0; i < 20; i++) {
     // Bottom Left to Top Right barrier parts
     const gapSize = 300;
     const offset = 400; // Shift off center

     // Block 1
     if (i * 80 < GAME_WIDTH - gapSize - offset) {
         add(createEntity(EntityType.MOUNTAIN, Owner.NEUTRAL, { 
             x: 200 + i * 80, 
             y: GAME_HEIGHT - (200 + i * 80)
         }));
     }

     // Block 2 (Top Right side)
     // if (i * 80 > gapSize) {
     //    add(createEntity(EntityType.MOUNTAIN, Owner.NEUTRAL, { 
     //        x: centerX + 200 + i * 60, 
     //        y: centerY - 200 - i * 60 
     //    }));
     // }
  }

  // Random mountains
  for (let i = 0; i < 15; i++) {
      const x = Math.random() * GAME_WIDTH;
      const y = Math.random() * GAME_HEIGHT;
      // Keep away from bases
      if (getDistance({x,y}, {x:200, y:1800}) > 600 && getDistance({x,y}, {x:1800, y:200}) > 600) {
          add(createEntity(EntityType.MOUNTAIN, Owner.NEUTRAL, {x, y}));
      }
  }


  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };
  add(createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos));
  // Player Workers
  for (let i = 0; i < 4; i++) {
    add(createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 })); 
  }
  // Player Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  // AI Workers
  for (let i = 0; i < 4; i++) {
    add(createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 }));
  }
  // AI Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  return {
    entities,
    effects,
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: 1400 },
    gameTime: 0,
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    // Static objects (Buildings, Mountains) logic
    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const minDist = entity.radius + other.radius;

    if (dist < minDist && dist > 0) {
      const push = (minDist - dist);
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const pushFactor = isStatic ? 1.0 : 0.5; // If hitting static, pushed out fully. If unit, share push.

      entity.position.x += Math.cos(angle) * push * pushFactor * 0.2; // Soft push
      entity.position.y += Math.sin(angle) * push * pushFactor * 0.2;
    }
  });
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;

    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN) return; // Skip logic for mountains

    // 1. Building Construction / Production
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    if (entity.state === 'IDLE') {
        if (stats.damage > 0) {
            let target: Entity | null = null;
            let minDist = stats.range + 50; 

            entities.forEach(e => {
                if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN) {
                    const d = getDistance(entity.position, e.position);
                    if (d < minDist) {
                        minDist = d;
                        target = e;
                    }
                }
            });

            if (target) {
                entity.targetId = (target as Entity).id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 5) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        if (!target || target.hp <= 0) {
           if (entity.targetPosition) {
             entity.state = 'MOVING'; 
           } else {
             entity.state = 'IDLE';
           }
           entity.targetId = null;
        } else {
           const dist = getDistance(entity.position, target.position);
           if (dist <= stats.range) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  entity.cooldown = stats.attackSpeed;
                  if (target.state === 'IDLE' && STATS[target.type].damage > 0) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            const newRes = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
            if (newRes) {
                entity.targetId = newRes.id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            const dist = getDistance(entity.position, target.position);
            if (dist <= 10) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id);
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            if (dist < base.radius + entity.radius + 5) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        // Spawn Effect
        const effectType = (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) ? 'BLOOD' : 'EXPLOSION';
        const effectScale = entity.radius / 10;
        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: 30,
            maxLife: 30,
            scale: effectScale
        });

        newEntities.delete(entity.id);
    }

    // Resolve physics
    resolveCollisions(entity, entities);

  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- SIMPLE AI ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) playerBuildings++;
      if (e.owner === Owner.AI && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    gameTime: state.gameTime + 1,
    victory
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  if (workers.length < 12 && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  if (barracks.length < 3 && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  if (army.length > 10) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      const targetPos = enemyBase ? enemyBase.position : { x: 200, y: 1800 }; 

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2 } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity } from '../services/gameLogic';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State via Refs
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                      }
                  }
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => keysPressed.current.add(e.code);
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, []);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; 
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else if (entity.type === EntityType.MOUNTAIN) {
        // Mountain Drawing
        ctx.fillStyle = '#4b5563'; // Gray 600
        ctx.beginPath();
        // Irregular mountain shape
        ctx.moveTo(0, -40); 
        ctx.lineTo(30, -10); 
        ctx.lineTo(20, 20); 
        ctx.lineTo(40, 40);
        ctx.lineTo(0, 30);
        ctx.lineTo(-30, 40);
        ctx.lineTo(-40, 10);
        ctx.lineTo(-20, -20);
        ctx.fill();
        // Highlights
        ctx.fillStyle = '#6b7280';
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(15, 0); ctx.lineTo(-5, 5);
        ctx.fill();
      } else {
        // Color based on owner
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // --- DRAW EFFECTS ---
    state.effects.forEach(fx => {
        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; // 1.0 down to 0.0

        if (fx.type === 'EXPLOSION') {
            const r = (1 - lifePct) * 40 * fx.scale;
            ctx.globalAlpha = lifePct;

            // Core
            ctx.fillStyle = '#fff7ed'; // light orange
            ctx.beginPath(); ctx.arc(0,0, r * 0.5, 0, Math.PI*2); ctx.fill();

            // Outer
            ctx.fillStyle = '#ea580c'; // orange red
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();

            // Smoke
            ctx.strokeStyle = '#57534e';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.arc(0,0, r * 1.2, 0, Math.PI*2); ctx.stroke();

        } else if (fx.type === 'BLOOD') {
            ctx.fillStyle = '#991b1b'; // Dark Red
            ctx.globalAlpha = lifePct;
            // Splatter
            ctx.beginPath(); ctx.arc(0,0, 10, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5,5, 6, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-5,-2, 4, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Selection Box Drawing
    if (mouseDownStateRef.current) {
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorldPos.x - startWorld.x, 
            currentWorldPos.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);
    }

    const mousePos = mousePosRef.current;

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    // Keyboard Pan
    const keySpeed = 20;
    if (keysPressed.current.has('ArrowLeft') || keysPressed.current.has('KeyA')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight') || keysPressed.current.has('KeyD')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp') || keysPressed.current.has('KeyW')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown') || keysPressed.current.has('KeyS')) gameStateRef.current.camera.y += keySpeed;

    // Edge Pan (Only if not dragging)
    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { // Right Click
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
          }
          return;
      }

      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { 
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 15;
             });

             gameStateRef.current.selection.forEach(id => {
                const unit = gameStateRef.current.entities.get(id);
                if (unit && unit.owner === Owner.PLAYER) {
                   if (clickedEntity) {
                       if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                           unit.state = 'GATHERING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                           unit.targetPosition = null;
                       } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                           unit.state = 'ATTACKING';
                           unit.targetId = clickedEntity.id;
                       }
                   } else {
                       unit.state = 'MOVING';
                       unit.targetPosition = pos;
                       unit.targetId = null;
                   }
                }
             });
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);

         const isClick = (screenDiffX < 5 && screenDiffY < 5);

         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             if (ent.type === EntityType.MOUNTAIN) return; // Cannot select mountains
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { 
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI',
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Entity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
}

export interface GameState {
  entities: Map<string, Entity>;
  effects: Effect[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
  };
  selection: string[]; // IDs of selected entities
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  speed: number;
  attackSpeed: number; // Frames between attacks
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: type === EntityType.MINERAL ? 1500 : 0,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

export const initGame = (): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---

  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          // Avoid start areas
          if (getDistance({x,y}, {x:200, y:1800}) < 400) continue;
          if (getDistance({x,y}, {x:1800, y:200}) < 400) continue;

          // Avoid map edges
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  // Center Mountains
  generateCluster(EntityType.MOUNTAIN, 20, GAME_WIDTH/2, GAME_HEIGHT/2, 300);

  // Random Lakes
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.25, GAME_HEIGHT * 0.25, 200);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.75, GAME_HEIGHT * 0.75, 200);

  // Random Mountains
  for(let i=0; i<3; i++) {
      generateCluster(EntityType.MOUNTAIN, 8, Math.random() * GAME_WIDTH, Math.random() * GAME_HEIGHT, 150);
  }


  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  // Player Workers
  for (let i = 0; i < 4; i++) {
    add(createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 })); 
  }
  // Player Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  // Auto-set Player Base Rally to nearest mineral
  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  // AI Workers
  for (let i = 0; i < 4; i++) {
    add(createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 }));
  }
  // AI Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  return {
    entities,
    effects,
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: 1400 },
    gameTime: 0,
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    // Static objects (Buildings, Mountains, Water) logic
    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const minDist = entity.radius + other.radius;

    if (dist < minDist && dist > 0) {
      const push = (minDist - dist);
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const pushFactor = isStatic ? 1.0 : 0.5; // If hitting static, pushed out fully. If unit, share push.

      entity.position.x += Math.cos(angle) * push * pushFactor * 0.2; // Soft push
      entity.position.y += Math.sin(angle) * push * pushFactor * 0.2;
    }
  });
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;

    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // --- RALLY POINT LOGIC ---
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     // Check if target is mineral
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     // Military or generic move
                     newUnit.state = 'MOVING';
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         // Attack move logic if hostile? For now just move.
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                 }
             } else if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                // AI Default Rally
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    if (entity.state === 'IDLE') {
        if (stats.damage > 0) {
            let target: Entity | null = null;
            let minDist = stats.range + 50; 

            entities.forEach(e => {
                if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
                    const d = getDistance(entity.position, e.position);
                    if (d < minDist) {
                        minDist = d;
                        target = e;
                    }
                }
            });

            if (target) {
                entity.targetId = (target as Entity).id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 5) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        if (!target || target.hp <= 0) {
           if (entity.targetPosition) {
             entity.state = 'MOVING'; 
           } else {
             entity.state = 'IDLE';
           }
           entity.targetId = null;
        } else {
           const dist = getDistance(entity.position, target.position);
           if (dist <= stats.range) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  entity.cooldown = stats.attackSpeed;
                  if (target.state === 'IDLE' && STATS[target.type].damage > 0) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            const newRes = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
            if (newRes) {
                entity.targetId = newRes.id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            const dist = getDistance(entity.position, target.position);
            if (dist <= 10) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id);
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            if (dist < base.radius + entity.radius + 5) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        const effectType = (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) ? 'BLOOD' : 'EXPLOSION';
        const effectScale = entity.radius / 10;
        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: 30,
            maxLife: 30,
            scale: effectScale
        });
        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- SIMPLE AI ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) playerBuildings++;
      if (e.owner === Owner.AI && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    gameTime: state.gameTime + 1,
    victory
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  if (workers.length < 12 && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  if (barracks.length < 3 && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  if (army.length > 10) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      const targetPos = enemyBase ? enemyBase.position : { x: 200, y: 1800 }; 

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef, useState } from 'react';
import { Entity, EntityType, GameState, Owner } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';

interface Props {
  gameState: GameState;
  selectedEntities: Entity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];

  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);
  const canBuild = allWorkers && selectedEntities.length === 1;

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const key = e.key.toUpperCase();

        // Prevent shortcuts if typing in an input (if added later)
        if ((e.target as HTMLElement).tagName === 'INPUT') return;

        if (singleSelection) {
            // Base Shortcuts
            if (singleSelection.type === EntityType.BASE) {
                if (key === 'W') onTrain(EntityType.WORKER);
            }
            // Barracks Shortcuts
            if (singleSelection.type === EntityType.BARRACKS) {
                if (key === 'M') onTrain(EntityType.MARINE);
            }
            // Worker Shortcuts
            if (singleSelection.type === EntityType.WORKER) {
                if (key === 'B') onCommand(`BUILD_${EntityType.BARRACKS}`);
                if (key === 'S') onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`);
            }
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [singleSelection, onTrain, onCommand]);


  // --- Minimap Logic ---
  const [isDraggingMinimap, setIsDraggingMinimap] = useState(false);
  const minimapRef = useRef<HTMLDivElement>(null);

  const updateCameraFromMinimap = (clientX: number, clientY: number) => {
      if (!minimapRef.current) return;
      const rect = minimapRef.current.getBoundingClientRect();
      const xPct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const yPct = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));

      const targetX = xPct * GAME_WIDTH;
      const targetY = yPct * GAME_HEIGHT;

      const centerX = targetX - (window.innerWidth / 2);
      const centerY = targetY - (window.innerHeight / 2);

      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
      }));
  };

  const handleMinimapMouseDown = (e: React.MouseEvent) => {
      setIsDraggingMinimap(true);
      updateCameraFromMinimap(e.clientX, e.clientY);
  };

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (isDraggingMinimap) {
              updateCameraFromMinimap(e.clientX, e.clientY);
          }
      };
      const handleMouseUp = () => {
          setIsDraggingMinimap(false);
      };

      if (isDraggingMinimap) {
          window.addEventListener('mousemove', handleMouseMove);
          window.addEventListener('mouseup', handleMouseUp);
      }
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
      };
  }, [isDraggingMinimap]);


  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between">
      {/* Top Bar */}
      <div className="bg-gray-900 bg-opacity-90 text-white p-2 flex gap-8 border-b border-gray-700 pointer-events-auto select-none">
         <div className="font-bold text-yellow-400">Minerals: {Math.floor(resources)}</div>
         <div className={supply.used > supply.max ? "text-red-500" : "text-green-400"}>
             Supply: {supply.used}/{supply.max}
         </div>
         <div className="text-gray-400">Time: {Math.floor(gameState.gameTime / 60)}s</div>
         {gameState.victory && (
             <div className="ml-auto font-bold text-2xl text-yellow-500 animate-pulse">
                 {gameState.victory === Owner.PLAYER ? "VICTORY!" : "DEFEAT"}
             </div>
         )}
      </div>

      {/* Bottom Panel */}
      <div className="h-48 bg-gray-900 border-t border-gray-700 flex pointer-events-auto select-none">
          {/* Minimap */}
          <div 
              ref={minimapRef}
              className="w-48 bg-black border-r border-gray-700 relative overflow-hidden cursor-move"
              onMouseDown={handleMinimapMouseDown}
          >
             {/* Map Features */}
             {(Array.from(gameState.entities.values()) as Entity[]).map(e => {
                 let color = 'bg-gray-500';
                 if (e.type === EntityType.WATER) color = 'bg-blue-800';
                 else if (e.type === EntityType.MOUNTAIN) color = 'bg-gray-700';
                 else if (e.type === EntityType.MINERAL) color = 'bg-teal-500';
                 else if (e.owner === Owner.PLAYER) color = 'bg-blue-500';
                 else if (e.owner === Owner.AI) color = 'bg-red-500';

                 // Don't render small features on minimap to save perf? Or simpler dots
                 const size = (e.type === EntityType.WATER || e.type === EntityType.MOUNTAIN) ? 4 : 2;

                 return (
                    <div key={e.id} 
                        className={`absolute rounded-full ${color}`}
                        style={{ 
                            left: `${(e.position.x / GAME_WIDTH) * 100}%`, 
                            top: `${(e.position.y / GAME_HEIGHT) * 100}%`,
                            width: size + 'px', height: size + 'px'
                        }} 
                    />
                 );
             })}

             {/* Camera Rect */}
             <div className="absolute border border-white pointer-events-none"
                  style={{
                      left: `${(gameState.camera.x / GAME_WIDTH) * 100}%`,
                      top: `${(gameState.camera.y / GAME_HEIGHT) * 100}%`,
                      width: `${(window.innerWidth / GAME_WIDTH) * 100}%`,
                      height: `${(window.innerHeight / GAME_HEIGHT) * 100}%`,
                  }}
             />
          </div>

          {/* Unit Info */}
          <div className="flex-1 p-4 border-r border-gray-700 flex flex-wrap gap-2 overflow-auto">
             {selectedEntities.length === 0 && <span className="text-gray-500">No selection</span>}
             {selectedEntities.length > 0 && selectedEntities.length < 12 && selectedEntities.map(e => (
                 <div key={e.id} className="w-16 h-16 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-xs text-white">
                     <div className={`w-3 h-3 rounded-full mb-1 ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                     <span>{e.type}</span>
                     <div className="w-full h-1 bg-red-900 mt-1">
                         <div className="h-full bg-green-500" style={{ width: `${(e.hp / e.maxHp) * 100}%`}} />
                     </div>
                 </div>
             ))}
             {selectedEntities.length >= 12 && (
                 <div className="text-white p-4">
                     Selected: {selectedEntities.length} Units
                 </div>
             )}
          </div>

          {/* Command Card */}
          <div className="w-64 bg-gray-800 p-2 grid grid-cols-3 gap-2">
              {/* Build Commands */}
              {canBuild && (
                  <>
                    <CommandButton 
                        label="Depot (100)" 
                        hotkey="S" 
                        cost={100} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} 
                    />
                    <CommandButton 
                        label="Barracks (150)" 
                        hotkey="B" 
                        cost={150} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} 
                    />
                  </>
              )}

              {/* Train Commands */}
              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Worker (50)" 
                      hotkey="W" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.WORKER].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {singleSelection?.type === EntityType.BARRACKS && (
                  <CommandButton 
                      label="Marine (50)" 
                      hotkey="M" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.MARINE)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.MARINE].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
          </div>
      </div>
    </div>
  );
};

const CommandButton = ({ label, hotkey, cost, currentResources, onClick, progress, maxProgress, queue }: any) => {
    const disabled = currentResources < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`relative bg-gray-700 border border-gray-500 text-white text-xs p-1 hover:bg-gray-600 active:bg-gray-500 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center justify-center h-20`}
        >
            <span className="font-bold text-yellow-300 mb-1">{hotkey}</span>
            <span className="text-center">{label}</span>
            {queue > 0 && <span className="absolute top-0 right-0 bg-blue-600 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center">{queue}</span>}
            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-black">
                    <div className="h-full bg-white" style={{ width: `${(progress / maxProgress) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2 } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity } from '../services/gameLogic';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State via Refs
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                      }
                  }
              }
          }

          if (detail.action === 'SET_RALLY') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent) {
                  ent.rallyPoint = detail.pos;
                  ent.rallyTargetId = detail.targetId;
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => keysPressed.current.add(e.code);
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, []);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Rally Point Line (if selected building)
      if (state.selection.includes(entity.id) && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.save();
          // Draw line from building to rally point
          ctx.strokeStyle = '#fbbf24'; // Yellow
          ctx.setLineDash([5, 5]);
          ctx.beginPath();
          ctx.moveTo(0, 0); // Local 0,0 is entity center
          // Need to transform back to global for lineTo, or just subtract entity pos
          ctx.lineTo(entity.rallyPoint.x - entity.position.x, entity.rallyPoint.y - entity.position.y);
          ctx.stroke();
          ctx.restore();
      }

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; 
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else if (entity.type === EntityType.MOUNTAIN) {
        ctx.fillStyle = '#4b5563'; 
        ctx.beginPath();
        ctx.moveTo(0, -40); 
        ctx.lineTo(30, -10); ctx.lineTo(20, 20); ctx.lineTo(40, 40);
        ctx.lineTo(0, 30); ctx.lineTo(-30, 40); ctx.lineTo(-40, 10); ctx.lineTo(-20, -20);
        ctx.fill();
        ctx.fillStyle = '#6b7280';
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(15, 0); ctx.lineTo(-5, 5);
        ctx.fill();
      } else if (entity.type === EntityType.WATER) {
        // Water Effect
        ctx.fillStyle = '#1e3a8a';
        ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0,0, 25, 0, Math.PI*2); ctx.stroke();
        // Simple Wave
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath(); 
        ctx.moveTo(-15, 0); ctx.quadraticCurveTo(0, -10, 15, 0);
        ctx.stroke();
      } else {
        // Color based on owner
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // --- DRAW EFFECTS ---
    state.effects.forEach(fx => {
        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; // 1.0 down to 0.0

        if (fx.type === 'EXPLOSION') {
            const r = (1 - lifePct) * 40 * fx.scale;
            ctx.globalAlpha = lifePct;
            ctx.fillStyle = '#fff7ed'; 
            ctx.beginPath(); ctx.arc(0,0, r * 0.5, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#ea580c'; 
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = '#57534e';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.arc(0,0, r * 1.2, 0, Math.PI*2); ctx.stroke();
        } else if (fx.type === 'BLOOD') {
            ctx.fillStyle = '#991b1b'; 
            ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.arc(0,0, 10, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5,5, 6, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-5,-2, 4, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Selection Box Drawing
    if (mouseDownStateRef.current) {
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorldPos.x - startWorld.x, 
            currentWorldPos.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);
    }

    const mousePos = mousePosRef.current;

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    if (keysPressed.current.has('ArrowLeft') || keysPressed.current.has('KeyA')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight') || keysPressed.current.has('KeyD')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp') || keysPressed.current.has('KeyW')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown') || keysPressed.current.has('KeyS')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  // Need keySpeed definition in loop scope or ref const
  const keySpeed = 20;

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { // Right Click
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
          }
          return;
      }

      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { 
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 15;
             });

             // Check if selection contains buildings -> Set Rally Point
             const hasBuildingsSelected = gameStateRef.current.selection.some(id => {
                 const ent = gameStateRef.current.entities.get(id);
                 return ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS);
             });

             if (hasBuildingsSelected) {
                  // Set Rally Point
                  gameStateRef.current.selection.forEach(id => {
                      const ent = gameStateRef.current.entities.get(id);
                      if (ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS)) {
                          window.dispatchEvent(new CustomEvent('GAME_COMMAND', {
                              detail: { 
                                  action: 'SET_RALLY', 
                                  id: ent.id, 
                                  pos, 
                                  targetId: clickedEntity ? clickedEntity.id : null 
                              }
                          }));
                      }
                  });
             } else {
                 // Move Units
                 gameStateRef.current.selection.forEach(id => {
                    const unit = gameStateRef.current.entities.get(id);
                    if (unit && unit.owner === Owner.PLAYER) {
                       if (clickedEntity) {
                           if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                               unit.state = 'GATHERING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                           }
                       } else {
                           unit.state = 'MOVING';
                           unit.targetPosition = pos;
                           unit.targetId = null;
                       }
                    }
                 });
             }
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);

         const isClick = (screenDiffX < 5 && screenDiffY < 5);

         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             if (ent.type === EntityType.MOUNTAIN || ent.type === EntityType.WATER) return; // Cannot select terrain
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { 
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

// Simple synth audio service
let audioCtx: AudioContext | null = null;
let isMuted = false;

const getCtx = () => {
    if (!audioCtx) {
        audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtx;
};

export const toggleMute = () => {
    isMuted = !isMuted;
    return isMuted;
};

export const getMuteState = () => isMuted;

export const playSound = (type: 'shoot' | 'explosion' | 'train' | 'build' | 'error' | 'click') => {
    if (isMuted) return;
    const ctx = getCtx();
    if (ctx.state === 'suspended') ctx.resume();

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'shoot') {
        osc.type = 'square';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(100, now + 0.1);
        gain.gain.setValueAtTime(0.1, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
        osc.start(now);
        osc.stop(now + 0.1);
    } 
    else if (type === 'explosion') {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(100, now);
        osc.frequency.exponentialRampToValueAtTime(10, now + 0.3);
        gain.gain.setValueAtTime(0.2, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
        osc.start(now);
        osc.stop(now + 0.3);
    }
    else if (type === 'train') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(600, now);
        osc.frequency.linearRampToValueAtTime(800, now + 0.1);
        gain.gain.setValueAtTime(0.1, now);
        gain.gain.linearRampToValueAtTime(0, now + 0.2);
        osc.start(now);
        osc.stop(now + 0.2);
    }
    else if (type === 'build') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(200, now);
        osc.frequency.linearRampToValueAtTime(400, now + 0.2);
        gain.gain.setValueAtTime(0.1, now);
        gain.gain.linearRampToValueAtTime(0, now + 0.2);
        osc.start(now);
        osc.stop(now + 0.2);
    }
    else if (type === 'error') {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(150, now);
        osc.frequency.linearRampToValueAtTime(100, now + 0.15);
        gain.gain.setValueAtTime(0.1, now);
        gain.gain.linearRampToValueAtTime(0, now + 0.15);
        osc.start(now);
        osc.stop(now + 0.15);
    }
    else if (type === 'click') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, now);
        gain.gain.setValueAtTime(0.05, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
        osc.start(now);
        osc.stop(now + 0.05);
    }
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI',
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Entity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
}

export interface GameState {
  entities: Map<string, Entity>;
  effects: Effect[];
  soundEvents: string[]; // Queue of sound events to play
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
  };
  selection: string[]; // IDs of selected entities
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  speed: number;
  attackSpeed: number; // Frames between attacks
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: type === EntityType.MINERAL ? 1500 : 0,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

export const initGame = (): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---

  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, {x:200, y:1800}) < 400) continue;
          if (getDistance({x,y}, {x:1800, y:200}) < 400) continue;

          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  generateCluster(EntityType.MOUNTAIN, 20, GAME_WIDTH/2, GAME_HEIGHT/2, 300);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.25, GAME_HEIGHT * 0.25, 200);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.75, GAME_HEIGHT * 0.75, 200);

  for(let i=0; i<3; i++) {
      generateCluster(EntityType.MOUNTAIN, 8, Math.random() * GAME_WIDTH, Math.random() * GAME_HEIGHT, 150);
  }


  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  // Player Workers
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    // Auto Mine for starting workers
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }
  // Player Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  // Auto-set Player Base Rally
  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  // AI Workers
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    // AI Auto Mine
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }
  // AI Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  return {
    entities,
    effects,
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: 1400 },
    gameTime: 0,
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const minDist = entity.radius + other.radius;

    if (dist < minDist && dist > 0) {
      const push = (minDist - dist);
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const pushFactor = isStatic ? 1.0 : 0.5;

      entity.position.x += Math.cos(angle) * push * pushFactor * 0.2; 
      entity.position.y += Math.sin(angle) * push * pushFactor * 0.2;
    }
  });
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  const soundEvents: string[] = [];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;

    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) {
           entity.constructionProgress = 100;
           // Building complete sound?
       }
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // --- RALLY POINT LOGIC ---
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING';
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                 }
             } else if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    if (entity.state === 'IDLE') {
        if (stats.damage > 0) {
            let target: Entity | null = null;
            let minDist = stats.range + 50; 

            entities.forEach(e => {
                if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
                    const d = getDistance(entity.position, e.position);
                    if (d < minDist) {
                        minDist = d;
                        target = e;
                    }
                }
            });

            if (target) {
                entity.targetId = (target as Entity).id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 5) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        if (!target || target.hp <= 0) {
           if (entity.targetPosition) {
             entity.state = 'MOVING'; 
           } else {
             entity.state = 'IDLE';
           }
           entity.targetId = null;
        } else {
           const dist = getDistance(entity.position, target.position);
           if (dist <= stats.range) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  entity.cooldown = stats.attackSpeed;
                  // Fire sound could be added here, but might spam
                  if (target.state === 'IDLE' && STATS[target.type].damage > 0) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            const newRes = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
            if (newRes) {
                entity.targetId = newRes.id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            const dist = getDistance(entity.position, target.position);
            if (dist <= 10) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id);
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            if (dist < base.radius + entity.radius + 5) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        const effectType = (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) ? 'BLOOD' : 'EXPLOSION';
        const effectScale = entity.radius / 10;
        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: 30,
            maxLife: 30,
            scale: effectScale
        });
        soundEvents.push('explosion'); // Trigger explosion sound
        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- SIMPLE AI ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) playerBuildings++;
      if (e.owner === Owner.AI && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  if (workers.length < 12 && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  if (barracks.length < 3 && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  if (army.length > 10) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      const targetPos = enemyBase ? enemyBase.position : { x: 200, y: 1800 }; 

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2 } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity } from '../services/gameLogic';
import { playSound } from '../services/audio';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State via Refs
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                          playSound('train');
                      } else {
                          playSound('error');
                      }
                  } else {
                      playSound('error');
                  }
              }
          }

          if (detail.action === 'SET_RALLY') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent) {
                  ent.rallyPoint = detail.pos;
                  ent.rallyTargetId = detail.targetId;
                  playSound('click');
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => keysPressed.current.add(e.code);
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, []);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Rally Point Line (if selected building)
      if (state.selection.includes(entity.id) && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.save();
          // Draw line from building to rally point
          ctx.strokeStyle = '#fbbf24'; // Yellow
          ctx.setLineDash([5, 5]);
          ctx.beginPath();
          ctx.moveTo(0, 0); // Local 0,0 is entity center
          // Need to transform back to global for lineTo, or just subtract entity pos
          ctx.lineTo(entity.rallyPoint.x - entity.position.x, entity.rallyPoint.y - entity.position.y);
          ctx.stroke();
          ctx.restore();
      }

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; 
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else if (entity.type === EntityType.MOUNTAIN) {
        ctx.fillStyle = '#4b5563'; 
        ctx.beginPath();
        ctx.moveTo(0, -40); 
        ctx.lineTo(30, -10); ctx.lineTo(20, 20); ctx.lineTo(40, 40);
        ctx.lineTo(0, 30); ctx.lineTo(-30, 40); ctx.lineTo(-40, 10); ctx.lineTo(-20, -20);
        ctx.fill();
        ctx.fillStyle = '#6b7280';
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(15, 0); ctx.lineTo(-5, 5);
        ctx.fill();
      } else if (entity.type === EntityType.WATER) {
        // Water Effect
        ctx.fillStyle = '#1e3a8a';
        ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0,0, 25, 0, Math.PI*2); ctx.stroke();
        // Simple Wave
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath(); 
        ctx.moveTo(-15, 0); ctx.quadraticCurveTo(0, -10, 15, 0);
        ctx.stroke();
      } else {
        // Color based on owner
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20); // Door
          // Roof design
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            // Tools
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Gun
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        // Construction/Production Bar
        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        // Train Queue Indicators
        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines (Lasers)
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // --- DRAW EFFECTS ---
    state.effects.forEach(fx => {
        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; // 1.0 down to 0.0

        if (fx.type === 'EXPLOSION') {
            const r = (1 - lifePct) * 40 * fx.scale;
            ctx.globalAlpha = lifePct;
            ctx.fillStyle = '#fff7ed'; 
            ctx.beginPath(); ctx.arc(0,0, r * 0.5, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#ea580c'; 
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = '#57534e';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.arc(0,0, r * 1.2, 0, Math.PI*2); ctx.stroke();
        } else if (fx.type === 'BLOOD') {
            ctx.fillStyle = '#991b1b'; 
            ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.arc(0,0, 10, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5,5, 6, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-5,-2, 4, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Selection Box Drawing
    if (mouseDownStateRef.current) {
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;

        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(
            startWorld.x, 
            startWorld.y, 
            currentWorldPos.x - startWorld.x, 
            currentWorldPos.y - startWorld.y
        );
        ctx.setLineDash([]);
    }

    // Ghost Building Placement
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];

       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);

       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    ctx.restore();
  };

  const loop = () => {
    if (!gameStateRef.current.victory) {
        gameStateRef.current = updateGame(gameStateRef.current);

        // Consume Sound Events
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }

    const mousePos = mousePosRef.current;

    // Smooth camera pan (Edge Panning)
    const panSpeed = 15;
    const margin = 20;

    // Keyboard Pan - Removed WASD, only Arrows
    const keySpeed = 20;
    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---

  const handleMouseDown = (e: React.MouseEvent) => {
    // Middle Mouse Button Pan
    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { // Right Click
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { // Left Click
      if (commandMode) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
             playSound('build');
          } else {
              playSound('error');
          }
          return;
      }

      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
      // playSound('click'); // Maybe too noisy
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { 
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 15;
             });

             // Check if selection contains buildings -> Set Rally Point
             const hasBuildingsSelected = gameStateRef.current.selection.some(id => {
                 const ent = gameStateRef.current.entities.get(id);
                 return ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS);
             });

             if (hasBuildingsSelected) {
                  // Set Rally Point
                  gameStateRef.current.selection.forEach(id => {
                      const ent = gameStateRef.current.entities.get(id);
                      if (ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS)) {
                          window.dispatchEvent(new CustomEvent('GAME_COMMAND', {
                              detail: { 
                                  action: 'SET_RALLY', 
                                  id: ent.id, 
                                  pos, 
                                  targetId: clickedEntity ? clickedEntity.id : null 
                              }
                          }));
                      }
                  });
             } else {
                 // Move Units
                 playSound('click');
                 gameStateRef.current.selection.forEach(id => {
                    const unit = gameStateRef.current.entities.get(id);
                    if (unit && unit.owner === Owner.PLAYER) {
                       if (clickedEntity) {
                           if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                               unit.state = 'GATHERING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                           }
                       } else {
                           unit.state = 'MOVING';
                           unit.targetPosition = pos;
                           unit.targetId = null;
                       }
                    }
                 });
             }
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);

         const isClick = (screenDiffX < 5 && screenDiffY < 5);

         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];

         gameStateRef.current.entities.forEach(ent => {
             if (ent.type === EntityType.MOUNTAIN || ent.type === EntityType.WATER) return; // Cannot select terrain
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { 
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick) playSound('click');

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className="cursor-crosshair block"
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Entity, EntityType, GameState, Owner } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { toggleMute, getMuteState } from '../services/audio';

interface Props {
  gameState: GameState;
  selectedEntities: Entity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];
  const [isMuted, setIsMuted] = useState(getMuteState());

  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);
  const canBuild = allWorkers && selectedEntities.length === 1;

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const key = e.key.toUpperCase();

        if ((e.target as HTMLElement).tagName === 'INPUT') return;

        if (singleSelection) {
            // Base Shortcuts
            if (singleSelection.type === EntityType.BASE) {
                if (key === 'W') onTrain(EntityType.WORKER);
            }
            // Barracks Shortcuts
            if (singleSelection.type === EntityType.BARRACKS) {
                if (key === 'M') onTrain(EntityType.MARINE);
            }
            // Worker Shortcuts
            if (singleSelection.type === EntityType.WORKER) {
                if (key === 'B') onCommand(`BUILD_${EntityType.BARRACKS}`);
                if (key === 'S') onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`);
            }
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [singleSelection, onTrain, onCommand]);


  // --- Minimap Logic ---
  const [isDraggingMinimap, setIsDraggingMinimap] = useState(false);
  const minimapRef = useRef<HTMLDivElement>(null);

  const updateCameraFromMinimap = (clientX: number, clientY: number) => {
      if (!minimapRef.current) return;
      const rect = minimapRef.current.getBoundingClientRect();
      const xPct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const yPct = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));

      const targetX = xPct * GAME_WIDTH;
      const targetY = yPct * GAME_HEIGHT;

      const centerX = targetX - (window.innerWidth / 2);
      const centerY = targetY - (window.innerHeight / 2);

      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
      }));
  };

  const handleMinimapMouseDown = (e: React.MouseEvent) => {
      setIsDraggingMinimap(true);
      updateCameraFromMinimap(e.clientX, e.clientY);
  };

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (isDraggingMinimap) {
              updateCameraFromMinimap(e.clientX, e.clientY);
          }
      };
      const handleMouseUp = () => {
          setIsDraggingMinimap(false);
      };

      if (isDraggingMinimap) {
          window.addEventListener('mousemove', handleMouseMove);
          window.addEventListener('mouseup', handleMouseUp);
      }
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
      };
  }, [isDraggingMinimap]);


  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between">
      {/* Top Bar */}
      <div className="bg-gray-900 bg-opacity-90 text-white p-2 flex gap-8 border-b border-gray-700 pointer-events-auto select-none items-center">
         <div className="font-bold text-yellow-400">Minerals: {Math.floor(resources)}</div>
         <div className={supply.used > supply.max ? "text-red-500" : "text-green-400"}>
             Supply: {supply.used}/{supply.max}
         </div>
         <div className="text-gray-400">Time: {Math.floor(gameState.gameTime / 60)}s</div>
         <button 
            className="px-2 py-1 bg-gray-700 rounded text-xs hover:bg-gray-600"
            onClick={() => setIsMuted(toggleMute())}
         >
             {isMuted ? 'Unmute Sound' : 'Mute Sound'}
         </button>
         {gameState.victory && (
             <div className="ml-auto font-bold text-2xl text-yellow-500 animate-pulse">
                 {gameState.victory === Owner.PLAYER ? "VICTORY!" : "DEFEAT"}
             </div>
         )}
      </div>

      {/* Bottom Panel */}
      <div className="h-48 bg-gray-900 border-t border-gray-700 flex pointer-events-auto select-none">
          {/* Minimap */}
          <div 
              ref={minimapRef}
              className="w-48 bg-black border-r border-gray-700 relative overflow-hidden cursor-move"
              onMouseDown={handleMinimapMouseDown}
          >
             {/* Map Features */}
             {(Array.from(gameState.entities.values()) as Entity[]).map(e => {
                 let color = 'bg-gray-500';
                 if (e.type === EntityType.WATER) color = 'bg-blue-800';
                 else if (e.type === EntityType.MOUNTAIN) color = 'bg-gray-700';
                 else if (e.type === EntityType.MINERAL) color = 'bg-teal-500';
                 else if (e.owner === Owner.PLAYER) color = 'bg-blue-500';
                 else if (e.owner === Owner.AI) color = 'bg-red-500';

                 const size = (e.type === EntityType.WATER || e.type === EntityType.MOUNTAIN) ? 4 : 2;

                 return (
                    <div key={e.id} 
                        className={`absolute rounded-full ${color}`}
                        style={{ 
                            left: `${(e.position.x / GAME_WIDTH) * 100}%`, 
                            top: `${(e.position.y / GAME_HEIGHT) * 100}%`,
                            width: size + 'px', height: size + 'px'
                        }} 
                    />
                 );
             })}

             {/* Camera Rect */}
             <div className="absolute border border-white pointer-events-none"
                  style={{
                      left: `${(gameState.camera.x / GAME_WIDTH) * 100}%`,
                      top: `${(gameState.camera.y / GAME_HEIGHT) * 100}%`,
                      width: `${(window.innerWidth / GAME_WIDTH) * 100}%`,
                      height: `${(window.innerHeight / GAME_HEIGHT) * 100}%`,
                  }}
             />
          </div>

          {/* Unit Info */}
          <div className="flex-1 p-4 border-r border-gray-700 flex flex-wrap gap-2 overflow-auto">
             {selectedEntities.length === 0 && <span className="text-gray-500">No selection</span>}
             {selectedEntities.length > 0 && selectedEntities.length < 12 && selectedEntities.map(e => (
                 <div key={e.id} className="w-16 h-16 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-xs text-white">
                     <div className={`w-3 h-3 rounded-full mb-1 ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                     <span>{e.type}</span>
                     <div className="w-full h-1 bg-red-900 mt-1">
                         <div className="h-full bg-green-500" style={{ width: `${(e.hp / e.maxHp) * 100}%`}} />
                     </div>
                 </div>
             ))}
             {selectedEntities.length >= 12 && (
                 <div className="text-white p-4">
                     Selected: {selectedEntities.length} Units
                 </div>
             )}
          </div>

          {/* Command Card */}
          <div className="w-64 bg-gray-800 p-2 grid grid-cols-3 gap-2">
              {/* Build Commands */}
              {canBuild && (
                  <>
                    <CommandButton 
                        label="Depot (100)" 
                        hotkey="S" 
                        cost={100} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} 
                    />
                    <CommandButton 
                        label="Barracks (150)" 
                        hotkey="B" 
                        cost={150} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} 
                    />
                  </>
              )}

              {/* Train Commands */}
              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Worker (50)" 
                      hotkey="W" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.WORKER].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {singleSelection?.type === EntityType.BARRACKS && (
                  <CommandButton 
                      label="Marine (50)" 
                      hotkey="M" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.MARINE)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.MARINE].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
          </div>
      </div>
    </div>
  );
};

const CommandButton = ({ label, hotkey, cost, currentResources, onClick, progress, maxProgress, queue }: any) => {
    const disabled = currentResources < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`relative bg-gray-700 border border-gray-500 text-white text-xs p-1 hover:bg-gray-600 active:bg-gray-500 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center justify-center h-20`}
        >
            <span className="font-bold text-yellow-300 mb-1">{hotkey}</span>
            <span className="text-center">{label}</span>
            {queue > 0 && <span className="absolute top-0 right-0 bg-blue-600 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center">{queue}</span>}
            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-black">
                    <div className="h-full bg-white" style={{ width: `${(progress / maxProgress) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: type === EntityType.MINERAL ? 1500 : 0,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

export const initGame = (): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---

  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, {x:200, y:1800}) < 400) continue;
          if (getDistance({x,y}, {x:1800, y:200}) < 400) continue;

          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  generateCluster(EntityType.MOUNTAIN, 20, GAME_WIDTH/2, GAME_HEIGHT/2, 300);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.25, GAME_HEIGHT * 0.25, 200);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.75, GAME_HEIGHT * 0.75, 200);

  for(let i=0; i<3; i++) {
      generateCluster(EntityType.MOUNTAIN, 8, Math.random() * GAME_WIDTH, Math.random() * GAME_HEIGHT, 150);
  }


  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };

  // 1. Create Minerals FIRST so workers can find them
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  // 2. Create Base
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);

  // 3. Create Workers
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    // Auto Mine for starting workers
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }

  // Auto-set Player Base Rally
  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };

  // 1. AI Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }

  // 2. AI Base
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));

  // 3. AI Workers
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    // AI Auto Mine
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }

  return {
    entities,
    effects,
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: 1400 },
    gameTime: 0,
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const minDist = entity.radius + other.radius;

    if (dist < minDist && dist > 0) {
      const push = (minDist - dist);
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const pushFactor = isStatic ? 1.0 : 0.5;

      entity.position.x += Math.cos(angle) * push * pushFactor * 0.2; 
      entity.position.y += Math.sin(angle) * push * pushFactor * 0.2;
    }
  });
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  const soundEvents: string[] = [];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;

    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) {
           entity.constructionProgress = 100;
       }
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // --- RALLY POINT LOGIC ---
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING';
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                 }
             } else if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    if (entity.state === 'IDLE') {
        if (stats.damage > 0 && entity.type !== EntityType.WORKER) { // Prevent workers from auto-attacking
            let target: Entity | null = null;
            let minDist = stats.range + 50; 

            entities.forEach(e => {
                if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
                    const d = getDistance(entity.position, e.position);
                    if (d < minDist) {
                        minDist = d;
                        target = e;
                    }
                }
            });

            if (target) {
                entity.targetId = (target as Entity).id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 5) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        if (!target || target.hp <= 0) {
           if (entity.targetPosition) {
             entity.state = 'MOVING'; 
           } else {
             entity.state = 'IDLE';
           }
           entity.targetId = null;
        } else {
           const dist = getDistance(entity.position, target.position);
           if (dist <= stats.range) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  entity.cooldown = stats.attackSpeed;

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            const newRes = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
            if (newRes) {
                entity.targetId = newRes.id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            const dist = getDistance(entity.position, target.position);
            if (dist <= 10) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id);
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            if (dist < base.radius + entity.radius + 5) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        const effectType = (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) ? 'BLOOD' : 'EXPLOSION';
        const effectScale = entity.radius / 10;
        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: 30,
            maxLife: 30,
            scale: effectScale
        });
        soundEvents.push('explosion');
        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- SIMPLE AI ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) playerBuildings++;
      if (e.owner === Owner.AI && (e.type === EntityType.BASE || e.type === EntityType.BARRACKS)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  if (workers.length < 12 && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  if (barracks.length < 3 && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  if (army.length > 10) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      const targetPos = enemyBase ? enemyBase.position : { x: 200, y: 1800 }; 

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: type === EntityType.MINERAL ? 1500 : 0,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

export const initGame = (): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---
  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, {x:200, y:1800}) < 400) continue;
          if (getDistance({x,y}, {x:1800, y:200}) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  generateCluster(EntityType.MOUNTAIN, 20, GAME_WIDTH/2, GAME_HEIGHT/2, 300);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.25, GAME_HEIGHT * 0.25, 200);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.75, GAME_HEIGHT * 0.75, 200);

  for(let i=0; i<3; i++) {
      generateCluster(EntityType.MOUNTAIN, 8, Math.random() * GAME_WIDTH, Math.random() * GAME_HEIGHT, 150);
  }

  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };

  // 1. Minerals
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  // 2. Base
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  // 3. Workers
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }

  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }

  // Camera Centering on Player Base
  // Base at 200, 1800. 
  // We want to center it. If window size is WxH.
  // CameraX = 200 - W/2, CameraY = 1800 - H/2.
  // We don't have window size here easily, but we can approximate or rely on the caller to adjust, 
  // but standard 1080p -> H=900ish available? 
  // 1800 - 450 = 1350. 
  // Let's safe clamp.
  const startCameraY = Math.max(0, 1800 - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));

  return {
    entities,
    effects,
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: startCameraY },
    gameTime: 0,
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const minDist = entity.radius + other.radius;

    if (dist < minDist && dist > 0) {
      const push = (minDist - dist);
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const pushFactor = isStatic ? 1.0 : 0.5;

      entity.position.x += Math.cos(angle) * push * pushFactor * 0.2; 
      entity.position.y += Math.sin(angle) * push * pushFactor * 0.2;
    }
  });
};

const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT;

