const CommandButton = ({ label, hotkey, cost, currentResources, onClick, progress, maxProgress, queue }: any) => {
    const disabled = currentResources < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`relative bg-gray-700 border border-gray-500 text-white text-xs p-1 hover:bg-gray-600 active:bg-gray-500 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center justify-center h-20 shadow-sm transition-colors`}
        >
            <span className="font-bold text-yellow-300 mb-1">{hotkey}</span>
            <span className="text-center leading-tight">{label}</span>
            {queue > 0 && <span className="absolute top-0 right-0 bg-blue-600 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center shadow">{queue}</span>}
            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-black">
                    <div className="h-full bg-white transition-all duration-75" style={{ width: `${(progress / maxProgress) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, Notification } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  // 10,000 minerals total per base. 8 patches per base. 1250 per patch.
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, Entity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---
  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, {x:200, y:1800}) < 400) continue;
          if (getDistance({x,y}, {x:1800, y:200}) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  generateCluster(EntityType.MOUNTAIN, 20, GAME_WIDTH/2, GAME_HEIGHT/2, 300);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.25, GAME_HEIGHT * 0.25, 200);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.75, GAME_HEIGHT * 0.75, 200);

  for(let i=0; i<3; i++) {
      generateCluster(EntityType.MOUNTAIN, 8, Math.random() * GAME_WIDTH, Math.random() * GAME_HEIGHT, 150);
  }

  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };

  // 1. Minerals (8 patches)
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  // 2. Base
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  // 3. Workers
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }

  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }

  const startCameraY = Math.max(0, 1800 - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: startCameraY },
    gameTime: 0,
    difficulty
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; // Extra spacing for natural look

    // Separation Force (Soft Collision)
    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      // Stronger push if actual overlap, softer if just "too close"
      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; // Bounce harder off static objects

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT;

const acquireTarget = (entity: Entity, entities: Map<string, Entity>) => {
    const stats = STATS[entity.type];
    let bestTarget: Entity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;

                // Priority 1: Retaliate against someone attacking me
                if (e.targetId === entity.id) score += 5000;

                // Priority 2: Protect Base (if I'm near my base)
                // (Simplified: just attacking anyone nearby)

                // Priority 3: Units > Buildings
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; // Buildings have positive score so they ARE targeted

                // Priority 4: Distance (Close is better)
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const addNotification = (state: GameState, text: string) => {
    // Avoid duplicate spam
    if (!state.notifications.some(n => n.text === text && n.life > 60)) {
        state.notifications.push({
            id: `not_${Math.random()}`,
            text,
            life: 120 // 2 seconds
        });
    }
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Handle Rally
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE)) {
                         newUnit.state = 'ATTACKING'; // Attack Move
                     }
                 }
             } else if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
             if (entity.owner === Owner.PLAYER && state.gameTime % 60 === 0) {
                 addNotification(state, "Supply Capped!");
             }
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    // --- AUTO TARGET ACQUISITION (IDLE) ---
    if (entity.state === 'IDLE') {
        if (stats.damage > 0 && entity.type !== EntityType.WORKER) { 
            const target = acquireTarget(entity, entities);
            if (target) {
                entity.targetId = target.id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // Retaliation Check (If I'm being attacked, switch to attacker)
        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner) {
                // If I am currently attacking a building, or just moving, switch to attacker
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            // Clear flag after checking
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        // Target Dead or Invalid
        if (!target || target.hp <= 0) {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                // Attack Move Logic
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        // Engage Target
        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; // Account for target size so we don't walk INSIDE it

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; // Mark for retaliation
                  entity.cooldown = stats.attackSpeed;

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              // Chase
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;

        // Validate target
        if (!target || target.resourceAmount! <= 0) {
            // Find new mineral
            let newRes: Entity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     // Check if patch is full (max 3 workers)
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });

            if (newRes) {
                entity.targetId = (newRes as Entity).id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            // Check if too many workers on this patch, if so, look for another
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 // Try to find a better one
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }

            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; // increased margin to ensure connection
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id); // Mineral Depleted
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');
        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- MARKERS UPDATE ---
  newMarkers = newMarkers.filter(mk => {
      mk.life--;
      return mk.life > 0;
  });

  // --- NOTIFICATIONS UPDATE ---
  newNotifications = newNotifications.filter(n => {
      n.life--;
      return n.life > 0;
  });

  // --- AI LOGIC ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if (e.owner === Owner.AI && isBuilding(e.type)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  // Difficulty Multipliers
  let maxWorkers = 12;
  let attackThreshold = 10;
  let expansionAggression = false;

  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = 8;
      attackThreshold = 15;
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = 16;
      attackThreshold = 8;
      expansionAggression = true;
  }

  // 1. Train Workers
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  // 2. Manage Workers
  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // 3. Build Supply
  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  // 4. Build Barracks
  if (barracks.length < (state.difficulty === Difficulty.HARD ? 5 : 3) && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  // 5. Train Army
  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  // 6. Attack Logic
  if (army.length > attackThreshold) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      // Fallback: any enemy unit
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER);

      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             // Attack Move to base
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI',
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export enum Difficulty {
    EASY = 'EASY',
    MEDIUM = 'MEDIUM',
    HARD = 'HARD'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD' | 'BUILDING_EXPLOSION';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Marker {
  id: string;
  position: Vector2;
  type: 'MOVE' | 'ATTACK';
  life: number;
  maxLife: number;
}

export interface Notification {
    id: string;
    text: string;
    life: number;
}

export interface Entity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
  lastAttackerId?: string | null; // For retaliation
}

export interface GameState {
  entities: Map<string, Entity>;
  effects: Effect[];
  markers: Marker[];
  notifications: Notification[];
  soundEvents: string[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
  };
  selection: string[];
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
  difficulty: Difficulty;
  paused: boolean;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  speed: number;
  attackSpeed: number;
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, Notification } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  // 10,000 minerals total per base. 8 patches per base. 1250 per patch.
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, Entity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---
  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, {x:200, y:1800}) < 400) continue;
          if (getDistance({x,y}, {x:1800, y:200}) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  generateCluster(EntityType.MOUNTAIN, 20, GAME_WIDTH/2, GAME_HEIGHT/2, 300);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.25, GAME_HEIGHT * 0.25, 200);
  generateCluster(EntityType.WATER, 15, GAME_WIDTH * 0.75, GAME_HEIGHT * 0.75, 200);

  for(let i=0; i<3; i++) {
      generateCluster(EntityType.MOUNTAIN, 8, Math.random() * GAME_WIDTH, Math.random() * GAME_HEIGHT, 150);
  }

  // Player Start (Bottom Left)
  const playerBasePos = { x: 200, y: 1800 };

  // 1. Minerals (8 patches)
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x - 150 * Math.cos(angle), 
      y: playerBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  // 2. Base
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  // 3. Workers
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }

  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // AI Start (Top Right)
  const aiBasePos = { x: 1800, y: 200 };
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI + Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x - 150 * Math.cos(angle), 
      y: aiBasePos.y - 150 * Math.sin(angle) 
    }));
  }
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }

  const startCameraY = Math.max(0, 1800 - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: 0, y: startCameraY },
    gameTime: 0,
    difficulty,
    paused: false
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; // Extra spacing for natural look

    // Separation Force (Soft Collision)
    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      // Stronger push if actual overlap, softer if just "too close"
      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; // Bounce harder off static objects

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT;

const acquireTarget = (entity: Entity, entities: Map<string, Entity>) => {
    const stats = STATS[entity.type];
    let bestTarget: Entity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;

                // Priority 1: Retaliate against someone attacking me
                if (e.targetId === entity.id) score += 5000;

                // Priority 2: Protect Base (if I'm near my base)
                // (Simplified: just attacking anyone nearby)

                // Priority 3: Units > Buildings
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; // Buildings have positive score so they ARE targeted

                // Priority 4: Distance (Close is better)
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const addNotification = (state: GameState, text: string) => {
    // Avoid duplicate spam
    if (!state.notifications.some(n => n.text === text && n.life > 60)) {
        state.notifications.push({
            id: `not_${Math.random()}`,
            text,
            life: 120 // 2 seconds
        });
    }
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Handle Rally
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE)) {
                         newUnit.state = 'ATTACKING'; // Attack Move
                     }
                 }
             } else if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
             if (entity.owner === Owner.PLAYER && state.gameTime % 60 === 0) {
                 addNotification(state, "Supply Capped!");
             }
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    // --- AUTO TARGET ACQUISITION (IDLE) ---
    if (entity.state === 'IDLE') {
        if (stats.damage > 0 && entity.type !== EntityType.WORKER) { 
            const target = acquireTarget(entity, entities);
            if (target) {
                entity.targetId = target.id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // Retaliation Check (If I'm being attacked, switch to attacker)
        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner) {
                // If I am currently attacking a building, or just moving, switch to attacker
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            // Clear flag after checking
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        // Target Dead or Invalid
        if (!target || target.hp <= 0) {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                // Attack Move Logic
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        // Engage Target
        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; // Account for target size so we don't walk INSIDE it

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; // Mark for retaliation
                  entity.cooldown = stats.attackSpeed;

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              // Chase
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;

        // Validate target
        if (!target || target.resourceAmount! <= 0) {
            // Find new mineral
            let newRes: Entity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     // Check if patch is full (max 3 workers)
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });

            if (newRes) {
                entity.targetId = (newRes as Entity).id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            // Check if too many workers on this patch, if so, look for another
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 // Try to find a better one
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }

            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; // increased margin to ensure connection
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id); // Mineral Depleted
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');
        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- MARKERS UPDATE ---
  newMarkers = newMarkers.filter(mk => {
      mk.life--;
      return mk.life > 0;
  });

  // --- NOTIFICATIONS UPDATE ---
  newNotifications = newNotifications.filter(n => {
      n.life--;
      return n.life > 0;
  });

  // --- AI LOGIC ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if (e.owner === Owner.AI && isBuilding(e.type)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  // Difficulty Multipliers
  let maxWorkers = 12;
  let attackThreshold = 10;
  let expansionAggression = false;

  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = 8;
      attackThreshold = 15;
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = 16;
      attackThreshold = 8;
      expansionAggression = true;
  }

  // 1. Train Workers
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  // 2. Manage Workers
  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // 3. Build Supply
  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  // 4. Build Barracks
  if (barracks.length < (state.difficulty === Difficulty.HARD ? 5 : 3) && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  // 5. Train Army
  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  // 6. Attack Logic
  if (army.length > attackThreshold) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      // Fallback: any enemy unit
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER);

      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             // Attack Move to base
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Input State via Refs
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'RESTART') {
              gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
              // Force update to reset UI immediately
              onGameStateUpdate({ ...gameStateRef.current });
              return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); // Update UI immediately
              return;
          }

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                          playSound('train');
                      } else {
                          playSound('error');
                      }
                  } else {
                      addNotification(gameStateRef.current, "Not Enough Minerals!");
                      playSound('error');
                  }
              }
          }

          if (detail.action === 'SET_RALLY') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent) {
                  ent.rallyPoint = detail.pos;
                  ent.rallyTargetId = detail.targetId;
                  playSound('click');
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);

          const key = e.key.toUpperCase();
          if ((e.target as HTMLElement).tagName === 'INPUT') return;

          // Attack Move Shortcut
          if (key === 'A') {
              const hasAttackers = gameStateRef.current.selection.some(id => {
                  const ent = gameStateRef.current.entities.get(id);
                  return ent && ent.owner === Owner.PLAYER && STATS[ent.type].damage > 0;
              });
              if (hasAttackers) {
                  setCommandMode('ATTACK');
              }
          }

          // Pause Shortcut
          if (key === 'P') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current });
          }

          // Shortcuts
          if (key === '1') {
              const workers = Array.from(gameStateRef.current.entities.values()).filter(ent => 
                  ent.owner === Owner.PLAYER && ent.type === EntityType.WORKER
              );
              let target = workers.find(w => w.state === 'IDLE');
              if (!target) target = workers.find(w => w.state === 'GATHERING');
              if (!target && workers.length > 0) target = workers[0];

              if (target) {
                  gameStateRef.current.selection = [target.id];
                  onSelectionChange([target]);
                  playSound('click');
              }
          }
          if (key === '2') {
              const marines = Array.from(gameStateRef.current.entities.values()).filter(ent => 
                  ent.owner === Owner.PLAYER && ent.type === EntityType.MARINE
              );
              if (marines.length > 0) {
                  gameStateRef.current.selection = marines.map(m => m.id);
                  onSelectionChange(marines);
                  playSound('click');
              }
          }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, [onSelectionChange, setCommandMode]);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#4ade80'; // Green
             ctx.lineWidth = 2;
             const r = 15 * (0.5 + lifePct * 0.5); // Contract
             ctx.beginPath();
             for(let i=0; i<4; i++) {
                 ctx.rotate(Math.PI/2);
                 ctx.moveTo(0, -r); ctx.lineTo(4, -r-4); ctx.moveTo(0, -r); ctx.lineTo(-4, -r-4);
             }
             ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; // Red
             ctx.lineWidth = 2;
             ctx.beginPath();
             const r = 10;
             ctx.moveTo(-r, -r); ctx.lineTo(r, r);
             ctx.moveTo(r, -r); ctx.lineTo(-r, r);
             ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    state.entities.forEach(entity => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Rally Point
      if (state.selection.includes(entity.id) && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.save();
          ctx.strokeStyle = '#fbbf24'; 
          ctx.setLineDash([5, 5]);
          ctx.beginPath();
          ctx.moveTo(0, 0); 
          ctx.lineTo(entity.rallyPoint.x - entity.position.x, entity.rallyPoint.y - entity.position.y);
          ctx.stroke();
          ctx.restore();
      }

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body Drawing
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; 
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else if (entity.type === EntityType.MOUNTAIN) {
        ctx.fillStyle = '#4b5563'; 
        ctx.beginPath();
        ctx.moveTo(0, -40); 
        ctx.lineTo(30, -10); ctx.lineTo(20, 20); ctx.lineTo(40, 40);
        ctx.lineTo(0, 30); ctx.lineTo(-30, 40); ctx.lineTo(-40, 10); ctx.lineTo(-20, -20);
        ctx.fill();
        ctx.fillStyle = '#6b7280';
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(15, 0); ctx.lineTo(-5, 5);
        ctx.fill();
      } else if (entity.type === EntityType.WATER) {
        ctx.fillStyle = '#1e3a8a';
        ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0,0, 25, 0, Math.PI*2); ctx.stroke();
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath(); 
        ctx.moveTo(-15, 0); ctx.quadraticCurveTo(0, -10, 15, 0);
        ctx.stroke();
      } else {
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20);
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // --- DRAW EFFECTS ---
    state.effects.forEach(fx => {
        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; // 1.0 down to 0.0

        if (fx.type === 'EXPLOSION') {
            const r = (1 - lifePct) * 40 * fx.scale;
            ctx.globalAlpha = lifePct;
            ctx.fillStyle = '#fff7ed'; 
            ctx.beginPath(); ctx.arc(0,0, r * 0.5, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#ea580c'; 
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'BUILDING_EXPLOSION') {
             // More complex explosion
             const r = (1 - lifePct) * 80;
             ctx.globalAlpha = lifePct;
             ctx.fillStyle = '#fef08a';
             ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();

             for(let i=0; i<5; i++) {
                 const offsetAngle = (i/5) * Math.PI*2 + state.gameTime * 0.1;
                 const ex = Math.cos(offsetAngle) * r * 0.5;
                 const ey = Math.sin(offsetAngle) * r * 0.5;
                 ctx.fillStyle = i % 2 === 0 ? '#ef4444' : '#f97316';
                 ctx.beginPath(); ctx.arc(ex, ey, r*0.6, 0, Math.PI*2); ctx.fill();
             }
        } else if (fx.type === 'BLOOD') {
            ctx.fillStyle = '#991b1b'; 
            ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.arc(0,0, 10, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5,5, 6, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Selection Box
    if (mouseDownStateRef.current) {
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(startWorld.x, startWorld.y, currentWorldPos.x - startWorld.x, currentWorldPos.y - startWorld.y);
        ctx.setLineDash([]);
    }

    // Ghost Building
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];
       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    // Pause Overlay
    if (state.paused) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0); // Reset transform
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white';
        ctx.font = 'bold 48px sans-serif';
        ctx.textAlign = 'center';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 10;
        ctx.fillText('PAUSED', width / 2, height / 2);
        ctx.restore();
    }

    // Notifications (Screen Space)
    ctx.restore(); // Undo Camera transform for HUD-like elements
    if (state.notifications.length > 0) {
        ctx.save();
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#f87171';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;

        state.notifications.forEach((n, i) => {
            const y = height - 250 - (i * 30);
            const alpha = Math.min(1, n.life / 30);
            ctx.globalAlpha = alpha;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.restore();
    }

  };

  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }

    const mousePos = mousePosRef.current;

    // Edge Panning
    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---
  const handleMouseDown = (e: React.MouseEvent) => {
    if (gameStateRef.current.paused) return; // Ignore inputs when paused

    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { 
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { 
      if (commandMode === 'ATTACK') {
          const pos = getWorldPos(e.clientX, e.clientY);
          const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
             const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
             return dist < ent.radius + 15;
          });

          gameStateRef.current.selection.forEach(id => {
              const unit = gameStateRef.current.entities.get(id);
              if (unit && unit.owner === Owner.PLAYER) {
                  unit.state = 'ATTACKING';
                  unit.targetPosition = pos; // Default Attack Move to ground
                  unit.targetId = null;

                  if (clickedEntity && clickedEntity.owner !== Owner.PLAYER) {
                      unit.targetId = clickedEntity.id;
                      unit.targetPosition = null;
                  }

                  // Marker
                  gameStateRef.current.markers.push({
                      id: `mk_${Math.random()}`,
                      position: clickedEntity ? clickedEntity.position : pos,
                      type: 'ATTACK',
                      life: 20, maxLife: 20
                  });
              }
          });
          setCommandMode(null);
          playSound('click');
          return;
      }

      if (commandMode && commandMode.startsWith('BUILD_')) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
             playSound('build');
          } else {
              addNotification(gameStateRef.current, "Not Enough Minerals!");
              playSound('error');
          }
          return;
      }

      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    if (gameStateRef.current.paused) return;

    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;

     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { 
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const clickedEntity = (Array.from(gameStateRef.current.entities.values()) as Entity[]).find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 return dist < ent.radius + 15;
             });

             const hasBuildingsSelected = gameStateRef.current.selection.some(id => {
                 const ent = gameStateRef.current.entities.get(id);
                 return ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS);
             });

             if (hasBuildingsSelected) {
                  gameStateRef.current.selection.forEach(id => {
                      const ent = gameStateRef.current.entities.get(id);
                      if (ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS)) {
                          window.dispatchEvent(new CustomEvent('GAME_COMMAND', {
                              detail: { action: 'SET_RALLY', id: ent.id, pos, targetId: clickedEntity ? clickedEntity.id : null }
                          }));
                      }
                  });
             } else {
                 playSound('click');
                 gameStateRef.current.selection.forEach(id => {
                    const unit = gameStateRef.current.entities.get(id);
                    if (unit && unit.owner === Owner.PLAYER) {
                       if (clickedEntity) {
                           if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                               unit.state = 'GATHERING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'MOVE', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'ATTACK', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'ATTACK', life: 20, maxLife: 20 });
                           }
                       } else {
                           unit.state = 'MOVING';
                           unit.targetPosition = pos;
                           unit.targetId = null;
                           gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...pos }, type: 'MOVE', life: 20, maxLife: 20 });
                       }
                    }
                 });
             }
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);
         const isClick = (screenDiffX < 5 && screenDiffY < 5);
         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];
         gameStateRef.current.entities.forEach(ent => {
             if (ent.type === EntityType.MOUNTAIN || ent.type === EntityType.WATER) return; 
             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { 
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick) playSound('click');

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Entity, EntityType, GameState, Owner, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { toggleMute, getMuteState } from '../services/audio';

interface Props {
  gameState: GameState;
  selectedEntities: Entity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];
  const [isMuted, setIsMuted] = useState(getMuteState());
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Selection Logic
  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);
  const canBuild = allWorkers && selectedEntities.length === 1; // Only 1 worker can build at a time to keep UI simple

  // Group Selection logic
  const allBarracks = selectedEntities.filter(e => e.type === EntityType.BARRACKS && e.owner === Owner.PLAYER);
  const showBarracksMenu = singleSelection?.type === EntityType.BARRACKS || allBarracks.length > 0;

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const key = e.key.toUpperCase();
        if ((e.target as HTMLElement).tagName === 'INPUT') return;

        if (singleSelection?.type === EntityType.BASE) {
            if (key === 'W') onTrain(EntityType.WORKER);
        }

        if (showBarracksMenu) {
            if (key === 'M') handleMultiTrain(EntityType.MARINE);
        }

        if (singleSelection?.type === EntityType.WORKER) {
            if (key === 'B') onCommand(`BUILD_${EntityType.BARRACKS}`);
            if (key === 'S') onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`);
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [singleSelection, showBarracksMenu, onTrain, onCommand]);

  // Close menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setMenuOpen(false);
      }
    };
    if (menuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [menuOpen]);

  const handleMultiTrain = (type: EntityType) => {
      if (allBarracks.length > 0) {
          const bestBarracks = [...allBarracks].sort((a, b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'TRAIN', id: bestBarracks.id, type } 
          }));
      } else if (singleSelection) {
          onTrain(type);
      }
  };

  const handleRestart = () => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'RESTART', difficulty: gameState.difficulty } 
      }));
  };

  const changeDifficulty = (diff: Difficulty) => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'RESTART', difficulty: diff } 
      }));
  };

  const togglePause = () => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'TOGGLE_PAUSE' } 
      }));
  };

  const handleToggleMute = () => {
      setIsMuted(toggleMute());
  };

  // --- Minimap Logic ---
  const [isDraggingMinimap, setIsDraggingMinimap] = useState(false);
  const minimapRef = useRef<HTMLDivElement>(null);

  const updateCameraFromMinimap = (clientX: number, clientY: number) => {
      if (!minimapRef.current) return;
      const rect = minimapRef.current.getBoundingClientRect();
      const xPct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const yPct = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));

      const targetX = xPct * GAME_WIDTH;
      const targetY = yPct * GAME_HEIGHT;

      const centerX = targetX - (window.innerWidth / 2);
      const centerY = targetY - (window.innerHeight / 2);

      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
      }));
  };

  const handleMinimapMouseDown = (e: React.MouseEvent) => {
      setIsDraggingMinimap(true);
      updateCameraFromMinimap(e.clientX, e.clientY);
  };

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (isDraggingMinimap) {
              updateCameraFromMinimap(e.clientX, e.clientY);
          }
      };
      const handleMouseUp = () => {
          setIsDraggingMinimap(false);
      };

      if (isDraggingMinimap) {
          window.addEventListener('mousemove', handleMouseMove);
          window.addEventListener('mouseup', handleMouseUp);
      }
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
      };
  }, [isDraggingMinimap]);


  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between">
      {/* Top Bar */}
      <div className="bg-gray-900 bg-opacity-90 text-white p-2 flex gap-4 border-b border-gray-700 pointer-events-auto select-none items-center shadow-md justify-between px-4">
         <div className="flex gap-4">
             <div className="font-bold text-yellow-400">Minerals: {Math.floor(resources)}</div>
             <div className={supply.used > supply.max ? "text-red-500 font-bold" : "text-green-400"}>
                 Supply: {supply.used}/{supply.max}
             </div>
             <div className="text-gray-400 text-sm">Time: {Math.floor(gameState.gameTime / 60)}s</div>
         </div>

         {/* Menu Button */}
         <div className="relative" ref={menuRef}>
            <button 
                onClick={() => setMenuOpen(!menuOpen)}
                className="px-4 py-1 bg-gray-700 hover:bg-gray-600 rounded border border-gray-500 font-bold text-sm"
            >
                MENU
            </button>

            {menuOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-gray-800 border border-gray-600 rounded shadow-xl flex flex-col p-2 gap-2 z-50">
                    <button 
                        onClick={togglePause} 
                        className="text-left px-3 py-2 bg-gray-700 hover:bg-blue-600 rounded text-sm font-semibold"
                    >
                        {gameState.paused ? 'RESUME' : 'PAUSE'} (P)
                    </button>

                    <div className="border-t border-gray-600 my-1"></div>

                    <div className="text-xs text-gray-400 px-1 mb-1">Difficulty (Restarts Game)</div>
                    <div className="flex gap-1 mb-2">
                        {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map(d => (
                            <button 
                                key={d}
                                className={`flex-1 py-1 text-[10px] rounded border ${gameState.difficulty === d ? 'bg-blue-600 border-blue-400' : 'bg-gray-700 border-gray-600 hover:bg-gray-600'}`}
                                onClick={() => changeDifficulty(d)}
                            >
                                {d}
                            </button>
                        ))}
                    </div>

                    <button 
                        onClick={handleToggleMute} 
                        className="text-left px-3 py-2 bg-gray-700 hover:bg-gray-600 rounded text-sm"
                    >
                        Sound: {isMuted ? 'OFF' : 'ON'}
                    </button>

                    <div className="border-t border-gray-600 my-1"></div>

                    <button 
                        onClick={handleRestart} 
                        className="text-left px-3 py-2 bg-red-900 hover:bg-red-700 border border-red-800 rounded text-sm font-bold"
                    >
                        RESTART GAME
                    </button>
                </div>
            )}
         </div>
      </div>

      {/* Victory Screen Overlay */}
      {gameState.victory && (
         <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-70 z-50 pointer-events-auto">
             <div className="bg-gray-800 p-8 rounded-lg border-2 border-yellow-500 text-center shadow-2xl">
                 <h1 className="text-4xl font-bold text-yellow-500 mb-4">
                     {gameState.victory === Owner.PLAYER ? "VICTORY!" : "DEFEAT"}
                 </h1>
                 <button 
                    className="px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded"
                    onClick={handleRestart}
                 >
                     PLAY AGAIN
                 </button>
             </div>
         </div>
      )}

      {/* Bottom Panel */}
      <div className="h-48 bg-gray-900 border-t border-gray-700 flex pointer-events-auto select-none shadow-lg">
          {/* Minimap */}
          <div 
              ref={minimapRef}
              className="w-48 bg-black border-r border-gray-700 relative overflow-hidden cursor-move"
              onMouseDown={handleMinimapMouseDown}
          >
             {/* Map Features */}
             {(Array.from(gameState.entities.values()) as Entity[]).map(e => {
                 let color = 'bg-gray-500';
                 if (e.type === EntityType.WATER) color = 'bg-blue-800';
                 else if (e.type === EntityType.MOUNTAIN) color = 'bg-gray-700';
                 else if (e.type === EntityType.MINERAL) {
                     // Check if depleted
                     color = e.resourceAmount! > 0 ? 'bg-teal-500' : 'bg-gray-800';
                 }
                 else if (e.owner === Owner.PLAYER) color = 'bg-blue-500';
                 else if (e.owner === Owner.AI) color = 'bg-red-500';

                 const size = (e.type === EntityType.WATER || e.type === EntityType.MOUNTAIN) ? 4 : 2;

                 if (e.type === EntityType.MINERAL && e.resourceAmount! <= 0) return null;

                 return (
                    <div key={e.id} 
                        className={`absolute rounded-full ${color}`}
                        style={{ 
                            left: `${(e.position.x / GAME_WIDTH) * 100}%`, 
                            top: `${(e.position.y / GAME_HEIGHT) * 100}%`,
                            width: size + 'px', height: size + 'px'
                        }} 
                    />
                 );
             })}

             {/* Camera Rect */}
             <div className="absolute border border-white pointer-events-none"
                  style={{
                      left: `${(gameState.camera.x / GAME_WIDTH) * 100}%`,
                      top: `${(gameState.camera.y / GAME_HEIGHT) * 100}%`,
                      width: `${(window.innerWidth / GAME_WIDTH) * 100}%`,
                      height: `${(window.innerHeight / GAME_HEIGHT) * 100}%`,
                  }}
             />
          </div>

          {/* Unit Info */}
          <div className="flex-1 p-4 border-r border-gray-700 flex flex-wrap gap-2 overflow-auto content-start">
             {selectedEntities.length === 0 && <span className="text-gray-500 italic">No selection</span>}

             {/* Barracks Group View */}
             {allBarracks.length > 1 && selectedEntities.length === allBarracks.length ? (
                 <div className="flex flex-wrap gap-2">
                     {allBarracks.map(b => (
                         <div key={b.id} className="w-16 h-16 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-xs text-white relative">
                             <span>Barracks</span>
                             {b.trainQueue && b.trainQueue.length > 0 && (
                                 <div className="absolute top-1 right-1 text-blue-400 font-bold">{b.trainQueue.length}</div>
                             )}
                             <div className="w-full h-1 bg-gray-900 mt-2">
                                <div className="h-full bg-white" style={{ width: `${(b.trainProgress! / STATS[EntityType.MARINE].buildTime) * 100}%` }} />
                             </div>
                         </div>
                     ))}
                 </div>
             ) : (
                selectedEntities.length > 0 && selectedEntities.length < 18 && selectedEntities.map(e => (
                    <div key={e.id} className="w-12 h-12 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-[10px] text-white overflow-hidden">
                        <div className={`w-2 h-2 rounded-full mb-1 ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                        <span className="truncate w-full text-center">{e.type}</span>
                        <div className="w-full h-1 bg-red-900 mt-1">
                            <div className="h-full bg-green-500" style={{ width: `${(e.hp / e.maxHp) * 100}%`}} />
                        </div>
                    </div>
                ))
             )}

             {selectedEntities.length >= 18 && (
                 <div className="text-white p-4 font-bold text-lg">
                     Selected: {selectedEntities.length} Units
                 </div>
             )}
          </div>

          {/* Command Card */}
          <div className="w-64 bg-gray-800 p-2 grid grid-cols-3 gap-2">
              {/* Build Commands */}
              {canBuild && (
                  <>
                    <CommandButton 
                        label="Depot (100)" 
                        hotkey="S" 
                        cost={100} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} 
                    />
                    <CommandButton 
                        label="Barracks (150)" 
                        hotkey="B" 
                        cost={150} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} 
                    />
                  </>
              )}

              {/* Train Commands */}
              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Worker (50)" 
                      hotkey="W" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.WORKER].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {showBarracksMenu && (
                  <CommandButton 
                      label="Marine (50)" 
                      hotkey="M" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => handleMultiTrain(EntityType.MARINE)} 
                      // If multiple selected, progress bar is a bit ambiguous, just show generic
                      progress={singleSelection ? singleSelection.trainProgress : 0}
                      maxProgress={STATS[EntityType.MARINE].buildTime}
                      queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
              )}
          </div>
      </div>
    </div>
  );
};

const CommandButton = ({ label, hotkey, cost, currentResources, onClick, progress, maxProgress, queue }: any) => {
    const disabled = currentResources < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`relative bg-gray-700 border border-gray-500 text-white text-xs p-1 hover:bg-gray-600 active:bg-gray-500 disabled:opacity-50 disabled:cursor-not-allowed flex flex-col items-center justify-center h-20 shadow-sm transition-colors`}
        >
            <span className="font-bold text-yellow-300 mb-1">{hotkey}</span>
            <span className="text-center leading-tight">{label}</span>
            {queue > 0 && <span className="absolute top-0 right-0 bg-blue-600 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center shadow">{queue}</span>}
            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-black">
                    <div className="h-full bg-white transition-all duration-75" style={{ width: `${(progress / maxProgress) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI',
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export enum Difficulty {
    EASY = 'EASY',
    MEDIUM = 'MEDIUM',
    HARD = 'HARD'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD' | 'BUILDING_EXPLOSION';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Marker {
  id: string;
  position: Vector2;
  type: 'MOVE' | 'ATTACK';
  life: number;
  maxLife: number;
}

export interface Notification {
    id: string;
    text: string;
    life: number;
}

export interface Entity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
  lastAttackerId?: string | null; // For retaliation
}

export interface GameState {
  entities: Map<string, Entity>;
  effects: Effect[];
  markers: Marker[];
  notifications: Notification[];
  soundEvents: string[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
  };
  selection: string[];
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
  difficulty: Difficulty;
  paused: boolean;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  vision: number;
  speed: number;
  attackSpeed: number;
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, Notification } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  // 10,000 minerals total per base. 8 patches per base. 1250 per patch.
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, Entity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---
  // Player Start (Bottom Leftish)
  // Randomize start slightly
  const playerBaseX = 150 + Math.random() * 100;
  const playerBaseY = GAME_HEIGHT - (150 + Math.random() * 100);
  const playerBasePos = { x: playerBaseX, y: playerBaseY };

  // AI Start (Top Rightish)
  const aiBaseX = GAME_WIDTH - (150 + Math.random() * 100);
  const aiBaseY = 150 + Math.random() * 100;
  const aiBasePos = { x: aiBaseX, y: aiBaseY };

  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          // Keep away from bases
          if (getDistance({x,y}, playerBasePos) < 500) continue;
          if (getDistance({x,y}, aiBasePos) < 500) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  // Randomized Terrain
  const numMountainClusters = 10 + Math.floor(Math.random() * 15);
  for(let i=0; i<numMountainClusters; i++) {
      generateCluster(
          EntityType.MOUNTAIN, 
          5 + Math.floor(Math.random() * 10), 
          Math.random() * GAME_WIDTH, 
          Math.random() * GAME_HEIGHT, 
          100 + Math.random() * 100
      );
  }

  const numWaterClusters = 5 + Math.floor(Math.random() * 8);
  for(let i=0; i<numWaterClusters; i++) {
      generateCluster(
          EntityType.WATER, 
          5 + Math.floor(Math.random() * 10), 
          Math.random() * GAME_WIDTH, 
          Math.random() * GAME_HEIGHT, 
          100 + Math.random() * 100
      );
  }

  // Expansion Minerals (Randomly placed away from bases)
  const numExpansions = 4 + Math.floor(Math.random() * 4);
  for(let i=0; i<numExpansions; i++) {
      let exX = Math.random() * (GAME_WIDTH - 200) + 100;
      let exY = Math.random() * (GAME_HEIGHT - 200) + 100;

      // Ensure not too close to bases
      if (getDistance({x:exX, y:exY}, playerBasePos) > 600 && getDistance({x:exX, y:exY}, aiBasePos) > 600) {
          generateCluster(EntityType.MINERAL, 6, exX, exY, 80);
      }
  }

  // --- PLAYER SETUP ---
  // 1. Minerals (8 patches in semicircle towards center)
  // Calculate angle towards center map to face minerals that way
  const pCenterAngle = Math.atan2((GAME_HEIGHT/2) - playerBasePos.y, (GAME_WIDTH/2) - playerBasePos.x);

  for (let i = 0; i < 8; i++) {
    const angle = pCenterAngle - (Math.PI/2) + (i / 7) * Math.PI; // Semicircle
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x + 200 * Math.cos(angle), 
      y: playerBasePos.y + 200 * Math.sin(angle) 
    }));
  }
  // 2. Base
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  // 3. Workers
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }

  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // --- AI SETUP ---
  const aiCenterAngle = Math.atan2((GAME_HEIGHT/2) - aiBasePos.y, (GAME_WIDTH/2) - aiBasePos.x);
  for (let i = 0; i < 8; i++) {
    const angle = aiCenterAngle - (Math.PI/2) + (i / 7) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x + 200 * Math.cos(angle), 
      y: aiBasePos.y + 200 * Math.sin(angle) 
    }));
  }
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }

  const startCameraY = Math.max(0, playerBasePos.y - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));
  const startCameraX = Math.max(0, playerBasePos.x - (typeof window !== 'undefined' ? window.innerWidth / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: startCameraX, y: startCameraY },
    gameTime: 0,
    difficulty,
    paused: false
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; // Extra spacing for natural look

    // Separation Force (Soft Collision)
    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      // Stronger push if actual overlap, softer if just "too close"
      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; // Bounce harder off static objects

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT;

const acquireTarget = (entity: Entity, entities: Map<string, Entity>) => {
    const stats = STATS[entity.type];
    let bestTarget: Entity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;

                // Priority 1: Retaliate against someone attacking me
                if (e.targetId === entity.id) score += 5000;

                // Priority 2: Protect Base (if I'm near my base)
                // (Simplified: just attacking anyone nearby)

                // Priority 3: Units > Buildings
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; // Buildings have positive score so they ARE targeted

                // Priority 4: Distance (Close is better)
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const addNotification = (state: GameState, text: string) => {
    // Avoid duplicate spam
    if (!state.notifications.some(n => n.text === text && n.life > 60)) {
        state.notifications.push({
            id: `not_${Math.random()}`,
            text,
            life: 120 // 2 seconds
        });
    }
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Handle Rally
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE)) {
                         newUnit.state = 'ATTACKING'; // Attack Move
                     }
                 }
             } else if (entity.owner === Owner.AI && unitType === EntityType.MARINE) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
             if (entity.owner === Owner.PLAYER && state.gameTime % 60 === 0) {
                 addNotification(state, "Supply Capped!");
             }
          }
       }
    }

    // 3. Action Logic
    const stats = STATS[entity.type];

    // --- AUTO TARGET ACQUISITION (IDLE) ---
    if (entity.state === 'IDLE') {
        if (stats.damage > 0 && entity.type !== EntityType.WORKER) { 
            const target = acquireTarget(entity, entities);
            if (target) {
                entity.targetId = target.id;
                entity.state = 'ATTACKING';
            }
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // Retaliation Check (If I'm being attacked, switch to attacker)
        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner) {
                // If I am currently attacking a building, or just moving, switch to attacker
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            // Clear flag after checking
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        // Target Dead or Invalid
        if (!target || target.hp <= 0) {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                // Attack Move Logic
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        // Engage Target
        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; // Account for target size so we don't walk INSIDE it

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; // Mark for retaliation
                  entity.cooldown = stats.attackSpeed;

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              // Chase
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
        const target = entity.targetId ? entities.get(entity.targetId) : null;

        // Validate target
        if (!target || target.resourceAmount! <= 0) {
            // Find new mineral
            let newRes: Entity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     // Check if patch is full (max 3 workers)
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });

            if (newRes) {
                entity.targetId = (newRes as Entity).id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            // Check if too many workers on this patch, if so, look for another
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 // Try to find a better one
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }

            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; // increased margin to ensure connection
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id); // Mineral Depleted
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (entity.type === EntityType.MARINE || entity.type === EntityType.WORKER) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');
        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- MARKERS UPDATE ---
  newMarkers = newMarkers.filter(mk => {
      mk.life--;
      return mk.life > 0;
  });

  // --- NOTIFICATIONS UPDATE ---
  newNotifications = newNotifications.filter(n => {
      n.life--;
      return n.life > 0;
  });

  // --- AI LOGIC ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if (e.owner === Owner.AI && isBuilding(e.type)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  // Difficulty Multipliers
  let maxWorkers = 12;
  let attackThreshold = 10;
  let expansionAggression = false;

  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = 8;
      attackThreshold = 15;
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = 16;
      attackThreshold = 8;
      expansionAggression = true;
  }

  // 1. Train Workers
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  // 2. Manage Workers
  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // 3. Build Supply
  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  // 4. Build Barracks
  if (barracks.length < (state.difficulty === Difficulty.HARD ? 5 : 3) && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  // 5. Train Army
  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              b.trainQueue.push(EntityType.MARINE);
              resources[Owner.AI] -= 50;
          }
      });
  }

  // 6. Attack Logic
  if (army.length > attackThreshold) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      // Fallback: any enemy unit
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER);

      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING') {
             // Attack Move to base
             unit.state = 'ATTACKING';
             unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Fog of War Canvases (Offscreen)
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  // Input State via Refs
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Initialize offscreen canvases
  useEffect(() => {
      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;
  }, []);

  // Reset Fog on Restart
  useEffect(() => {
      if (gameStateRef.current.gameTime === 0 && exploredCanvasRef.current) {
          const ctx = exploredCanvasRef.current.getContext('2d');
          if (ctx) {
             ctx.globalCompositeOperation = 'source-over';
             ctx.fillStyle = 'black';
             ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
          }
      }
  }, [gameStateRef.current.gameTime]); // Dependencies might be tricky with ref mutation, handled in loop

  // Helper to check visibility
  const isEntityVisible = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      // Simple optimization: check if close to any player unit's vision
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'RESTART') {
              gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
              // Reset explored canvas
              if (exploredCanvasRef.current) {
                  const ctx = exploredCanvasRef.current.getContext('2d');
                  if (ctx) {
                     ctx.globalCompositeOperation = 'source-over';
                     ctx.fillStyle = 'black';
                     ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                  }
              }
              onGameStateUpdate({ ...gameStateRef.current });
              return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); // Update UI immediately
              return;
          }

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                          playSound('train');
                      } else {
                          playSound('error');
                      }
                  } else {
                      addNotification(gameStateRef.current, "Not Enough Minerals!");
                      playSound('error');
                  }
              }
          }

          if (detail.action === 'SET_RALLY') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent) {
                  ent.rallyPoint = detail.pos;
                  ent.rallyTargetId = detail.targetId;
                  playSound('click');
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);

          const key = e.key.toUpperCase();
          if ((e.target as HTMLElement).tagName === 'INPUT') return;

          // Attack Move Shortcut
          if (key === 'A') {
              const hasAttackers = gameStateRef.current.selection.some(id => {
                  const ent = gameStateRef.current.entities.get(id);
                  return ent && ent.owner === Owner.PLAYER && STATS[ent.type].damage > 0;
              });
              if (hasAttackers) {
                  setCommandMode('ATTACK');
              }
          }

          // Pause Shortcut
          if (key === 'P') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current });
          }

          // Shortcuts
          if (key === '1') {
              const workers = Array.from(gameStateRef.current.entities.values()).filter(ent => 
                  ent.owner === Owner.PLAYER && ent.type === EntityType.WORKER
              );
              let target = workers.find(w => w.state === 'IDLE');
              if (!target) target = workers.find(w => w.state === 'GATHERING');
              if (!target && workers.length > 0) target = workers[0];

              if (target) {
                  gameStateRef.current.selection = [target.id];
                  onSelectionChange([target]);
                  playSound('click');
              }
          }
          if (key === '2') {
              const marines = Array.from(gameStateRef.current.entities.values()).filter(ent => 
                  ent.owner === Owner.PLAYER && ent.type === EntityType.MARINE
              );
              if (marines.length > 0) {
                  gameStateRef.current.selection = marines.map(m => m.id);
                  onSelectionChange(marines);
                  playSound('click');
              }
          }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, [onSelectionChange, setCommandMode]);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Filter Visible Entities
    const allEntities = Array.from(state.entities.values());
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER);
    // Pre-calculate visibility for drawing
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG UPDATE (Offscreen) ---
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            // Update Explored
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            // Setup Current Vision
            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.6)'; // Dim for visited but not visible
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath();
                ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2);
                ctxExp.fill();

                ctxVis.beginPath();
                ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2);
                ctxVis.fill();
            });
        }
    }

    // --- DRAW WORLD ---
    // Clear
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // Draw Map Borders
    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#4ade80'; // Green
             ctx.lineWidth = 2;
             const r = 15 * (0.5 + lifePct * 0.5); // Contract
             ctx.beginPath();
             for(let i=0; i<4; i++) {
                 ctx.rotate(Math.PI/2);
                 ctx.moveTo(0, -r); ctx.lineTo(4, -r-4); ctx.moveTo(0, -r); ctx.lineTo(-4, -r-4);
             }
             ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; // Red
             ctx.lineWidth = 2;
             ctx.beginPath();
             const r = 10;
             ctx.moveTo(-r, -r); ctx.lineTo(r, r);
             ctx.moveTo(r, -r); ctx.lineTo(-r, r);
             ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    state.entities.forEach(entity => {
      // VISIBILITY CHECK
      if (!visibleEntities.has(entity.id)) return;

      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Rally Point
      if (state.selection.includes(entity.id) && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.save();
          ctx.strokeStyle = '#fbbf24'; 
          ctx.setLineDash([5, 5]);
          ctx.beginPath();
          ctx.moveTo(0, 0); 
          ctx.lineTo(entity.rallyPoint.x - entity.position.x, entity.rallyPoint.y - entity.position.y);
          ctx.stroke();
          ctx.restore();
      }

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body Drawing
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; 
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else if (entity.type === EntityType.MOUNTAIN) {
        ctx.fillStyle = '#4b5563'; 
        ctx.beginPath();
        ctx.moveTo(0, -40); 
        ctx.lineTo(30, -10); ctx.lineTo(20, 20); ctx.lineTo(40, 40);
        ctx.lineTo(0, 30); ctx.lineTo(-30, 40); ctx.lineTo(-40, 10); ctx.lineTo(-20, -20);
        ctx.fill();
        ctx.fillStyle = '#6b7280';
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(15, 0); ctx.lineTo(-5, 5);
        ctx.fill();
      } else if (entity.type === EntityType.WATER) {
        ctx.fillStyle = '#1e3a8a';
        ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0,0, 25, 0, Math.PI*2); ctx.stroke();
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath(); 
        ctx.moveTo(-15, 0); ctx.quadraticCurveTo(0, -10, 15, 0);
        ctx.stroke();
      } else {
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20);
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
    });

    // --- DRAW EFFECTS ---
    state.effects.forEach(fx => {
        // Effects visible if position is visible (simplified)
        // Optimization: check distance to player units
        let visible = false;
        // Fast check
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; // 1.0 down to 0.0

        if (fx.type === 'EXPLOSION') {
            const r = (1 - lifePct) * 40 * fx.scale;
            ctx.globalAlpha = lifePct;
            ctx.fillStyle = '#fff7ed'; 
            ctx.beginPath(); ctx.arc(0,0, r * 0.5, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#ea580c'; 
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'BUILDING_EXPLOSION') {
             const r = (1 - lifePct) * 80;
             ctx.globalAlpha = lifePct;
             ctx.fillStyle = '#fef08a';
             ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();

             for(let i=0; i<5; i++) {
                 const offsetAngle = (i/5) * Math.PI*2 + state.gameTime * 0.1;
                 const ex = Math.cos(offsetAngle) * r * 0.5;
                 const ey = Math.sin(offsetAngle) * r * 0.5;
                 ctx.fillStyle = i % 2 === 0 ? '#ef4444' : '#f97316';
                 ctx.beginPath(); ctx.arc(ex, ey, r*0.6, 0, Math.PI*2); ctx.fill();
             }
        } else if (fx.type === 'BLOOD') {
            ctx.fillStyle = '#991b1b'; 
            ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.arc(0,0, 10, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5,5, 6, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // --- DRAW FOG OVERLAY ---
    if (visionCanvasRef.current) ctx.drawImage(visionCanvasRef.current, 0, 0); // Dim non-visible areas
    if (exploredCanvasRef.current) ctx.drawImage(exploredCanvasRef.current, 0, 0); // Black out unexplored

    // Selection Box
    if (mouseDownStateRef.current) {
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(startWorld.x, startWorld.y, currentWorldPos.x - startWorld.x, currentWorldPos.y - startWorld.y);
        ctx.setLineDash([]);
    }

    // Ghost Building
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];
       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    // Pause Overlay
    if (state.paused) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0); // Reset transform
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white';
        ctx.font = 'bold 48px sans-serif';
        ctx.textAlign = 'center';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 10;
        ctx.fillText('PAUSED', width / 2, height / 2);
        ctx.restore();
    }

    // Notifications (Screen Space)
    ctx.restore(); // Undo Camera transform for HUD-like elements
    if (state.notifications.length > 0) {
        ctx.save();
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#f87171';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;

        state.notifications.forEach((n, i) => {
            const y = height - 250 - (i * 30);
            const alpha = Math.min(1, n.life / 30);
            ctx.globalAlpha = alpha;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.restore();
    }

  };

  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }

    const mousePos = mousePosRef.current;

    // Edge Panning
    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---
  const handleMouseDown = (e: React.MouseEvent) => {
    if (gameStateRef.current.paused) return; // Ignore inputs when paused

    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { 
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { 
      if (commandMode === 'ATTACK') {
          const pos = getWorldPos(e.clientX, e.clientY);
          // Check Visibility for interaction
          const allEntities = Array.from(gameStateRef.current.entities.values());
          const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER);

          const clickedEntity = allEntities.find(ent => {
             const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
             if (dist < ent.radius + 15) {
                 return isEntityVisible(ent, playerUnits);
             }
             return false;
          });

          gameStateRef.current.selection.forEach(id => {
              const unit = gameStateRef.current.entities.get(id);
              if (unit && unit.owner === Owner.PLAYER) {
                  unit.state = 'ATTACKING';
                  unit.targetPosition = pos; // Default Attack Move to ground
                  unit.targetId = null;

                  if (clickedEntity && clickedEntity.owner !== Owner.PLAYER) {
                      unit.targetId = clickedEntity.id;
                      unit.targetPosition = null;
                  }

                  // Marker
                  gameStateRef.current.markers.push({
                      id: `mk_${Math.random()}`,
                      position: clickedEntity ? clickedEntity.position : pos,
                      type: 'ATTACK',
                      life: 20, maxLife: 20
                  });
              }
          });
          setCommandMode(null);
          playSound('click');
          return;
      }

      if (commandMode && commandMode.startsWith('BUILD_')) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
             playSound('build');
          } else {
              addNotification(gameStateRef.current, "Not Enough Minerals!");
              playSound('error');
          }
          return;
      }

      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    if (gameStateRef.current.paused) return;

    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;

     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { 
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);

             // Check Visibility for Interaction
             const allEntities = Array.from(gameStateRef.current.entities.values());
             const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER);

             const clickedEntity = allEntities.find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 if (dist < ent.radius + 15) {
                     return isEntityVisible(ent, playerUnits);
                 }
                 return false;
             });

             const hasBuildingsSelected = gameStateRef.current.selection.some(id => {
                 const ent = gameStateRef.current.entities.get(id);
                 return ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS);
             });

             if (hasBuildingsSelected) {
                  gameStateRef.current.selection.forEach(id => {
                      const ent = gameStateRef.current.entities.get(id);
                      if (ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS)) {
                          window.dispatchEvent(new CustomEvent('GAME_COMMAND', {
                              detail: { action: 'SET_RALLY', id: ent.id, pos, targetId: clickedEntity ? clickedEntity.id : null }
                          }));
                      }
                  });
             } else {
                 playSound('click');
                 gameStateRef.current.selection.forEach(id => {
                    const unit = gameStateRef.current.entities.get(id);
                    if (unit && unit.owner === Owner.PLAYER) {
                       if (clickedEntity) {
                           if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                               unit.state = 'GATHERING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'MOVE', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.MARINE) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'ATTACK', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'ATTACK', life: 20, maxLife: 20 });
                           }
                       } else {
                           unit.state = 'MOVING';
                           unit.targetPosition = pos;
                           unit.targetId = null;
                           gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...pos }, type: 'MOVE', life: 20, maxLife: 20 });
                       }
                    }
                 });
             }
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);
         const isClick = (screenDiffX < 5 && screenDiffY < 5);
         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];

         // Only select Visible things (own units are always visible)
         const allEntities = Array.from(gameStateRef.current.entities.values());
         const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER);

         gameStateRef.current.entities.forEach(ent => {
             if (ent.type === EntityType.MOUNTAIN || ent.type === EntityType.WATER) return; 

             // Must be visible to be selected
             if (!isEntityVisible(ent, playerUnits)) return;

             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { 
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick) playSound('click');

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI',
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  MEDIC = 'MEDIC',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  BUNKER = 'BUNKER',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export enum Difficulty {
    EASY = 'EASY',
    MEDIUM = 'MEDIUM',
    HARD = 'HARD'
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD' | 'BUILDING_EXPLOSION' | 'HEAL';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Marker {
  id: string;
  position: Vector2;
  type: 'MOVE' | 'ATTACK' | 'LOAD';
  life: number;
  maxLife: number;
}

export interface Notification {
    id: string;
    text: string;
    life: number;
}

export interface Entity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING' | 'ENTERING' | 'GARRISONED' | 'HEALING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
  lastAttackerId?: string | null; // For retaliation
  garrison?: string[]; // IDs of units inside (for Bunker)
  containerId?: string | null; // ID of entity this unit is inside
}

export interface GameState {
  entities: Map<string, Entity>;
  effects: Effect[];
  markers: Marker[];
  notifications: Notification[];
  soundEvents: string[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
  };
  selection: string[];
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
  difficulty: Difficulty;
  paused: boolean;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  vision: number;
  speed: number;
  attackSpeed: number;
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
  healRate?: number; // For Medics
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { Entity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, Notification } from '../types';

let idCounter = 0;
export const generateId = () => `ent_${++idCounter}`;

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2): Entity => {
  const stats = STATS[type];
  // 10,000 minerals total per base. 8 patches per base. 1250 per patch.
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null,
    garrison: [],
    containerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, Entity>, type?: EntityType, owner?: Owner) => {
  let nearest: Entity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (e.state === 'GARRISONED') return;
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, Entity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

const isBio = (type: EntityType) => type === EntityType.WORKER || type === EntityType.MARINE || type === EntityType.MEDIC;
const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT || type === EntityType.BUNKER;

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM): GameState => {
  const entities = new Map<string, Entity>();
  const effects: Effect[] = [];

  const add = (e: Entity) => entities.set(e.id, e);

  // --- MAP GENERATION ---
  // Player Start (Bottom Leftish)
  // Randomize start slightly
  const playerBaseX = 150 + Math.random() * 100;
  const playerBaseY = GAME_HEIGHT - (150 + Math.random() * 100);
  const playerBasePos = { x: playerBaseX, y: playerBaseY };

  // AI Start (Top Rightish)
  const aiBaseX = GAME_WIDTH - (150 + Math.random() * 100);
  const aiBaseY = 150 + Math.random() * 100;
  const aiBasePos = { x: aiBaseX, y: aiBaseY };

  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = Math.random() * Math.PI * 2;
          const dist = Math.random() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          // Keep away from bases
          if (getDistance({x,y}, playerBasePos) < 500) continue;
          if (getDistance({x,y}, aiBasePos) < 500) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  // Randomized Terrain
  const numMountainClusters = 10 + Math.floor(Math.random() * 15);
  for(let i=0; i<numMountainClusters; i++) {
      generateCluster(
          EntityType.MOUNTAIN, 
          5 + Math.floor(Math.random() * 10), 
          Math.random() * GAME_WIDTH, 
          Math.random() * GAME_HEIGHT, 
          100 + Math.random() * 100
      );
  }

  const numWaterClusters = 5 + Math.floor(Math.random() * 8);
  for(let i=0; i<numWaterClusters; i++) {
      generateCluster(
          EntityType.WATER, 
          5 + Math.floor(Math.random() * 10), 
          Math.random() * GAME_WIDTH, 
          Math.random() * GAME_HEIGHT, 
          100 + Math.random() * 100
      );
  }

  // Expansion Minerals (Randomly placed away from bases)
  const numExpansions = 4 + Math.floor(Math.random() * 4);
  for(let i=0; i<numExpansions; i++) {
      let exX = Math.random() * (GAME_WIDTH - 200) + 100;
      let exY = Math.random() * (GAME_HEIGHT - 200) + 100;

      // Ensure not too close to bases
      if (getDistance({x:exX, y:exY}, playerBasePos) > 600 && getDistance({x:exX, y:exY}, aiBasePos) > 600) {
          generateCluster(EntityType.MINERAL, 6, exX, exY, 80);
      }
  }

  // --- PLAYER SETUP ---
  const pCenterAngle = Math.atan2((GAME_HEIGHT/2) - playerBasePos.y, (GAME_WIDTH/2) - playerBasePos.x);

  for (let i = 0; i < 8; i++) {
    const angle = pCenterAngle - (Math.PI/2) + (i / 7) * Math.PI; // Semicircle
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: playerBasePos.x + 200 * Math.cos(angle), 
      y: playerBasePos.y + 200 * Math.sin(angle) 
    }));
  }
  const pBase = createEntity(EntityType.BASE, Owner.PLAYER, playerBasePos);
  add(pBase);
  for (let i = 0; i < 4; i++) {
    const worker = createEntity(EntityType.WORKER, Owner.PLAYER, { x: playerBasePos.x + 60 + i * 20, y: playerBasePos.y - 80 });
    add(worker);
    const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (mineral) {
        worker.state = 'GATHERING';
        worker.targetId = mineral.id;
    }
  }
  const nearestMineral = findNearest(pBase.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
  if (nearestMineral) {
      pBase.rallyPoint = nearestMineral.position;
      pBase.rallyTargetId = nearestMineral.id;
  }

  // --- AI SETUP ---
  const aiCenterAngle = Math.atan2((GAME_HEIGHT/2) - aiBasePos.y, (GAME_WIDTH/2) - aiBasePos.x);
  for (let i = 0; i < 8; i++) {
    const angle = aiCenterAngle - (Math.PI/2) + (i / 7) * Math.PI; 
    add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
      x: aiBasePos.x + 200 * Math.cos(angle), 
      y: aiBasePos.y + 200 * Math.sin(angle) 
    }));
  }
  add(createEntity(EntityType.BASE, Owner.AI, aiBasePos));
  for (let i = 0; i < 4; i++) {
    const w = createEntity(EntityType.WORKER, Owner.AI, { x: aiBasePos.x - 60 - i * 20, y: aiBasePos.y + 80 });
    add(w);
    const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
    if (m) {
        w.state = 'GATHERING';
        w.targetId = m.id;
    }
  }

  const startCameraY = Math.max(0, playerBasePos.y - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));
  const startCameraX = Math.max(0, playerBasePos.x - (typeof window !== 'undefined' ? window.innerWidth / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 } 
    },
    selection: [],
    camera: { x: startCameraX, y: startCameraY },
    gameTime: 0,
    difficulty,
    paused: false
  };
};

const resolveCollisions = (entity: Entity, entities: Map<string, Entity>) => {
  if (entity.state === 'BUILDING' || entity.state === 'GARRISONED') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;
    if (other.state === 'GARRISONED') return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; 

    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; 

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const acquireTarget = (entity: Entity, entities: Map<string, Entity>) => {
    const stats = STATS[entity.type];
    let bestTarget: Entity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;

                // Priority 1: Retaliate against someone attacking me
                if (e.targetId === entity.id) score += 5000;

                // Priority 3: Units > Buildings
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; // Buildings have positive score so they ARE targeted

                // Priority 4: Distance (Close is better)
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const addNotification = (state: GameState, text: string) => {
    if (!state.notifications.some(n => n.text === text && n.life > 60)) {
        state.notifications.push({
            id: `not_${Math.random()}`,
            text,
            life: 120 
        });
    }
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  // Recalculate supply
  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    // Don't count garrisoned units for collisions but maybe for supply? Yes, they exist.
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 
    if (entity.state === 'GARRISONED') return; // Skip updating units inside bunkers

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 

             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Rally Logic
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                         // Attack move for soldiers, just move for medic usually but simpler to generic move
                         newUnit.state = unitType === EntityType.MEDIC ? 'MOVING' : 'ATTACKING'; 
                     }
                 }
             } else if (entity.owner === Owner.AI && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                newUnit.targetPosition = { x: GAME_WIDTH / 2, y: GAME_HEIGHT / 2 };
                newUnit.state = 'ATTACKING';
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
             if (entity.owner === Owner.PLAYER && state.gameTime % 60 === 0) {
                 addNotification(state, "Supply Capped!");
             }
          }
       }
    }

    const stats = STATS[entity.type];

    // --- BUNKER LOGIC ---
    if (entity.type === EntityType.BUNKER) {
        if (entity.garrison && entity.garrison.length > 0) {
            // Bunker acts as a turret if manned
            // Find target
            let target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp <= 0 || getDistance(entity.position, target.position) > stats.range) {
                target = acquireTarget(entity, entities);
                entity.targetId = target ? target.id : null;
            }

            if (target) {
                const dist = getDistance(entity.position, target.position);
                if (dist <= stats.range) {
                    if (entity.cooldown <= 0) {
                        // All marines inside shoot? Or just base bunker fire rate boosted?
                        // Simple: Bunker fires periodically based on number of marines
                        const marineStats = STATS[EntityType.MARINE];
                        // Damage = 1 Marine shot. Frequency increases with count.
                        // wait time = 30 / count
                        target.hp -= marineStats.damage;
                        entity.cooldown = Math.max(5, 30 / entity.garrison.length);

                        // FX?
                        if (target.hp <= 0) {
                           entity.targetId = null;
                        }
                    }
                }
            }
        }
    }

    // --- MEDIC LOGIC ---
    if (entity.type === EntityType.MEDIC) {
        if (entity.state === 'IDLE' || entity.state === 'MOVING' || entity.state === 'ATTACKING') {
            // Look for heal target
            let healTarget: Entity | null = null;
            let bestHealDist = stats.vision; // Look within vision

            entities.forEach(e => {
                if (e.owner === entity.owner && isBio(e.type) && e.hp < e.maxHp && e.state !== 'GARRISONED') {
                    const d = getDistance(entity.position, e.position);
                    if (d < bestHealDist) {
                        bestHealDist = d;
                        healTarget = e;
                    }
                }
            });

            if (healTarget) {
                const d = getDistance(entity.position, healTarget.position);
                if (d <= stats.range) {
                    entity.state = 'HEALING';
                    entity.targetId = healTarget.id;
                    entity.targetPosition = null; // Stop moving to heal
                } else {
                    // Move towards wounded
                    const angle = Math.atan2(healTarget.position.y - entity.position.y, healTarget.position.x - entity.position.x);
                    entity.position.x += Math.cos(angle) * stats.speed;
                    entity.position.y += Math.sin(angle) * stats.speed;
                }
            }
        }

        if (entity.state === 'HEALING') {
            const target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp >= target.maxHp || getDistance(entity.position, target.position) > stats.range + 20) {
                 entity.state = 'IDLE';
                 entity.targetId = null;
            } else {
                 if (entity.cooldown <= 0) {
                     target.hp = Math.min(target.maxHp, target.hp + (stats.healRate || 5));
                     entity.cooldown = stats.attackSpeed;
                     // Heal Effect
                     newEffects.push({
                        id: `fx_${Math.random()}`,
                        type: 'HEAL',
                        position: { ...target.position },
                        life: 20,
                        maxLife: 20,
                        scale: 1
                     });
                 }
            }
        }
    }

    // --- ENTERING BUNKER LOGIC ---
    if (entity.state === 'ENTERING' && entity.targetId) {
        const bunker = entities.get(entity.targetId);
        if (bunker && bunker.type === EntityType.BUNKER && bunker.hp > 0 && bunker.owner === entity.owner) {
             const dist = getDistance(entity.position, bunker.position);
             if (dist < bunker.radius + entity.radius + 10) {
                 if (!bunker.garrison) bunker.garrison = [];
                 if (bunker.garrison.length < 4) {
                     bunker.garrison.push(entity.id);
                     entity.state = 'GARRISONED';
                     entity.containerId = bunker.id;
                     entity.targetId = null;
                     entity.targetPosition = null;
                     playSound('click'); // Door sound?
                 } else {
                     entity.state = 'IDLE'; // Bunker full
                 }
             } else {
                 // Move to bunker
                 const angle = Math.atan2(bunker.position.y - entity.position.y, bunker.position.x - entity.position.x);
                 entity.position.x += Math.cos(angle) * stats.speed;
                 entity.position.y += Math.sin(angle) * stats.speed;
             }
        } else {
            entity.state = 'IDLE';
        }
    }

    // --- STANDARD ACTION LOGIC ---
    // (Only for non-garrisoned, non-entering units)

    // Auto Target
    if (entity.state === 'IDLE' && entity.type !== EntityType.MEDIC && entity.type !== EntityType.WORKER && stats.damage > 0) {
        const target = acquireTarget(entity, entities);
        if (target) {
            entity.targetId = target.id;
            entity.state = 'ATTACKING';
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner && attacker.state !== 'GARRISONED') {
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        if (!target || target.hp <= 0 || target.state === 'GARRISONED') {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; 

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; 
                  entity.cooldown = stats.attackSpeed;

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    // Gathering logic remains similar...
    if (entity.state === 'GATHERING') {
         const target = entity.targetId ? entities.get(entity.targetId) : null;

        // Validate target
        if (!target || target.resourceAmount! <= 0) {
            // Find new mineral
            let newRes: Entity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     // Check if patch is full (max 3 workers)
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });

            if (newRes) {
                entity.targetId = (newRes as Entity).id;
            } else {
                entity.state = 'IDLE';
            }
        } else {
            // Check if too many workers on this patch, if so, look for another
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 // Try to find a better one
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }

            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; 
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) {
                        newEntities.delete(target.id); // Mineral Depleted
                    }
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;

                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (isBio(entity.type)) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');

        // Eject Garrison
        if (entity.garrison && entity.garrison.length > 0) {
            entity.garrison.forEach(id => {
                const unit = newEntities.get(id);
                if (unit) {
                    unit.state = 'IDLE';
                    unit.containerId = null;
                    // Scatter slightly
                    unit.position = { 
                        x: entity.position.x + (Math.random() * 40 - 20), 
                        y: entity.position.y + (Math.random() * 40 - 20) 
                    };
                }
            });
        }

        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  // --- UNLOAD COMMAND HANDLING (Deferred state changes) ---
  // Commands are processed in GameCanvas, but if we need a loop check for unloading, we do it here.
  // Actually, we can handle "UNLOAD_ALL" command by simply iterating garrison in command handler or here.
  // Let's assume GameCanvas sets a flag or we handle it via state updates if needed.
  // But strictly, unit updates above handle movement. "UNLOAD" is an instant state change usually.

  // --- EFFECTS UPDATE ---
  newEffects = newEffects.filter(fx => {
      fx.life--;
      return fx.life > 0;
  });

  // --- MARKERS UPDATE ---
  newMarkers = newMarkers.filter(mk => {
      mk.life--;
      return mk.life > 0;
  });

  // --- NOTIFICATIONS UPDATE ---
  newNotifications = newNotifications.filter(n => {
      n.life--;
      return n.life > 0;
  });

  // --- AI LOGIC ---
  if (state.gameTime % 30 === 0) {
    runAI(state, newEntities, resources, supply);
  }

  // Check Victory
  let playerBuildings = 0;
  let aiBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if (e.owner === Owner.AI && isBuilding(e.type)) aiBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = Owner.AI; 
  if (aiBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, Entity>, resources: any, supply: any) => {
  const myUnits = Array.from(entities.values()).filter(e => e.owner === Owner.AI);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const army = myUnits.filter(e => e.type === EntityType.MARINE || e.type === EntityType.MEDIC);

  const myMinerals = resources[Owner.AI];
  const mySupply = supply[Owner.AI];

  let maxWorkers = 12;
  let attackThreshold = 10;

  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = 8;
      attackThreshold = 15;
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = 16;
      attackThreshold = 8;
  }

  // 1. Train Workers
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.find(b => !b.trainQueue || b.trainQueue.length < 1);
      if (base) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[Owner.AI] -= 50;
      }
  }

  // 2. Manage Workers
  workers.forEach(w => {
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // 3. Build Supply
  if (mySupply.max - mySupply.used <= 2 && myMinerals >= 100) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 100;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 200, y: basePos.y + (Math.random() - 0.5) * 200 };

          const depot = createEntity(EntityType.SUPPLY_DEPOT, Owner.AI, buildPos);
          depot.constructionProgress = 0;
          entities.set(depot.id, depot);
      }
  }

  // 4. Build Barracks
  if (barracks.length < (state.difficulty === Difficulty.HARD ? 5 : 3) && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
      if (builder) {
          resources[Owner.AI] -= 150;
          const basePos = bases[0]?.position || builder.position;
          const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };

          const b = createEntity(EntityType.BARRACKS, Owner.AI, buildPos);
          b.constructionProgress = 0;
          entities.set(b.id, b);
      }
  }

  // 5. Train Army (Marines and Medics)
  if (barracks.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if ((!b.trainQueue || b.trainQueue.length < 5) && resources[Owner.AI] >= 50 && b.constructionProgress! >= 100) {
              if (!b.trainQueue) b.trainQueue = [];
              // 1 in 4 chance for medic if Hard, else mostly marines
              const type = (Math.random() < 0.25 && resources[Owner.AI] >= 75) ? EntityType.MEDIC : EntityType.MARINE;
              const cost = STATS[type].cost;
              if (resources[Owner.AI] >= cost) {
                  b.trainQueue.push(type);
                  resources[Owner.AI] -= cost;
              }
          }
      });
  }

  // 6. Attack Logic
  if (army.length > attackThreshold) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === Owner.PLAYER);
      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state !== 'ATTACKING' && unit.state !== 'HEALING') {
             if (unit.type === EntityType.MEDIC) {
                 // Medics just move with army or idle to heal
                 // Simple AI: Medic follows nearest marine
                 if (unit.state === 'IDLE') {
                     const marine = army.find(a => a.type === EntityType.MARINE);
                     if (marine) {
                         unit.state = 'MOVING';
                         unit.targetPosition = marine.position;
                     }
                 }
             } else {
                 unit.state = 'ATTACKING';
                 unit.targetPosition = targetPos;
             }
          }
      });
  }
};

import React, { useEffect, useRef } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
}

export const GameCanvas: React.FC<Props> = ({ onGameStateUpdate, onSelectionChange, commandMode, setCommandMode }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame());
  const requestRef = useRef<number>(0);

  // Fog of War Canvases (Offscreen)
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  // Input State via Refs
  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  // Camera Controls State
  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false); // Middle mouse
  const isRightDragging = useRef(false);  // Right mouse
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  // Initialize offscreen canvases
  useEffect(() => {
      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;
  }, []);

  // Reset Fog on Restart
  useEffect(() => {
      if (gameStateRef.current.gameTime === 0 && exploredCanvasRef.current) {
          const ctx = exploredCanvasRef.current.getContext('2d');
          if (ctx) {
             ctx.globalCompositeOperation = 'source-over';
             ctx.fillStyle = 'black';
             ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
          }
      }
  }, [gameStateRef.current.gameTime]); 

  // Helper to check visibility
  const isEntityVisible = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // Command Listener
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail;

          if (detail.action === 'RESTART') {
              gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
              if (exploredCanvasRef.current) {
                  const ctx = exploredCanvasRef.current.getContext('2d');
                  if (ctx) {
                     ctx.globalCompositeOperation = 'source-over';
                     ctx.fillStyle = 'black';
                     ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                  }
              }
              onGameStateUpdate({ ...gameStateRef.current });
              return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA') {
              gameStateRef.current.camera = { 
                  x: Math.max(0, Math.min(detail.x, GAME_WIDTH - window.innerWidth)), 
                  y: Math.max(0, Math.min(detail.y, GAME_HEIGHT - window.innerHeight)) 
              };
              return;
          }

          if (detail.action === 'TRAIN') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.owner === Owner.PLAYER) {
                  const stats = STATS[detail.type as EntityType];
                  if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
                      if (!ent.trainQueue) ent.trainQueue = [];
                      if (ent.trainQueue.length < 5) {
                          ent.trainQueue.push(detail.type);
                          gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
                          playSound('train');
                      } else {
                          playSound('error');
                      }
                  } else {
                      addNotification(gameStateRef.current, "Not Enough Minerals!");
                      playSound('error');
                  }
              }
          }

          if (detail.action === 'UNLOAD_ALL') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent && ent.type === EntityType.BUNKER && ent.garrison) {
                  ent.garrison.forEach(unitId => {
                      const unit = gameStateRef.current.entities.get(unitId);
                      if (unit) {
                          unit.state = 'IDLE';
                          unit.containerId = null;
                          // Spawn around bunker
                          const angle = Math.random() * Math.PI * 2;
                          unit.position = {
                              x: ent.position.x + Math.cos(angle) * (ent.radius + 15),
                              y: ent.position.y + Math.sin(angle) * (ent.radius + 15)
                          };
                      }
                  });
                  ent.garrison = [];
                  playSound('click');
              }
          }

          if (detail.action === 'SET_RALLY') {
              const ent = gameStateRef.current.entities.get(detail.id);
              if (ent) {
                  ent.rallyPoint = detail.pos;
                  ent.rallyTargetId = detail.targetId;
                  playSound('click');
              }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, []);

  // Keyboard Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);

          const key = e.key.toUpperCase();
          if ((e.target as HTMLElement).tagName === 'INPUT') return;

          // Attack Move Shortcut
          if (key === 'A') {
              const hasAttackers = gameStateRef.current.selection.some(id => {
                  const ent = gameStateRef.current.entities.get(id);
                  return ent && ent.owner === Owner.PLAYER && STATS[ent.type].damage > 0;
              });
              if (hasAttackers) {
                  setCommandMode('ATTACK');
              }
          }

          // Pause Shortcut
          if (key === 'P') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current });
          }

          // Shortcuts
          if (key === '1') {
              const workers = Array.from(gameStateRef.current.entities.values()).filter(ent => 
                  ent.owner === Owner.PLAYER && ent.type === EntityType.WORKER
              );
              let target = workers.find(w => w.state === 'IDLE');
              if (!target) target = workers.find(w => w.state === 'GATHERING');
              if (!target && workers.length > 0) target = workers[0];

              if (target) {
                  gameStateRef.current.selection = [target.id];
                  onSelectionChange([target]);
                  playSound('click');
              }
          }
          if (key === '2') {
              const marines = Array.from(gameStateRef.current.entities.values()).filter(ent => 
                  ent.owner === Owner.PLAYER && ent.type === EntityType.MARINE
              );
              if (marines.length > 0) {
                  gameStateRef.current.selection = marines.map(m => m.id);
                  onSelectionChange(marines);
                  playSound('click');
              }
          }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => {
          window.removeEventListener('keydown', onKeyDown);
          window.removeEventListener('keyup', onKeyUp);
      };
  }, [onSelectionChange, setCommandMode]);

  const getWorldPos = (clientX: number, clientY: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const x = clientX - rect.left + gameStateRef.current.camera.x;
    const y = clientY - rect.top + gameStateRef.current.camera.y;
    return { x, y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    // Filter Visible Entities
    const allEntities = Array.from(state.entities.values());
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG UPDATE (Offscreen) ---
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            // Update Explored
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            // Setup Current Vision
            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.6)'; 
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath();
                ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2);
                ctxExp.fill();

                ctxVis.beginPath();
                ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2);
                ctxVis.fill();
            });
        }
    }

    // --- DRAW WORLD ---
    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    ctx.translate(-state.camera.x, -state.camera.y);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    ctx.strokeStyle = '#444';
    ctx.strokeRect(0,0, GAME_WIDTH, GAME_HEIGHT);

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#4ade80'; // Green
             ctx.lineWidth = 2;
             const r = 15 * (0.5 + lifePct * 0.5); 
             ctx.beginPath();
             for(let i=0; i<4; i++) {
                 ctx.rotate(Math.PI/2);
                 ctx.moveTo(0, -r); ctx.lineTo(4, -r-4); ctx.moveTo(0, -r); ctx.lineTo(-4, -r-4);
             }
             ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; // Red
             ctx.lineWidth = 2;
             ctx.beginPath();
             const r = 10;
             ctx.moveTo(-r, -r); ctx.lineTo(r, r);
             ctx.moveTo(r, -r); ctx.lineTo(-r, r);
             ctx.stroke();
        } else if (mk.type === 'LOAD') {
            ctx.strokeStyle = '#fbbf24'; // Yellow
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(0, 0, 10 + lifePct * 10, 0, Math.PI * 2);
            ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    state.entities.forEach(entity => {
      // VISIBILITY CHECK
      if (!visibleEntities.has(entity.id)) return;

      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      // Rally Point
      if (state.selection.includes(entity.id) && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.save();
          ctx.strokeStyle = '#fbbf24'; 
          ctx.setLineDash([5, 5]);
          ctx.beginPath();
          ctx.moveTo(0, 0); 
          ctx.lineTo(entity.rallyPoint.x - entity.position.x, entity.rallyPoint.y - entity.position.y);
          ctx.stroke();
          ctx.restore();
      }

      // Selection Ring
      if (state.selection.includes(entity.id)) {
        ctx.strokeStyle = '#00ff00';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Body Drawing
      if (entity.type === EntityType.MINERAL) {
        ctx.fillStyle = '#38bdf8'; 
        ctx.beginPath();
        ctx.moveTo(0, -12); ctx.lineTo(10, -5); ctx.lineTo(6, 8); ctx.lineTo(-6, 8); ctx.lineTo(-10, -5);
        ctx.fill();
        ctx.strokeStyle = '#0ea5e9';
        ctx.stroke();
      } else if (entity.type === EntityType.MOUNTAIN) {
        ctx.fillStyle = '#4b5563'; 
        ctx.beginPath();
        ctx.moveTo(0, -40); 
        ctx.lineTo(30, -10); ctx.lineTo(20, 20); ctx.lineTo(40, 40);
        ctx.lineTo(0, 30); ctx.lineTo(-30, 40); ctx.lineTo(-40, 10); ctx.lineTo(-20, -20);
        ctx.fill();
        ctx.fillStyle = '#6b7280';
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(15, 0); ctx.lineTo(-5, 5);
        ctx.fill();
      } else if (entity.type === EntityType.WATER) {
        ctx.fillStyle = '#1e3a8a';
        ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0,0, 25, 0, Math.PI*2); ctx.stroke();
        ctx.strokeStyle = 'rgba(255,255,255,0.3)';
        ctx.beginPath(); 
        ctx.moveTo(-15, 0); ctx.quadraticCurveTo(0, -10, 15, 0);
        ctx.stroke();
      } else {
        ctx.fillStyle = entity.owner === Owner.PLAYER ? '#3b82f6' : '#ef4444';

        if (entity.type === EntityType.BASE) {
          ctx.fillRect(-30, -30, 60, 60);
          ctx.fillStyle = '#1e3a8a';
          ctx.fillRect(-10, 10, 20, 20);
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.moveTo(-30, -30); ctx.lineTo(30,30); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(30, -30); ctx.lineTo(-30,30); ctx.stroke();
        } else if (entity.type === EntityType.BARRACKS) {
            ctx.fillRect(-25, -25, 50, 50);
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(-15, -15, 30, 30);
        } else if (entity.type === EntityType.BUNKER) {
            ctx.fillRect(-20, -20, 40, 40);
            ctx.fillStyle = '#374151';
            ctx.fillRect(-15, -5, 30, 10); // Slit
            // Indicators for garrison
            if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#22c55e';
                 for(let i=0; i<entity.garrison.length; i++) {
                     ctx.beginPath(); ctx.arc(-12 + i * 8, 12, 3, 0, Math.PI*2); ctx.fill();
                 }
            }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
            ctx.fillRect(-15, -15, 30, 30);
            ctx.beginPath(); ctx.moveTo(-15, -15); ctx.lineTo(15,15); ctx.stroke();
        } else if (entity.type === EntityType.WORKER) {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();
            ctx.fillStyle = '#9ca3af';
            ctx.beginPath(); ctx.arc(4, 4, 3, 0, Math.PI * 2); ctx.fill();
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#38bdf8'; 
                ctx.beginPath(); ctx.arc(0, -6, 4, 0, Math.PI * 2); ctx.fill();
            }
        } else if (entity.type === EntityType.MARINE) {
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(10, 0); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
            ctx.fillStyle = '#e5e7eb'; // White
            ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
            // Red Cross
            ctx.fillStyle = '#ef4444';
            ctx.fillRect(-2, -5, 4, 10);
            ctx.fillRect(-5, -2, 10, 4);
        }

        // HP Bar
        if (entity.hp < entity.maxHp || state.selection.includes(entity.id)) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 24;
            ctx.fillStyle = 'red';
            ctx.fillRect(-w/2, -entity.radius - 10, w, 4);
            ctx.fillStyle = '#22c55e'; // Green
            ctx.fillRect(-w/2, -entity.radius - 10, w * pct, 4);
        }

        if (entity.constructionProgress! < 100) {
            ctx.fillStyle = 'yellow';
            ctx.fillRect(-15, 0, 30, 4);
            ctx.fillStyle = 'blue';
            ctx.fillRect(-15, 0, 30 * (entity.constructionProgress! / 100), 4);
        }

        if (entity.trainQueue && entity.trainQueue.length > 0) {
             ctx.fillStyle = 'white';
             ctx.beginPath(); ctx.arc(0, -entity.radius-15, 2, 0, Math.PI*2); ctx.fill();
        }
      }
      ctx.restore();

      // Attack Lines
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? 'yellow' : 'white';
              ctx.lineWidth = entity.type === EntityType.MARINE ? 2 : 1;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
          }
      }
      // Bunker Attack Line
      if (entity.type === EntityType.BUNKER && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
           if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = 'yellow';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
           }
      }
      // Medic Beam
      if (entity.state === 'HEALING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 10) {
          const target = state.entities.get(entity.targetId);
           if (target) {
              ctx.strokeStyle = '#22c55e';
              ctx.lineWidth = 2;
              ctx.setLineDash([5, 5]);
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y);
              ctx.lineTo(target.position.x, target.position.y);
              ctx.stroke();
              ctx.setLineDash([]);
           }
      }
    });

    // --- DRAW EFFECTS ---
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION') {
            const r = (1 - lifePct) * 40 * fx.scale;
            ctx.globalAlpha = lifePct;
            ctx.fillStyle = '#fff7ed'; 
            ctx.beginPath(); ctx.arc(0,0, r * 0.5, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#ea580c'; 
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'BUILDING_EXPLOSION') {
             const r = (1 - lifePct) * 80;
             ctx.globalAlpha = lifePct;
             ctx.fillStyle = '#fef08a';
             ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();

             for(let i=0; i<5; i++) {
                 const offsetAngle = (i/5) * Math.PI*2 + state.gameTime * 0.1;
                 const ex = Math.cos(offsetAngle) * r * 0.5;
                 const ey = Math.sin(offsetAngle) * r * 0.5;
                 ctx.fillStyle = i % 2 === 0 ? '#ef4444' : '#f97316';
                 ctx.beginPath(); ctx.arc(ex, ey, r*0.6, 0, Math.PI*2); ctx.fill();
             }
        } else if (fx.type === 'BLOOD') {
            ctx.fillStyle = '#991b1b'; 
            ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.arc(0,0, 10, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5,5, 6, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#22c55e';
            ctx.globalAlpha = lifePct;
            ctx.lineWidth = 2;
            ctx.beginPath(); 
            ctx.moveTo(0, -10 + lifePct * 10); ctx.lineTo(0, -20);
            ctx.moveTo(-5, -15); ctx.lineTo(5, -15);
            ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // --- DRAW FOG OVERLAY ---
    if (visionCanvasRef.current) ctx.drawImage(visionCanvasRef.current, 0, 0); 
    if (exploredCanvasRef.current) ctx.drawImage(exploredCanvasRef.current, 0, 0);

    // Selection Box
    if (mouseDownStateRef.current) {
        const currentWorldPos = {
            x: mousePos.x + state.camera.x,
            y: mousePos.y + state.camera.y
        };
        const startWorld = mouseDownStateRef.current.world;
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(startWorld.x, startWorld.y, currentWorldPos.x - startWorld.x, currentWorldPos.y - startWorld.y);
        ctx.setLineDash([]);
    }

    // Ghost Building
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = { x: mousePos.x + state.camera.x, y: mousePos.y + state.camera.y };
       const stats = STATS[type];
       ctx.fillStyle = 'rgba(34, 197, 94, 0.5)';
       ctx.fillRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.strokeRect(worldMouse.x - stats.width/2, worldMouse.y - stats.height/2, stats.width, stats.height);
    }

    // Pause Overlay
    if (state.paused) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0); // Reset transform
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white';
        ctx.font = 'bold 48px sans-serif';
        ctx.textAlign = 'center';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 10;
        ctx.fillText('PAUSED', width / 2, height / 2);
        ctx.restore();
    }

    // Notifications (Screen Space)
    ctx.restore(); // Undo Camera transform for HUD-like elements
    if (state.notifications.length > 0) {
        ctx.save();
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#f87171';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;

        state.notifications.forEach((n, i) => {
            const y = height - 250 - (i * 30);
            const alpha = Math.min(1, n.life / 30);
            ctx.globalAlpha = alpha;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.restore();
    }

  };

  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }

    const mousePos = mousePosRef.current;

    // Edge Panning
    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > window.innerHeight - margin && mousePos.y <= window.innerHeight) gameStateRef.current.camera.y += panSpeed;
    }

    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, GAME_WIDTH - window.innerWidth));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, GAME_HEIGHT - window.innerHeight));

    if (canvasRef.current) {
      draw(canvasRef.current.getContext('2d')!);
    }

    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused) {
        onGameStateUpdate({ ...gameStateRef.current });
    }

    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  // --- Input Handlers ---
  const handleMouseDown = (e: React.MouseEvent) => {
    if (gameStateRef.current.paused) return; // Ignore inputs when paused

    if (e.button === 1) {
        e.preventDefault();
        isDraggingCamera.current = true;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.button === 2) { 
        e.preventDefault();
        rightDragStart.current = { x: e.clientX, y: e.clientY };
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        isRightDragging.current = false;
        return;
    }

    if (e.button === 0) { 
      if (commandMode === 'ATTACK') {
          const pos = getWorldPos(e.clientX, e.clientY);
          // Check Visibility for interaction
          const allEntities = Array.from(gameStateRef.current.entities.values());
          const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER);

          const clickedEntity = allEntities.find(ent => {
             const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
             if (dist < ent.radius + 15) {
                 return isEntityVisible(ent, playerUnits);
             }
             return false;
          });

          gameStateRef.current.selection.forEach(id => {
              const unit = gameStateRef.current.entities.get(id);
              if (unit && unit.owner === Owner.PLAYER) {
                  unit.state = 'ATTACKING';
                  unit.targetPosition = pos; // Default Attack Move to ground
                  unit.targetId = null;

                  if (clickedEntity && clickedEntity.owner !== Owner.PLAYER) {
                      unit.targetId = clickedEntity.id;
                      unit.targetPosition = null;
                  }

                  gameStateRef.current.markers.push({
                      id: `mk_${Math.random()}`,
                      position: clickedEntity ? clickedEntity.position : pos,
                      type: 'ATTACK',
                      life: 20, maxLife: 20
                  });
              }
          });
          setCommandMode(null);
          playSound('click');
          return;
      }

      if (commandMode && commandMode.startsWith('BUILD_')) {
          const type = commandMode.replace('BUILD_', '') as EntityType;
          const pos = getWorldPos(e.clientX, e.clientY);
          const stats = STATS[type];

          if (gameStateRef.current.resources[Owner.PLAYER] >= stats.cost) {
             gameStateRef.current.resources[Owner.PLAYER] -= stats.cost;
             const b = createEntity(type, Owner.PLAYER, pos);
             b.constructionProgress = 0; 
             gameStateRef.current.entities.set(b.id, b);
             setCommandMode(null);
             playSound('build');
          } else {
              addNotification(gameStateRef.current, "Not Enough Minerals!");
              playSound('error');
          }
          return;
      }

      const worldPos = getWorldPos(e.clientX, e.clientY);
      mouseDownStateRef.current = {
          screen: { x: e.clientX, y: e.clientY },
          world: worldPos
      };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };

    if (gameStateRef.current.paused) return;

    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
        return;
    }

    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) {
            isRightDragging.current = true;
        }

        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;

     if (e.button === 1) {
         isDraggingCamera.current = false;
         return;
     }

     if (e.button === 2) { 
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);

             // Check Visibility for Interaction
             const allEntities = Array.from(gameStateRef.current.entities.values());
             const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');

             const clickedEntity = allEntities.find(ent => {
                 const dist = Math.sqrt(Math.pow(ent.position.x - pos.x, 2) + Math.pow(ent.position.y - pos.y, 2));
                 if (dist < ent.radius + 15) {
                     return isEntityVisible(ent, playerUnits);
                 }
                 return false;
             });

             const hasBuildingsSelected = gameStateRef.current.selection.some(id => {
                 const ent = gameStateRef.current.entities.get(id);
                 return ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS);
             });

             if (hasBuildingsSelected) {
                  gameStateRef.current.selection.forEach(id => {
                      const ent = gameStateRef.current.entities.get(id);
                      if (ent && ent.owner === Owner.PLAYER && (ent.type === EntityType.BASE || ent.type === EntityType.BARRACKS)) {
                          window.dispatchEvent(new CustomEvent('GAME_COMMAND', {
                              detail: { action: 'SET_RALLY', id: ent.id, pos, targetId: clickedEntity ? clickedEntity.id : null }
                          }));
                      }
                  });
             } else {
                 playSound('click');
                 gameStateRef.current.selection.forEach(id => {
                    const unit = gameStateRef.current.entities.get(id);
                    if (unit && unit.owner === Owner.PLAYER) {
                       if (clickedEntity) {
                           if (clickedEntity.owner === Owner.NEUTRAL && clickedEntity.type === EntityType.MINERAL && unit.type === EntityType.WORKER) {
                               unit.state = 'GATHERING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'MOVE', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner !== Owner.PLAYER && (unit.type === EntityType.MARINE || unit.type === EntityType.MEDIC)) {
                               // Medic won't attack but will move to
                               unit.state = unit.type === EntityType.MEDIC ? 'MOVING' : 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'ATTACK', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner !== Owner.PLAYER && unit.type === EntityType.WORKER) {
                               unit.state = 'ATTACKING';
                               unit.targetId = clickedEntity.id;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'ATTACK', life: 20, maxLife: 20 });
                           } else if (clickedEntity.owner === Owner.PLAYER && clickedEntity.type === EntityType.BUNKER && unit.type === EntityType.MARINE) {
                               // Load into Bunker
                               unit.state = 'ENTERING';
                               unit.targetId = clickedEntity.id;
                               unit.targetPosition = null;
                               gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...clickedEntity.position }, type: 'LOAD', life: 20, maxLife: 20 });
                           }
                       } else {
                           unit.state = 'MOVING';
                           unit.targetPosition = pos;
                           unit.targetId = null;
                           gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: { ...pos }, type: 'MOVE', life: 20, maxLife: 20 });
                       }
                    }
                 });
             }
             setCommandMode(null);
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         const screenDiffX = Math.abs(e.clientX - mouseDownStateRef.current.screen.x);
         const screenDiffY = Math.abs(e.clientY - mouseDownStateRef.current.screen.y);
         const isClick = (screenDiffX < 5 && screenDiffY < 5);
         const currentWorldPos = getWorldPos(e.clientX, e.clientY);
         const startWorld = mouseDownStateRef.current.world;

         const minX = Math.min(startWorld.x, currentWorldPos.x);
         const maxX = Math.max(startWorld.x, currentWorldPos.x);
         const minY = Math.min(startWorld.y, currentWorldPos.y);
         const maxY = Math.max(startWorld.y, currentWorldPos.y);

         const newSelection: string[] = [];

         // Only select Visible things (own units are always visible)
         const allEntities = Array.from(gameStateRef.current.entities.values());
         const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');

         gameStateRef.current.entities.forEach(ent => {
             if (ent.type === EntityType.MOUNTAIN || ent.type === EntityType.WATER) return; 
             if (ent.state === 'GARRISONED') return; // Cannot select garrisoned units directly

             // Must be visible to be selected
             if (!isEntityVisible(ent, playerUnits)) return;

             if (!isClick && ent.owner !== Owner.PLAYER) return; 

             if (isClick) {
                 const dx = ent.position.x - currentWorldPos.x;
                 const dy = ent.position.y - currentWorldPos.y;
                 if (Math.sqrt(dx*dx + dy*dy) < ent.radius + 15) { 
                     newSelection.push(ent.id);
                 }
             } else {
                 if (ent.position.x > minX && ent.position.x < maxX && 
                     ent.position.y > minY && ent.position.y < maxY) {
                         if (ent.owner === Owner.PLAYER) newSelection.push(ent.id);
                     }
             }
         });

         if (isClick) playSound('click');

         if (isClick && newSelection.length > 1) {
             gameStateRef.current.selection = [newSelection[0]];
         } else {
             gameStateRef.current.selection = newSelection;
         }

         if (!isClick && newSelection.length > 0) {
             const units = newSelection.filter(id => {
                 const t = gameStateRef.current.entities.get(id)?.type;
                 return t !== EntityType.BASE && t !== EntityType.BARRACKS && t !== EntityType.SUPPLY_DEPOT && t !== EntityType.BUNKER;
             });
             if (units.length > 0) gameStateRef.current.selection = units;
         }

         const selectedEntities = gameStateRef.current.selection
            .map(id => gameStateRef.current.entities.get(id)!)
            .filter(Boolean);

         onSelectionChange(selectedEntities);
         mouseDownStateRef.current = null;
     }
  };

  const handleMouseLeave = () => {
     mouseDownStateRef.current = null;
     isDraggingCamera.current = false;
     isRightDragging.current = false;
     mousePosRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  };

  return (
    <canvas
      ref={canvasRef}
      width={window.innerWidth}
      height={window.innerHeight}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Entity, EntityType, GameState, Owner, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { toggleMute, getMuteState } from '../services/audio';

interface Props {
  gameState: GameState;
  selectedEntities: Entity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];
  const [isMuted, setIsMuted] = useState(getMuteState());
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Selection Logic
  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);
  const canBuild = allWorkers && selectedEntities.length === 1; // Only 1 worker can build at a time to keep UI simple

  // Group Selection logic
  const allBarracks = selectedEntities.filter(e => e.type === EntityType.BARRACKS && e.owner === Owner.PLAYER);
  const showBarracksMenu = singleSelection?.type === EntityType.BARRACKS || allBarracks.length > 0;

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const key = e.key.toUpperCase();
        if ((e.target as HTMLElement).tagName === 'INPUT') return;

        if (singleSelection?.type === EntityType.BASE) {
            if (key === 'W') onTrain(EntityType.WORKER);
        }

        if (showBarracksMenu) {
            if (key === 'M') handleMultiTrain(EntityType.MARINE);
            if (key === 'E') handleMultiTrain(EntityType.MEDIC);
        }

        if (singleSelection?.type === EntityType.WORKER) {
            if (key === 'B') onCommand(`BUILD_${EntityType.BARRACKS}`);
            if (key === 'S') onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`);
            if (key === 'U') onCommand(`BUILD_${EntityType.BUNKER}`);
        }

        if (singleSelection?.type === EntityType.BUNKER && singleSelection.owner === Owner.PLAYER) {
            if (key === 'D') handleUnload();
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [singleSelection, showBarracksMenu, onTrain, onCommand]);

  // Close menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setMenuOpen(false);
      }
    };
    if (menuOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [menuOpen]);

  const handleMultiTrain = (type: EntityType) => {
      if (allBarracks.length > 0) {
          const bestBarracks = [...allBarracks].sort((a, b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'TRAIN', id: bestBarracks.id, type } 
          }));
      } else if (singleSelection) {
          onTrain(type);
      }
  };

  const handleUnload = () => {
      if (singleSelection && singleSelection.type === EntityType.BUNKER) {
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'UNLOAD_ALL', id: singleSelection.id } 
          }));
      }
  };

  const handleRestart = () => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'RESTART', difficulty: gameState.difficulty } 
      }));
  };

  const changeDifficulty = (diff: Difficulty) => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'RESTART', difficulty: diff } 
      }));
  };

  const togglePause = () => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'TOGGLE_PAUSE' } 
      }));
  };

  const handleToggleMute = () => {
      setIsMuted(toggleMute());
  };

  // --- Minimap Logic ---
  const [isDraggingMinimap, setIsDraggingMinimap] = useState(false);
  const minimapRef = useRef<HTMLDivElement>(null);

  const updateCameraFromMinimap = (clientX: number, clientY: number) => {
      if (!minimapRef.current) return;
      const rect = minimapRef.current.getBoundingClientRect();
      const xPct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const yPct = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));

      const targetX = xPct * GAME_WIDTH;
      const targetY = yPct * GAME_HEIGHT;

      const centerX = targetX - (window.innerWidth / 2);
      const centerY = targetY - (window.innerHeight / 2);

      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
      }));
  };

  const handleMinimapMouseDown = (e: React.MouseEvent) => {
      setIsDraggingMinimap(true);
      updateCameraFromMinimap(e.clientX, e.clientY);
  };

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (isDraggingMinimap) {
              updateCameraFromMinimap(e.clientX, e.clientY);
          }
      };
      const handleMouseUp = () => {
          setIsDraggingMinimap(false);
      };

      if (isDraggingMinimap) {
          window.addEventListener('mousemove', handleMouseMove);
          window.addEventListener('mouseup', handleMouseUp);
      }
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
      };
  }, [isDraggingMinimap]);


  // Helper for Fog of War on Minimap
  const isVisibleOnMinimap = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      if (entity.type === EntityType.MINERAL && entity.resourceAmount! <= 0) return false;

      // Optimisation: Player units are already filtered in the parent, but we need a list
      // Iterate players units to see if this entity is close enough
      for(const pu of playerUnits) {
          const dx = entity.position.x - pu.position.x;
          const dy = entity.position.y - pu.position.y;
          // Simple squared check is faster, assume max vision ~500
          if (dx*dx + dy*dy < 250000) { // 500^2
              return true;
          }
      }
      return false;
  };

  const allEntities = Array.from(gameState.entities.values());
  const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');

  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between">
      {/* Top Bar */}
      <div className="bg-gray-900 bg-opacity-90 text-white p-2 flex gap-4 border-b border-gray-700 pointer-events-auto select-none items-center shadow-md justify-between px-4">
         <div className="flex gap-4">
             <div className="font-bold text-yellow-400">Minerals: {Math.floor(resources)}</div>
             <div className={supply.used > supply.max ? "text-red-500 font-bold" : "text-green-400"}>
                 Supply: {supply.used}/{supply.max}
             </div>
             <div className="text-gray-400 text-sm">Time: {Math.floor(gameState.gameTime / 60)}s</div>
         </div>

         {/* Menu Button */}
         <div className="relative" ref={menuRef}>
            <button 
                onClick={() => setMenuOpen(!menuOpen)}
                className="px-4 py-1 bg-gray-700 hover:bg-gray-600 rounded border border-gray-500 font-bold text-sm"
            >
                MENU
            </button>

            {menuOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-gray-800 border border-gray-600 rounded shadow-xl flex flex-col p-2 gap-2 z-50">
                    <button 
                        onClick={togglePause} 
                        className="text-left px-3 py-2 bg-gray-700 hover:bg-blue-600 rounded text-sm font-semibold"
                    >
                        {gameState.paused ? 'RESUME' : 'PAUSE'} (P)
                    </button>

                    <div className="border-t border-gray-600 my-1"></div>

                    <div className="text-xs text-gray-400 px-1 mb-1">Difficulty (Restarts Game)</div>
                    <div className="flex gap-1 mb-2">
                        {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map(d => (
                            <button 
                                key={d}
                                className={`flex-1 py-1 text-[10px] rounded border ${gameState.difficulty === d ? 'bg-blue-600 border-blue-400' : 'bg-gray-700 border-gray-600 hover:bg-gray-600'}`}
                                onClick={() => changeDifficulty(d)}
                            >
                                {d}
                            </button>
                        ))}
                    </div>

                    <button 
                        onClick={handleToggleMute} 
                        className="text-left px-3 py-2 bg-gray-700 hover:bg-gray-600 rounded text-sm"
                    >
                        Sound: {isMuted ? 'OFF' : 'ON'}
                    </button>

                    <div className="border-t border-gray-600 my-1"></div>

                    <button 
                        onClick={handleRestart} 
                        className="text-left px-3 py-2 bg-red-900 hover:bg-red-700 border border-red-800 rounded text-sm font-bold"
                    >
                        RESTART GAME
                    </button>
                </div>
            )}
         </div>
      </div>

      {/* Victory Screen Overlay */}
      {gameState.victory && (
         <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-70 z-50 pointer-events-auto">
             <div className="bg-gray-800 p-8 rounded-lg border-2 border-yellow-500 text-center shadow-2xl">
                 <h1 className="text-4xl font-bold text-yellow-500 mb-4">
                     {gameState.victory === Owner.PLAYER ? "VICTORY!" : "DEFEAT"}
                 </h1>
                 <button 
                    className="px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded"
                    onClick={handleRestart}
                 >
                     PLAY AGAIN
                 </button>
             </div>
         </div>
      )}

      {/* Bottom Panel */}
      <div className="h-48 bg-gray-900 border-t border-gray-700 flex pointer-events-auto select-none shadow-lg">
          {/* Minimap */}
          <div 
              ref={minimapRef}
              className="w-48 bg-black border-r border-gray-700 relative overflow-hidden cursor-move"
              onMouseDown={handleMinimapMouseDown}
          >
             {/* Map Features */}
             {allEntities.map(e => {
                 if (e.state === 'GARRISONED') return null;
                 if (!isVisibleOnMinimap(e, playerUnits)) return null;

                 let color = 'bg-gray-500';
                 if (e.type === EntityType.WATER) color = 'bg-blue-800';
                 else if (e.type === EntityType.MOUNTAIN) color = 'bg-gray-700';
                 else if (e.type === EntityType.MINERAL) color = 'bg-teal-500';
                 else if (e.owner === Owner.PLAYER) color = 'bg-blue-500';
                 else if (e.owner === Owner.AI) color = 'bg-red-500';

                 const size = (e.type === EntityType.WATER || e.type === EntityType.MOUNTAIN) ? 4 : 2;

                 return (
                    <div key={e.id} 
                        className={`absolute rounded-full ${color}`}
                        style={{ 
                            left: `${(e.position.x / GAME_WIDTH) * 100}%`, 
                            top: `${(e.position.y / GAME_HEIGHT) * 100}%`,
                            width: size + 'px', height: size + 'px'
                        }} 
                    />
                 );
             })}

             {/* Camera Rect */}
             <div className="absolute border border-white pointer-events-none"
                  style={{
                      left: `${(gameState.camera.x / GAME_WIDTH) * 100}%`,
                      top: `${(gameState.camera.y / GAME_HEIGHT) * 100}%`,
                      width: `${(window.innerWidth / GAME_WIDTH) * 100}%`,
                      height: `${(window.innerHeight / GAME_HEIGHT) * 100}%`,
                  }}
             />
          </div>

          {/* Unit Info */}
          <div className="flex-1 p-4 border-r border-gray-700 flex flex-wrap gap-2 overflow-auto content-start">
             {selectedEntities.length === 0 && <span className="text-gray-500 italic">No selection</span>}

             {/* Barracks Group View */}
             {allBarracks.length > 1 && selectedEntities.length === allBarracks.length ? (
                 <div className="flex flex-wrap gap-2">
                     {allBarracks.map(b => (
                         <div key={b.id} className="w-16 h-16 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-xs text-white relative">
                             <span>Barracks</span>
                             {b.trainQueue && b.trainQueue.length > 0 && (
                                 <div className="absolute top-1 right-1 text-blue-400 font-bold">{b.trainQueue.length}</div>
                             )}
                             <div className="w-full h-1 bg-gray-900 mt-2">
                                <div className="h-full bg-white" style={{ width: `${(b.trainProgress! / STATS[EntityType.MARINE].buildTime) * 100}%` }} />
                             </div>
                         </div>
                     ))}
                 </div>
             ) : (
                selectedEntities.length > 0 && selectedEntities.length < 18 && selectedEntities.map(e => (
                    <div key={e.id} className="w-12 h-12 bg-gray-800 border border-gray-600 p-1 flex flex-col items-center justify-center text-[10px] text-white overflow-hidden">
                        <div className={`w-2 h-2 rounded-full mb-1 ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                        <span className="truncate w-full text-center">{e.type}</span>
                        {/* Garrison Indicator */}
                        {e.garrison && e.garrison.length > 0 && (
                            <div className="flex gap-0.5 mt-0.5">
                                {e.garrison.map((_, i) => <div key={i} className="w-1 h-1 bg-green-500 rounded-full" />)}
                            </div>
                        )}
                        <div className="w-full h-1 bg-red-900 mt-1">
                            <div className="h-full bg-green-500" style={{ width: `${(e.hp / e.maxHp) * 100}%`}} />
                        </div>
                    </div>
                ))
             )}

             {selectedEntities.length >= 18 && (
                 <div className="text-white p-4 font-bold text-lg">
                     Selected: {selectedEntities.length} Units
                 </div>
             )}
          </div>

          {/* Command Card */}
          <div className="w-64 bg-gray-800 p-2 grid grid-cols-3 gap-2">
              {/* Build Commands */}
              {canBuild && (
                  <>
                    <CommandButton 
                        label="Depot (100)" 
                        hotkey="S" 
                        cost={100} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} 
                    />
                    <CommandButton 
                        label="Barracks (150)" 
                        hotkey="B" 
                        cost={150} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} 
                    />
                    <CommandButton 
                        label="Bunker (100)" 
                        hotkey="U" 
                        cost={100} 
                        currentResources={resources}
                        onClick={() => onCommand(`BUILD_${EntityType.BUNKER}`)} 
                    />
                  </>
              )}

              {/* Train Commands */}
              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Worker (50)" 
                      hotkey="W" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress}
                      maxProgress={STATS[EntityType.WORKER].buildTime}
                      queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {showBarracksMenu && (
                  <>
                  <CommandButton 
                      label="Marine (50)" 
                      hotkey="M" 
                      cost={50} 
                      currentResources={resources}
                      onClick={() => handleMultiTrain(EntityType.MARINE)} 
                      progress={singleSelection ? singleSelection.trainProgress : 0}
                      maxProgress={STATS[EntityType.MARINE].buildTime}
                      queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
                  <CommandButton 
                      label="Medic (75)" 
                      hotkey="E" 
                      cost={75} 
                      currentResources={resources}
                      onClick={() => handleMultiTrain(EntityType.MEDIC)} 
                      progress={singleSelection ? singleSelection.trainProgress : 0}
                      maxProgress={STATS[EntityType.MEDIC].buildTime}
                      queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
                  </>
              )}

              {/* Bunker Commands */}
              {singleSelection?.type === EntityType.BUNKER && singleSelection.owner === Owner.PLAYER && (
                  <button 
                      onClick={handleUnload}
                      className={`relative bg-gray-700 border border-gray-500 text-white text-xs p-1 hover:bg-gray-600 active:bg-gray-500 flex flex-col items-center justify-center h-20 shadow-sm transition-colors`}
                  >
                      <span className="font-bold text-yellow-300 mb-1">D</span>
                      <span className="text-center leading-tight">Unload All</span>
