        <div className="w-full h-full bg-slate-950 flex items-center justify-center font-mono text-white">
            <div className="max-w-md w-full bg-slate-900 border border-slate-700 p-8 rounded-lg shadow-2xl text-center">
                 <button onClick={() => { network.close(); setMode('MULTIPLAYER_MENU'); setOpponent(null); setOpponentReady(false); setIsReady(false); }} className="float-left text-slate-500 hover:text-white mb-4 text-xs uppercase tracking-widest">
                    &larr; Cancel
                </button>
                <div className="clear-both"></div>

                <h2 className="text-xl font-bold mb-6 text-slate-300 uppercase tracking-widest">
                    {isHosting ? 'Hosting Game' : 'Joining Game'}
                </h2>

                {isHosting && !opponent && (
                    <div className="bg-slate-800 p-6 rounded border border-slate-700 mb-6">
                        <p className="text-slate-400 text-xs uppercase mb-2">Share this code with your friend</p>
                        <div className="flex items-center gap-2 justify-center mb-4">
                            <span className="text-4xl font-black text-cyan-400 tracking-widest bg-black/30 px-6 py-4 rounded select-all font-mono border border-cyan-900/50">
                                {hostCode || "...."}
                            </span>
                        </div>
                        {hostCode && (
                            <button onClick={copyCode} className="text-xs text-slate-500 hover:text-white underline mb-4">
                                Click to Copy Code
                            </button>
                        )}
                        <div className="flex items-center justify-center gap-3">
                             <div className="w-2 h-2 bg-cyan-500 rounded-full animate-ping"></div>
                             <span className="text-sm text-slate-500">Waiting for opponent...</span>
                        </div>
                    </div>
                )}

                {!isHosting && !opponent && (
                    <div className="py-8 bg-slate-800 rounded border border-slate-700 mb-6">
                         <div className="flex flex-col items-center justify-center gap-4">
                             <div className="w-3 h-3 bg-cyan-500 rounded-full animate-ping"></div>
                             <span className="text-sm text-slate-400 font-mono">Connecting to {joinCode}...</span>
                        </div>
                    </div>
                )}

                {opponent && (
                    <div className="space-y-6">
                        <div className="bg-slate-800 p-4 rounded border border-slate-700 shadow-inner">
                             <div className="flex justify-between items-center mb-3 pb-3 border-b border-slate-700">
                                <span className="text-slate-300 font-bold">{name} (You)</span>
                                <span className={`text-xs font-bold px-2 py-1 rounded ${isReady ? "bg-green-900 text-green-300" : "bg-yellow-900 text-yellow-300"}`}>
                                    {isReady ? "READY" : "NOT READY"}
                                </span>
                            </div>
                            <div className="flex justify-between items-center">
                                <span className="text-slate-300 font-bold">{opponent.name}</span>
                                <span className={`text-xs font-bold px-2 py-1 rounded ${opponentReady ? "bg-green-900 text-green-300" : "bg-slate-700 text-slate-400"}`}>
                                    {opponentReady ? "READY" : "WAITING"}
                                </span>
                            </div>
                        </div>

                        <button 
                            onClick={toggleReady}
                            className={`w-full py-4 font-bold rounded uppercase tracking-widest transition-colors shadow-lg
                                ${isReady ? 'bg-yellow-600 hover:bg-yellow-500 text-white' : 'bg-green-600 hover:bg-green-500 text-white'}
                            `}
                        >
                            {isReady ? "Cancel Ready" : "READY UP"}
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

