// Network Types
export type NetMessage = 
  | { type: 'JOIN', payload: { name: string, id: string } }
  | { type: 'WELCOME', payload: { seed: number, hostId: string } }
  | { type: 'READY', payload: { id: string, ready: boolean } }
  | { type: 'START_GAME', payload: { seed: number } }
  | { type: 'GAME_COMMAND', payload: { action: string, data: any, owner: Owner } }
  | { type: 'ERROR', payload: { message: string } };

export interface PlayerInfo {
    id: string;
    name: string;
    isReady: boolean;
    isHost: boolean;
}

import { NetMessage } from '../types';
import { Peer, DataConnection } from 'peerjs';

type MessageHandler = (msg: NetMessage) => void;

class NetworkService {
    private peer: Peer | null = null;
    private conn: DataConnection | null = null;
    private listeners: MessageHandler[] = [];
    public id: string = '';
    public name: string = 'Player';

    constructor() {
        // Peer initialized on demand
    }

    public setName(name: string) {
        this.name = name;
    }

    private generateShortId(): string {
        // Exclude I, O, 0, 1, Q to avoid confusion
        const chars = 'ABCDEFGHJKLMNPRSTUVWXYZ23456789';
        let result = '';
        for (let i = 0; i < 4; i++) {
            result += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return result;
    }

    public async hostGame(customId?: string): Promise<string> {
        return new Promise((resolve, reject) => {
            let attempts = 0;

            const attemptHost = () => {
                if (attempts > 10 && !customId) {
                    reject(new Error("Could not find a free game code. Please try again."));
                    return;
                }
                attempts++;

                if (this.peer) {
                    this.peer.destroy();
                    this.peer = null;
                }

                // Use custom ID if provided, otherwise generate short ID
                const peerId = customId || this.generateShortId();

                // Initialize Peer with this ID
                this.peer = new Peer(peerId, {
                    debug: 1
                });

                this.peer.on('open', (id) => {
                    this.id = id;
                    this.conn = null; // Ensure fresh state
                    resolve(id);
                });

                this.peer.on('connection', (conn) => {
                    this.handleConnection(conn);
                });

                this.peer.on('error', (err: any) => {
                    if (err.type === 'unavailable-id') {
                        if (customId) {
                            reject(new Error("Room is already taken."));
                        } else {
                            // ID taken, retry with new random
                            console.log(`ID ${peerId} taken, retrying...`);
                            attemptHost();
                        }
                    } else {
                        console.error('Peer error:', err);
                        reject(err);
                    }
                });
            };

            attemptHost();
        });
    }

    public async joinGame(hostId: string): Promise<void> {
        return new Promise((resolve, reject) => {
            // If we are already a peer (e.g. hosting a private room), we can try to connect from this peer
            // If not, create a new one.
            if (!this.peer || this.peer.disconnected) {
                if (this.peer) this.peer.destroy();
                this.peer = new Peer();
            }

            const connectToHost = () => {
                const conn = this.peer!.connect(hostId);

                if (!conn) {
                    reject(new Error("Connection failed immediately."));
                    return;
                }

                // Connection events
                conn.on('open', () => {
                    this.handleConnection(conn);
                    resolve();
                });

                conn.on('error', (err) => {
                    console.error('Connection error:', err);
                    reject(err);
                });

                // PeerJS sometimes doesn't fire error on immediate fail in some versions,
                // but the 'close' might fire.
                conn.on('close', () => {
                   // If closed before open resolved? logic handled in handleConnection
                });

                // Timeout if connection hangs
                setTimeout(() => {
                    if (!conn.open) {
                         // Don't reject if we already resolved/connected
                        if (!this.conn) reject(new Error("Connection timed out. Room might be full or closed."));
                    }
                }, 5000);
            };

            if (this.peer.open) {
                connectToHost();
            } else {
                this.peer.on('open', () => connectToHost());
                this.peer.on('error', (err) => reject(err));
            }
        });
    }

    // Helper to check if a room exists without fully committing to join flow UI
    public checkPublicRoom(roomId: string): Promise<boolean> {
        return new Promise((resolve) => {
             // We need a temp peer to check
             const tempPeer = new Peer();
             let resolved = false;

             tempPeer.on('open', () => {
                 const conn = tempPeer.connect(roomId);
                 conn.on('open', () => {
                     if (!resolved) { resolved = true; resolve(true); }
                     conn.close();
                     tempPeer.destroy();
                 });
                 conn.on('error', () => {
                      // Likely unavailable
                 });
                 setTimeout(() => {
                     if (!resolved) { resolved = true; resolve(false); }
                     tempPeer.destroy();
                 }, 2000);
             });
             tempPeer.on('error', () => {
                 if (!resolved) { resolved = true; resolve(false); }
             });
        });
    }

    private handleConnection(conn: DataConnection) {
        // Enforce 1v1 Limit
        if (this.conn && this.conn.open) {
            console.warn("Rejecting connection: Room full");
            conn.on('open', () => {
                 conn.send({ type: 'ERROR', payload: { message: "Room is full!" } });
                 setTimeout(() => conn.close(), 500);
            });
            return;
        }

        this.conn = conn;

        this.conn.on('data', (data) => {
            this.notify(data as NetMessage);
        });

        this.conn.on('close', () => {
            console.log("Connection closed");
            this.conn = null;
            // Notify listeners of disconnect if needed, or rely on them handling lack of messages
        });

        this.conn.on('error', (err) => console.error("Conn Error", err));
    }

    public send(msg: NetMessage) {
        if (this.conn && this.conn.open) {
            this.conn.send(msg);
        } else {
            console.warn("Cannot send, connection not open", msg);
        }
    }

    public subscribe(handler: MessageHandler) {
        this.listeners.push(handler);
        return () => {
            this.listeners = this.listeners.filter(h => h !== handler);
        };
    }

    private notify(msg: NetMessage) {
        this.listeners.forEach(l => l(msg));
    }

    public close() {
        if (this.conn) this.conn.close();
        if (this.peer) this.peer.destroy();
        this.conn = null;
        this.peer = null;
    }
}

export const network = new NetworkService();

import React, { useEffect, useState } from 'react';
import { network } from '../services/network';
import { PlayerInfo, Difficulty } from '../types';

interface Props {
    onGameStart: (seed: number, isHost: boolean) => void;
    onSinglePlayerStart: (difficulty: Difficulty) => void;
}

const PUBLIC_ROOMS = [
    { id: 'STAR_DRAFT_ROOM_ALPHA', name: 'Sector Alpha' },
    { id: 'STAR_DRAFT_ROOM_BETA', name: 'Sector Beta' },
    { id: 'STAR_DRAFT_ROOM_GAMMA', name: 'Sector Gamma' }
];

export const Lobby: React.FC<Props> = ({ onGameStart, onSinglePlayerStart }) => {
    // MODES: MENU -> NAME_INPUT -> LOBBY (Hosting Private + Viewing Public) -> JOINING (Transition)
    const [mode, setMode] = useState<'MENU' | 'SINGLEPLAYER' | 'NAME_INPUT' | 'LOBBY' | 'JOINING'>('MENU');
    const [name, setName] = useState('Player');
    const [opponent, setOpponent] = useState<PlayerInfo | null>(null);
    const [isReady, setIsReady] = useState(false);
    const [opponentReady, setOpponentReady] = useState(false);
    const [seed, setSeed] = useState<number>(0);
    const [isHost, setIsHost] = useState(false);
    const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
    const [hostCode, setHostCode] = useState(''); // Private code
    const [joinCode, setJoinCode] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [statusMsg, setStatusMsg] = useState('');

    useEffect(() => {
        const handleMsg = (msg: any) => {
            if (msg.type === 'JOIN' && !opponent) {
                // Received JOIN request (I am Host)
                setOpponent({ id: msg.payload.id, name: msg.payload.name, isReady: false, isHost: false });
                const newSeed = Math.random() * 10000;
                setSeed(newSeed);
                network.send({ type: 'WELCOME', payload: { seed: newSeed, hostId: network.id } });
            }
            if (msg.type === 'WELCOME' && !opponent) {
                // Received WELCOME (I am Client)
                setSeed(msg.payload.seed);
                setOpponent({ id: msg.payload.hostId, name: 'Opponent', isReady: false, isHost: true });
                setStatusMsg('');
                setMode('LOBBY'); // ensure we are in lobby view (but now with opponent)
            }
            if (msg.type === 'READY' && opponent) {
                setOpponentReady(msg.payload.ready);
            }
            if (msg.type === 'START_GAME' && opponent) {
                onGameStart(seed, isHost);
            }
            if (msg.type === 'ERROR') {
                setError(msg.payload.message);
                network.close(); // Disconnect
                setOpponent(null);
                setMode('NAME_INPUT'); // Kick back
            }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [opponent, seed, onGameStart, isHost]);

    useEffect(() => {
        if (isReady && opponentReady && isHost) {
            network.send({ type: 'START_GAME', payload: { seed } });
            onGameStart(seed, true);
        }
    }, [isReady, opponentReady, isHost, seed, onGameStart]);

    const enterLobby = async () => {
        if (!name) return setError("Please enter a name");
        network.setName(name);
        setMode('LOBBY');
        setIsHost(true);
        // Automatically host a private room
        try {
            const id = await network.hostGame();
            setHostCode(id);
        } catch (e: any) {
            setError("Failed to generate private room.");
        }
    };

    const joinPrivate = async () => {
        if (!joinCode || joinCode.length !== 4) return setError("Invalid Code");
        setError(null);
        setStatusMsg("Joining Private Room...");
        try {
             // If we were hosting, close it first? No, joinGame handles peer reuse or reconnect.
             // But simpler to just call join.
             await network.joinGame(joinCode);
             network.send({ type: 'JOIN', payload: { name, id: network.id } });
             setIsHost(false);
        } catch (e: any) {
             setError(e.message);
             setStatusMsg("");
             // Re-host private?
             const id = await network.hostGame();
             setHostCode(id);
             setIsHost(true);
        }
    };

    const handlePublicRoomClick = async (room: { id: string, name: string }) => {
        setError(null);
        setStatusMsg(`Connecting to ${room.name}...`);

        try {
            // 1. Try to Join
            await network.joinGame(room.id);
            // 2. If successful, send JOIN
            network.send({ type: 'JOIN', payload: { name, id: network.id } });
            setIsHost(false);
            setHostCode(room.id); // Just for display
        } catch (e: any) {
            // 3. If join failed, assume room is free and Try to Host
            // We must destroy current peer (private host) to claim the public ID
            console.log("Join failed, attempting to host...", e);
            setStatusMsg(`Creating ${room.name}...`);
            try {
                await network.hostGame(room.id);
                setHostCode(room.id); // "STAR_DRAFT_ROOM_ALPHA"
                setIsHost(true);
                setOpponent(null); 
                setStatusMsg("");
            } catch (hostErr: any) {
                setError("Room is busy or unavailable.");
                setStatusMsg("");
                // Revert to private host
                const id = await network.hostGame();
                setHostCode(id);
            }
        }
    };

    const toggleReady = () => {
        const newState = !isReady;
        setIsReady(newState);
        network.send({ type: 'READY', payload: { id: network.id, ready: newState } });
    };

    const copyCode = () => {
        navigator.clipboard.writeText(hostCode);
        alert("Code copied!");
    };

    // --- MAIN MENU ---
    if (mode === 'MENU') {
        return (
            <div className="w-full h-full bg-slate-950 flex items-center justify-center font-mono text-white">
                <div className="max-w-md w-full bg-slate-900 border border-slate-700 p-8 rounded-lg shadow-2xl text-center">
                    <h1 className="text-4xl font-black mb-2 text-cyan-400 tracking-tighter">STARDRAFT</h1>
                    <p className="text-slate-500 mb-8 text-sm uppercase tracking-widest">Minimalist RTS</p>

                    <div className="space-y-4">
                        <button 
                            onClick={() => setMode('SINGLEPLAYER')}
                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded uppercase tracking-widest transition-all hover:scale-105 shadow-lg"
                        >
                            Single Player
                        </button>
                        <button 
                            onClick={() => setMode('NAME_INPUT')}
                            className="w-full py-4 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded uppercase tracking-widest transition-all hover:scale-105 shadow-lg"
                        >
                            Multiplayer
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    // --- SINGLE PLAYER ---
    if (mode === 'SINGLEPLAYER') {
        return (
            <div className="w-full h-full bg-slate-950 flex items-center justify-center font-mono text-white">
                <div className="max-w-md w-full bg-slate-900 border border-slate-700 p-8 rounded-lg shadow-2xl">
                    <button onClick={() => setMode('MENU')} className="text-slate-500 hover:text-white mb-4 text-xs uppercase tracking-widest">
                        &larr; Back
                    </button>
                    <h1 className="text-3xl font-bold mb-8 text-center text-emerald-400">VS COMPUTER</h1>

                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm text-slate-400 mb-3 text-center uppercase tracking-widest">Select Difficulty</label>
                            <div className="grid grid-cols-3 gap-2">
                                {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map(diff => (
                                    <button
                                        key={diff}
                                        onClick={() => setSelectedDifficulty(diff)}
                                        className={`py-3 px-2 rounded font-bold text-sm uppercase transition-colors border ${
                                            selectedDifficulty === diff 
                                            ? 'bg-emerald-600 border-emerald-400 text-white' 
                                            : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                                        }`}
                                    >
                                        {diff}
                                    </button>
                                ))}
                            </div>
                        </div>
                        <button 
                            onClick={() => onSinglePlayerStart(selectedDifficulty)}
                            className="w-full py-4 bg-emerald-500 hover:bg-emerald-400 text-white font-bold rounded uppercase tracking-widest transition-colors shadow-lg mt-4"
                        >
                            Start Game
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    // --- NAME INPUT ---
    if (mode === 'NAME_INPUT') {
         return (
             <div className="w-full h-full bg-slate-950 flex items-center justify-center font-mono text-white">
                <div className="max-w-md w-full bg-slate-900 border border-slate-700 p-8 rounded-lg shadow-2xl">
                    <button onClick={() => setMode('MENU')} className="text-slate-500 hover:text-white mb-4 text-xs uppercase tracking-widest">
                        &larr; Back
                    </button>
                    <h1 className="text-3xl font-bold mb-8 text-center text-cyan-400">MULTIPLAYER</h1>
                    {error && <div className="bg-red-900/50 text-red-200 p-3 mb-4 rounded text-sm border border-red-800">{error}</div>}
                    <div>
                        <label className="block text-sm text-slate-400 mb-2">Enter Username</label>
                        <input 
                            type="text" 
                            value={name} 
                            onChange={(e) => setName(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && enterLobby()}
                            className="w-full bg-slate-800 border border-slate-600 p-3 rounded text-white focus:outline-none focus:border-cyan-500 mb-4"
                        />
                        <button onClick={enterLobby} className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 rounded font-bold uppercase tracking-widest shadow-lg">
                            Enter Lobby
                        </button>
                    </div>
                </div>
            </div>
         );
    }

    // --- MAIN LOBBY ---
    if (mode === 'LOBBY') {
        return (
            <div className="w-full h-full bg-slate-950 flex items-center justify-center font-mono text-white p-4">
                <div className="max-w-4xl w-full bg-slate-900 border border-slate-700 rounded-lg shadow-2xl flex flex-col md:flex-row overflow-hidden min-h-[500px]">

                    {/* LEFT PANEL: Public Rooms */}
                    <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-slate-700 bg-slate-800/50">
                        <h2 className="text-xl font-bold mb-6 text-slate-300 uppercase tracking-widest flex items-center gap-2">
                            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                            Public Sectors
                        </h2>

                        <div className="space-y-3">
                            {PUBLIC_ROOMS.map(room => (
                                <button
                                    key={room.id}
                                    disabled={!!opponent || statusMsg !== ''}
                                    onClick={() => handlePublicRoomClick(room)}
                                    className="w-full p-4 bg-slate-800 hover:bg-slate-700 border border-slate-600 hover:border-cyan-500 rounded flex justify-between items-center group transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <div className="flex flex-col items-start">
                                        <span className="font-bold text-slate-200 group-hover:text-cyan-400 transition-colors">{room.name}</span>
                                        <span className="text-xs text-slate-500">Official Server</span>
                                    </div>
