                                    </div>
                                    <span className="text-xs bg-slate-900 text-slate-400 px-2 py-1 rounded group-hover:bg-cyan-900/30 group-hover:text-cyan-300">
                                        JOIN / CREATE
                                    </span>
                                </button>
                            ))}
                        </div>

                        <div className="mt-8 pt-6 border-t border-slate-700">
