    };

    const joinPrivate = async () => {
        if (!joinCode || joinCode.length !== 4) return setError("Invalid Code (Must be 4 chars)");
        setError(null);
        setStatusMsg("Joining Private Room...");
        try {
             await network.joinGame(joinCode);
