                // Revert to private host
                const id = await network.hostGame();
                setHostCode(id);
            }
        }
    };

    const toggleReady = () => {
        const newState = !isReady;
        setIsReady(newState);
        network.send({ type: 'READY', payload: { id: network.id, ready: newState } });
    };

    const copyCode = () => {
        navigator.clipboard.writeText(hostCode);
        alert("Code copied!");
    };

