                     ))}
                 </div>
                 <button 
                    onClick={() => onCommand('QUIT')}
                    className="w-full py-3 px-4 bg-slate-800 hover:bg-slate-700 text-orange-400 border border-slate-700 hover:border-orange-500 rounded font-bold uppercase tracking-widest transition-colors"
                 >
                    Return to Menu
                 </button>
             </div>
         </div>
      )}

      {/* Bottom Panel - Modern RTS Style */}
      <div className="h-56 bg-slate-900/95 border-t border-slate-600 flex pointer-events-auto select-none shadow-2xl backdrop-blur">
          {/* Minimap Container */}
          <div className="h-full w-56 bg-black border-r border-slate-600 relative p-2 flex-shrink-0">
              <div 
                  ref={minimapRef}
                  className="w-full h-full relative bg-slate-950 border border-slate-800 cursor-crosshair overflow-hidden"
