                                <div className={`w-1.5 h-1.5 absolute top-1 left-1 rounded-full ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                                <div className="w-full h-full flex items-center justify-center text-[9px] text-slate-300 font-bold uppercase overflow-hidden p-0.5 text-center leading-none">
                                    {e.type.substring(0, 4)}
