                                {e.garrison && e.garrison.length > 0 && (
                                    <div className="flex gap-0.5 absolute bottom-2 left-1">
                                        {e.garrison.map((_, i) => <div key={i} className="w-1 h-1 bg-emerald-500 rounded-full" />)}
