          </div>

          {/* Command Card */}
          <div className="w-72 bg-slate-800 p-3 grid grid-cols-3 grid-rows-3 gap-2 flex-shrink-0 shadow-inner">
              {canBuild && (
                  <>
                    <CommandButton label="Supply Depot" sub="100" hotkey="S" cost={100} res={resources} onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} />
                    <CommandButton label="Barracks" sub="150" hotkey="B" cost={150} res={resources} onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} />
                    <CommandButton label="Bunker" sub="100" hotkey="U" cost={100} res={resources} onClick={() => onCommand(`BUILD_${EntityType.BUNKER}`)} />
                  </>
              )}

              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Train Worker" sub="50" hotkey="W" cost={50} res={resources} 
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress} max={STATS[EntityType.WORKER].buildTime} queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {showBarracksMenu && (
                  <>
                  <CommandButton 
                      label="Train Marine" sub="50" hotkey="M" cost={50} res={resources} 
                      onClick={() => handleMultiTrain(EntityType.MARINE)} 
                      progress={singleSelection ? singleSelection.trainProgress : 0} max={STATS[EntityType.MARINE].buildTime} queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
                  <CommandButton 
                      label="Train Medic" sub="75" hotkey="E" cost={75} res={resources} 
                      onClick={() => handleMultiTrain(EntityType.MEDIC)} 
                      progress={singleSelection ? singleSelection.trainProgress : 0} max={STATS[EntityType.MEDIC].buildTime} queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
                  </>
              )}

              {singleSelection?.type === EntityType.BUNKER && singleSelection.owner === Owner.PLAYER && (
                  <button 
                      onClick={handleUnload}
                      className="bg-slate-700 border border-slate-500 hover:bg-slate-600 active:bg-slate-500 rounded flex flex-col items-center justify-center relative shadow-sm"
                  >
                      <span className="text-yellow-400 font-bold text-xs absolute top-1 right-1">D</span>
                      <span className="text-white text-[10px] font-bold mt-1">UNLOAD</span>
                  </button>
              )}
          </div>
      </div>
    </div>
  );
};

const CommandButton = ({ label, sub, hotkey, cost, res, onClick, progress, max, queue }: any) => {
    const disabled = res < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`
                relative rounded border flex flex-col items-center justify-center p-1 transition-all
                ${disabled 
                    ? 'bg-slate-800 border-slate-700 opacity-50 cursor-not-allowed' 
                    : 'bg-slate-700 border-slate-500 hover:bg-slate-600 active:bg-slate-500 hover:border-cyan-400 shadow-md'}
            `}
        >
            <span className="absolute top-1 right-1 text-xs font-bold text-yellow-400 leading-none">{hotkey}</span>
            <span className="text-[10px] text-slate-200 font-bold leading-tight text-center mt-2">{label}</span>
            <span className="text-[9px] text-cyan-300 leading-none">{sub}</span>

            {queue > 0 && <span className="absolute top-1 left-1 bg-blue-600 text-white text-[9px] w-4 h-4 rounded-full flex items-center justify-center shadow">{queue}</span>}

            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-slate-900 rounded-b">
                    <div className="h-full bg-white opacity-80" style={{ width: `${(progress / max) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

// Simple synth audio service
let audioCtx: AudioContext | null = null;
let isMuted = false;

// Shared buffers
let explosionBuffer: AudioBuffer | null = null;
let noiseBuffer: AudioBuffer | null = null;

const getCtx = () => {
    if (!audioCtx) {
        audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        // Create buffers once
        noiseBuffer = createNoiseBuffer(audioCtx, 2);
    }
    return audioCtx;
};

export const toggleMute = () => {
    isMuted = !isMuted;
    return isMuted;
};

export const getMuteState = () => isMuted;

const createNoiseBuffer = (ctx: AudioContext, duration: number) => {
    const bufferSize = ctx.sampleRate * duration;
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
        data[i] = Math.random() * 2 - 1;
    }
    return buffer;
};

export const playSound = (type: 'shoot' | 'explosion' | 'train' | 'build' | 'error' | 'click') => {
    if (isMuted) return;
    const ctx = getCtx();
    if (ctx.state === 'suspended') ctx.resume();

    const now = ctx.currentTime;
    const masterGain = ctx.createGain();
    masterGain.connect(ctx.destination);

    // Helper for envelopes
    const ramp = (param: AudioParam, start: number, end: number, dur: number) => {
        param.setValueAtTime(start, now);
        param.exponentialRampToValueAtTime(end, now + dur);
    };

    if (type === 'shoot') {
        // 1. "Kick" - low punch
        const osc = ctx.createOscillator();
        osc.frequency.setValueAtTime(150, now);
        osc.frequency.exponentialRampToValueAtTime(50, now + 0.1);
        const oscGain = ctx.createGain();
        ramp(oscGain.gain, 0.3, 0.001, 0.1);
        osc.connect(oscGain);
        oscGain.connect(masterGain);
        osc.start(now);
        osc.stop(now + 0.1);

        // 2. "Snap" - high frequency noise
        if (noiseBuffer) {
            const noise = ctx.createBufferSource();
            noise.buffer = noiseBuffer;
            const noiseFilter = ctx.createBiquadFilter();
            noiseFilter.type = 'highpass';
            noiseFilter.frequency.value = 1000;
            const noiseGain = ctx.createGain();
            ramp(noiseGain.gain, 0.2, 0.001, 0.08);
            noise.connect(noiseFilter);
            noiseFilter.connect(noiseGain);
            noiseGain.connect(masterGain);
            noise.start(now);
            noise.stop(now + 0.1);
        }
    } 
    else if (type === 'explosion') {
        // Deep rumble
        if (noiseBuffer) {
            const noise = ctx.createBufferSource();
            noise.buffer = noiseBuffer;
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            ramp(filter.frequency, 800, 100, 0.8);

            const gain = ctx.createGain();
            ramp(gain.gain, 0.8, 0.001, 0.8);

            noise.connect(filter);
            filter.connect(gain);
            gain.connect(masterGain);
            noise.start(now);
            noise.stop(now + 1.0);
        }
    }
    else if (type === 'train') {
        // Sci-fi servo sound
        const osc = ctx.createOscillator();
        osc.type = 'sawtooth';
        ramp(osc.frequency, 200, 800, 0.4);

        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0, now);
        gain.gain.linearRampToValueAtTime(0.1, now + 0.1);
        gain.gain.linearRampToValueAtTime(0, now + 0.4);

        const filter = ctx.createBiquadFilter();
        filter.type = 'lowpass';
        ramp(filter.frequency, 400, 2000, 0.4);

        osc.connect(filter);
        filter.connect(gain);
        gain.connect(masterGain);
        osc.start(now);
        osc.stop(now + 0.4);
    }
    else if (type === 'build') {
        // Heavy metallic ratchet
        const osc = ctx.createOscillator();
        osc.type = 'square';
        osc.frequency.setValueAtTime(80, now);

        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0.15, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);

        // AM Modulation for "ratchet" texture
        const lfo = ctx.createOscillator();
        lfo.type = 'square';
        lfo.frequency.value = 25;
        const lfoGain = ctx.createGain();
        lfoGain.gain.value = 500;
        lfo.connect(lfoGain);
        lfoGain.connect(osc.frequency);
        lfo.start(now);

        osc.connect(gain);
        gain.connect(masterGain);
        osc.start(now);
        osc.stop(now + 0.2);
    }
    else if (type === 'error') {
        // Digital Buzzer
        const osc1 = ctx.createOscillator();
        const osc2 = ctx.createOscillator();
        osc1.type = 'sawtooth';
        osc2.type = 'square';
        osc1.frequency.value = 150;
        osc2.frequency.value = 155; // Detuned

        const gain = ctx.createGain();
        ramp(gain.gain, 0.1, 0.001, 0.3);

        osc1.connect(gain);
        osc2.connect(gain);
        gain.connect(masterGain);
        osc1.start(now);
        osc2.start(now);
        osc1.stop(now + 0.3);
        osc2.stop(now + 0.3);
    }
    else if (type === 'click') {
        // Crisp blip
        const osc = ctx.createOscillator();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(2000, now);
        osc.frequency.exponentialRampToValueAtTime(1000, now + 0.05);

        const gain = ctx.createGain();
        ramp(gain.gain, 0.1, 0.001, 0.05);

        osc.connect(gain);
        gain.connect(masterGain);
        osc.start(now);
        osc.stop(now + 0.05);
    }
};

import React, { useEffect, useRef, useState } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

export const GameCanvas: React.FC<Props> = ({ 
    onGameStateUpdate, 
    onSelectionChange, 
    commandMode, 
    setCommandMode,
    isMultiplayer = false,
    gameSeed = 0,
    isHost = true,
    difficulty = Difficulty.MEDIUM
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame(difficulty, isMultiplayer, gameSeed, isHost));
  const requestRef = useRef<number>(0);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });

  // Offscreen Buffers
  const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false);
  const isRightDragging = useRef(false);
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  useEffect(() => {
    const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Initialize Assets
  useEffect(() => {
      terrainCanvasRef.current = renderTerrain();

      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;

      onGameStateUpdate({ ...gameStateRef.current });

      // Center camera
      const entities = Array.from(gameStateRef.current.entities.values()) as Entity[];
      const myBase = entities.find(e => e.type === EntityType.BASE && e.owner === Owner.PLAYER);
      if (myBase) {
          gameStateRef.current.camera.x = Math.max(0, myBase.position.x - window.innerWidth / 2);
          gameStateRef.current.camera.y = Math.max(0, myBase.position.y - (window.innerHeight - UI_TOP_HEIGHT) / 2);
      }
  }, []);

  useEffect(() => {
      if (!isMultiplayer) return;
      const handleNetMsg = (msg: NetMessage) => {
          if (msg.type === 'GAME_COMMAND') {
              const { action, data, owner } = msg.payload;
              if (owner !== Owner.PLAYER) {
                 const event = new CustomEvent('GAME_COMMAND', { detail: { ...data, action, _isRemote: true } });
                 window.dispatchEvent(event);
              }
          }
      };
      const unsubscribe = network.subscribe(handleNetMsg);
      return unsubscribe;
  }, [isMultiplayer]);

  // Game Command Handler
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail as any;
          const isRemote = detail._isRemote;

          if (isMultiplayer && !isRemote) {
              if (!['MOVE_CAMERA', 'TOGGLE_PAUSE'].includes(detail.action)) {
                  network.send({ type: 'GAME_COMMAND', payload: { action: detail.action, data: detail, owner: Owner.PLAYER } });
              }
          }

          if (detail.action === 'RESTART' && !isMultiplayer) {
                gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
                if (exploredCanvasRef.current) {
                    const ctx = exploredCanvasRef.current.getContext('2d');
                    if (ctx) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.fillStyle = 'black';
                        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                    }
                }
                onGameStateUpdate({ ...gameStateRef.current });
                return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA' && !isRemote) {
              const UI_BOTTOM_HEIGHT = 224;
              const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
              const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
              gameStateRef.current.camera = { x: Math.max(0, Math.min(detail.x, maxCamX)), y: Math.max(0, Math.min(detail.y, maxCamY)) };
              return;
          }

          // Simplified Game Logic forwarding (Ideally moved to a shared reducer)
          // For now we trust the event handlers in updateGame loop or specific logic here
          const logicEvents = ['TRAIN', 'UNLOAD_ALL', 'SET_RALLY', 'MINIMAP_ACTION', 'UNIT_COMMAND'];
          if (logicEvents.includes(detail.action)) {
             // Logic handling is partly distributed between UI (dispatch) and Game Loop (update)
             // But direct state mutations happen here for immediate feedback before next frame
             // Actually, game state updates happen in the loop or specific helpers.
             // We'll reimplement specific command handling here to keep it working:
             const ents = gameStateRef.current.entities;
             if (detail.action === 'TRAIN') {
                 const ent = ents.get(detail.id);
                 const owner = isRemote ? Owner.OPPONENT : Owner.PLAYER;
                 if (ent && ent.owner === owner) {
                     const s = STATS[detail.type as EntityType];
                     if (gameStateRef.current.resources[owner] >= s.cost) {
                         if (!ent.trainQueue) ent.trainQueue = [];
                         if (ent.trainQueue.length < 5) {
                             ent.trainQueue.push(detail.type);
                             gameStateRef.current.resources[owner] -= s.cost;
                             if(!isRemote) playSound('train');
                         }
                     } else if (!isRemote) { playSound('error'); addNotification(gameStateRef.current, "Not Enough Minerals"); }
                 }
             }
             if (detail.action === 'MINIMAP_ACTION' && !isRemote) {
                 const selected = gameStateRef.current.selection;
                 const pos = {x: detail.x, y: detail.y};
                 gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: pos, type: 'MOVE', life: 20, maxLife: 20 });
                 selected.forEach(id => {
                     const u = ents.get(id);
                     if (u && u.owner === Owner.PLAYER) {
                         u.state = 'MOVING';
                         u.targetPosition = pos;
                         u.targetId = null;
                         if (u.type === EntityType.MARINE && detail.unitAction === 'ATTACK') u.state = 'ATTACKING';
                     }
                 });
                 playSound('click');
             }
             if (detail.action === 'SET_RALLY') {
                 const ent = ents.get(detail.id);
                 if (ent) { ent.rallyPoint = detail.pos; ent.rallyTargetId = detail.targetId; if(!isRemote) playSound('click'); }
             }
             if (detail.action === 'UNLOAD_ALL') {
                  const ent = ents.get(detail.id);
                  if (ent && ent.garrison) {
                      ent.garrison.forEach(uid => {
                          const u = ents.get(uid);
                          if (u) {
                              u.state = 'IDLE'; u.containerId = null;
                              u.position = { x: ent.position.x + (Math.random()*40-20), y: ent.position.y + 30 };
                          }
                      });
                      ent.garrison = [];
                      if(!isRemote) playSound('click');
                  }
             }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, [isMultiplayer, windowSize]);

  // Input Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);
          if ((e.target as HTMLElement).tagName === 'INPUT') return;
          const key = e.key.toUpperCase();
          if (key === 'A') setCommandMode('ATTACK');
          if (key === 'P') { gameStateRef.current.paused = !gameStateRef.current.paused; onGameStateUpdate({...gameStateRef.current}); }
          // Group logic skipped for brevity, works as before
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
  }, [setCommandMode]);

  const getWorldPos = (cx: number, cy: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: cx - rect.left + gameStateRef.current.camera.x, y: cy - rect.top + gameStateRef.current.camera.y };
  };

  const isEntityVisible = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // --- DRAWING ---
  const drawUnit = (ctx: CanvasRenderingContext2D, entity: Entity, isSelected: boolean) => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      const isPlayer = entity.owner === Owner.PLAYER;
      const primaryColor = isPlayer ? '#3b82f6' : '#ef4444'; // Blue : Red
      const secondaryColor = isPlayer ? '#1e40af' : '#991b1b';

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
      ctx.fill();

      // Construction
      if (entity.constructionProgress! < 100) {
          ctx.globalAlpha = 0.6;
          // Scaffold
          ctx.strokeStyle = '#fbbf24';
          ctx.setLineDash([4, 2]);
          ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
          ctx.setLineDash([]);
      }

      if (entity.type === EntityType.WORKER) {
          // Body
          const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
          grad.addColorStop(0, '#e5e7eb');
          grad.addColorStop(1, '#9ca3af');
          ctx.fillStyle = grad;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Backpack (Resources)
          if (entity.resourceAmount && entity.resourceAmount > 0) {
              ctx.fillStyle = '#06b6d4'; // Blue crystal
              ctx.fillRect(-4, -6, 8, 4);
          } else {
              ctx.fillStyle = '#374151'; // Empty pack
              ctx.fillRect(-4, -5, 8, 3);
          }

          // Drill Arm
          ctx.fillStyle = '#4b5563';
          ctx.save();
          const angle = entity.targetPosition ? Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x) : 0;
          ctx.rotate(angle);
          ctx.fillRect(4, -1, 6, 2); // Arm
          ctx.fillStyle = '#d1d5db';
          ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(14, 0); ctx.lineTo(10, 2); ctx.fill(); // Tip
          ctx.restore();

      } else if (entity.type === EntityType.MARINE) {
          // Shoulders
          ctx.fillStyle = secondaryColor;
          ctx.beginPath(); ctx.arc(-5, -2, 3, 0, Math.PI * 2); ctx.fill();
          ctx.beginPath(); ctx.arc(5, -2, 3, 0, Math.PI * 2); ctx.fill();

          // Body
          ctx.fillStyle = primaryColor;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Gun
          ctx.save();
          // Ideally rotate towards target, simplified:
          if (entity.state === 'ATTACKING') {
              const tId = entity.targetId;
              // We'd need target position here to rotate correctly, but visual abstraction is OK
          }
          ctx.fillStyle = '#111827';
          ctx.fillRect(2, -1, 10, 3); // Gun barrel
          ctx.restore();

          // Visor reflection
          ctx.fillStyle = 'rgba(255,255,255,0.8)';
          ctx.beginPath(); ctx.arc(1, -2, 1.5, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.MEDIC) {
          ctx.fillStyle = '#fff';
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
          // Cross
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(-2, -5, 4, 10);
          ctx.fillRect(-5, -2, 10, 4);
          // Shield/Pack
          ctx.strokeStyle = '#d1d5db';
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.stroke();

      } else if (entity.type === EntityType.BASE) {
          // Base Plate
          ctx.fillStyle = '#374151';
          ctx.fillRect(-30, -30, 60, 60);

          // Structure
          const grad = ctx.createLinearGradient(-30, -30, 30, 30);
          grad.addColorStop(0, primaryColor);
          grad.addColorStop(1, secondaryColor);
          ctx.fillStyle = grad;
          ctx.fillRect(-25, -25, 50, 50);

          // Detail Lines
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.lineWidth = 2;
          ctx.beginPath(); 
          ctx.moveTo(-25, 0); ctx.lineTo(25, 0); 
          ctx.moveTo(0, -25); ctx.lineTo(0, 25);
          ctx.stroke();

          // Center Hub
          ctx.fillStyle = '#111827';
          ctx.fillRect(-10, -10, 20, 20);
          // Blinking Light
          const blink = Math.sin(Date.now() / 200) > 0;
          ctx.fillStyle = blink ? '#ef4444' : '#7f1d1d';
          ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.BARRACKS) {
          ctx.fillStyle = '#1f2937';
          ctx.fillRect(-25, -25, 50, 50);

          // Roof Hatch
          ctx.fillStyle = primaryColor;
          ctx.beginPath();
          ctx.moveTo(-20, -20); ctx.lineTo(20, -20); ctx.lineTo(15, 15); ctx.lineTo(-15, 15);
          ctx.fill();

          // Stripes
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(-15, 15); ctx.lineTo(-15, 25);
          ctx.moveTo(15, 15); ctx.lineTo(15, 25);
          ctx.stroke();

      } else if (entity.type === EntityType.MINERAL) {
          // Crystals
          ctx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Glow
          ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();

          ctx.fillStyle = '#06b6d4';
          const drawCrystal = (ox: number, oy: number, s: number, r: number) => {
              ctx.save();
              ctx.translate(ox, oy);
              ctx.rotate(r);
              ctx.beginPath();
              ctx.moveTo(0, -s); ctx.lineTo(s*0.6, 0); ctx.lineTo(0, s); ctx.lineTo(-s*0.6, 0);
              ctx.fill();
              // Facet
              ctx.fillStyle = '#67e8f9';
              ctx.beginPath(); ctx.moveTo(0, -s); ctx.lineTo(s*0.3, 0); ctx.lineTo(0, s*0.4);
              ctx.fill();
              ctx.fillStyle = '#06b6d4'; // Reset
              ctx.restore();
          };

          drawCrystal(0, -5, 10, 0);
          drawCrystal(-6, 4, 8, -0.5);
          drawCrystal(6, 4, 8, 0.5);

      } else if (entity.type === EntityType.MOUNTAIN) {
          ctx.fillStyle = '#44403c';
          ctx.beginPath();
          // Irregular rock shape
          ctx.moveTo(-30, 20); ctx.lineTo(-10, 30); ctx.lineTo(20, 25); ctx.lineTo(35, 0);
          ctx.lineTo(20, -30); ctx.lineTo(-10, -35); ctx.lineTo(-35, -10);
          ctx.fill();

          // Highlights
          ctx.fillStyle = '#57534e';
          ctx.beginPath();
          ctx.moveTo(-10, -20); ctx.lineTo(10, -10); ctx.lineTo(0, 10);
          ctx.fill();

      } else if (entity.type === EntityType.WATER) {
          ctx.fillStyle = '#1e3a8a';
          ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(0,0, 28, 0, Math.PI*2); ctx.stroke();
      }

      // Selection Ring
      if (isSelected) {
          ctx.strokeStyle = '#10b981';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
          ctx.stroke();

          // Health Bar (Only if selected or damaged)
          const pct = Math.max(0, entity.hp / entity.maxHp);
          const w = 24;
          ctx.fillStyle = '#000';
          ctx.fillRect(-w/2 - 1, -entity.radius - 12, w + 2, 6);
          ctx.fillStyle = pct > 0.5 ? '#10b981' : '#ef4444';
          ctx.fillRect(-w/2, -entity.radius - 11, w * pct, 4);
      } else if (entity.hp < entity.maxHp) {
           const pct = Math.max(0, entity.hp / entity.maxHp);
           const w = 20;
           ctx.fillStyle = '#000';
           ctx.fillRect(-w/2, -entity.radius - 8, w, 4);
           ctx.fillStyle = '#ef4444'; 
           ctx.fillRect(-w/2, -entity.radius - 8, w * pct, 4);
      }

      ctx.restore();
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    const allEntities = Array.from(state.entities.values()) as Entity[];
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG & TERRAIN ---
    // Draw Terrain Cache
    if (terrainCanvasRef.current) {
        // Draw terrain shifted by camera
        ctx.drawImage(terrainCanvasRef.current, -state.camera.x, -state.camera.y);
    } else {
        ctx.fillStyle = '#111'; ctx.fillRect(0,0,width,height);
    }

    // Fog Calculation
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.7)'; // Darker fog
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath(); ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxExp.fill();
                ctxVis.beginPath(); ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxVis.fill();
            });
        }

        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
        // Draw Explored (Darkened Terrain)
        ctx.drawImage(exploredCanvasRef.current, 0, 0);
        // We need to re-apply the terrain 'under' the FOW? 
        // Actually, normally you draw terrain, then draw FOW overlay.
        // FOW overlay is black with alpha.
    } else {
        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
    }

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2;
             const r = 10 * (1 + (1-lifePct));
             ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0, -r); ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
             const r = 10;
             ctx.beginPath(); ctx.moveTo(-r, -r); ctx.lineTo(r, r); ctx.moveTo(r, -r); ctx.lineTo(-r, r); ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    // Sort by Y for pseudo-depth
    const sorted = [...allEntities].sort((a,b) => a.position.y - b.position.y);
    sorted.forEach((entity: Entity) => {
      if (!visibleEntities.has(entity.id)) return;
      const isSelected = state.selection.includes(entity.id);
      drawUnit(ctx, entity, isSelected);

      // Rally Lines
      if (isSelected && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.strokeStyle = '#f59e0b'; ctx.setLineDash([5, 5]); ctx.beginPath();
          ctx.moveTo(entity.position.x, entity.position.y); ctx.lineTo(entity.rallyPoint.x, entity.rallyPoint.y);
          ctx.stroke(); ctx.setLineDash([]);
      }

      // Attack Beams
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? '#facc15' : 'white';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y - 5);
              ctx.lineTo(target.position.x, target.position.y - 5);
              ctx.stroke();

              // Hit flash
              ctx.fillStyle = '#fff';
              ctx.beginPath(); ctx.arc(target.position.x, target.position.y - 5, 5, 0, Math.PI*2); ctx.fill();
          }
      }
    });

    // Effects
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION' || fx.type === 'BUILDING_EXPLOSION') {
            const r = (1 - lifePct) * (fx.type === 'BUILDING_EXPLOSION' ? 100 : 40) * fx.scale;
            const alpha = lifePct;
            ctx.globalAlpha = alpha;
            const grad = ctx.createRadialGradient(0,0,0,0,0,r);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, '#f59e0b');
            grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2; ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0,-15*lifePct); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-3,-15*lifePct); ctx.lineTo(3,-15*lifePct); ctx.stroke();
        }
        ctx.restore();
    });

    // Draw Fog Overlay on top
    if (visionCanvasRef.current) {
         ctx.drawImage(visionCanvasRef.current, 0, 0);
    }

    ctx.restore(); // Pop Camera

    // Screen Space UI (Selection Box)
    if (mouseDownStateRef.current) {
        const startScreen = mouseDownStateRef.current.screen;
        const curScreen = mousePos;
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(startScreen.x, startScreen.y, curScreen.x - startScreen.x, curScreen.y - startScreen.y);
        ctx.setLineDash([]);
    }

    // Build Preview
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = getWorldPos(mousePos.x, mousePos.y);
       const stats = STATS[type];

       ctx.save();
       ctx.translate(worldMouse.x - gameStateRef.current.camera.x, worldMouse.y - gameStateRef.current.camera.y);

       const valid = gameStateRef.current.resources[Owner.PLAYER] >= stats.cost;
       ctx.fillStyle = valid ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)';
       ctx.fillRect(-stats.width/2, -stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = '#fff';
       ctx.strokeRect(-stats.width/2, -stats.height/2, stats.width, stats.height);

       ctx.restore();
    }

    // Notification & Pause UI
    if (state.paused) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white'; ctx.font = 'bold 48px monospace'; ctx.textAlign = 'center';
        ctx.fillText('PAUSED', width / 2, height / 2);
    }
    if (state.notifications.length > 0) {
        ctx.font = 'bold 20px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#f87171';
        state.notifications.forEach((n, i) => {
            const y = height - 300 - (i * 30);
            ctx.globalAlpha = n.life / 60;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.globalAlpha = 1;
    }
  };

  // Loop & Input Handlers (Same as previous)
  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }
    const mousePos = mousePosRef.current;

    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > windowSize.height - margin && mousePos.y <= windowSize.height) gameStateRef.current.camera.y += panSpeed;
    }

    const UI_BOTTOM_HEIGHT = 224; 
    const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
    const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, maxCamX));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, maxCamY));

    if (canvasRef.current) draw(canvasRef.current.getContext('2d')!);
    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused || gameStateRef.current.victory) {
        onGameStateUpdate({ ...gameStateRef.current });
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (gameStateRef.current.paused) return;
      if (e.button === 1) { e.preventDefault(); isDraggingCamera.current = true; lastDragPos.current = { x: e.clientX, y: e.clientY }; return; }
      if (e.button === 2) { e.preventDefault(); rightDragStart.current = { x: e.clientX, y: e.clientY }; lastDragPos.current = { x: e.clientX, y: e.clientY }; isRightDragging.current = false; return; }
      if (e.button === 0) {
          if (commandMode === 'ATTACK') {
              const pos = getWorldPos(e.clientX, e.clientY);
              const all = Array.from(gameStateRef.current.entities.values());
              const pUnits = all.filter(en => en.owner === Owner.PLAYER);
              const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

              gameStateRef.current.selection.forEach(id => {
                 const u = gameStateRef.current.entities.get(id);
                 if (u && u.owner === Owner.PLAYER) {
                     u.state = 'ATTACKING'; u.targetPosition = pos; u.targetId = target ? target.id : null;
                     if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'UNIT_COMMAND', subAction: 'ATTACK', unitId: id, targetPos: pos, targetId: target?.id } }));
                 }
              });
              gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: target ? target.position : pos, type: 'ATTACK', life: 20, maxLife: 20 });
              setCommandMode(null); playSound('click'); return;
          }
          if (commandMode && commandMode.startsWith('BUILD_')) {
              const type = commandMode.replace('BUILD_', '') as EntityType;
              const pos = getWorldPos(e.clientX, e.clientY);
              const s = STATS[type];
              if (gameStateRef.current.resources[Owner.PLAYER] >= s.cost) {
                  gameStateRef.current.resources[Owner.PLAYER] -= s.cost;
                  const b = createEntity(type, Owner.PLAYER, pos, `${network.id}_b_${Math.random()}`);
                  b.constructionProgress = 0; gameStateRef.current.entities.set(b.id, b);
                  setCommandMode(null); playSound('build');
                  if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'BUILD', type, pos } }));
              } else { addNotification(gameStateRef.current, "Not Enough Minerals"); playSound('error'); }
              return;
          }
          const wPos = getWorldPos(e.clientX, e.clientY);
          mouseDownStateRef.current = { screen: {x:e.clientX, y:e.clientY}, world: wPos };
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };
    if (gameStateRef.current.paused) return;
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) isRightDragging.current = true;
        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;
     if (e.button === 1) { isDraggingCamera.current = false; return; }
     if (e.button === 2) {
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const all = Array.from(gameStateRef.current.entities.values());
             const pUnits = all.filter(en => en.owner === Owner.PLAYER);
             const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

             // Same Logic as before, just triggering minimap actions
             // Simplification: We dispatch an internal event or call logic directly
             // Reusing the click logic from original file:
             const selection = gameStateRef.current.selection;
             if (selection.length > 0) {
                 const hasBuildings = selection.some(id => { const u=gameStateRef.current.entities.get(id); return u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE || u.type===EntityType.BARRACKS)});
                 if (hasBuildings) {
                     selection.forEach(id => {
                         const u=gameStateRef.current.entities.get(id);
                         if(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE||u.type===EntityType.BARRACKS)) {
                             window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action:'SET_RALLY', id:u.id, pos, targetId: target?target.id:null}}));
                         }
                     });
                 } else {
                     playSound('click');
                     let moveType = 'MOVE';
                     let tId = null;
                     if (target && target.owner !== Owner.PLAYER) { moveType = 'ATTACK'; tId = target.id; }
                     else if (target && target.type === EntityType.MINERAL) { moveType = 'GATHER'; tId = target.id; }

                     // Dispatch for local processing
                     window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y, unitAction: moveType, targetId: tId }}));
                 }
             }
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         // Selection Box Logic
         const start = mouseDownStateRef.current.world;
         const cur = getWorldPos(e.clientX, e.clientY);
         const dist = Math.sqrt(Math.pow(e.clientX - mouseDownStateRef.current.screen.x, 2) + Math.pow(e.clientY - mouseDownStateRef.current.screen.y, 2));
         const isClick = dist < 5;

         const minX = Math.min(start.x, cur.x); const maxX = Math.max(start.x, cur.x);
         const minY = Math.min(start.y, cur.y); const maxY = Math.max(start.y, cur.y);

         const newSel: string[] = [];
         const all = Array.from(gameStateRef.current.entities.values());
         const pUnits = all.filter(en => en.owner === Owner.PLAYER);

         all.forEach(en => {
             if (en.type === EntityType.MOUNTAIN || en.type === EntityType.WATER || en.state==='GARRISONED') return;
             if (!isEntityVisible(en, pUnits)) return;
             if (!isClick && en.owner !== Owner.PLAYER) return;

             if (isClick) {
                 if (Math.sqrt(Math.pow(en.position.x-cur.x,2)+Math.pow(en.position.y-cur.y,2)) < en.radius+15) newSel.push(en.id);
             } else {
                 if (en.position.x > minX && en.position.x < maxX && en.position.y > minY && en.position.y < maxY && en.owner === Owner.PLAYER) newSel.push(en.id);
             }
         });

         if (isClick && newSel.length > 0) { playSound('click'); gameStateRef.current.selection = [newSel[0]]; }
         else if (newSel.length > 0) {
              const nonBuildings = newSel.filter(id => { const t = gameStateRef.current.entities.get(id)?.type; return t!==EntityType.BASE && t!==EntityType.BARRACKS && t!==EntityType.SUPPLY_DEPOT && t!==EntityType.BUNKER });
              gameStateRef.current.selection = nonBuildings.length > 0 ? nonBuildings : newSel;
         } else {
             gameStateRef.current.selection = [];
         }

         onSelectionChange(gameStateRef.current.selection.map(id => gameStateRef.current.entities.get(id)!).filter(Boolean));
         mouseDownStateRef.current = null;
     }
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  return (
    <canvas
      ref={canvasRef}
      width={windowSize.width}
      height={windowSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { mouseDownStateRef.current=null; isDraggingCamera.current=false; isRightDragging.current=false; }}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

export const GameCanvas: React.FC<Props> = ({ 
    onGameStateUpdate, 
    onSelectionChange, 
    commandMode, 
    setCommandMode,
    isMultiplayer = false,
    gameSeed = 0,
    isHost = true,
    difficulty = Difficulty.MEDIUM
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame(difficulty, isMultiplayer, gameSeed, isHost));
  const requestRef = useRef<number>(0);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });

  // Offscreen Buffers
  const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false);
  const isRightDragging = useRef(false);
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  useEffect(() => {
    const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Initialize Assets
  useEffect(() => {
      terrainCanvasRef.current = renderTerrain();

      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;

      onGameStateUpdate({ ...gameStateRef.current });

      // Center camera
      const entities = Array.from(gameStateRef.current.entities.values()) as Entity[];
      const myBase = entities.find(e => e.type === EntityType.BASE && e.owner === Owner.PLAYER);
      if (myBase) {
          gameStateRef.current.camera.x = Math.max(0, myBase.position.x - window.innerWidth / 2);
          gameStateRef.current.camera.y = Math.max(0, myBase.position.y - (window.innerHeight - UI_TOP_HEIGHT) / 2);
      }
  }, []);

  useEffect(() => {
      if (!isMultiplayer) return;
      const handleNetMsg = (msg: NetMessage) => {
          if (msg.type === 'GAME_COMMAND') {
              const { action, data, owner } = msg.payload;
              if (owner !== Owner.PLAYER) {
                 const event = new CustomEvent('GAME_COMMAND', { detail: { ...data, action, _isRemote: true } });
                 window.dispatchEvent(event);
              }
          }
      };
      const unsubscribe = network.subscribe(handleNetMsg);
      return unsubscribe;
  }, [isMultiplayer]);

  // Game Command Handler
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail as any;
          const isRemote = detail._isRemote;

          if (isMultiplayer && !isRemote) {
              if (!['MOVE_CAMERA', 'TOGGLE_PAUSE'].includes(detail.action)) {
                  network.send({ type: 'GAME_COMMAND', payload: { action: detail.action, data: detail, owner: Owner.PLAYER } });
              }
          }

          if (detail.action === 'RESTART' && !isMultiplayer) {
                gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
                if (exploredCanvasRef.current) {
                    const ctx = exploredCanvasRef.current.getContext('2d');
                    if (ctx) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.fillStyle = 'black';
                        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                    }
                }
                onGameStateUpdate({ ...gameStateRef.current });
                return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA' && !isRemote) {
              const UI_BOTTOM_HEIGHT = 224;
              const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
              const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
              gameStateRef.current.camera = { x: Math.max(0, Math.min(detail.x, maxCamX)), y: Math.max(0, Math.min(detail.y, maxCamY)) };
              return;
          }

          // Simplified Game Logic forwarding (Ideally moved to a shared reducer)
          // For now we trust the event handlers in updateGame loop or specific logic here
          const logicEvents = ['TRAIN', 'UNLOAD_ALL', 'SET_RALLY', 'MINIMAP_ACTION', 'UNIT_COMMAND'];
          if (logicEvents.includes(detail.action)) {
             // Logic handling is partly distributed between UI (dispatch) and Game Loop (update)
             // But direct state mutations happen here for immediate feedback before next frame
             // Actually, game state updates happen in the loop or specific helpers.
             // We'll reimplement specific command handling here to keep it working:
             const ents = gameStateRef.current.entities;
             if (detail.action === 'TRAIN') {
                 const ent = ents.get(detail.id);
                 const owner = isRemote ? Owner.OPPONENT : Owner.PLAYER;
                 if (ent && ent.owner === owner) {
                     const s = STATS[detail.type as EntityType];
                     if (gameStateRef.current.resources[owner] >= s.cost) {
                         if (!ent.trainQueue) ent.trainQueue = [];
                         if (ent.trainQueue.length < 5) {
                             ent.trainQueue.push(detail.type);
                             gameStateRef.current.resources[owner] -= s.cost;
                             if(!isRemote) playSound('train');
                         }
                     } else if (!isRemote) { playSound('error'); addNotification(gameStateRef.current, "Not Enough Minerals"); }
                 }
             }
             if (detail.action === 'MINIMAP_ACTION' && !isRemote) {
                 const selected = gameStateRef.current.selection;
                 const pos = {x: detail.x, y: detail.y};
                 gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: pos, type: 'MOVE', life: 20, maxLife: 20 });
                 selected.forEach(id => {
                     const u = ents.get(id);
                     if (u && u.owner === Owner.PLAYER) {
                         u.state = 'MOVING';
                         u.targetPosition = pos;
                         u.targetId = null;
                         if (u.type === EntityType.MARINE && detail.unitAction === 'ATTACK') u.state = 'ATTACKING';
                     }
                 });
                 playSound('click');
             }
             if (detail.action === 'SET_RALLY') {
                 const ent = ents.get(detail.id);
                 if (ent) { ent.rallyPoint = detail.pos; ent.rallyTargetId = detail.targetId; if(!isRemote) playSound('click'); }
             }
             if (detail.action === 'UNLOAD_ALL') {
                  const ent = ents.get(detail.id);
                  if (ent && ent.garrison) {
                      ent.garrison.forEach(uid => {
                          const u = ents.get(uid);
                          if (u) {
                              u.state = 'IDLE'; u.containerId = null;
                              u.position = { x: ent.position.x + (Math.random()*40-20), y: ent.position.y + 30 };
                          }
                      });
                      ent.garrison = [];
                      if(!isRemote) playSound('click');
                  }
             }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, [isMultiplayer, windowSize]);

  // Input Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);
          if ((e.target as HTMLElement).tagName === 'INPUT') return;
          const key = e.key.toUpperCase();
          if (key === 'A') setCommandMode('ATTACK');
          if (key === 'P') { gameStateRef.current.paused = !gameStateRef.current.paused; onGameStateUpdate({...gameStateRef.current}); }
          // Group logic skipped for brevity, works as before
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
  }, [setCommandMode]);

  const getWorldPos = (cx: number, cy: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: cx - rect.left + gameStateRef.current.camera.x, y: cy - rect.top + gameStateRef.current.camera.y };
  };

  const isEntityVisible = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // --- DRAWING ---
  const drawUnit = (ctx: CanvasRenderingContext2D, entity: Entity, isSelected: boolean) => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      const isPlayer = entity.owner === Owner.PLAYER;
      const primaryColor = isPlayer ? '#3b82f6' : '#ef4444'; // Blue : Red
      const secondaryColor = isPlayer ? '#1e40af' : '#991b1b';

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
      ctx.fill();

      // Construction
      if (entity.constructionProgress! < 100) {
          ctx.globalAlpha = 0.6;
          // Scaffold
          ctx.strokeStyle = '#fbbf24';
          ctx.setLineDash([4, 2]);
          ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
          ctx.setLineDash([]);
      }

      if (entity.type === EntityType.WORKER) {
          // Body
          const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
          grad.addColorStop(0, '#e5e7eb');
          grad.addColorStop(1, '#9ca3af');
          ctx.fillStyle = grad;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Backpack (Resources)
          if (entity.resourceAmount && entity.resourceAmount > 0) {
              ctx.fillStyle = '#06b6d4'; // Blue crystal
              ctx.fillRect(-4, -6, 8, 4);
          } else {
              ctx.fillStyle = '#374151'; // Empty pack
              ctx.fillRect(-4, -5, 8, 3);
          }

          // Drill Arm
          ctx.fillStyle = '#4b5563';
          ctx.save();
          const angle = entity.targetPosition ? Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x) : 0;
          ctx.rotate(angle);
          ctx.fillRect(4, -1, 6, 2); // Arm
          ctx.fillStyle = '#d1d5db';
          ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(14, 0); ctx.lineTo(10, 2); ctx.fill(); // Tip
          ctx.restore();

      } else if (entity.type === EntityType.MARINE) {
          // Shoulders
          ctx.fillStyle = secondaryColor;
          ctx.beginPath(); ctx.arc(-5, -2, 3, 0, Math.PI * 2); ctx.fill();
          ctx.beginPath(); ctx.arc(5, -2, 3, 0, Math.PI * 2); ctx.fill();

          // Body
          ctx.fillStyle = primaryColor;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Gun
          ctx.save();
          // Ideally rotate towards target, simplified:
          if (entity.state === 'ATTACKING') {
              const tId = entity.targetId;
              // We'd need target position here to rotate correctly, but visual abstraction is OK
          }
          ctx.fillStyle = '#111827';
          ctx.fillRect(2, -1, 10, 3); // Gun barrel
          ctx.restore();

          // Visor reflection
          ctx.fillStyle = 'rgba(255,255,255,0.8)';
          ctx.beginPath(); ctx.arc(1, -2, 1.5, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.MEDIC) {
          ctx.fillStyle = '#fff';
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
          // Cross
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(-2, -5, 4, 10);
          ctx.fillRect(-5, -2, 10, 4);
          // Shield/Pack
          ctx.strokeStyle = '#d1d5db';
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.stroke();

      } else if (entity.type === EntityType.BASE) {
          // Base Plate
          ctx.fillStyle = '#374151';
          ctx.fillRect(-30, -30, 60, 60);

          // Structure
          const grad = ctx.createLinearGradient(-30, -30, 30, 30);
          grad.addColorStop(0, primaryColor);
          grad.addColorStop(1, secondaryColor);
          ctx.fillStyle = grad;
          ctx.fillRect(-25, -25, 50, 50);

          // Detail Lines
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.lineWidth = 2;
          ctx.beginPath(); 
          ctx.moveTo(-25, 0); ctx.lineTo(25, 0); 
          ctx.moveTo(0, -25); ctx.lineTo(0, 25);
          ctx.stroke();

          // Center Hub
          ctx.fillStyle = '#111827';
          ctx.fillRect(-10, -10, 20, 20);
          // Blinking Light
          const blink = Math.sin(Date.now() / 200) > 0;
          ctx.fillStyle = blink ? '#ef4444' : '#7f1d1d';
          ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.BARRACKS) {
          ctx.fillStyle = '#1f2937';
          ctx.fillRect(-25, -25, 50, 50);

          // Roof Hatch
          ctx.fillStyle = primaryColor;
          ctx.beginPath();
          ctx.moveTo(-20, -20); ctx.lineTo(20, -20); ctx.lineTo(15, 15); ctx.lineTo(-15, 15);
          ctx.fill();

          // Stripes
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(-15, 15); ctx.lineTo(-15, 25);
          ctx.moveTo(15, 15); ctx.lineTo(15, 25);
          ctx.stroke();

      } else if (entity.type === EntityType.MINERAL) {
          // Crystals
          ctx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Glow
          ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();

          ctx.fillStyle = '#06b6d4';
          const drawCrystal = (ox: number, oy: number, s: number, r: number) => {
              ctx.save();
              ctx.translate(ox, oy);
              ctx.rotate(r);
              ctx.beginPath();
              ctx.moveTo(0, -s); ctx.lineTo(s*0.6, 0); ctx.lineTo(0, s); ctx.lineTo(-s*0.6, 0);
              ctx.fill();
              // Facet
              ctx.fillStyle = '#67e8f9';
              ctx.beginPath(); ctx.moveTo(0, -s); ctx.lineTo(s*0.3, 0); ctx.lineTo(0, s*0.4);
              ctx.fill();
              ctx.fillStyle = '#06b6d4'; // Reset
              ctx.restore();
          };

          drawCrystal(0, -5, 10, 0);
          drawCrystal(-6, 4, 8, -0.5);
          drawCrystal(6, 4, 8, 0.5);

      } else if (entity.type === EntityType.MOUNTAIN) {
          ctx.fillStyle = '#44403c';
          ctx.beginPath();
          // Irregular rock shape
          ctx.moveTo(-30, 20); ctx.lineTo(-10, 30); ctx.lineTo(20, 25); ctx.lineTo(35, 0);
          ctx.lineTo(20, -30); ctx.lineTo(-10, -35); ctx.lineTo(-35, -10);
          ctx.fill();

          // Highlights
          ctx.fillStyle = '#57534e';
          ctx.beginPath();
          ctx.moveTo(-10, -20); ctx.lineTo(10, -10); ctx.lineTo(0, 10);
          ctx.fill();

      } else if (entity.type === EntityType.WATER) {
          ctx.fillStyle = '#1e3a8a';
          ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(0,0, 28, 0, Math.PI*2); ctx.stroke();
      }

      // Selection Ring
      if (isSelected) {
          ctx.strokeStyle = '#10b981';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
          ctx.stroke();

          // Health Bar (Only if selected or damaged)
          const pct = Math.max(0, entity.hp / entity.maxHp);
          const w = 24;
          ctx.fillStyle = '#000';
          ctx.fillRect(-w/2 - 1, -entity.radius - 12, w + 2, 6);
          ctx.fillStyle = pct > 0.5 ? '#10b981' : '#ef4444';
          ctx.fillRect(-w/2, -entity.radius - 11, w * pct, 4);
      } else if (entity.hp < entity.maxHp) {
           const pct = Math.max(0, entity.hp / entity.maxHp);
           const w = 20;
           ctx.fillStyle = '#000';
           ctx.fillRect(-w/2, -entity.radius - 8, w, 4);
           ctx.fillStyle = '#ef4444'; 
           ctx.fillRect(-w/2, -entity.radius - 8, w * pct, 4);
      }

      ctx.restore();
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    const allEntities = Array.from(state.entities.values()) as Entity[];
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG & TERRAIN ---
    // Draw Terrain Cache
    if (terrainCanvasRef.current) {
        // Draw terrain shifted by camera
        ctx.drawImage(terrainCanvasRef.current, -state.camera.x, -state.camera.y);
    } else {
        ctx.fillStyle = '#111'; ctx.fillRect(0,0,width,height);
    }

    // Fog Calculation
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.7)'; // Darker fog
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath(); ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxExp.fill();
                ctxVis.beginPath(); ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxVis.fill();
            });
        }

        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
        // Draw Explored (Darkened Terrain)
        ctx.drawImage(exploredCanvasRef.current, 0, 0);
        // We need to re-apply the terrain 'under' the FOW? 
        // Actually, normally you draw terrain, then draw FOW overlay.
        // FOW overlay is black with alpha.
    } else {
        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
    }

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2;
             const r = 10 * (1 + (1-lifePct));
             ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0, -r); ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
             const r = 10;
             ctx.beginPath(); ctx.moveTo(-r, -r); ctx.lineTo(r, r); ctx.moveTo(r, -r); ctx.lineTo(-r, r); ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    // Sort by Y for pseudo-depth
    const sorted = [...allEntities].sort((a,b) => a.position.y - b.position.y);
    sorted.forEach((entity: Entity) => {
      if (!visibleEntities.has(entity.id)) return;
      const isSelected = state.selection.includes(entity.id);
      drawUnit(ctx, entity, isSelected);

      // Rally Lines
      if (isSelected && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.strokeStyle = '#f59e0b'; ctx.setLineDash([5, 5]); ctx.beginPath();
          ctx.moveTo(entity.position.x, entity.position.y); ctx.lineTo(entity.rallyPoint.x, entity.rallyPoint.y);
          ctx.stroke(); ctx.setLineDash([]);
      }

      // Attack Beams
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? '#facc15' : 'white';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y - 5);
              ctx.lineTo(target.position.x, target.position.y - 5);
              ctx.stroke();

              // Hit flash
              ctx.fillStyle = '#fff';
              ctx.beginPath(); ctx.arc(target.position.x, target.position.y - 5, 5, 0, Math.PI*2); ctx.fill();
          }
      }
    });

    // Effects
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION' || fx.type === 'BUILDING_EXPLOSION') {
            const r = (1 - lifePct) * (fx.type === 'BUILDING_EXPLOSION' ? 100 : 40) * fx.scale;
            const alpha = lifePct;
            ctx.globalAlpha = alpha;
            const grad = ctx.createRadialGradient(0,0,0,0,0,r);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, '#f59e0b');
            grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2; ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0,-15*lifePct); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-3,-15*lifePct); ctx.lineTo(3,-15*lifePct); ctx.stroke();
        }
        ctx.restore();
    });

    // Draw Fog Overlay on top
    if (visionCanvasRef.current) {
         ctx.drawImage(visionCanvasRef.current, 0, 0);
    }

    ctx.restore(); // Pop Camera

    // Screen Space UI (Selection Box)
    if (mouseDownStateRef.current) {
        const startScreen = mouseDownStateRef.current.screen;
        const curScreen = mousePos;
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(startScreen.x, startScreen.y, curScreen.x - startScreen.x, curScreen.y - startScreen.y);
        ctx.setLineDash([]);
    }

    // Build Preview
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = getWorldPos(mousePos.x, mousePos.y);
       const stats = STATS[type];

       ctx.save();
       ctx.translate(worldMouse.x - gameStateRef.current.camera.x, worldMouse.y - gameStateRef.current.camera.y);

       const valid = gameStateRef.current.resources[Owner.PLAYER] >= stats.cost;
       ctx.fillStyle = valid ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)';
       ctx.fillRect(-stats.width/2, -stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = '#fff';
       ctx.strokeRect(-stats.width/2, -stats.height/2, stats.width, stats.height);

       ctx.restore();
    }

    // Notification & Pause UI
    if (state.paused) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white'; ctx.font = 'bold 48px monospace'; ctx.textAlign = 'center';
        ctx.fillText('PAUSED', width / 2, height / 2);
    }
    if (state.notifications.length > 0) {
        ctx.font = 'bold 20px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#f87171';
        state.notifications.forEach((n, i) => {
            const y = height - 300 - (i * 30);
            ctx.globalAlpha = n.life / 60;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.globalAlpha = 1;
    }
  };

  // Loop & Input Handlers (Same as previous)
  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }
    const mousePos = mousePosRef.current;

    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > windowSize.height - margin && mousePos.y <= windowSize.height) gameStateRef.current.camera.y += panSpeed;
    }

    const UI_BOTTOM_HEIGHT = 224; 
    const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
    const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, maxCamX));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, maxCamY));

    if (canvasRef.current) draw(canvasRef.current.getContext('2d')!);
    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused || gameStateRef.current.victory) {
        onGameStateUpdate({ ...gameStateRef.current });
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (gameStateRef.current.paused) return;
      if (e.button === 1) { e.preventDefault(); isDraggingCamera.current = true; lastDragPos.current = { x: e.clientX, y: e.clientY }; return; }
      if (e.button === 2) { e.preventDefault(); rightDragStart.current = { x: e.clientX, y: e.clientY }; lastDragPos.current = { x: e.clientX, y: e.clientY }; isRightDragging.current = false; return; }
      if (e.button === 0) {
          if (commandMode === 'ATTACK') {
              const pos = getWorldPos(e.clientX, e.clientY);
              const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
              const pUnits = all.filter(en => en.owner === Owner.PLAYER);
              const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

              gameStateRef.current.selection.forEach(id => {
                 const u = gameStateRef.current.entities.get(id) as Entity | undefined;
                 if (u && u.owner === Owner.PLAYER) {
                     u.state = 'ATTACKING'; u.targetPosition = pos; u.targetId = target ? target.id : null;
                     if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'UNIT_COMMAND', subAction: 'ATTACK', unitId: id, targetPos: pos, targetId: target?.id } }));
                 }
              });
              gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: target ? target.position : pos, type: 'ATTACK', life: 20, maxLife: 20 });
              setCommandMode(null); playSound('click'); return;
          }
          if (commandMode && commandMode.startsWith('BUILD_')) {
              const type = commandMode.replace('BUILD_', '') as EntityType;
              const pos = getWorldPos(e.clientX, e.clientY);
              const s = STATS[type];
              if (gameStateRef.current.resources[Owner.PLAYER] >= s.cost) {
                  gameStateRef.current.resources[Owner.PLAYER] -= s.cost;
                  const b = createEntity(type, Owner.PLAYER, pos, `${network.id}_b_${Math.random()}`);
                  b.constructionProgress = 0; gameStateRef.current.entities.set(b.id, b);
                  setCommandMode(null); playSound('build');
                  if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'BUILD', type, pos } }));
              } else { addNotification(gameStateRef.current, "Not Enough Minerals"); playSound('error'); }
              return;
          }
          const wPos = getWorldPos(e.clientX, e.clientY);
          mouseDownStateRef.current = { screen: {x:e.clientX, y:e.clientY}, world: wPos };
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };
    if (gameStateRef.current.paused) return;
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) isRightDragging.current = true;
        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;
     if (e.button === 1) { isDraggingCamera.current = false; return; }
     if (e.button === 2) {
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
             const pUnits = all.filter(en => en.owner === Owner.PLAYER);
             const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

             // Same Logic as before, just triggering minimap actions
             // Simplification: We dispatch an internal event or call logic directly
             // Reusing the click logic from original file:
             const selection = gameStateRef.current.selection;
             if (selection.length > 0) {
                 const hasBuildings = selection.some(id => { const u=gameStateRef.current.entities.get(id) as Entity | undefined; return !!(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE || u.type===EntityType.BARRACKS))});
                 if (hasBuildings) {
                     selection.forEach(id => {
                         const u=gameStateRef.current.entities.get(id) as Entity | undefined;
                         if(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE||u.type===EntityType.BARRACKS)) {
                             window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action:'SET_RALLY', id:u.id, pos, targetId: target?target.id:null}}));
                         }
                     });
                 } else {
                     playSound('click');
                     let moveType = 'MOVE';
                     let tId = null;
                     if (target && target.owner !== Owner.PLAYER) { moveType = 'ATTACK'; tId = target.id; }
                     else if (target && target.type === EntityType.MINERAL) { moveType = 'GATHER'; tId = target.id; }

                     // Dispatch for local processing
                     window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y, unitAction: moveType, targetId: tId }}));
                 }
             }
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         // Selection Box Logic
         const start = mouseDownStateRef.current.world;
         const cur = getWorldPos(e.clientX, e.clientY);
         const dist = Math.sqrt(Math.pow(e.clientX - mouseDownStateRef.current.screen.x, 2) + Math.pow(e.clientY - mouseDownStateRef.current.screen.y, 2));
         const isClick = dist < 5;

         const minX = Math.min(start.x, cur.x); const maxX = Math.max(start.x, cur.x);
         const minY = Math.min(start.y, cur.y); const maxY = Math.max(start.y, cur.y);

         const newSel: string[] = [];
         const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
         const pUnits = all.filter(en => en.owner === Owner.PLAYER);

         all.forEach(en => {
             if (en.type === EntityType.MOUNTAIN || en.type === EntityType.WATER || en.state==='GARRISONED') return;
             if (!isEntityVisible(en, pUnits)) return;
             if (!isClick && en.owner !== Owner.PLAYER) return;

             if (isClick) {
                 if (Math.sqrt(Math.pow(en.position.x-cur.x,2)+Math.pow(en.position.y-cur.y,2)) < en.radius+15) newSel.push(en.id);
             } else {
                 if (en.position.x > minX && en.position.x < maxX && en.position.y > minY && en.position.y < maxY && en.owner === Owner.PLAYER) newSel.push(en.id);
             }
         });

         if (isClick && newSel.length > 0) { playSound('click'); gameStateRef.current.selection = [newSel[0]]; }
         else if (newSel.length > 0) {
              const nonBuildings = newSel.filter(id => { const t = (gameStateRef.current.entities.get(id) as Entity | undefined)?.type; return t!==EntityType.BASE && t!==EntityType.BARRACKS && t!==EntityType.SUPPLY_DEPOT && t!==EntityType.BUNKER });
              gameStateRef.current.selection = nonBuildings.length > 0 ? nonBuildings : newSel;
         } else {
             gameStateRef.current.selection = [];
         }

         onSelectionChange(gameStateRef.current.selection.map(id => gameStateRef.current.entities.get(id)!).filter(Boolean) as Entity[]);
         mouseDownStateRef.current = null;
     }
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  return (
    <canvas
      ref={canvasRef}
      width={windowSize.width}
      height={windowSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { mouseDownStateRef.current=null; isDraggingCamera.current=false; isRightDragging.current=false; }}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

export const GameCanvas: React.FC<Props> = ({ 
    onGameStateUpdate, 
    onSelectionChange, 
    commandMode, 
    setCommandMode,
    isMultiplayer = false,
    gameSeed = 0,
    isHost = true,
    difficulty = Difficulty.MEDIUM
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame(difficulty, isMultiplayer, gameSeed, isHost));
  const requestRef = useRef<number>(0);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });

  // Offscreen Buffers
  const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false);
  const isRightDragging = useRef(false);
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  useEffect(() => {
    const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Initialize Assets
  useEffect(() => {
      terrainCanvasRef.current = renderTerrain();

      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;

      onGameStateUpdate({ ...gameStateRef.current });

      // Center camera
      const entities = Array.from(gameStateRef.current.entities.values()) as Entity[];
      const myBase = entities.find(e => e.type === EntityType.BASE && e.owner === Owner.PLAYER);
      if (myBase) {
          gameStateRef.current.camera.x = Math.max(0, myBase.position.x - window.innerWidth / 2);
          gameStateRef.current.camera.y = Math.max(0, myBase.position.y - (window.innerHeight - UI_TOP_HEIGHT) / 2);
      }
  }, []);

  useEffect(() => {
      if (!isMultiplayer) return;
      const handleNetMsg = (msg: NetMessage) => {
          if (msg.type === 'GAME_COMMAND') {
              const { action, data, owner } = msg.payload;
              if (owner !== Owner.PLAYER) {
                 const event = new CustomEvent('GAME_COMMAND', { detail: { ...data, action, _isRemote: true } });
                 window.dispatchEvent(event);
              }
          }
      };
      const unsubscribe = network.subscribe(handleNetMsg);
      return unsubscribe;
  }, [isMultiplayer]);

  // Game Command Handler
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail as any;
          const isRemote = detail._isRemote;

          if (isMultiplayer && !isRemote) {
              if (!['MOVE_CAMERA', 'TOGGLE_PAUSE'].includes(detail.action)) {
                  network.send({ type: 'GAME_COMMAND', payload: { action: detail.action, data: detail, owner: Owner.PLAYER } });
              }
          }

          if (detail.action === 'RESTART' && !isMultiplayer) {
                gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
                if (exploredCanvasRef.current) {
                    const ctx = exploredCanvasRef.current.getContext('2d');
                    if (ctx) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.fillStyle = 'black';
                        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                    }
                }
                onGameStateUpdate({ ...gameStateRef.current });
                return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA' && !isRemote) {
              const UI_BOTTOM_HEIGHT = 224;
              const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
              const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
              gameStateRef.current.camera = { x: Math.max(0, Math.min(detail.x, maxCamX)), y: Math.max(0, Math.min(detail.y, maxCamY)) };
              return;
          }

          const logicEvents = ['TRAIN', 'UNLOAD_ALL', 'SET_RALLY', 'MINIMAP_ACTION', 'UNIT_COMMAND'];
          if (logicEvents.includes(detail.action)) {
             const ents = gameStateRef.current.entities;
             if (detail.action === 'TRAIN') {
                 const ent = ents.get(detail.id);
                 const owner = isRemote ? Owner.OPPONENT : Owner.PLAYER;
                 if (ent && ent.owner === owner) {
                     const s = STATS[detail.type as EntityType];
                     if (gameStateRef.current.resources[owner] >= s.cost) {
                         if (!ent.trainQueue) ent.trainQueue = [];
                         if (ent.trainQueue.length < 5) {
                             ent.trainQueue.push(detail.type);
                             gameStateRef.current.resources[owner] -= s.cost;
                             if(!isRemote) playSound('train');
                         }
                     } else if (!isRemote) { playSound('error'); addNotification(gameStateRef.current, "Not Enough Minerals"); }
                 }
             }
             if (detail.action === 'MINIMAP_ACTION' && !isRemote) {
                 const selected = gameStateRef.current.selection;
                 const pos = {x: detail.x, y: detail.y};
                 gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: pos, type: 'MOVE', life: 20, maxLife: 20 });
                 selected.forEach(id => {
                     const u = ents.get(id);
                     if (u && u.owner === Owner.PLAYER) {
                         u.state = 'MOVING';
                         u.targetPosition = pos;
                         u.targetId = null;
                         if (u.type === EntityType.MARINE && detail.unitAction === 'ATTACK') u.state = 'ATTACKING';
                     }
                 });
                 playSound('click');
             }
             if (detail.action === 'SET_RALLY') {
                 const ent = ents.get(detail.id);
                 if (ent) { ent.rallyPoint = detail.pos; ent.rallyTargetId = detail.targetId; if(!isRemote) playSound('click'); }
             }
             if (detail.action === 'UNLOAD_ALL') {
                  const ent = ents.get(detail.id);
                  if (ent && ent.garrison) {
                      ent.garrison.forEach(uid => {
                          const u = ents.get(uid);
                          if (u) {
                              u.state = 'IDLE'; u.containerId = null;
                              u.position = { x: ent.position.x + (Math.random()*40-20), y: ent.position.y + 30 };
                          }
                      });
                      ent.garrison = [];
                      if(!isRemote) playSound('click');
                  }
             }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, [isMultiplayer, windowSize]);

  // Input Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);
          if ((e.target as HTMLElement).tagName === 'INPUT') return;
          const key = e.key.toUpperCase();
          if (key === 'A') setCommandMode('ATTACK');
          if (key === 'P') { gameStateRef.current.paused = !gameStateRef.current.paused; onGameStateUpdate({...gameStateRef.current}); }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
  }, [setCommandMode]);

  const getWorldPos = (cx: number, cy: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: cx - rect.left + gameStateRef.current.camera.x, y: cy - rect.top + gameStateRef.current.camera.y };
  };

  const isEntityVisible = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // --- DRAWING ---
  const drawUnit = (ctx: CanvasRenderingContext2D, entity: Entity, isSelected: boolean) => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      const isPlayer = entity.owner === Owner.PLAYER;
      const primaryColor = isPlayer ? '#3b82f6' : '#ef4444'; // Blue : Red
      const secondaryColor = isPlayer ? '#1e40af' : '#991b1b';

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
      ctx.fill();

      // Construction
      if (entity.constructionProgress! < 100) {
          ctx.globalAlpha = 0.6;
          // Scaffold
          ctx.strokeStyle = '#fbbf24';
          ctx.setLineDash([4, 2]);
          ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
          ctx.setLineDash([]);
      }

      if (entity.type === EntityType.WORKER) {
          // Body
          const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
          grad.addColorStop(0, '#e5e7eb');
          grad.addColorStop(1, '#9ca3af');
          ctx.fillStyle = grad;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Backpack (Resources)
          if (entity.resourceAmount && entity.resourceAmount > 0) {
              ctx.fillStyle = '#06b6d4'; // Blue crystal
              ctx.fillRect(-4, -6, 8, 4);
          } else {
              ctx.fillStyle = '#374151'; // Empty pack
              ctx.fillRect(-4, -5, 8, 3);
          }

          // Drill Arm
          ctx.fillStyle = '#4b5563';
          ctx.save();
          const angle = entity.targetPosition ? Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x) : 0;
          ctx.rotate(angle);
          ctx.fillRect(4, -1, 6, 2); // Arm
          ctx.fillStyle = '#d1d5db';
          ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(14, 0); ctx.lineTo(10, 2); ctx.fill(); // Tip
          ctx.restore();

      } else if (entity.type === EntityType.MARINE) {
          // Shoulders
          ctx.fillStyle = secondaryColor;
          ctx.beginPath(); ctx.arc(-5, -2, 3, 0, Math.PI * 2); ctx.fill();
          ctx.beginPath(); ctx.arc(5, -2, 3, 0, Math.PI * 2); ctx.fill();

          // Body
          ctx.fillStyle = primaryColor;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Gun
          ctx.save();
          // Ideally rotate towards target, simplified:
          if (entity.state === 'ATTACKING') {
              const tId = entity.targetId;
              // We'd need target position here to rotate correctly, but visual abstraction is OK
          }
          ctx.fillStyle = '#111827';
          ctx.fillRect(2, -1, 10, 3); // Gun barrel
          ctx.restore();

          // Visor reflection
          ctx.fillStyle = 'rgba(255,255,255,0.8)';
          ctx.beginPath(); ctx.arc(1, -2, 1.5, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.MEDIC) {
          ctx.fillStyle = '#fff';
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
          // Cross
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(-2, -5, 4, 10);
          ctx.fillRect(-5, -2, 10, 4);
          // Shield/Pack
          ctx.strokeStyle = '#d1d5db';
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.stroke();

      } else if (entity.type === EntityType.BASE) {
          // Base Plate
          ctx.fillStyle = '#374151';
          ctx.fillRect(-30, -30, 60, 60);

          // Structure
          const grad = ctx.createLinearGradient(-30, -30, 30, 30);
          grad.addColorStop(0, primaryColor);
          grad.addColorStop(1, secondaryColor);
          ctx.fillStyle = grad;
          ctx.fillRect(-25, -25, 50, 50);

          // Detail Lines
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.lineWidth = 2;
          ctx.beginPath(); 
          ctx.moveTo(-25, 0); ctx.lineTo(25, 0); 
          ctx.moveTo(0, -25); ctx.lineTo(0, 25);
          ctx.stroke();

          // Center Hub
          ctx.fillStyle = '#111827';
          ctx.fillRect(-10, -10, 20, 20);
          // Blinking Light
          const blink = Math.sin(Date.now() / 200) > 0;
          ctx.fillStyle = blink ? '#ef4444' : '#7f1d1d';
          ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.BARRACKS) {
          ctx.fillStyle = '#1f2937';
          ctx.fillRect(-25, -25, 50, 50);

          // Roof Hatch
          ctx.fillStyle = primaryColor;
          ctx.beginPath();
          ctx.moveTo(-20, -20); ctx.lineTo(20, -20); ctx.lineTo(15, 15); ctx.lineTo(-15, 15);
          ctx.fill();

          // Stripes
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(-15, 15); ctx.lineTo(-15, 25);
          ctx.moveTo(15, 15); ctx.lineTo(15, 25);
          ctx.stroke();

      } else if (entity.type === EntityType.MINERAL) {
          // Crystals
          ctx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Glow
          ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();

          ctx.fillStyle = '#06b6d4';
          const drawCrystal = (ox: number, oy: number, s: number, r: number) => {
              ctx.save();
              ctx.translate(ox, oy);
              ctx.rotate(r);
              ctx.beginPath();
              ctx.moveTo(0, -s); ctx.lineTo(s*0.6, 0); ctx.lineTo(0, s); ctx.lineTo(-s*0.6, 0);
              ctx.fill();
              // Facet
              ctx.fillStyle = '#67e8f9';
              ctx.beginPath(); ctx.moveTo(0, -s); ctx.lineTo(s*0.3, 0); ctx.lineTo(0, s*0.4);
              ctx.fill();
              ctx.fillStyle = '#06b6d4'; // Reset
              ctx.restore();
          };

          drawCrystal(0, -5, 10, 0);
          drawCrystal(-6, 4, 8, -0.5);
          drawCrystal(6, 4, 8, 0.5);

      } else if (entity.type === EntityType.MOUNTAIN) {
          ctx.fillStyle = '#44403c';
          ctx.beginPath();
          // Irregular rock shape
          ctx.moveTo(-30, 20); ctx.lineTo(-10, 30); ctx.lineTo(20, 25); ctx.lineTo(35, 0);
          ctx.lineTo(20, -30); ctx.lineTo(-10, -35); ctx.lineTo(-35, -10);
          ctx.fill();

          // Highlights
          ctx.fillStyle = '#57534e';
          ctx.beginPath();
          ctx.moveTo(-10, -20); ctx.lineTo(10, -10); ctx.lineTo(0, 10);
          ctx.fill();

      } else if (entity.type === EntityType.WATER) {
          ctx.fillStyle = '#1e3a8a';
          ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(0,0, 28, 0, Math.PI*2); ctx.stroke();
      }

      // Selection Ring
      if (isSelected) {
          ctx.strokeStyle = '#10b981';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
          ctx.stroke();

          // Health Bar (Only if selected or damaged)
          const pct = Math.max(0, entity.hp / entity.maxHp);
          const w = 24;
          ctx.fillStyle = '#000';
          ctx.fillRect(-w/2 - 1, -entity.radius - 12, w + 2, 6);
          ctx.fillStyle = pct > 0.5 ? '#10b981' : '#ef4444';
          ctx.fillRect(-w/2, -entity.radius - 11, w * pct, 4);
      } else if (entity.hp < entity.maxHp) {
           const pct = Math.max(0, entity.hp / entity.maxHp);
           const w = 20;
           ctx.fillStyle = '#000';
           ctx.fillRect(-w/2, -entity.radius - 8, w, 4);
           ctx.fillStyle = '#ef4444'; 
           ctx.fillRect(-w/2, -entity.radius - 8, w * pct, 4);
      }

      ctx.restore();
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    const allEntities = Array.from(state.entities.values()) as Entity[];
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG & TERRAIN ---
    // Draw Terrain Cache
    if (terrainCanvasRef.current) {
        // Draw terrain shifted by camera
        ctx.drawImage(terrainCanvasRef.current, -state.camera.x, -state.camera.y);
    } else {
        ctx.fillStyle = '#111'; ctx.fillRect(0,0,width,height);
    }

    // Fog Calculation
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.7)'; // Darker fog
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath(); ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxExp.fill();
                ctxVis.beginPath(); ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxVis.fill();
            });
        }

        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
        // Draw Explored (Darkened Terrain)
        ctx.drawImage(exploredCanvasRef.current, 0, 0);
    } else {
        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
    }

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2;
             const r = 10 * (1 + (1-lifePct));
             ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0, -r); ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
             const r = 10;
             ctx.beginPath(); ctx.moveTo(-r, -r); ctx.lineTo(r, r); ctx.moveTo(r, -r); ctx.lineTo(-r, r); ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    // Sort by Y for pseudo-depth
    const sorted = [...allEntities].sort((a,b) => a.position.y - b.position.y);
    sorted.forEach((entity: Entity) => {
      if (!visibleEntities.has(entity.id)) return;
      const isSelected = state.selection.includes(entity.id);
      drawUnit(ctx, entity, isSelected);

      // Rally Lines
      if (isSelected && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.strokeStyle = '#f59e0b'; ctx.setLineDash([5, 5]); ctx.beginPath();
          ctx.moveTo(entity.position.x, entity.position.y); ctx.lineTo(entity.rallyPoint.x, entity.rallyPoint.y);
          ctx.stroke(); ctx.setLineDash([]);
      }

      // Attack Beams
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? '#facc15' : 'white';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y - 5);
              ctx.lineTo(target.position.x, target.position.y - 5);
              ctx.stroke();

              // Hit flash
              ctx.fillStyle = '#fff';
              ctx.beginPath(); ctx.arc(target.position.x, target.position.y - 5, 5, 0, Math.PI*2); ctx.fill();
          }
      }
    });

    // Effects
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION' || fx.type === 'BUILDING_EXPLOSION') {
            const r = (1 - lifePct) * (fx.type === 'BUILDING_EXPLOSION' ? 100 : 40) * fx.scale;
            const alpha = lifePct;
            ctx.globalAlpha = alpha;
            const grad = ctx.createRadialGradient(0,0,0,0,0,r);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, '#f59e0b');
            grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2; ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0,-15*lifePct); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-3,-15*lifePct); ctx.lineTo(3,-15*lifePct); ctx.stroke();
        }
        ctx.restore();
    });

    // Draw Fog Overlay on top
    if (visionCanvasRef.current) {
         ctx.drawImage(visionCanvasRef.current, 0, 0);
    }

    ctx.restore(); // Pop Camera

    // Screen Space UI (Selection Box)
    if (mouseDownStateRef.current) {
        const startScreen = mouseDownStateRef.current.screen;
        const curScreen = mousePos;

        // CORRECT COORDINATE TRANSFORMATION FOR CANVAS RENDER
        const rect = ctx.canvas.getBoundingClientRect();
        const startX = startScreen.x - rect.left;
        const startY = startScreen.y - rect.top;
        const curX = curScreen.x - rect.left;
        const curY = curScreen.y - rect.top;

        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(startX, startY, curX - startX, curY - startY);
        ctx.setLineDash([]);
    }

    // Build Preview
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = getWorldPos(mousePos.x, mousePos.y);
       const stats = STATS[type];

       ctx.save();
       ctx.translate(worldMouse.x - gameStateRef.current.camera.x, worldMouse.y - gameStateRef.current.camera.y);

       const valid = gameStateRef.current.resources[Owner.PLAYER] >= stats.cost;
       ctx.fillStyle = valid ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)';
       ctx.fillRect(-stats.width/2, -stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = '#fff';
       ctx.strokeRect(-stats.width/2, -stats.height/2, stats.width, stats.height);

       ctx.restore();
    }

    // Notification & Pause UI
    if (state.paused) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white'; ctx.font = 'bold 48px monospace'; ctx.textAlign = 'center';
        ctx.fillText('PAUSED', width / 2, height / 2);
    }
    if (state.notifications.length > 0) {
        ctx.font = 'bold 20px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#f87171';
        state.notifications.forEach((n, i) => {
            const y = height - 300 - (i * 30);
            ctx.globalAlpha = n.life / 60;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.globalAlpha = 1;
    }
  };

  // Loop & Input Handlers (Same as previous)
  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }
    const mousePos = mousePosRef.current;

    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > windowSize.height - margin && mousePos.y <= windowSize.height) gameStateRef.current.camera.y += panSpeed;
    }

    const UI_BOTTOM_HEIGHT = 224; 
    const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
    const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, maxCamX));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, maxCamY));

    if (canvasRef.current) draw(canvasRef.current.getContext('2d')!);
    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused || gameStateRef.current.victory) {
        onGameStateUpdate({ ...gameStateRef.current });
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (gameStateRef.current.paused) return;
      if (e.button === 1) { e.preventDefault(); isDraggingCamera.current = true; lastDragPos.current = { x: e.clientX, y: e.clientY }; return; }
      if (e.button === 2) { e.preventDefault(); rightDragStart.current = { x: e.clientX, y: e.clientY }; lastDragPos.current = { x: e.clientX, y: e.clientY }; isRightDragging.current = false; return; }
      if (e.button === 0) {
          if (commandMode === 'ATTACK') {
              const pos = getWorldPos(e.clientX, e.clientY);
              const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
              const pUnits = all.filter(en => en.owner === Owner.PLAYER);
              const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

              gameStateRef.current.selection.forEach(id => {
                 const u = gameStateRef.current.entities.get(id) as Entity | undefined;
                 if (u && u.owner === Owner.PLAYER) {
                     u.state = 'ATTACKING'; u.targetPosition = pos; u.targetId = target ? target.id : null;
                     if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'UNIT_COMMAND', subAction: 'ATTACK', unitId: id, targetPos: pos, targetId: target?.id } }));
                 }
              });
              gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: target ? target.position : pos, type: 'ATTACK', life: 20, maxLife: 20 });
              setCommandMode(null); playSound('click'); return;
          }
          if (commandMode && commandMode.startsWith('BUILD_')) {
              const type = commandMode.replace('BUILD_', '') as EntityType;
              const pos = getWorldPos(e.clientX, e.clientY);
              const s = STATS[type];
              if (gameStateRef.current.resources[Owner.PLAYER] >= s.cost) {
                  gameStateRef.current.resources[Owner.PLAYER] -= s.cost;
                  const b = createEntity(type, Owner.PLAYER, pos, `${network.id}_b_${Math.random()}`);
                  b.constructionProgress = 0; gameStateRef.current.entities.set(b.id, b);
                  setCommandMode(null); playSound('build');
                  if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'BUILD', type, pos } }));
              } else { addNotification(gameStateRef.current, "Not Enough Minerals"); playSound('error'); }
              return;
          }
          const wPos = getWorldPos(e.clientX, e.clientY);
          mouseDownStateRef.current = { screen: {x:e.clientX, y:e.clientY}, world: wPos };
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };
    if (gameStateRef.current.paused) return;
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) isRightDragging.current = true;
        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;
     if (e.button === 1) { isDraggingCamera.current = false; return; }
     if (e.button === 2) {
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
             const pUnits = all.filter(en => en.owner === Owner.PLAYER);
             const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

             const selection = gameStateRef.current.selection;
             if (selection.length > 0) {
                 const hasBuildings = selection.some(id => { const u=gameStateRef.current.entities.get(id) as Entity | undefined; return !!(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE || u.type===EntityType.BARRACKS))});
                 if (hasBuildings) {
                     selection.forEach(id => {
                         const u=gameStateRef.current.entities.get(id) as Entity | undefined;
                         if(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE||u.type===EntityType.BARRACKS)) {
                             window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action:'SET_RALLY', id:u.id, pos, targetId: target?target.id:null}}));
                         }
                     });
                 } else {
                     playSound('click');
                     let moveType = 'MOVE';
                     let tId = null;
                     if (target && target.owner !== Owner.PLAYER) { moveType = 'ATTACK'; tId = target.id; }
                     else if (target && target.type === EntityType.MINERAL) { moveType = 'GATHER'; tId = target.id; }

                     window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y, unitAction: moveType, targetId: tId }}));
                 }
             }
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         // Selection Box Logic
         const start = mouseDownStateRef.current.world;
         const cur = getWorldPos(e.clientX, e.clientY);
         const dist = Math.sqrt(Math.pow(e.clientX - mouseDownStateRef.current.screen.x, 2) + Math.pow(e.clientY - mouseDownStateRef.current.screen.y, 2));
         const isClick = dist < 5;

         const minX = Math.min(start.x, cur.x); const maxX = Math.max(start.x, cur.x);
         const minY = Math.min(start.y, cur.y); const maxY = Math.max(start.y, cur.y);

         const newSel: string[] = [];
         const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
         const pUnits = all.filter(en => en.owner === Owner.PLAYER);

         all.forEach(en => {
             if (en.type === EntityType.MOUNTAIN || en.type === EntityType.WATER || en.state==='GARRISONED') return;
             if (!isEntityVisible(en, pUnits)) return;
             if (!isClick && en.owner !== Owner.PLAYER) return;

             if (isClick) {
                 if (Math.sqrt(Math.pow(en.position.x-cur.x,2)+Math.pow(en.position.y-cur.y,2)) < en.radius+15) newSel.push(en.id);
             } else {
                 if (en.position.x > minX && en.position.x < maxX && en.position.y > minY && en.position.y < maxY && en.owner === Owner.PLAYER) newSel.push(en.id);
             }
         });

         if (isClick && newSel.length > 0) { 
             playSound('click'); 
             const clickedId = newSel[0]; 

             // Shift-Click Toggle
             if (e.shiftKey) {
                 const prev = gameStateRef.current.selection;
                 if (prev.includes(clickedId)) {
                     gameStateRef.current.selection = prev.filter(id => id !== clickedId);
                 } else {
                     gameStateRef.current.selection = [...prev, clickedId];
                 }
             } else {
                 gameStateRef.current.selection = [clickedId];
             }
         }
         else if (newSel.length > 0) {
              const nonBuildings = newSel.filter(id => { const t = (gameStateRef.current.entities.get(id) as Entity | undefined)?.type; return t!==EntityType.BASE && t!==EntityType.BARRACKS && t!==EntityType.SUPPLY_DEPOT && t!==EntityType.BUNKER });
              // Drag selection usually excludes buildings unless ONLY buildings are selected, OR shift is used.
              // For shift drag, we just add whatever is valid.
              const candidates = nonBuildings.length > 0 ? nonBuildings : newSel;

              if (e.shiftKey) {
                   const combined = new Set([...gameStateRef.current.selection, ...candidates]);
                   gameStateRef.current.selection = Array.from(combined);
              } else {
                   gameStateRef.current.selection = candidates;
              }
         } else if (!e.shiftKey) {
             gameStateRef.current.selection = [];
         }

         onSelectionChange(gameStateRef.current.selection.map(id => gameStateRef.current.entities.get(id)!).filter(Boolean) as Entity[]);
         mouseDownStateRef.current = null;
     }
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  return (
    <canvas
      ref={canvasRef}
      width={windowSize.width}
      height={windowSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { mouseDownStateRef.current=null; isDraggingCamera.current=false; isRightDragging.current=false; }}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GameState, Entity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: Entity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

export const GameCanvas: React.FC<Props> = ({ 
    onGameStateUpdate, 
    onSelectionChange, 
    commandMode, 
    setCommandMode,
    isMultiplayer = false,
    gameSeed = 0,
    isHost = true,
    difficulty = Difficulty.MEDIUM
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame(difficulty, isMultiplayer, gameSeed, isHost));
  const requestRef = useRef<number>(0);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });

  // Offscreen Buffers
  const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false);
  const isRightDragging = useRef(false);
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  useEffect(() => {
    const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Initialize Assets
  useEffect(() => {
      terrainCanvasRef.current = renderTerrain();

      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;

      onGameStateUpdate({ ...gameStateRef.current });

      // Center camera
      const entities = Array.from(gameStateRef.current.entities.values()) as Entity[];
      const myBase = entities.find(e => e.type === EntityType.BASE && e.owner === Owner.PLAYER);
      if (myBase) {
          gameStateRef.current.camera.x = Math.max(0, myBase.position.x - window.innerWidth / 2);
          gameStateRef.current.camera.y = Math.max(0, myBase.position.y - (window.innerHeight - UI_TOP_HEIGHT) / 2);
      }
  }, []);

  useEffect(() => {
      if (!isMultiplayer) return;
      const handleNetMsg = (msg: NetMessage) => {
          if (msg.type === 'GAME_COMMAND') {
              const { action, data, owner } = msg.payload;
              if (owner !== Owner.PLAYER) {
                 const event = new CustomEvent('GAME_COMMAND', { detail: { ...data, action, _isRemote: true } });
                 window.dispatchEvent(event);
              }
          }
      };
      const unsubscribe = network.subscribe(handleNetMsg);
      return unsubscribe;
  }, [isMultiplayer]);

  // Game Command Handler
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail as any;
          const isRemote = detail._isRemote;

          if (isMultiplayer && !isRemote) {
              if (!['MOVE_CAMERA', 'TOGGLE_PAUSE'].includes(detail.action)) {
                  network.send({ type: 'GAME_COMMAND', payload: { action: detail.action, data: detail, owner: Owner.PLAYER } });
              }
          }

          if (detail.action === 'RESTART' && !isMultiplayer) {
                gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
                if (exploredCanvasRef.current) {
                    const ctx = exploredCanvasRef.current.getContext('2d');
                    if (ctx) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.fillStyle = 'black';
                        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                    }
                }
                onGameStateUpdate({ ...gameStateRef.current });
                return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA' && !isRemote) {
              const UI_BOTTOM_HEIGHT = 224;
              const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
              const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
              gameStateRef.current.camera = { x: Math.max(0, Math.min(detail.x, maxCamX)), y: Math.max(0, Math.min(detail.y, maxCamY)) };
              return;
          }

          const logicEvents = ['TRAIN', 'UNLOAD_ALL', 'SET_RALLY', 'MINIMAP_ACTION', 'UNIT_COMMAND'];
          if (logicEvents.includes(detail.action)) {
             const ents = gameStateRef.current.entities;
             if (detail.action === 'TRAIN') {
                 const ent = ents.get(detail.id);
                 const owner = isRemote ? Owner.OPPONENT : Owner.PLAYER;
                 if (ent && ent.owner === owner) {
                     const s = STATS[detail.type as EntityType];
                     if (gameStateRef.current.resources[owner] >= s.cost) {
                         if (!ent.trainQueue) ent.trainQueue = [];
                         if (ent.trainQueue.length < 5) {
                             ent.trainQueue.push(detail.type);
                             gameStateRef.current.resources[owner] -= s.cost;
                             if(!isRemote) playSound('train');
                         }
                     } else if (!isRemote) { playSound('error'); addNotification(gameStateRef.current, "Not Enough Minerals"); }
                 }
             }
             if (detail.action === 'MINIMAP_ACTION' && !isRemote) {
                 const selected = gameStateRef.current.selection;
                 const pos = {x: detail.x, y: detail.y};
                 gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: pos, type: 'MOVE', life: 20, maxLife: 20 });
                 selected.forEach(id => {
                     const u = ents.get(id);
                     if (u && u.owner === Owner.PLAYER) {
                         u.state = 'MOVING';
                         u.targetPosition = pos;
                         u.targetId = null;
                         if (u.type === EntityType.MARINE && detail.unitAction === 'ATTACK') u.state = 'ATTACKING';
                     }
                 });
                 playSound('click');
             }
             if (detail.action === 'SET_RALLY') {
                 const ent = ents.get(detail.id);
                 if (ent) { ent.rallyPoint = detail.pos; ent.rallyTargetId = detail.targetId; if(!isRemote) playSound('click'); }
             }
             if (detail.action === 'UNLOAD_ALL') {
                  const ent = ents.get(detail.id);
                  if (ent && ent.garrison) {
                      ent.garrison.forEach(uid => {
                          const u = ents.get(uid);
                          if (u) {
                              u.state = 'IDLE'; u.containerId = null;
                              u.position = { x: ent.position.x + (Math.random()*40-20), y: ent.position.y + 30 };
                          }
                      });
                      ent.garrison = [];
                      if(!isRemote) playSound('click');
                  }
             }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, [isMultiplayer, windowSize]);

  // Input Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);
          if ((e.target as HTMLElement).tagName === 'INPUT') return;
          const key = e.key.toUpperCase();
          if (key === 'A') setCommandMode('ATTACK');
          if (key === 'P') { gameStateRef.current.paused = !gameStateRef.current.paused; onGameStateUpdate({...gameStateRef.current}); }

          // --- SHORTCUTS ---
          // 1: Select Worker (Idle > Gathering > Any)
          if (key === '1') {
              const ents = Array.from(gameStateRef.current.entities.values()) as Entity[];
              const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

              let target = workers.find(w => w.state === 'IDLE');
              if (!target) target = workers.find(w => w.state === 'GATHERING');
              if (!target && workers.length > 0) target = workers[0];

              if (target) {
                  gameStateRef.current.selection = [target.id];
                  onSelectionChange([target]);
                  playSound('click');
              }
          }

          // 2: Select All Army (Marines + Medics)
          if (key === '2') {
              const ents = Array.from(gameStateRef.current.entities.values()) as Entity[];
              const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
              if (army.length > 0) {
                  gameStateRef.current.selection = army.map(u => u.id);
                  onSelectionChange(army);
                  playSound('click');
              }
          }

          // Space: Center Camera on Selection or Base
          if (key === ' ') {
              e.preventDefault();
              if (gameStateRef.current.selection.length > 0) {
                  const id = gameStateRef.current.selection[0];
                  const ent = gameStateRef.current.entities.get(id);
                  if (ent && canvasRef.current) {
                      gameStateRef.current.camera.x = Math.max(0, ent.position.x - canvasRef.current.width / 2);
                      gameStateRef.current.camera.y = Math.max(0, ent.position.y - canvasRef.current.height / 2);
                  }
              } else {
                  const base = Array.from(gameStateRef.current.entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                  if (base && canvasRef.current) {
                      gameStateRef.current.camera.x = Math.max(0, base.position.x - canvasRef.current.width / 2);
                      gameStateRef.current.camera.y = Math.max(0, base.position.y - canvasRef.current.height / 2);
                  }
              }
          }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
  }, [setCommandMode]);

  const getWorldPos = (cx: number, cy: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: cx - rect.left + gameStateRef.current.camera.x, y: cy - rect.top + gameStateRef.current.camera.y };
  };

  const isEntityVisible = (entity: Entity, playerUnits: Entity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // --- DRAWING ---
  const drawUnit = (ctx: CanvasRenderingContext2D, entity: Entity, isSelected: boolean) => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      const isPlayer = entity.owner === Owner.PLAYER;
      const primaryColor = isPlayer ? '#3b82f6' : '#ef4444'; // Blue : Red
      const secondaryColor = isPlayer ? '#1e40af' : '#991b1b';

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
      ctx.fill();

      // Construction
      if (entity.constructionProgress! < 100) {
          ctx.globalAlpha = 0.6;
          // Scaffold
          ctx.strokeStyle = '#fbbf24';
          ctx.setLineDash([4, 2]);
          ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
          ctx.setLineDash([]);
      }

      if (entity.type === EntityType.WORKER) {
          // Body
          const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
          grad.addColorStop(0, '#e5e7eb');
          grad.addColorStop(1, '#9ca3af');
          ctx.fillStyle = grad;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Backpack (Resources)
          if (entity.resourceAmount && entity.resourceAmount > 0) {
              ctx.fillStyle = '#06b6d4'; // Blue crystal
              ctx.fillRect(-4, -6, 8, 4);
          } else {
              ctx.fillStyle = '#374151'; // Empty pack
              ctx.fillRect(-4, -5, 8, 3);
          }

          // Drill Arm
          ctx.fillStyle = '#4b5563';
          ctx.save();
          const angle = entity.targetPosition ? Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x) : 0;
          ctx.rotate(angle);
          ctx.fillRect(4, -1, 6, 2); // Arm
          ctx.fillStyle = '#d1d5db';
          ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(14, 0); ctx.lineTo(10, 2); ctx.fill(); // Tip
          ctx.restore();

      } else if (entity.type === EntityType.MARINE) {
          // Shoulders
          ctx.fillStyle = secondaryColor;
          ctx.beginPath(); ctx.arc(-5, -2, 3, 0, Math.PI * 2); ctx.fill();
          ctx.beginPath(); ctx.arc(5, -2, 3, 0, Math.PI * 2); ctx.fill();

          // Body
          ctx.fillStyle = primaryColor;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Gun
          ctx.save();
          // Ideally rotate towards target, simplified:
          if (entity.state === 'ATTACKING') {
              const tId = entity.targetId;
              // We'd need target position here to rotate correctly, but visual abstraction is OK
          }
          ctx.fillStyle = '#111827';
          ctx.fillRect(2, -1, 10, 3); // Gun barrel
          ctx.restore();

          // Visor reflection
          ctx.fillStyle = 'rgba(255,255,255,0.8)';
          ctx.beginPath(); ctx.arc(1, -2, 1.5, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.MEDIC) {
          ctx.fillStyle = '#fff';
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
          // Cross
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(-2, -5, 4, 10);
          ctx.fillRect(-5, -2, 10, 4);
          // Shield/Pack
          ctx.strokeStyle = '#d1d5db';
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.stroke();

      } else if (entity.type === EntityType.BASE) {
          // Base Plate
          ctx.fillStyle = '#374151';
          ctx.fillRect(-30, -30, 60, 60);

          // Structure
          const grad = ctx.createLinearGradient(-30, -30, 30, 30);
          grad.addColorStop(0, primaryColor);
          grad.addColorStop(1, secondaryColor);
          ctx.fillStyle = grad;
          ctx.fillRect(-25, -25, 50, 50);

          // Detail Lines
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.lineWidth = 2;
          ctx.beginPath(); 
          ctx.moveTo(-25, 0); ctx.lineTo(25, 0); 
          ctx.moveTo(0, -25); ctx.lineTo(0, 25);
          ctx.stroke();

          // Center Hub
          ctx.fillStyle = '#111827';
          ctx.fillRect(-10, -10, 20, 20);
          // Blinking Light
          const blink = Math.sin(Date.now() / 200) > 0;
          ctx.fillStyle = blink ? '#ef4444' : '#7f1d1d';
          ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.BARRACKS) {
          ctx.fillStyle = '#1f2937';
          ctx.fillRect(-25, -25, 50, 50);

          // Roof Hatch
          ctx.fillStyle = primaryColor;
          ctx.beginPath();
          ctx.moveTo(-20, -20); ctx.lineTo(20, -20); ctx.lineTo(15, 15); ctx.lineTo(-15, 15);
          ctx.fill();

          // Stripes
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(-15, 15); ctx.lineTo(-15, 25);
          ctx.moveTo(15, 15); ctx.lineTo(15, 25);
          ctx.stroke();

      } else if (entity.type === EntityType.MINERAL) {
          // Crystals
          ctx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Glow
          ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();

          ctx.fillStyle = '#06b6d4';
          const drawCrystal = (ox: number, oy: number, s: number, r: number) => {
              ctx.save();
              ctx.translate(ox, oy);
              ctx.rotate(r);
              ctx.beginPath();
              ctx.moveTo(0, -s); ctx.lineTo(s*0.6, 0); ctx.lineTo(0, s); ctx.lineTo(-s*0.6, 0);
              ctx.fill();
              // Facet
              ctx.fillStyle = '#67e8f9';
              ctx.beginPath(); ctx.moveTo(0, -s); ctx.lineTo(s*0.3, 0); ctx.lineTo(0, s*0.4);
              ctx.fill();
              ctx.fillStyle = '#06b6d4'; // Reset
              ctx.restore();
          };

          drawCrystal(0, -5, 10, 0);
          drawCrystal(-6, 4, 8, -0.5);
          drawCrystal(6, 4, 8, 0.5);

      } else if (entity.type === EntityType.MOUNTAIN) {
          ctx.fillStyle = '#44403c';
          ctx.beginPath();
          // Irregular rock shape
          ctx.moveTo(-30, 20); ctx.lineTo(-10, 30); ctx.lineTo(20, 25); ctx.lineTo(35, 0);
          ctx.lineTo(20, -30); ctx.lineTo(-10, -35); ctx.lineTo(-35, -10);
          ctx.fill();

          // Highlights
          ctx.fillStyle = '#57534e';
          ctx.beginPath();
          ctx.moveTo(-10, -20); ctx.lineTo(10, -10); ctx.lineTo(0, 10);
          ctx.fill();

      } else if (entity.type === EntityType.WATER) {
          ctx.fillStyle = '#1e3a8a';
          ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(0,0, 28, 0, Math.PI*2); ctx.stroke();
      }

      // Selection Ring
      if (isSelected) {
          ctx.strokeStyle = '#10b981';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
          ctx.stroke();

          // Health Bar (Only if selected or damaged)
          const pct = Math.max(0, entity.hp / entity.maxHp);
          const w = 24;
          ctx.fillStyle = '#000';
          ctx.fillRect(-w/2 - 1, -entity.radius - 12, w + 2, 6);
          ctx.fillStyle = pct > 0.5 ? '#10b981' : '#ef4444';
          ctx.fillRect(-w/2, -entity.radius - 11, w * pct, 4);
      } else if (entity.hp < entity.maxHp) {
           const pct = Math.max(0, entity.hp / entity.maxHp);
           const w = 20;
           ctx.fillStyle = '#000';
           ctx.fillRect(-w/2, -entity.radius - 8, w, 4);
           ctx.fillStyle = '#ef4444'; 
           ctx.fillRect(-w/2, -entity.radius - 8, w * pct, 4);
      }

      ctx.restore();
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    const allEntities = Array.from(state.entities.values()) as Entity[];
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG & TERRAIN ---
    // Draw Terrain Cache
    if (terrainCanvasRef.current) {
        // Draw terrain shifted by camera
        ctx.drawImage(terrainCanvasRef.current, -state.camera.x, -state.camera.y);
    } else {
        ctx.fillStyle = '#111'; ctx.fillRect(0,0,width,height);
    }

    // Fog Calculation
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.7)'; // Darker fog
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath(); ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxExp.fill();
                ctxVis.beginPath(); ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxVis.fill();
            });
        }

        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
        // Draw Explored (Darkened Terrain)
        ctx.drawImage(exploredCanvasRef.current, 0, 0);
    } else {
        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
    }

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2;
             const r = 10 * (1 + (1-lifePct));
             ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0, -r); ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
             const r = 10;
             ctx.beginPath(); ctx.moveTo(-r, -r); ctx.lineTo(r, r); ctx.moveTo(r, -r); ctx.lineTo(-r, r); ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    // Sort by Y for pseudo-depth
    const sorted = [...allEntities].sort((a,b) => a.position.y - b.position.y);
    sorted.forEach((entity: Entity) => {
      if (!visibleEntities.has(entity.id)) return;
      const isSelected = state.selection.includes(entity.id);
      drawUnit(ctx, entity, isSelected);

      // Rally Lines
      if (isSelected && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.strokeStyle = '#f59e0b'; ctx.setLineDash([5, 5]); ctx.beginPath();
          ctx.moveTo(entity.position.x, entity.position.y); ctx.lineTo(entity.rallyPoint.x, entity.rallyPoint.y);
          ctx.stroke(); ctx.setLineDash([]);
      }

      // Attack Beams
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? '#facc15' : 'white';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y - 5);
              ctx.lineTo(target.position.x, target.position.y - 5);
              ctx.stroke();

              // Hit flash
              ctx.fillStyle = '#fff';
              ctx.beginPath(); ctx.arc(target.position.x, target.position.y - 5, 5, 0, Math.PI*2); ctx.fill();
          }
      }
    });

    // Effects
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION' || fx.type === 'BUILDING_EXPLOSION') {
            const r = (1 - lifePct) * (fx.type === 'BUILDING_EXPLOSION' ? 100 : 40) * fx.scale;
            const alpha = lifePct;
            ctx.globalAlpha = alpha;
            const grad = ctx.createRadialGradient(0,0,0,0,0,r);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, '#f59e0b');
            grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2; ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0,-15*lifePct); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-3,-15*lifePct); ctx.lineTo(3,-15*lifePct); ctx.stroke();
        }
        ctx.restore();
    });

    // Draw Fog Overlay on top
    if (visionCanvasRef.current) {
         ctx.drawImage(visionCanvasRef.current, 0, 0);
    }

    ctx.restore(); // Pop Camera

    // Screen Space UI (Selection Box)
    if (mouseDownStateRef.current) {
        const startScreen = mouseDownStateRef.current.screen;
        const curScreen = mousePos;

        // CORRECT COORDINATE TRANSFORMATION FOR CANVAS RENDER
        const rect = ctx.canvas.getBoundingClientRect();
        const startX = startScreen.x - rect.left;
        const startY = startScreen.y - rect.top;
        const curX = curScreen.x - rect.left;
        const curY = curScreen.y - rect.top;

        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(startX, startY, curX - startX, curY - startY);
        ctx.setLineDash([]);
    }

    // Build Preview
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = getWorldPos(mousePos.x, mousePos.y);
       const stats = STATS[type];

       ctx.save();
       ctx.translate(worldMouse.x - gameStateRef.current.camera.x, worldMouse.y - gameStateRef.current.camera.y);

       const valid = gameStateRef.current.resources[Owner.PLAYER] >= stats.cost;
       ctx.fillStyle = valid ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)';
       ctx.fillRect(-stats.width/2, -stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = '#fff';
       ctx.strokeRect(-stats.width/2, -stats.height/2, stats.width, stats.height);

       ctx.restore();
    }

    // Notification & Pause UI
    if (state.paused) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white'; ctx.font = 'bold 48px monospace'; ctx.textAlign = 'center';
        ctx.fillText('PAUSED', width / 2, height / 2);
    }
    if (state.notifications.length > 0) {
        ctx.font = 'bold 20px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#f87171';
        state.notifications.forEach((n, i) => {
            const y = height - 300 - (i * 30);
            ctx.globalAlpha = n.life / 60;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.globalAlpha = 1;
    }
  };

  // Loop & Input Handlers (Same as previous)
  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }
    const mousePos = mousePosRef.current;

    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > windowSize.height - margin && mousePos.y <= windowSize.height) gameStateRef.current.camera.y += panSpeed;
    }

    const UI_BOTTOM_HEIGHT = 224; 
    const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
    const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, maxCamX));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, maxCamY));

    if (canvasRef.current) draw(canvasRef.current.getContext('2d')!);
    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused || gameStateRef.current.victory) {
        onGameStateUpdate({ ...gameStateRef.current });
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (gameStateRef.current.paused) return;
      if (e.button === 1) { e.preventDefault(); isDraggingCamera.current = true; lastDragPos.current = { x: e.clientX, y: e.clientY }; return; }
      if (e.button === 2) { e.preventDefault(); rightDragStart.current = { x: e.clientX, y: e.clientY }; lastDragPos.current = { x: e.clientX, y: e.clientY }; isRightDragging.current = false; return; }
      if (e.button === 0) {
          if (commandMode === 'ATTACK') {
              const pos = getWorldPos(e.clientX, e.clientY);
              const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
              const pUnits = all.filter(en => en.owner === Owner.PLAYER);
              const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

              gameStateRef.current.selection.forEach(id => {
                 const u = gameStateRef.current.entities.get(id) as Entity | undefined;
                 if (u && u.owner === Owner.PLAYER) {
                     u.state = 'ATTACKING'; u.targetPosition = pos; u.targetId = target ? target.id : null;
                     if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'UNIT_COMMAND', subAction: 'ATTACK', unitId: id, targetPos: pos, targetId: target?.id } }));
                 }
              });
              gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: target ? target.position : pos, type: 'ATTACK', life: 20, maxLife: 20 });
              setCommandMode(null); playSound('click'); return;
          }
          if (commandMode && commandMode.startsWith('BUILD_')) {
              const type = commandMode.replace('BUILD_', '') as EntityType;
              const pos = getWorldPos(e.clientX, e.clientY);
              const s = STATS[type];
              if (gameStateRef.current.resources[Owner.PLAYER] >= s.cost) {
                  gameStateRef.current.resources[Owner.PLAYER] -= s.cost;
                  const b = createEntity(type, Owner.PLAYER, pos, `${network.id}_b_${Math.random()}`);
                  b.constructionProgress = 0; gameStateRef.current.entities.set(b.id, b);
                  setCommandMode(null); playSound('build');
                  if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'BUILD', type, pos } }));
              } else { addNotification(gameStateRef.current, "Not Enough Minerals"); playSound('error'); }
              return;
          }
          const wPos = getWorldPos(e.clientX, e.clientY);
          mouseDownStateRef.current = { screen: {x:e.clientX, y:e.clientY}, world: wPos };
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };
    if (gameStateRef.current.paused) return;
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) isRightDragging.current = true;
        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;
     if (e.button === 1) { isDraggingCamera.current = false; return; }
     if (e.button === 2) {
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
             const pUnits = all.filter(en => en.owner === Owner.PLAYER);
             const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

             const selection = gameStateRef.current.selection;
             if (selection.length > 0) {
                 const hasBuildings = selection.some(id => { const u=gameStateRef.current.entities.get(id) as Entity | undefined; return !!(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE || u.type===EntityType.BARRACKS))});
                 if (hasBuildings) {
                     selection.forEach(id => {
                         const u=gameStateRef.current.entities.get(id) as Entity | undefined;
                         if(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE||u.type===EntityType.BARRACKS)) {
                             window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action:'SET_RALLY', id:u.id, pos, targetId: target?target.id:null}}));
                         }
                     });
                 } else {
                     playSound('click');
                     let moveType = 'MOVE';
                     let tId = null;
                     if (target && target.owner !== Owner.PLAYER) { moveType = 'ATTACK'; tId = target.id; }
                     else if (target && target.type === EntityType.MINERAL) { moveType = 'GATHER'; tId = target.id; }

                     window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y, unitAction: moveType, targetId: tId }}));
                 }
             }
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         // Selection Box Logic
         const start = mouseDownStateRef.current.world;
         const cur = getWorldPos(e.clientX, e.clientY);
         const dist = Math.sqrt(Math.pow(e.clientX - mouseDownStateRef.current.screen.x, 2) + Math.pow(e.clientY - mouseDownStateRef.current.screen.y, 2));
         const isClick = dist < 5;

         const minX = Math.min(start.x, cur.x); const maxX = Math.max(start.x, cur.x);
         const minY = Math.min(start.y, cur.y); const maxY = Math.max(start.y, cur.y);

         const newSel: string[] = [];
         const all = Array.from(gameStateRef.current.entities.values()) as Entity[];
         const pUnits = all.filter(en => en.owner === Owner.PLAYER);

         all.forEach(en => {
             if (en.type === EntityType.MOUNTAIN || en.type === EntityType.WATER || en.state==='GARRISONED') return;
             if (!isEntityVisible(en, pUnits)) return;
             if (!isClick && en.owner !== Owner.PLAYER) return;

             if (isClick) {
                 if (Math.sqrt(Math.pow(en.position.x-cur.x,2)+Math.pow(en.position.y-cur.y,2)) < en.radius+15) newSel.push(en.id);
             } else {
                 if (en.position.x > minX && en.position.x < maxX && en.position.y > minY && en.position.y < maxY && en.owner === Owner.PLAYER) newSel.push(en.id);
             }
         });

         if (isClick && newSel.length > 0) { 
             playSound('click'); 
             const clickedId = newSel[0]; 

             // Shift-Click Toggle
             if (e.shiftKey) {
                 const prev = gameStateRef.current.selection;
                 if (prev.includes(clickedId)) {
                     gameStateRef.current.selection = prev.filter(id => id !== clickedId);
                 } else {
                     gameStateRef.current.selection = [...prev, clickedId];
                 }
             } else {
                 gameStateRef.current.selection = [clickedId];
             }
         }
         else if (newSel.length > 0) {
              const nonBuildings = newSel.filter(id => { const t = (gameStateRef.current.entities.get(id) as Entity | undefined)?.type; return t!==EntityType.BASE && t!==EntityType.BARRACKS && t!==EntityType.SUPPLY_DEPOT && t!==EntityType.BUNKER });
              // Drag selection usually excludes buildings unless ONLY buildings are selected, OR shift is used.
              // For shift drag, we just add whatever is valid.
              const candidates = nonBuildings.length > 0 ? nonBuildings : newSel;

              if (e.shiftKey) {
                   const combined = new Set([...gameStateRef.current.selection, ...candidates]);
                   gameStateRef.current.selection = Array.from(combined);
              } else {
                   gameStateRef.current.selection = candidates;
              }
         } else if (!e.shiftKey) {
             gameStateRef.current.selection = [];
         }

         onSelectionChange(gameStateRef.current.selection.map(id => gameStateRef.current.entities.get(id)!).filter(Boolean) as Entity[]);
         mouseDownStateRef.current = null;
     }
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  return (
    <canvas
      ref={canvasRef}
      width={windowSize.width}
      height={windowSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { mouseDownStateRef.current=null; isDraggingCamera.current=false; isRightDragging.current=false; }}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI', // Kept for backward compatibility with single player
  OPPONENT = 'OPPONENT', // For multiplayer
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  MEDIC = 'MEDIC',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  BUNKER = 'BUNKER',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export enum Difficulty {
    EASY = 'EASY',
    MEDIUM = 'MEDIUM',
    HARD = 'HARD'
}

export enum AIStrategy {
    RUSH = 'RUSH', // Early attack, low economy
    MACRO = 'MACRO', // High economy, late attack
    TURTLE = 'TURTLE' // Defensive, builds bunkers
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD' | 'BUILDING_EXPLOSION' | 'HEAL';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Marker {
  id: string;
  position: Vector2;
  type: 'MOVE' | 'ATTACK' | 'LOAD';
  life: number;
  maxLife: number;
}

export interface Notification {
    id: string;
    text: string;
    life: number;
}

export interface GameEntity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING' | 'ENTERING' | 'GARRISONED' | 'HEALING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
  lastAttackerId?: string | null; // For retaliation
  garrison?: string[]; // IDs of units inside (for Bunker)
  containerId?: string | null; // ID of entity this unit is inside
}

export interface GameState {
  entities: Map<string, GameEntity>;
  effects: Effect[];
  markers: Marker[];
  notifications: Notification[];
  soundEvents: string[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
    [Owner.OPPONENT]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
    [Owner.OPPONENT]: { used: number; max: number };
  };
  selection: string[];
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
  difficulty: Difficulty;
  aiStrategy: AIStrategy; 
  paused: boolean;
  isMultiplayer: boolean;
  localPlayerId?: string;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  vision: number;
  speed: number;
  attackSpeed: number;
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
  healRate?: number; // For Medics
}

// Network Types
export type NetMessage = 
  | { type: 'JOIN', payload: { name: string, id: string } }
  | { type: 'WELCOME', payload: { seed: number, hostId: string } }
  | { type: 'READY', payload: { id: string, ready: boolean } }
  | { type: 'START_GAME', payload: { seed: number } }
  | { type: 'GAME_COMMAND', payload: { action: string, data: any, owner: Owner } }
  | { type: 'ERROR', payload: { message: string } };

export interface PlayerInfo {
    id: string;
    name: string;
    isReady: boolean;
    isHost: boolean;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT } from '../constants';
import { GameEntity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, AIStrategy } from '../types';
import { SeededRandom } from './random';

let idCounter = 0;
// We need to synchronize IDs in multiplayer. 
// In a real app, we'd use GUIDs or owner-prefixed IDs. 
// For this simple version, Host generates odd IDs, Client generates even IDs, or we rely on the prefix.
export const generateId = (prefix: string = 'ent') => `${prefix}_${++idCounter}_${Math.floor(Math.random()*1000)}`;

export const addNotification = (state: GameState, text: string) => {
    state.notifications.push({
        id: `n_${Math.random()}`,
        text,
        life: 120
    });
};

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2, id?: string): GameEntity => {
  const stats = STATS[type];
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: id || generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null,
    garrison: [],
    containerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, GameEntity>, type?: EntityType, owner?: Owner) => {
  let nearest: GameEntity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (e.state === 'GARRISONED') return;
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, GameEntity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

const isBio = (type: EntityType) => type === EntityType.WORKER || type === EntityType.MARINE || type === EntityType.MEDIC;
const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT || type === EntityType.BUNKER;

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM, isMultiplayer = false, seed = Math.random() * 10000, isHost = true): GameState => {
  const entities = new Map<string, GameEntity>();
  const effects: Effect[] = [];
  const add = (e: GameEntity) => entities.set(e.id, e);

  // Use seeded random
  const rng = new SeededRandom(seed);

  // --- RANDOMIZED BASE PLACEMENT ---
  // Define 4 corners with padding
  const corners = [
      { x: 150, y: 150 }, // TL
      { x: GAME_WIDTH - 150, y: 150 }, // TR
      { x: 150, y: GAME_HEIGHT - 150 }, // BL
      { x: GAME_WIDTH - 150, y: GAME_HEIGHT - 150 } // BR
  ];

  // Shuffle corners using seeded random
  // Fisher-Yates shuffle
  for (let i = corners.length - 1; i > 0; i--) {
        const j = Math.floor(rng.next() * (i + 1));
        [corners[i], corners[j]] = [corners[j], corners[i]];
  }

  // If Host (Player 1), we are at corners[0]. If Client (Player 2), we are at corners[0] but visually we might want to swap?
  // Actually, to keep it simple: Player is ALWAYS corners[0] in singleplayer.
  // In multiplayer: 
  //   Host -> Owner.PLAYER at corners[0], Opponent -> Owner.OPPONENT at corners[1].
  //   Client -> Owner.PLAYER at corners[1], Opponent -> Owner.OPPONENT at corners[0].

  let myBasePos = corners[0];
  let opBasePos = corners[1];

  if (isMultiplayer && !isHost) {
      // If I am the client, I spawn at the second position, and the opponent (Host) is at the first.
      // But from MY perspective, I am Owner.PLAYER.
      myBasePos = corners[1];
      opBasePos = corners[0];
  }

  // Add random offset to prevent exact static spots
  const jitter = (pt: Vector2) => ({
      x: pt.x + (rng.next() - 0.5) * 50,
      y: pt.y + (rng.next() - 0.5) * 50
  });

  myBasePos = jitter(myBasePos);
  opBasePos = jitter(opBasePos);

  // --- RANDOM STRATEGY ---
  const strategies = [AIStrategy.RUSH, AIStrategy.MACRO, AIStrategy.TURTLE];
  const aiStrategy = strategies[Math.floor(rng.next() * strategies.length)];

  // --- MAP GENERATION ---
  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = rng.next() * Math.PI * 2;
          const dist = rng.next() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, myBasePos) < 400) continue;
          if (getDistance({x,y}, opBasePos) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  // Terrain
  for(let i=0; i<15; i++) {
      generateCluster(EntityType.MOUNTAIN, 5, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 150);
  }
  for(let i=0; i<8; i++) {
      generateCluster(EntityType.WATER, 4, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 120);
  }

  // Expansion Minerals: 2, 4, 6, or 8 clusters
  const possibleExpansions = [2, 4, 6, 8];
  const numExpansions = possibleExpansions[Math.floor(rng.next() * possibleExpansions.length)];

  for(let i=0; i<numExpansions; i++) {
      let exX = rng.range(150, GAME_WIDTH - 300);
      let exY = rng.range(150, GAME_HEIGHT - 300);

      let safe = false;
      let attempts = 0;
      while (!safe && attempts < 10) {
          if (getDistance({x:exX, y:exY}, myBasePos) > 700 && getDistance({x:exX, y:exY}, opBasePos) > 700) {
              safe = true;
          } else {
              exX = rng.range(150, GAME_WIDTH - 300);
              exY = rng.range(150, GAME_HEIGHT - 300);
          }
          attempts++;
      }
      generateCluster(EntityType.MINERAL, 7, exX, exY, 70);
  }

  // --- PLAYER SETUP ---
  const spawnBase = (pos: Vector2, owner: Owner) => {
      const centerAngle = Math.atan2((GAME_HEIGHT/2) - pos.y, (GAME_WIDTH/2) - pos.x);
      for (let i = 0; i < 8; i++) {
        const angle = centerAngle - (Math.PI/2) + (i / 7) * Math.PI; 
        add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
          x: pos.x + 220 * Math.cos(angle), 
          y: pos.y + 220 * Math.sin(angle) 
        }));
      }
      const base = createEntity(EntityType.BASE, owner, pos);
      add(base);
      for (let i = 0; i < 4; i++) {
        const worker = createEntity(EntityType.WORKER, owner, { 
            x: pos.x + (rng.next()-0.5)*50, 
            y: pos.y + (rng.next()-0.5)*50 
        });
        add(worker);
        const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
        if (mineral) {
            worker.state = 'GATHERING';
            worker.targetId = mineral.id;
        }
      }
      const nearestMineral = findNearest(base.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
      if (nearestMineral) {
          base.rallyPoint = nearestMineral.position;
          base.rallyTargetId = nearestMineral.id;
      }
  };

  spawnBase(myBasePos, Owner.PLAYER);
  const opponentOwner = isMultiplayer ? Owner.OPPONENT : Owner.AI;
  spawnBase(opBasePos, opponentOwner);

  const startCameraY = Math.max(0, myBasePos.y - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));
  const startCameraX = Math.max(0, myBasePos.x - (typeof window !== 'undefined' ? window.innerWidth / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50, [Owner.OPPONENT]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 },
      [Owner.OPPONENT]: { used: 4, max: 10 }
    },
    selection: [],
    camera: { x: startCameraX, y: startCameraY },
    gameTime: 0,
    difficulty,
    aiStrategy,
    victory: undefined,
    paused: false,
    isMultiplayer
  };
};

const resolveCollisions = (entity: GameEntity, entities: Map<string, GameEntity>) => {
  if (entity.state === 'BUILDING' || entity.state === 'GARRISONED') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;
    if (other.state === 'GARRISONED') return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; 

    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; 

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const acquireTarget = (entity: GameEntity, entities: Map<string, GameEntity>) => {
    const stats = STATS[entity.type];
    let bestTarget: GameEntity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;
                if (e.targetId === entity.id) score += 5000;
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; 
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };
  supply[Owner.OPPONENT] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    // Supply Logic Fix: Only fully constructed buildings provide supply
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);
  supply[Owner.OPPONENT].max = Math.min(supply[Owner.OPPONENT].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 
    if (entity.state === 'GARRISONED') return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) {
           entity.constructionProgress = 100;
           // Completed sound?
       }
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 
             // IMPORTANT: In multiplayer, ID generation must be consistent or handled by owner.
             // We use a random suffix in generateId, which is risky for exact sync.
             // For this clone, we assume "good enough" sync or command-based spawning.
             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Inherit rally point
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                         newUnit.state = unitType === EntityType.MEDIC ? 'MOVING' : 'ATTACKING'; 
                     }
                 }
             } else if ((entity.owner === Owner.AI || entity.owner === Owner.OPPONENT) && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                // AI Units just spawn
                newUnit.state = 'IDLE'; 
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    const stats = STATS[entity.type];

    // --- BUNKER LOGIC ---
    if (entity.type === EntityType.BUNKER) {
        if (entity.garrison && entity.garrison.length > 0) {
            let target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp <= 0 || getDistance(entity.position, target.position) > stats.range) {
                target = acquireTarget(entity, entities);
                entity.targetId = target ? target.id : null;
            }

            if (target) {
                const dist = getDistance(entity.position, target.position);
                if (dist <= stats.range) {
                    if (entity.cooldown <= 0) {
                        const marineStats = STATS[EntityType.MARINE];
                        target.hp -= marineStats.damage;
                        entity.cooldown = Math.max(5, 30 / entity.garrison.length);

                        if (target.hp <= 0) entity.targetId = null;
                        soundEvents.push('shoot');
                    }
                }
            }
        }
    }

    // --- MEDIC LOGIC ---
    if (entity.type === EntityType.MEDIC) {
        if (['IDLE', 'MOVING', 'ATTACKING'].includes(entity.state)) {
            let healTarget: GameEntity | null = null;
            let bestHealDist = stats.vision;

            entities.forEach(e => {
                if (e.owner === entity.owner && isBio(e.type) && e.hp < e.maxHp && e.state !== 'GARRISONED') {
                    const d = getDistance(entity.position, e.position);
                    if (d < bestHealDist) {
                        bestHealDist = d;
                        healTarget = e;
                    }
                }
            });

            if (healTarget) {
                const d = getDistance(entity.position, healTarget.position);
                if (d <= stats.range) {
                    entity.state = 'HEALING';
                    entity.targetId = healTarget.id;
                    entity.targetPosition = null; 
                } else {
                    const angle = Math.atan2(healTarget.position.y - entity.position.y, healTarget.position.x - entity.position.x);
                    entity.position.x += Math.cos(angle) * stats.speed;
                    entity.position.y += Math.sin(angle) * stats.speed;
                }
            }
        }

        if (entity.state === 'HEALING') {
            const target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp >= target.maxHp || getDistance(entity.position, target.position) > stats.range + 20) {
                 entity.state = 'IDLE';
                 entity.targetId = null;
            } else {
                 if (entity.cooldown <= 0) {
                     target.hp = Math.min(target.maxHp, target.hp + (stats.healRate || 5));
                     entity.cooldown = stats.attackSpeed;
                     newEffects.push({
                        id: `fx_${Math.random()}`,
                        type: 'HEAL',
                        position: { ...target.position },
                        life: 20, maxLife: 20, scale: 1
                     });
                 }
            }
        }
    }

    // --- ENTERING BUNKER LOGIC ---
    if (entity.state === 'ENTERING' && entity.targetId) {
        const bunker = entities.get(entity.targetId);
        // Bunker Fix: Must be built to enter
        if (bunker && bunker.type === EntityType.BUNKER && bunker.hp > 0 && bunker.owner === entity.owner && bunker.constructionProgress! >= 100) {
             const dist = getDistance(entity.position, bunker.position);
             if (dist < bunker.radius + entity.radius + 10) {
                 if (!bunker.garrison) bunker.garrison = [];
                 if (bunker.garrison.length < 4) {
                     bunker.garrison.push(entity.id);
                     entity.state = 'GARRISONED';
                     entity.containerId = bunker.id;
                     entity.targetId = null;
                     entity.targetPosition = null;
                     soundEvents.push('click'); 
                 } else {
                     entity.state = 'IDLE'; 
                 }
             } else {
                 const angle = Math.atan2(bunker.position.y - entity.position.y, bunker.position.x - entity.position.x);
                 entity.position.x += Math.cos(angle) * stats.speed;
                 entity.position.y += Math.sin(angle) * stats.speed;
             }
        } else {
            entity.state = 'IDLE';
        }
    }

    // --- STANDARD ACTION LOGIC ---
    if (entity.state === 'IDLE' && entity.type !== EntityType.MEDIC && entity.type !== EntityType.WORKER && stats.damage > 0) {
        const target = acquireTarget(entity, entities);
        if (target) {
            entity.targetId = target.id;
            entity.state = 'ATTACKING';
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner && attacker.state !== 'GARRISONED') {
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        if (!target || target.hp <= 0 || target.state === 'GARRISONED') {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; 

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; 
                  entity.cooldown = stats.attackSpeed;
                  soundEvents.push('shoot');

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
         const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            let newRes: GameEntity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });
            if (newRes) entity.targetId = (newRes as GameEntity).id;
            else entity.state = 'IDLE';
        } else {
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }
            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; 
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) newEntities.delete(target.id);
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;
                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (isBio(entity.type)) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');

        if (entity.garrison && entity.garrison.length > 0) {
            entity.garrison.forEach(id => {
                const unit = newEntities.get(id);
                if (unit) {
                    unit.state = 'IDLE';
                    unit.containerId = null;
                    unit.position = { 
                        x: entity.position.x + (Math.random() * 40 - 20), 
                        y: entity.position.y + (Math.random() * 40 - 20) 
                    };
                }
            });
        }

        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  newEffects = newEffects.filter(fx => { fx.life--; return fx.life > 0; });
  newMarkers = newMarkers.filter(mk => { mk.life--; return mk.life > 0; });
  newNotifications = newNotifications.filter(n => { n.life--; return n.life > 0; });

  // ONLY RUN AI IF SINGLE PLAYER
  if (!state.isMultiplayer && state.gameTime % 30 === 0) {
      runAI(state, newEntities, resources, supply);
  }

  let playerBuildings = 0;
  let opponentBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if ((e.owner === Owner.AI || e.owner === Owner.OPPONENT) && isBuilding(e.type)) opponentBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = state.isMultiplayer ? Owner.OPPONENT : Owner.AI; 
  if (opponentBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, GameEntity>, resources: any, supply: any) => {
  const aiOwner = Owner.AI;
  const playerOwner = Owner.PLAYER;

  const myUnits = Array.from(entities.values()).filter(e => e.owner === aiOwner);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const bunkers = myUnits.filter(e => e.type === EntityType.BUNKER);
  const army = myUnits.filter(e => e.type === EntityType.MARINE || e.type === EntityType.MEDIC);
  const depots = myUnits.filter(e => e.type === EntityType.SUPPLY_DEPOT);

  const myMinerals = resources[aiOwner];
  const mySupply = supply[aiOwner];
  const strategy = state.aiStrategy;

  let maxWorkers = 12;
  let attackThreshold = 12;
  let expand = false;
  let buildBunkers = false;

  // Modify logic based on Strategy
  if (strategy === AIStrategy.RUSH) {
      maxWorkers = 10;
      attackThreshold = 8;
  } else if (strategy === AIStrategy.MACRO) {
      maxWorkers = 20;
      attackThreshold = 25;
      expand = true;
  } else if (strategy === AIStrategy.TURTLE) {
      maxWorkers = 14;
      attackThreshold = 30; // Wait for big army
      buildBunkers = true;
  }

  // Difficulty Override (Difficulty caps capability, Strategy directs it)
  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = Math.min(maxWorkers, 10);
      attackThreshold = Math.max(attackThreshold, 15);
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = Math.max(maxWorkers, 16);
  }

  // --- 0. DEFENSE CHECK ---
  let underAttack = false;
  let threatPos: Vector2 | null = null;

  if (bases.length > 0) {
      const mainBase = bases[0];
      const enemies = Array.from(entities.values()).filter(e => e.owner === playerOwner);
      const nearestEnemy = enemies.find(e => getDistance(e.position, mainBase.position) < 800);
      if (nearestEnemy) {
          underAttack = true;
          threatPos = nearestEnemy.position;
      }
  }

  if (underAttack && army.length === 0 && state.difficulty === Difficulty.HARD) {
       workers.slice(0, 5).forEach(w => {
           if (w.state !== 'ATTACKING') {
               w.state = 'ATTACKING';
               w.targetPosition = threatPos;
           }
       });
  }

  // --- 1. WORKERS ---
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.sort((a,b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
      if (base && (!base.trainQueue || base.trainQueue.length < 1)) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[aiOwner] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'ATTACKING' && !underAttack) w.state = 'IDLE';
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // --- 2. SUPPLY ---
  if (mySupply.max - mySupply.used <= 3 && myMinerals >= 100 && depots.length < 10) {
      const construction = myUnits.find(u => u.type === EntityType.SUPPLY_DEPOT && u.constructionProgress! < 100);
      if (!construction) {
          const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
          if (builder) {
              resources[aiOwner] -= 100;
              const basePos = bases[0]?.position || builder.position;
              const angle = Math.random() * Math.PI * 2;
              const dist = 100 + Math.random() * 100;
              const buildPos = { x: basePos.x + Math.cos(angle)*dist, y: basePos.y + Math.sin(angle)*dist };
              const depot = createEntity(EntityType.SUPPLY_DEPOT, aiOwner, buildPos);
              depot.constructionProgress = 0;
              entities.set(depot.id, depot);
          }
      }
  }

  // --- 3. BUILDINGS ---
  const desiredBarracks = (strategy === AIStrategy.RUSH) ? 4 : 3;
  if (barracks.length < desiredBarracks && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING');
      if (builder) {
           resources[aiOwner] -= 150;
           const basePos = bases[0]?.position || builder.position;
           const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };
           const b = createEntity(EntityType.BARRACKS, aiOwner, buildPos);
           b.constructionProgress = 0;
           entities.set(b.id, b);
      }
  }

  if (buildBunkers && bunkers.length < (bases.length * 2) && myMinerals >= 100 && barracks.length > 0) {
       const builder = workers.find(w => w.state === 'GATHERING');
       if (builder && bases.length > 0) {
           const base = bases[0];
           const center = { x: GAME_WIDTH/2, y: GAME_HEIGHT/2 };
           const angle = Math.atan2(center.y - base.position.y, center.x - base.position.x);
           const dist = 300;
           const buildPos = { x: base.position.x + Math.cos(angle)*dist + (Math.random()-0.5)*100, y: base.position.y + Math.sin(angle)*dist + (Math.random()-0.5)*100 };

           resources[aiOwner] -= 100;
           const bunk = createEntity(EntityType.BUNKER, aiOwner, buildPos);
           bunk.constructionProgress = 0;
           entities.set(bunk.id, bunk);
       }
  }

  // Garrison Bunkers (Turtle or defense)
  if (bunkers.length > 0 && army.length > 0) {
      bunkers.forEach(bunk => {
          if (bunk.hp > 0 && bunk.constructionProgress! >= 100 && (!bunk.garrison || bunk.garrison.length < 4)) {
              const marines = army.filter(u => u.type === EntityType.MARINE && u.state !== 'GARRISONED' && u.state !== 'ENTERING');
              let bestMarine: GameEntity | null = null;
              let bestDist = 500;
              marines.forEach(m => {
                  const d = getDistance(m.position, bunk.position);
                  if (d < bestDist) { bestDist = d; bestMarine = m; }
              });
              if (bestMarine) {
                  bestMarine.state = 'ENTERING';
                  bestMarine.targetId = bunk.id;
              }
          }
      });
  }

  // Expansion
  if (expand && bases.length < 3 && myMinerals >= 400) {
      let bestPatch: GameEntity | null = null;
      const minerals = Array.from(entities.values()).filter(e => e.type === EntityType.MINERAL);
      minerals.forEach(m => {
          let minDistToBase = Infinity;
          bases.forEach(b => {
             const d = getDistance(m.position, b.position);
             if (d < minDistToBase) minDistToBase = d;
          });
          if (minDistToBase > 800 && minDistToBase < 2000) {
              const nearbyBase = Array.from(entities.values()).find(e => e.type === EntityType.BASE && getDistance(e.position, m.position) < 300);
              if (!nearbyBase) bestPatch = m;
          }
      });

      if (bestPatch) {
          const builder = workers.find(w => w.state === 'GATHERING');
          if (builder) {
              resources[aiOwner] -= 400;
              const buildPos = { x: bestPatch.position.x + 100, y: bestPatch.position.y };
              const newBase = createEntity(EntityType.BASE, aiOwner, buildPos);
              newBase.constructionProgress = 0;
              entities.set(newBase.id, newBase);
              builder.position = { ...buildPos }; 
          }
      }
  }

  // --- 4. PRODUCTION ---
  if (barracks.length > 0 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if (b.constructionProgress! >= 100 && (!b.trainQueue || b.trainQueue.length < 5) && resources[aiOwner] >= 50) {
              let type = EntityType.MARINE;
              const medicCount = army.filter(u => u.type === EntityType.MEDIC).length;
              const marineCount = army.length - medicCount;
              const desiredMedicRatio = 0.25;

              if (marineCount > 2 && medicCount / (marineCount || 1) < desiredMedicRatio && resources[aiOwner] >= 75) {
                   type = EntityType.MEDIC;
              }
              if (resources[aiOwner] >= STATS[type].cost) {
                  if (!b.trainQueue) b.trainQueue = [];
                  b.trainQueue.push(type);
                  resources[aiOwner] -= STATS[type].cost;
              }
          }
      });
  }

  // --- 6. ARMY MOVEMENT ---
  if (underAttack && army.length > 0) {
      army.forEach(u => {
          if (u.state === 'GARRISONED') return;
          if (threatPos) {
              u.state = u.type === EntityType.MEDIC ? 'MOVING' : 'ATTACKING';
              u.targetPosition = threatPos;
          }
      });
      return;
  }

  if (army.length >= attackThreshold) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === playerOwner && e.type === EntityType.BASE);
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === playerOwner);
      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state === 'GARRISONED') return;
          if (unit.state === 'ATTACKING' && unit.targetId) return;

          if (unit.type === EntityType.MEDIC) {
               const buddy = army.find(a => a !== unit && a.type === EntityType.MARINE);
               if (buddy && getDistance(unit.position, buddy.position) > 100) {
                    unit.state = 'MOVING';
                    unit.targetPosition = buddy.position;
               } else {
                    unit.state = 'MOVING';
                    unit.targetPosition = targetPos;
               }
          } else {
               unit.state = 'ATTACKING';
               unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useState, useCallback, useEffect } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { Interface } from './components/Interface';
import { Lobby } from './components/Lobby';
import { GameState, GameEntity, EntityType, Owner, Difficulty } from './types';
import { STATS, UI_TOP_HEIGHT } from './constants';
import { initGame } from './services/gameLogic';

const App: React.FC = () => {
  const [view, setView] = useState<'LOBBY' | 'GAME'>('LOBBY');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [selectedEntities, setSelectedEntities] = useState<GameEntity[]>([]);
  const [commandMode, setCommandMode] = useState<string | null>(null);

  // Multiplayer Props
  const [isMultiplayer, setIsMultiplayer] = useState(false);
  const [gameSeed, setGameSeed] = useState(0);
  const [isHost, setIsHost] = useState(false);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);

  const handleGameStart = (seed: number, host: boolean) => {
      setGameSeed(seed);
      setIsHost(host);
      setIsMultiplayer(true);
      setDifficulty(Difficulty.MEDIUM); // Default MP difficulty to medium (or irrelevant)
      setView('GAME');
  };

  const handleSinglePlayer = (diff: Difficulty) => {
      setDifficulty(diff);
      setIsMultiplayer(false);
      setGameSeed(Math.random());
      setView('GAME');
  };

  const handleInterfaceTrain = (type: EntityType) => {
      // Find selected building
      selectedEntities.forEach(ent => {
          if (ent.owner === Owner.PLAYER) {
              window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'TRAIN', id: ent.id, type } }));
          }
      });
  };

  const handleInterfaceCommand = (cmd: string) => {
      if (cmd === 'QUIT') {
          setView('LOBBY');
          setGameState(null);
          // Optional: Reset other state
          setSelectedEntities([]);
          setCommandMode(null);
          return;
      }
      if (cmd === 'RESTART' && isMultiplayer) return; // Disable restart in MP for now
      if (cmd === 'RESTART') {
           window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'RESTART', difficulty } })); // Pass difficulty
           return;
      }
      setCommandMode(cmd); // e.g., 'BUILD_SUPPLY_DEPOT'
  };

  if (view === 'LOBBY') {
      return (
          <div className="relative w-full h-full bg-black">
              <Lobby onGameStart={handleGameStart} onSinglePlayerStart={handleSinglePlayer} />
          </div>
      )
  }

  return (
    <div className="relative w-full h-full bg-black overflow-hidden flex flex-col">
      {/* Spacer for Top Bar */}
      <div style={{ height: UI_TOP_HEIGHT }} className="w-full flex-shrink-0 bg-slate-900" />

      <div className="flex-1 relative overflow-hidden">
          <GameCanvas 
            onGameStateUpdate={setGameState} 
            onSelectionChange={setSelectedEntities}
            commandMode={commandMode}
            setCommandMode={setCommandMode}
            isMultiplayer={isMultiplayer}
            gameSeed={gameSeed}
            isHost={isHost}
            difficulty={difficulty}
          />
      </div>

      {gameState && (
          <Interface 
            gameState={gameState} 
            selectedEntities={selectedEntities}
            onCommand={handleInterfaceCommand}
            onTrain={handleInterfaceTrain}
          />
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { GameEntity, EntityType, GameState, Owner, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { toggleMute, getMuteState } from '../services/audio';

interface Props {
  gameState: GameState;
  selectedEntities: GameEntity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];
  const [isMuted, setIsMuted] = useState(getMuteState());
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Selection Logic
  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);
  const canBuild = allWorkers && selectedEntities.length === 1; 

  const allBarracks = selectedEntities.filter(e => e.type === EntityType.BARRACKS && e.owner === Owner.PLAYER);
  const showBarracksMenu = singleSelection?.type === EntityType.BARRACKS || allBarracks.length > 0;

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const key = e.key.toUpperCase();
        if ((e.target as HTMLElement).tagName === 'INPUT') return;

        if (singleSelection?.type === EntityType.BASE) {
            if (key === 'W') onTrain(EntityType.WORKER);
        }

        if (showBarracksMenu) {
            if (key === 'M') handleMultiTrain(EntityType.MARINE);
            if (key === 'E') handleMultiTrain(EntityType.MEDIC);
        }

        if (singleSelection?.type === EntityType.WORKER) {
            if (key === 'B') onCommand(`BUILD_${EntityType.BARRACKS}`);
            if (key === 'S') onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`);
            if (key === 'U') onCommand(`BUILD_${EntityType.BUNKER}`);
        }

        if (singleSelection?.type === EntityType.BUNKER && singleSelection.owner === Owner.PLAYER) {
            if (key === 'D') handleUnload();
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [singleSelection, showBarracksMenu, onTrain, onCommand]);

  // Close menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setMenuOpen(false);
      }
    };
    if (menuOpen) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [menuOpen]);

  const handleMultiTrain = (type: EntityType) => {
      if (allBarracks.length > 0) {
          const bestBarracks = [...allBarracks].sort((a, b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'TRAIN', id: bestBarracks.id, type } 
          }));
      } else if (singleSelection) {
          onTrain(type);
      }
  };

  const handleUnload = () => {
      if (singleSelection && singleSelection.type === EntityType.BUNKER) {
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'UNLOAD_ALL', id: singleSelection.id } 
          }));
      }
  };

  const changeDifficulty = (diff: Difficulty) => {
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'RESTART', difficulty: diff } 
      }));
  };

  const togglePause = () => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'TOGGLE_PAUSE' } }));
  };

  const handleToggleMute = () => setIsMuted(toggleMute());

  // --- Minimap Logic ---
  const [isDraggingMinimap, setIsDraggingMinimap] = useState(false);
  const minimapRef = useRef<HTMLDivElement>(null);

  const getMinimapPos = (clientX: number, clientY: number) => {
      if (!minimapRef.current) return null;
      const rect = minimapRef.current.getBoundingClientRect();
      const xPct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const yPct = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
      return { x: xPct * GAME_WIDTH, y: yPct * GAME_HEIGHT };
  };

  const handleMinimapInteraction = (e: React.MouseEvent) => {
      const pos = getMinimapPos(e.clientX, e.clientY);
      if (!pos) return;

      if (e.button === 0) {
          // Left Click: Move Camera
          setIsDraggingMinimap(true);
          const centerX = pos.x - (window.innerWidth / 2);
          const centerY = pos.y - (window.innerHeight / 2);
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
          }));
      } else if (e.button === 2) {
          // Right Click: Move Unit / Attack Move
          e.preventDefault();
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y } 
          }));
      }
  };

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (isDraggingMinimap) {
              const pos = getMinimapPos(e.clientX, e.clientY);
              if (pos) {
                  const centerX = pos.x - (window.innerWidth / 2);
                  const centerY = pos.y - (window.innerHeight / 2);
                  window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
                      detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
                  }));
              }
          }
      };
      const handleMouseUp = () => setIsDraggingMinimap(false);

      if (isDraggingMinimap) {
          window.addEventListener('mousemove', handleMouseMove);
          window.addEventListener('mouseup', handleMouseUp);
      }
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
      };
  }, [isDraggingMinimap]);


  const isVisibleOnMinimap = (entity: GameEntity, playerUnits: GameEntity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      if (entity.type === EntityType.MINERAL && entity.resourceAmount! <= 0) return false;
      for(const pu of playerUnits) {
          const dx = entity.position.x - pu.position.x;
          const dy = entity.position.y - pu.position.y;
          if (dx*dx + dy*dy < 250000) return true;
      }
      return false;
  };

  const allEntities: GameEntity[] = Array.from(gameState.entities.values());
  const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');

  return (
    <div className="absolute inset-0 pointer-events-none flex flex-col justify-between font-mono">
      {/* Top Bar - Modern HUD Look */}
      <div 
         style={{ height: UI_TOP_HEIGHT }}
         className="bg-slate-900/90 text-white backdrop-blur-sm border-b border-slate-700 pointer-events-auto select-none flex items-center justify-between px-4 shadow-lg flex-shrink-0"
      >
         <div className="flex gap-6 items-center">
             <div className="flex flex-col">
                 <span className="text-xs text-slate-400 uppercase tracking-widest">Minerals</span>
                 <span className="text-xl font-bold text-cyan-400 font-mono tracking-tighter">{Math.floor(resources)}</span>
             </div>
             <div className="flex flex-col">
                 <span className="text-xs text-slate-400 uppercase tracking-widest">Supply</span>
                 <span className={`text-xl font-bold font-mono tracking-tighter ${supply.used > supply.max ? "text-red-500" : "text-emerald-400"}`}>
                    {supply.used}<span className="text-slate-500">/</span>{supply.max}
                 </span>
             </div>
             <div className="flex flex-col pl-4 border-l border-slate-700">
                <span className="text-xs text-slate-400 uppercase tracking-widest">Timer</span>
                <span className="text-lg text-white font-mono">{Math.floor(gameState.gameTime / 60)}s</span>
             </div>
         </div>

         {/* Menu Button */}
         <div className="relative" ref={menuRef}>
            <button 
                onClick={() => setMenuOpen(!menuOpen)}
                className="px-4 py-2 bg-slate-800 hover:bg-slate-700 border border-slate-600 rounded text-xs font-bold uppercase tracking-widest transition-colors"
            >
                Menu
            </button>

            {menuOpen && (
                <div className="absolute right-0 top-full mt-2 w-56 bg-slate-900 border border-slate-600 rounded shadow-2xl flex flex-col p-1 z-50 text-sm">
                    <button onClick={togglePause} className="text-left px-4 py-3 hover:bg-slate-800 rounded font-semibold text-white transition-colors">
                        {gameState.paused ? 'Resume Game' : 'Pause Game'} <span className="float-right text-slate-500 text-xs mt-1">P</span>
                    </button>
                    <button onClick={handleToggleMute} className="text-left px-4 py-3 hover:bg-slate-800 rounded text-slate-300 transition-colors">
                        Sound: {isMuted ? 'Off' : 'On'}
                    </button>
                    <div className="h-px bg-slate-700 my-1"></div>
                    <button onClick={() => changeDifficulty(gameState.difficulty)} className="text-left px-4 py-3 text-red-400 hover:bg-red-900/30 rounded font-bold transition-colors">
                        Restart Match
                    </button>
                    <button onClick={() => onCommand('QUIT')} className="text-left px-4 py-3 text-orange-400 hover:bg-orange-900/30 rounded font-bold transition-colors">
                        Quit to Menu
                    </button>
                </div>
            )}
         </div>
      </div>

      {/* Victory/Defeat Overlay */}
      {gameState.victory && (
         <div className="absolute inset-0 flex items-center justify-center bg-black/80 z-50 pointer-events-auto backdrop-blur-sm">
             <div className="bg-slate-900 p-10 rounded-xl border border-slate-600 text-center shadow-2xl max-w-lg w-full relative overflow-hidden">
                 {/* Decorative background glow */}
                 <div className={`absolute top-0 left-0 w-full h-2 ${gameState.victory === Owner.PLAYER ? 'bg-gradient-to-r from-emerald-500 to-cyan-500' : 'bg-gradient-to-r from-red-600 to-orange-600'}`}></div>

                 <h1 className={`text-6xl font-black mb-2 tracking-tight ${gameState.victory === Owner.PLAYER ? "text-transparent bg-clip-text bg-gradient-to-b from-emerald-400 to-cyan-500" : "text-red-500"}`}>
                     {gameState.victory === Owner.PLAYER ? "VICTORY" : "DEFEAT"}
                 </h1>
                 <p className="text-slate-400 mb-8 font-mono text-sm uppercase tracking-widest">
                    {gameState.victory === Owner.PLAYER ? "Opposition Neutralized" : "Critical Mission Failure"}
                 </p>

                 <div className="grid grid-cols-2 gap-3 mb-4">
                     {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map(d => (
                         <button 
                            key={d}
                            className={`py-3 px-2 rounded font-bold text-sm uppercase tracking-wide border transition-all col-span-1 first:col-span-2 first:mb-0
                                ${gameState.difficulty === d 
                                    ? 'bg-slate-100 text-slate-900 border-white' 
                                    : 'bg-slate-800 text-slate-400 border-slate-700 hover:bg-slate-700 hover:text-white hover:border-slate-500'}
                            `}
                            onClick={() => changeDifficulty(d)}
                         >
                             Restart ({d})
                         </button>
                     ))}
                 </div>
                 <button 
                    onClick={() => onCommand('QUIT')}
                    className="w-full py-3 px-4 bg-slate-800 hover:bg-slate-700 text-orange-400 border border-slate-700 hover:border-orange-500 rounded font-bold uppercase tracking-widest transition-colors"
                 >
                    Return to Menu
                 </button>
             </div>
         </div>
      )}

      {/* Bottom Panel - Modern RTS Style */}
      <div className="h-56 bg-slate-900/95 border-t border-slate-600 flex pointer-events-auto select-none shadow-2xl backdrop-blur">
          {/* Minimap Container */}
          <div className="h-full w-56 bg-black border-r border-slate-600 relative p-2 flex-shrink-0">
              <div 
                  ref={minimapRef}
                  className="w-full h-full relative bg-slate-950 border border-slate-800 cursor-crosshair overflow-hidden"
                  onMouseDown={handleMinimapInteraction}
                  onContextMenu={(e) => handleMinimapInteraction(e)}
              >
                 {/* Map Features */}
                 {allEntities.map(e => {
                     if (e.state === 'GARRISONED') return null;
                     if (!isVisibleOnMinimap(e, playerUnits)) return null;

                     let color = 'bg-slate-600';
                     if (e.type === EntityType.WATER) color = 'bg-blue-900';
                     else if (e.type === EntityType.MOUNTAIN) color = 'bg-slate-700';
                     else if (e.type === EntityType.MINERAL) color = 'bg-cyan-500';
                     else if (e.owner === Owner.PLAYER) color = 'bg-blue-500';
                     else if (e.owner === Owner.AI) color = 'bg-red-500';

                     const size = (e.type === EntityType.WATER || e.type === EntityType.MOUNTAIN) ? 4 : 3;

                     return (
                        <div key={e.id} 
                            className={`absolute rounded-full ${color}`}
                            style={{ 
                                left: `${(e.position.x / GAME_WIDTH) * 100}%`, 
                                top: `${(e.position.y / GAME_HEIGHT) * 100}%`,
                                width: size + 'px', height: size + 'px'
                            }} 
                        />
                     );
                 })}
                 {/* Camera Rect */}
                 <div className="absolute border-2 border-white pointer-events-none shadow-[0_0_10px_rgba(255,255,255,0.5)]"
                      style={{
                          left: `${(gameState.camera.x / GAME_WIDTH) * 100}%`,
                          top: `${(gameState.camera.y / GAME_HEIGHT) * 100}%`,
                          width: `${(window.innerWidth / GAME_WIDTH) * 100}%`,
                          height: `${(window.innerHeight / GAME_HEIGHT) * 100}%`,
                      }}
                 />
              </div>
          </div>

          {/* Unit Info Panel */}
          <div className="flex-1 p-4 border-r border-slate-700 bg-slate-900 overflow-hidden flex flex-col">
             {selectedEntities.length === 0 ? (
                 <div className="h-full flex items-center justify-center text-slate-600 uppercase tracking-widest text-sm font-bold">
                     No Selection
                 </div>
             ) : (
                <>
                <div className="flex flex-wrap gap-1 content-start overflow-auto pr-2 custom-scrollbar">
                     {/* Group logic for Barracks */}
                     {allBarracks.length > 1 && selectedEntities.length === allBarracks.length ? (
                         allBarracks.map(b => (
                             <div key={b.id} className="w-10 h-10 bg-slate-800 border border-slate-600 relative mb-1">
                                 <div className="absolute inset-0 flex items-center justify-center text-[10px] text-slate-300">B</div>
                                 {b.trainQueue && b.trainQueue.length > 0 && (
                                     <div className="absolute -top-1 -right-1 bg-cyan-600 text-white text-[9px] w-3 h-3 rounded-full flex items-center justify-center">{b.trainQueue.length}</div>
                                 )}
                                 <div className="absolute bottom-0 left-0 w-full h-1 bg-slate-900">
                                    <div className="h-full bg-cyan-400" style={{ width: `${(b.trainProgress! / STATS[EntityType.MARINE].buildTime) * 100}%` }} />
                                 </div>
                             </div>
                         ))
                     ) : (
                        selectedEntities.map(e => (
                            <div key={e.id} className="w-10 h-10 bg-slate-800 border border-slate-600 relative mb-1 group">
                                <div className={`w-1.5 h-1.5 absolute top-1 left-1 rounded-full ${e.owner === Owner.PLAYER ? 'bg-blue-500' : 'bg-red-500'}`} />
                                <div className="w-full h-full flex items-center justify-center text-[9px] text-slate-300 font-bold uppercase overflow-hidden p-0.5 text-center leading-none">
                                    {e.type.substring(0, 4)}
                                </div>
                                {e.garrison && e.garrison.length > 0 && (
                                    <div className="flex gap-0.5 absolute bottom-2 left-1">
                                        {e.garrison.map((_, i) => <div key={i} className="w-1 h-1 bg-emerald-500 rounded-full" />)}
                                    </div>
                                )}
                                <div className="absolute bottom-0 left-0 w-full h-1 bg-slate-700">
                                    <div className="h-full bg-emerald-500" style={{ width: `${(e.hp / e.maxHp) * 100}%`}} />
                                </div>
                            </div>
                        ))
                     )}
                </div>
                <div className="mt-auto pt-2 border-t border-slate-700 text-xs text-slate-400 font-mono">
                    {selectedEntities.length} Unit{selectedEntities.length !== 1 && 's'} Selected
                </div>
                </>
             )}
          </div>

          {/* Command Card */}
          <div className="w-72 bg-slate-800 p-3 grid grid-cols-3 grid-rows-3 gap-2 flex-shrink-0 shadow-inner">
              {canBuild && (
                  <>
                    <CommandButton label="Supply Depot" sub="100" hotkey="S" cost={100} res={resources} onClick={() => onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`)} />
                    <CommandButton label="Barracks" sub="150" hotkey="B" cost={150} res={resources} onClick={() => onCommand(`BUILD_${EntityType.BARRACKS}`)} />
                    <CommandButton label="Bunker" sub="100" hotkey="U" cost={100} res={resources} onClick={() => onCommand(`BUILD_${EntityType.BUNKER}`)} />
                  </>
              )}

              {singleSelection?.type === EntityType.BASE && (
                  <CommandButton 
                      label="Train Worker" sub="50" hotkey="W" cost={50} res={resources} 
                      onClick={() => onTrain(EntityType.WORKER)} 
                      progress={singleSelection.trainProgress} max={STATS[EntityType.WORKER].buildTime} queue={singleSelection.trainQueue?.length || 0}
                  />
              )}
              {showBarracksMenu && (
                  <>
                  <CommandButton 
                      label="Train Marine" sub="50" hotkey="M" cost={50} res={resources} 
                      onClick={() => handleMultiTrain(EntityType.MARINE)} 
                      progress={singleSelection ? singleSelection.trainProgress : 0} max={STATS[EntityType.MARINE].buildTime} queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
                  <CommandButton 
                      label="Train Medic" sub="75" hotkey="E" cost={75} res={resources} 
                      onClick={() => handleMultiTrain(EntityType.MEDIC)} 
                      progress={singleSelection ? singleSelection.trainProgress : 0} max={STATS[EntityType.MEDIC].buildTime} queue={singleSelection ? singleSelection.trainQueue?.length : 0}
                  />
                  </>
              )}

              {singleSelection?.type === EntityType.BUNKER && singleSelection.owner === Owner.PLAYER && (
                  <button 
                      onClick={handleUnload}
                      className="bg-slate-700 border border-slate-500 hover:bg-slate-600 active:bg-slate-500 rounded flex flex-col items-center justify-center relative shadow-sm"
                  >
                      <span className="text-yellow-400 font-bold text-xs absolute top-1 right-1">D</span>
                      <span className="text-white text-[10px] font-bold mt-1">UNLOAD</span>
                  </button>
              )}
          </div>
      </div>
    </div>
  );
};

const CommandButton = ({ label, sub, hotkey, cost, res, onClick, progress, max, queue }: any) => {
    const disabled = res < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`
                relative rounded border flex flex-col items-center justify-center p-1 transition-all
                ${disabled 
                    ? 'bg-slate-800 border-slate-700 opacity-50 cursor-not-allowed' 
                    : 'bg-slate-700 border-slate-500 hover:bg-slate-600 active:bg-slate-500 hover:border-cyan-400 shadow-md'}
            `}
        >
            <span className="absolute top-1 right-1 text-xs font-bold text-yellow-400 leading-none">{hotkey}</span>
            <span className="text-[10px] text-slate-200 font-bold leading-tight text-center mt-2">{label}</span>
            <span className="text-[9px] text-cyan-300 leading-none">{sub}</span>

            {queue > 0 && <span className="absolute top-1 left-1 bg-blue-600 text-white text-[9px] w-4 h-4 rounded-full flex items-center justify-center shadow">{queue}</span>}

            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-slate-900 rounded-b">
                    <div className="h-full bg-white opacity-80" style={{ width: `${(progress / max) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

import React, { useEffect, useRef, useState } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

export const GameCanvas: React.FC<Props> = ({ 
    onGameStateUpdate, 
    onSelectionChange, 
    commandMode, 
    setCommandMode,
    isMultiplayer = false,
    gameSeed = 0,
    isHost = true,
    difficulty = Difficulty.MEDIUM
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame(difficulty, isMultiplayer, gameSeed, isHost));
  const requestRef = useRef<number>(0);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });

  // Offscreen Buffers
  const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false);
  const isRightDragging = useRef(false);
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  useEffect(() => {
    const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Initialize Assets
  useEffect(() => {
      terrainCanvasRef.current = renderTerrain();

      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;

      onGameStateUpdate({ ...gameStateRef.current });

      // Center camera
      const entities = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
      const myBase = entities.find(e => e.type === EntityType.BASE && e.owner === Owner.PLAYER);
      if (myBase) {
          gameStateRef.current.camera.x = Math.max(0, myBase.position.x - window.innerWidth / 2);
          gameStateRef.current.camera.y = Math.max(0, myBase.position.y - (window.innerHeight - UI_TOP_HEIGHT) / 2);
      }
  }, []);

  useEffect(() => {
      if (!isMultiplayer) return;
      const handleNetMsg = (msg: NetMessage) => {
          if (msg.type === 'GAME_COMMAND') {
              const { action, data, owner } = msg.payload;
              if (owner !== Owner.PLAYER) {
                 const event = new CustomEvent('GAME_COMMAND', { detail: { ...data, action, _isRemote: true } });
                 window.dispatchEvent(event);
              }
          }
      };
      const unsubscribe = network.subscribe(handleNetMsg);
      return unsubscribe;
  }, [isMultiplayer]);

  // Game Command Handler
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail as any;
          const isRemote = detail._isRemote;

          if (isMultiplayer && !isRemote) {
              if (!['MOVE_CAMERA', 'TOGGLE_PAUSE'].includes(detail.action)) {
                  network.send({ type: 'GAME_COMMAND', payload: { action: detail.action, data: detail, owner: Owner.PLAYER } });
              }
          }

          if (detail.action === 'RESTART' && !isMultiplayer) {
                gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
                if (exploredCanvasRef.current) {
                    const ctx = exploredCanvasRef.current.getContext('2d');
                    if (ctx) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.fillStyle = 'black';
                        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                    }
                }
                onGameStateUpdate({ ...gameStateRef.current });
                return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA' && !isRemote) {
              const UI_BOTTOM_HEIGHT = 224;
              const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
              const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
              gameStateRef.current.camera = { x: Math.max(0, Math.min(detail.x, maxCamX)), y: Math.max(0, Math.min(detail.y, maxCamY)) };
              return;
          }

          const logicEvents = ['TRAIN', 'UNLOAD_ALL', 'SET_RALLY', 'MINIMAP_ACTION', 'UNIT_COMMAND'];
          if (logicEvents.includes(detail.action)) {
             const ents = gameStateRef.current.entities;
             if (detail.action === 'TRAIN') {
                 const ent = ents.get(detail.id);
                 const owner = isRemote ? Owner.OPPONENT : Owner.PLAYER;
                 if (ent && ent.owner === owner) {
                     const s = STATS[detail.type as EntityType];
                     if (gameStateRef.current.resources[owner] >= s.cost) {
                         if (!ent.trainQueue) ent.trainQueue = [];
                         if (ent.trainQueue.length < 5) {
                             ent.trainQueue.push(detail.type);
                             gameStateRef.current.resources[owner] -= s.cost;
                             if(!isRemote) playSound('train');
                         }
                     } else if (!isRemote) { playSound('error'); addNotification(gameStateRef.current, "Not Enough Minerals"); }
                 }
             }
             if (detail.action === 'MINIMAP_ACTION' && !isRemote) {
                 const selected = gameStateRef.current.selection;
                 const pos = {x: detail.x, y: detail.y};
                 gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: pos, type: 'MOVE', life: 20, maxLife: 20 });
                 selected.forEach(id => {
                     const u = ents.get(id);
                     if (u && u.owner === Owner.PLAYER) {
                         u.state = 'MOVING';
                         u.targetPosition = pos;
                         u.targetId = null;
                         if (u.type === EntityType.MARINE && detail.unitAction === 'ATTACK') u.state = 'ATTACKING';
                     }
                 });
                 playSound('click');
             }
             if (detail.action === 'SET_RALLY') {
                 const ent = ents.get(detail.id);
                 if (ent) { ent.rallyPoint = detail.pos; ent.rallyTargetId = detail.targetId; if(!isRemote) playSound('click'); }
             }
             if (detail.action === 'UNLOAD_ALL') {
                  const ent = ents.get(detail.id);
                  if (ent && ent.garrison) {
                      ent.garrison.forEach(uid => {
                          const u = ents.get(uid);
                          if (u) {
                              u.state = 'IDLE'; u.containerId = null;
                              u.position = { x: ent.position.x + (Math.random()*40-20), y: ent.position.y + 30 };
                          }
                      });
                      ent.garrison = [];
                      if(!isRemote) playSound('click');
                  }
             }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, [isMultiplayer, windowSize]);

  // Input Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);
          if ((e.target as HTMLElement).tagName === 'INPUT') return;
          const key = e.key.toUpperCase();
          if (key === 'A') setCommandMode('ATTACK');
          if (key === 'P') { gameStateRef.current.paused = !gameStateRef.current.paused; onGameStateUpdate({...gameStateRef.current}); }

          // --- SHORTCUTS ---
          // 1: Select Worker (Idle > Gathering > Any)
          if (key === '1') {
              const ents = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
              const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

              let target = workers.find(w => w.state === 'IDLE');
              if (!target) target = workers.find(w => w.state === 'GATHERING');
              if (!target && workers.length > 0) target = workers[0];

              if (target) {
                  gameStateRef.current.selection = [target.id];
                  onSelectionChange([target]);
                  playSound('click');
              }
          }

          // 2: Select All Army (Marines + Medics)
          if (key === '2') {
              const ents = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
              const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
              if (army.length > 0) {
                  gameStateRef.current.selection = army.map(u => u.id);
                  onSelectionChange(army);
                  playSound('click');
              }
          }

          // Space: Center Camera on Selection or Base
          if (key === ' ') {
              e.preventDefault();
              if (gameStateRef.current.selection.length > 0) {
                  const id = gameStateRef.current.selection[0];
                  const ent = gameStateRef.current.entities.get(id);
                  if (ent && canvasRef.current) {
                      gameStateRef.current.camera.x = Math.max(0, ent.position.x - canvasRef.current.width / 2);
                      gameStateRef.current.camera.y = Math.max(0, ent.position.y - canvasRef.current.height / 2);
                  }
              } else {
                  const base = Array.from(gameStateRef.current.entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                  if (base && canvasRef.current) {
                      gameStateRef.current.camera.x = Math.max(0, base.position.x - canvasRef.current.width / 2);
                      gameStateRef.current.camera.y = Math.max(0, base.position.y - canvasRef.current.height / 2);
                  }
              }
          }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
  }, [setCommandMode]);

  const getWorldPos = (cx: number, cy: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: cx - rect.left + gameStateRef.current.camera.x, y: cy - rect.top + gameStateRef.current.camera.y };
  };

  const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      const stats = STATS[entity.type];
      for (const pUnit of playerUnits) {
          const pStats = STATS[pUnit.type];
          const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
          if (dist < pStats.vision + entity.radius) return true;
      }
      return false;
  };

  // --- DRAWING ---
  const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
      ctx.save();
      ctx.translate(entity.position.x, entity.position.y);

      const isPlayer = entity.owner === Owner.PLAYER;
      const primaryColor = isPlayer ? '#3b82f6' : '#ef4444'; // Blue : Red
      const secondaryColor = isPlayer ? '#1e40af' : '#991b1b';

      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.beginPath();
      ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
      ctx.fill();

      // Construction
      if (entity.constructionProgress! < 100) {
          ctx.globalAlpha = 0.6;
          // Scaffold
          ctx.strokeStyle = '#fbbf24';
          ctx.setLineDash([4, 2]);
          ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
          ctx.setLineDash([]);
      }

      if (entity.type === EntityType.WORKER) {
          // Body
          const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
          grad.addColorStop(0, '#e5e7eb');
          grad.addColorStop(1, '#9ca3af');
          ctx.fillStyle = grad;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Backpack (Resources)
          if (entity.resourceAmount && entity.resourceAmount > 0) {
              ctx.fillStyle = '#06b6d4'; // Blue crystal
              ctx.fillRect(-4, -6, 8, 4);
          } else {
              ctx.fillStyle = '#374151'; // Empty pack
              ctx.fillRect(-4, -5, 8, 3);
          }

          // Drill Arm
          ctx.fillStyle = '#4b5563';
          ctx.save();
          const angle = entity.targetPosition ? Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x) : 0;
          ctx.rotate(angle);
          ctx.fillRect(4, -1, 6, 2); // Arm
          ctx.fillStyle = '#d1d5db';
          ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(14, 0); ctx.lineTo(10, 2); ctx.fill(); // Tip
          ctx.restore();

      } else if (entity.type === EntityType.MARINE) {
          // Shoulders
          ctx.fillStyle = secondaryColor;
          ctx.beginPath(); ctx.arc(-5, -2, 3, 0, Math.PI * 2); ctx.fill();
          ctx.beginPath(); ctx.arc(5, -2, 3, 0, Math.PI * 2); ctx.fill();

          // Body
          ctx.fillStyle = primaryColor;
          ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

          // Gun
          ctx.save();
          // Ideally rotate towards target, simplified:
          if (entity.state === 'ATTACKING') {
              const tId = entity.targetId;
              // We'd need target position here to rotate correctly, but visual abstraction is OK
          }
          ctx.fillStyle = '#111827';
          ctx.fillRect(2, -1, 10, 3); // Gun barrel
          ctx.restore();

          // Visor reflection
          ctx.fillStyle = 'rgba(255,255,255,0.8)';
          ctx.beginPath(); ctx.arc(1, -2, 1.5, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.MEDIC) {
          ctx.fillStyle = '#fff';
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
          // Cross
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(-2, -5, 4, 10);
          ctx.fillRect(-5, -2, 10, 4);
          // Shield/Pack
          ctx.strokeStyle = '#d1d5db';
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.stroke();

      } else if (entity.type === EntityType.BASE) {
          // Base Plate
          ctx.fillStyle = '#374151';
          ctx.fillRect(-30, -30, 60, 60);

          // Structure
          const grad = ctx.createLinearGradient(-30, -30, 30, 30);
          grad.addColorStop(0, primaryColor);
          grad.addColorStop(1, secondaryColor);
          ctx.fillStyle = grad;
          ctx.fillRect(-25, -25, 50, 50);

          // Detail Lines
          ctx.strokeStyle = 'rgba(255,255,255,0.2)';
          ctx.lineWidth = 2;
          ctx.beginPath(); 
          ctx.moveTo(-25, 0); ctx.lineTo(25, 0); 
          ctx.moveTo(0, -25); ctx.lineTo(0, 25);
          ctx.stroke();

          // Center Hub
          ctx.fillStyle = '#111827';
          ctx.fillRect(-10, -10, 20, 20);
          // Blinking Light
          const blink = Math.sin(Date.now() / 200) > 0;
          ctx.fillStyle = blink ? '#ef4444' : '#7f1d1d';
          ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

      } else if (entity.type === EntityType.BARRACKS) {
          ctx.fillStyle = '#1f2937';
          ctx.fillRect(-25, -25, 50, 50);

          // Roof Hatch
          ctx.fillStyle = primaryColor;
          ctx.beginPath();
          ctx.moveTo(-20, -20); ctx.lineTo(20, -20); ctx.lineTo(15, 15); ctx.lineTo(-15, 15);
          ctx.fill();

          // Stripes
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(-15, 15); ctx.lineTo(-15, 25);
          ctx.moveTo(15, 15); ctx.lineTo(15, 25);
          ctx.stroke();

      } else if (entity.type === EntityType.MINERAL) {
          // Crystals
          ctx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Glow
          ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();

          ctx.fillStyle = '#06b6d4';
          const drawCrystal = (ox: number, oy: number, s: number, r: number) => {
              ctx.save();
              ctx.translate(ox, oy);
              ctx.rotate(r);
              ctx.beginPath();
              ctx.moveTo(0, -s); ctx.lineTo(s*0.6, 0); ctx.lineTo(0, s); ctx.lineTo(-s*0.6, 0);
              ctx.fill();
              // Facet
              ctx.fillStyle = '#67e8f9';
              ctx.beginPath(); ctx.moveTo(0, -s); ctx.lineTo(s*0.3, 0); ctx.lineTo(0, s*0.4);
              ctx.fill();
              ctx.fillStyle = '#06b6d4'; // Reset
              ctx.restore();
          };

          drawCrystal(0, -5, 10, 0);
          drawCrystal(-6, 4, 8, -0.5);
          drawCrystal(6, 4, 8, 0.5);

      } else if (entity.type === EntityType.MOUNTAIN) {
          ctx.fillStyle = '#44403c';
          ctx.beginPath();
          // Irregular rock shape
          ctx.moveTo(-30, 20); ctx.lineTo(-10, 30); ctx.lineTo(20, 25); ctx.lineTo(35, 0);
          ctx.lineTo(20, -30); ctx.lineTo(-10, -35); ctx.lineTo(-35, -10);
          ctx.fill();

          // Highlights
          ctx.fillStyle = '#57534e';
          ctx.beginPath();
          ctx.moveTo(-10, -20); ctx.lineTo(10, -10); ctx.lineTo(0, 10);
          ctx.fill();

      } else if (entity.type === EntityType.WATER) {
          ctx.fillStyle = '#1e3a8a';
          ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
          ctx.strokeStyle = '#3b82f6';
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.arc(0,0, 28, 0, Math.PI*2); ctx.stroke();
      }

      // Selection Ring
      if (isSelected) {
          ctx.strokeStyle = '#10b981';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
          ctx.stroke();

          // Health Bar (Only if selected or damaged)
          const pct = Math.max(0, entity.hp / entity.maxHp);
          const w = 24;
          ctx.fillStyle = '#000';
          ctx.fillRect(-w/2 - 1, -entity.radius - 12, w + 2, 6);
          ctx.fillStyle = pct > 0.5 ? '#10b981' : '#ef4444';
          ctx.fillRect(-w/2, -entity.radius - 11, w * pct, 4);
      } else if (entity.hp < entity.maxHp) {
           const pct = Math.max(0, entity.hp / entity.maxHp);
           const w = 20;
           ctx.fillStyle = '#000';
           ctx.fillRect(-w/2, -entity.radius - 8, w, 4);
           ctx.fillStyle = '#ef4444'; 
           ctx.fillRect(-w/2, -entity.radius - 8, w * pct, 4);
      }

      ctx.restore();
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    const allEntities = Array.from(state.entities.values()) as GameEntity[];
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG & TERRAIN ---
    // Draw Terrain Cache
    if (terrainCanvasRef.current) {
        // Draw terrain shifted by camera
        ctx.drawImage(terrainCanvasRef.current, -state.camera.x, -state.camera.y);
    } else {
        ctx.fillStyle = '#111'; ctx.fillRect(0,0,width,height);
    }

    // Fog Calculation
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.7)'; // Darker fog
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath(); ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxExp.fill();
                ctxVis.beginPath(); ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxVis.fill();
            });
        }

        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
        // Draw Explored (Darkened Terrain)
        ctx.drawImage(exploredCanvasRef.current, 0, 0);
    } else {
        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
    }

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2;
             const r = 10 * (1 + (1-lifePct));
             ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0, -r); ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
             const r = 10;
             ctx.beginPath(); ctx.moveTo(-r, -r); ctx.lineTo(r, r); ctx.moveTo(r, -r); ctx.lineTo(-r, r); ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    // Sort by Y for pseudo-depth
    const sorted = [...allEntities].sort((a,b) => a.position.y - b.position.y);
    sorted.forEach((entity: GameEntity) => {
      if (!visibleEntities.has(entity.id)) return;
      const isSelected = state.selection.includes(entity.id);
      drawUnit(ctx, entity, isSelected);

      // Rally Lines
      if (isSelected && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.strokeStyle = '#f59e0b'; ctx.setLineDash([5, 5]); ctx.beginPath();
          ctx.moveTo(entity.position.x, entity.position.y); ctx.lineTo(entity.rallyPoint.x, entity.rallyPoint.y);
          ctx.stroke(); ctx.setLineDash([]);
      }

      // Attack Beams
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? '#facc15' : 'white';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y - 5);
              ctx.lineTo(target.position.x, target.position.y - 5);
              ctx.stroke();

              // Hit flash
              ctx.fillStyle = '#fff';
              ctx.beginPath(); ctx.arc(target.position.x, target.position.y - 5, 5, 0, Math.PI*2); ctx.fill();
          }
      }
    });

    // Effects
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION' || fx.type === 'BUILDING_EXPLOSION') {
            const r = (1 - lifePct) * (fx.type === 'BUILDING_EXPLOSION' ? 100 : 40) * fx.scale;
            const alpha = lifePct;
            ctx.globalAlpha = alpha;
            const grad = ctx.createRadialGradient(0,0,0,0,0,r);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, '#f59e0b');
            grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2; ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0,-15*lifePct); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-3,-15*lifePct); ctx.lineTo(3,-15*lifePct); ctx.stroke();
        }
        ctx.restore();
    });

    // Draw Fog Overlay on top
    if (visionCanvasRef.current) {
         ctx.drawImage(visionCanvasRef.current, 0, 0);
    }

    ctx.restore(); // Pop Camera

    // Screen Space UI (Selection Box)
    if (mouseDownStateRef.current) {
        const startScreen = mouseDownStateRef.current.screen;
        const curScreen = mousePos;

        // CORRECT COORDINATE TRANSFORMATION FOR CANVAS RENDER
        const rect = ctx.canvas.getBoundingClientRect();
        const startX = startScreen.x - rect.left;
        const startY = startScreen.y - rect.top;
        const curX = curScreen.x - rect.left;
        const curY = curScreen.y - rect.top;

        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(startX, startY, curX - startX, curY - startY);
        ctx.setLineDash([]);
    }

    // Build Preview
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = getWorldPos(mousePos.x, mousePos.y);
       const stats = STATS[type];

       ctx.save();
       ctx.translate(worldMouse.x - gameStateRef.current.camera.x, worldMouse.y - gameStateRef.current.camera.y);

       const valid = gameStateRef.current.resources[Owner.PLAYER] >= stats.cost;
       ctx.fillStyle = valid ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)';
       ctx.fillRect(-stats.width/2, -stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = '#fff';
       ctx.strokeRect(-stats.width/2, -stats.height/2, stats.width, stats.height);

       ctx.restore();
    }

    // Notification & Pause UI
    if (state.paused) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white'; ctx.font = 'bold 48px monospace'; ctx.textAlign = 'center';
        ctx.fillText('PAUSED', width / 2, height / 2);
    }
    if (state.notifications.length > 0) {
        ctx.font = 'bold 20px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#f87171';
        state.notifications.forEach((n, i) => {
            const y = height - 300 - (i * 30);
            ctx.globalAlpha = n.life / 60;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.globalAlpha = 1;
    }
  };

  // Loop & Input Handlers (Same as previous)
  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }
    const mousePos = mousePosRef.current;

    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > windowSize.height - margin && mousePos.y <= windowSize.height) gameStateRef.current.camera.y += panSpeed;
    }

    const UI_BOTTOM_HEIGHT = 224; 
    const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
    const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, maxCamX));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, maxCamY));

    if (canvasRef.current) draw(canvasRef.current.getContext('2d')!);
    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused || gameStateRef.current.victory) {
        onGameStateUpdate({ ...gameStateRef.current });
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (gameStateRef.current.paused) return;
      if (e.button === 1) { e.preventDefault(); isDraggingCamera.current = true; lastDragPos.current = { x: e.clientX, y: e.clientY }; return; }
      if (e.button === 2) { e.preventDefault(); rightDragStart.current = { x: e.clientX, y: e.clientY }; lastDragPos.current = { x: e.clientX, y: e.clientY }; isRightDragging.current = false; return; }
      if (e.button === 0) {
          if (commandMode === 'ATTACK') {
              const pos = getWorldPos(e.clientX, e.clientY);
              const all = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
              const pUnits = all.filter(en => en.owner === Owner.PLAYER);
              const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

              gameStateRef.current.selection.forEach(id => {
                 const u = gameStateRef.current.entities.get(id) as GameEntity | undefined;
                 if (u && u.owner === Owner.PLAYER) {
                     u.state = 'ATTACKING'; u.targetPosition = pos; u.targetId = target ? target.id : null;
                     if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'UNIT_COMMAND', subAction: 'ATTACK', unitId: id, targetPos: pos, targetId: target?.id } }));
                 }
              });
              gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: target ? target.position : pos, type: 'ATTACK', life: 20, maxLife: 20 });
              setCommandMode(null); playSound('click'); return;
          }
          if (commandMode && commandMode.startsWith('BUILD_')) {
              const type = commandMode.replace('BUILD_', '') as EntityType;
              const pos = getWorldPos(e.clientX, e.clientY);
              const s = STATS[type];
              if (gameStateRef.current.resources[Owner.PLAYER] >= s.cost) {
                  gameStateRef.current.resources[Owner.PLAYER] -= s.cost;
                  const b = createEntity(type, Owner.PLAYER, pos, `${network.id}_b_${Math.random()}`);
                  b.constructionProgress = 0; gameStateRef.current.entities.set(b.id, b);
                  setCommandMode(null); playSound('build');
                  if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'BUILD', type, pos } }));
              } else { addNotification(gameStateRef.current, "Not Enough Minerals"); playSound('error'); }
              return;
          }
          const wPos = getWorldPos(e.clientX, e.clientY);
          mouseDownStateRef.current = { screen: {x:e.clientX, y:e.clientY}, world: wPos };
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };
    if (gameStateRef.current.paused) return;
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) isRightDragging.current = true;
        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;
     if (e.button === 1) { isDraggingCamera.current = false; return; }
     if (e.button === 2) {
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const all = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
             const pUnits = all.filter(en => en.owner === Owner.PLAYER);
             const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

             const selection = gameStateRef.current.selection;
             if (selection.length > 0) {
                 const hasBuildings = selection.some(id => { const u=gameStateRef.current.entities.get(id) as GameEntity | undefined; return !!(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE || u.type===EntityType.BARRACKS))});
                 if (hasBuildings) {
                     selection.forEach(id => {
                         const u=gameStateRef.current.entities.get(id) as GameEntity | undefined;
                         if(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE||u.type===EntityType.BARRACKS)) {
                             window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action:'SET_RALLY', id:u.id, pos, targetId: target?target.id:null}}));
                         }
                     });
                 } else {
                     playSound('click');
                     let moveType = 'MOVE';
                     let tId = null;
                     if (target && target.owner !== Owner.PLAYER) { moveType = 'ATTACK'; tId = target.id; }
                     else if (target && target.type === EntityType.MINERAL) { moveType = 'GATHER'; tId = target.id; }

                     window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y, unitAction: moveType, targetId: tId }}));
                 }
             }
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         // Selection Box Logic
         const start = mouseDownStateRef.current.world;
         const cur = getWorldPos(e.clientX, e.clientY);
         const dist = Math.sqrt(Math.pow(e.clientX - mouseDownStateRef.current.screen.x, 2) + Math.pow(e.clientY - mouseDownStateRef.current.screen.y, 2));
         const isClick = dist < 5;

         const minX = Math.min(start.x, cur.x); const maxX = Math.max(start.x, cur.x);
         const minY = Math.min(start.y, cur.y); const maxY = Math.max(start.y, cur.y);

         const newSel: string[] = [];
         const all = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
         const pUnits = all.filter(en => en.owner === Owner.PLAYER);

         all.forEach(en => {
             if (en.type === EntityType.MOUNTAIN || en.type === EntityType.WATER || en.state==='GARRISONED') return;
             if (!isEntityVisible(en, pUnits)) return;
             if (!isClick && en.owner !== Owner.PLAYER) return;

             if (isClick) {
                 if (Math.sqrt(Math.pow(en.position.x-cur.x,2)+Math.pow(en.position.y-cur.y,2)) < en.radius+15) newSel.push(en.id);
             } else {
                 if (en.position.x > minX && en.position.x < maxX && en.position.y > minY && en.position.y < maxY && en.owner === Owner.PLAYER) newSel.push(en.id);
             }
         });

         if (isClick && newSel.length > 0) { 
             playSound('click'); 
             const clickedId = newSel[0]; 

             // Shift-Click Toggle
             if (e.shiftKey) {
                 const prev = gameStateRef.current.selection;
                 if (prev.includes(clickedId)) {
                     gameStateRef.current.selection = prev.filter(id => id !== clickedId);
                 } else {
                     gameStateRef.current.selection = [...prev, clickedId];
                 }
             } else {
                 gameStateRef.current.selection = [clickedId];
             }
         }
         else if (newSel.length > 0) {
              const nonBuildings = newSel.filter(id => { const t = (gameStateRef.current.entities.get(id) as GameEntity | undefined)?.type; return t!==EntityType.BASE && t!==EntityType.BARRACKS && t!==EntityType.SUPPLY_DEPOT && t!==EntityType.BUNKER });
              // Drag selection usually excludes buildings unless ONLY buildings are selected, OR shift is used.
              // For shift drag, we just add whatever is valid.
              const candidates = nonBuildings.length > 0 ? nonBuildings : newSel;

              if (e.shiftKey) {
                   const combined = new Set([...gameStateRef.current.selection, ...candidates]);
                   gameStateRef.current.selection = Array.from(combined);
              } else {
                   gameStateRef.current.selection = candidates;
              }
         } else if (!e.shiftKey) {
             gameStateRef.current.selection = [];
         }

         onSelectionChange(gameStateRef.current.selection.map(id => gameStateRef.current.entities.get(id)!).filter(Boolean) as GameEntity[]);
         mouseDownStateRef.current = null;
     }
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  return (
    <canvas
      ref={canvasRef}
      width={windowSize.width}
      height={windowSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { mouseDownStateRef.current=null; isDraggingCamera.current=false; isRightDragging.current=false; }}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    const stats = STATS[entity.type];
    for (const pUnit of playerUnits) {
        const pStats = STATS[pUnit.type];
        const dist = Math.sqrt(Math.pow(entity.position.x - pUnit.position.x, 2) + Math.pow(entity.position.y - pUnit.position.y, 2));
        if (dist < pStats.vision + entity.radius) return true;
    }
    return false;
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const primaryColor = isPlayer ? '#3b82f6' : '#ef4444'; // Blue : Red
    const secondaryColor = isPlayer ? '#1e40af' : '#991b1b';

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        // Scaffold
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
    }

    if (entity.type === EntityType.WORKER) {
        // Body
        const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
        grad.addColorStop(0, '#e5e7eb');
        grad.addColorStop(1, '#9ca3af');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

        // Backpack (Resources)
        if (entity.resourceAmount && entity.resourceAmount > 0) {
            ctx.fillStyle = '#06b6d4'; // Blue crystal
            ctx.fillRect(-4, -6, 8, 4);
        } else {
            ctx.fillStyle = '#374151'; // Empty pack
            ctx.fillRect(-4, -5, 8, 3);
        }

        // Drill Arm
        ctx.fillStyle = '#4b5563';
        ctx.save();
        const angle = entity.targetPosition ? Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x) : 0;
        ctx.rotate(angle);
        ctx.fillRect(4, -1, 6, 2); // Arm
        ctx.fillStyle = '#d1d5db';
        ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(14, 0); ctx.lineTo(10, 2); ctx.fill(); // Tip
        ctx.restore();

    } else if (entity.type === EntityType.MARINE) {
        // Shoulders
        ctx.fillStyle = secondaryColor;
        ctx.beginPath(); ctx.arc(-5, -2, 3, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.arc(5, -2, 3, 0, Math.PI * 2); ctx.fill();

        // Body
        ctx.fillStyle = primaryColor;
        ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI * 2); ctx.fill();

        // Gun
        ctx.save();
        // Ideally rotate towards target, simplified:
        if (entity.state === 'ATTACKING') {
            const tId = entity.targetId;
            // We'd need target position here to rotate correctly, but visual abstraction is OK
        }
        ctx.fillStyle = '#111827';
        ctx.fillRect(2, -1, 10, 3); // Gun barrel
        ctx.restore();

        // Visor reflection
        ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.beginPath(); ctx.arc(1, -2, 1.5, 0, Math.PI*2); ctx.fill();

    } else if (entity.type === EntityType.MEDIC) {
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
        // Cross
        ctx.fillStyle = '#ef4444';
        ctx.fillRect(-2, -5, 4, 10);
        ctx.fillRect(-5, -2, 10, 4);
        // Shield/Pack
        ctx.strokeStyle = '#d1d5db';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.stroke();

    } else if (entity.type === EntityType.BASE) {
        // Base Plate
        ctx.fillStyle = '#374151';
        ctx.fillRect(-30, -30, 60, 60);

        // Structure
        const grad = ctx.createLinearGradient(-30, -30, 30, 30);
        grad.addColorStop(0, primaryColor);
        grad.addColorStop(1, secondaryColor);
        ctx.fillStyle = grad;
        ctx.fillRect(-25, -25, 50, 50);

        // Detail Lines
        ctx.strokeStyle = 'rgba(255,255,255,0.2)';
        ctx.lineWidth = 2;
        ctx.beginPath(); 
        ctx.moveTo(-25, 0); ctx.lineTo(25, 0); 
        ctx.moveTo(0, -25); ctx.lineTo(0, 25);
        ctx.stroke();

        // Center Hub
        ctx.fillStyle = '#111827';
        ctx.fillRect(-10, -10, 20, 20);
        // Blinking Light
        const blink = Math.sin(Date.now() / 200) > 0;
        ctx.fillStyle = blink ? '#ef4444' : '#7f1d1d';
        ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

    } else if (entity.type === EntityType.BARRACKS) {
        ctx.fillStyle = '#1f2937';
        ctx.fillRect(-25, -25, 50, 50);

        // Roof Hatch
        ctx.fillStyle = primaryColor;
        ctx.beginPath();
        ctx.moveTo(-20, -20); ctx.lineTo(20, -20); ctx.lineTo(15, 15); ctx.lineTo(-15, 15);
        ctx.fill();

        // Stripes
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-15, 15); ctx.lineTo(-15, 25);
        ctx.moveTo(15, 15); ctx.lineTo(15, 25);
        ctx.stroke();

    } else if (entity.type === EntityType.MINERAL) {
        // Crystals
        ctx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Glow
        ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();

        ctx.fillStyle = '#06b6d4';
        const drawCrystal = (ox: number, oy: number, s: number, r: number) => {
            ctx.save();
            ctx.translate(ox, oy);
            ctx.rotate(r);
            ctx.beginPath();
            ctx.moveTo(0, -s); ctx.lineTo(s*0.6, 0); ctx.lineTo(0, s); ctx.lineTo(-s*0.6, 0);
            ctx.fill();
            // Facet
            ctx.fillStyle = '#67e8f9';
            ctx.beginPath(); ctx.moveTo(0, -s); ctx.lineTo(s*0.3, 0); ctx.lineTo(0, s*0.4);
            ctx.fill();
            ctx.fillStyle = '#06b6d4'; // Reset
            ctx.restore();
        };

        drawCrystal(0, -5, 10, 0);
        drawCrystal(-6, 4, 8, -0.5);
        drawCrystal(6, 4, 8, 0.5);

    } else if (entity.type === EntityType.MOUNTAIN) {
        ctx.fillStyle = '#44403c';
        ctx.beginPath();
        // Irregular rock shape
        ctx.moveTo(-30, 20); ctx.lineTo(-10, 30); ctx.lineTo(20, 25); ctx.lineTo(35, 0);
        ctx.lineTo(20, -30); ctx.lineTo(-10, -35); ctx.lineTo(-35, -10);
        ctx.fill();

        // Highlights
        ctx.fillStyle = '#57534e';
        ctx.beginPath();
        ctx.moveTo(-10, -20); ctx.lineTo(10, -10); ctx.lineTo(0, 10);
        ctx.fill();

    } else if (entity.type === EntityType.WATER) {
        ctx.fillStyle = '#1e3a8a';
        ctx.beginPath(); ctx.arc(0,0, 30, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0,0, 28, 0, Math.PI*2); ctx.stroke();
    }

    // Selection Ring
    if (isSelected) {
        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 5, 0, Math.PI * 2);
        ctx.stroke();

        // Health Bar (Only if selected or damaged)
        const pct = Math.max(0, entity.hp / entity.maxHp);
        const w = 24;
        ctx.fillStyle = '#000';
        ctx.fillRect(-w/2 - 1, -entity.radius - 12, w + 2, 6);
        ctx.fillStyle = pct > 0.5 ? '#10b981' : '#ef4444';
        ctx.fillRect(-w/2, -entity.radius - 11, w * pct, 4);
    } else if (entity.hp < entity.maxHp) {
            const pct = Math.max(0, entity.hp / entity.maxHp);
            const w = 20;
            ctx.fillStyle = '#000';
            ctx.fillRect(-w/2, -entity.radius - 8, w, 4);
            ctx.fillStyle = '#ef4444'; 
            ctx.fillRect(-w/2, -entity.radius - 8, w * pct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({ 
    onGameStateUpdate, 
    onSelectionChange, 
    commandMode, 
    setCommandMode,
    isMultiplayer = false,
    gameSeed = 0,
    isHost = true,
    difficulty = Difficulty.MEDIUM
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<GameState>(initGame(difficulty, isMultiplayer, gameSeed, isHost));
  const requestRef = useRef<number>(0);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });

  // Offscreen Buffers
  const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const exploredCanvasRef = useRef<HTMLCanvasElement | null>(null);
  const visionCanvasRef = useRef<HTMLCanvasElement | null>(null);

  const mouseDownStateRef = useRef<{ screen: Vector2, world: Vector2 } | null>(null);
  const mousePosRef = useRef<Vector2>({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

  const keysPressed = useRef<Set<string>>(new Set());
  const isDraggingCamera = useRef(false);
  const isRightDragging = useRef(false);
  const lastDragPos = useRef<Vector2>({ x: 0, y: 0 });
  const rightDragStart = useRef<Vector2>({ x: 0, y: 0 });

  useEffect(() => {
    const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight - UI_TOP_HEIGHT });
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Initialize Assets
  useEffect(() => {
      terrainCanvasRef.current = renderTerrain();

      const explored = document.createElement('canvas');
      explored.width = GAME_WIDTH;
      explored.height = GAME_HEIGHT;
      const ctxE = explored.getContext('2d');
      if (ctxE) {
          ctxE.fillStyle = 'black';
          ctxE.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      }
      exploredCanvasRef.current = explored;

      const vision = document.createElement('canvas');
      vision.width = GAME_WIDTH;
      vision.height = GAME_HEIGHT;
      visionCanvasRef.current = vision;

      onGameStateUpdate({ ...gameStateRef.current });

      // Center camera
      const entities = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
      const myBase = entities.find(e => e.type === EntityType.BASE && e.owner === Owner.PLAYER);
      if (myBase) {
          gameStateRef.current.camera.x = Math.max(0, myBase.position.x - window.innerWidth / 2);
          gameStateRef.current.camera.y = Math.max(0, myBase.position.y - (window.innerHeight - UI_TOP_HEIGHT) / 2);
      }
  }, []);

  useEffect(() => {
      if (!isMultiplayer) return;
      const handleNetMsg = (msg: NetMessage) => {
          if (msg.type === 'GAME_COMMAND') {
              const { action, data, owner } = msg.payload;
              if (owner !== Owner.PLAYER) {
                 const event = new CustomEvent('GAME_COMMAND', { detail: { ...data, action, _isRemote: true } });
                 window.dispatchEvent(event);
              }
          }
      };
      const unsubscribe = network.subscribe(handleNetMsg);
      return unsubscribe;
  }, [isMultiplayer]);

  // Game Command Handler
  useEffect(() => {
      const handleCommand = (e: Event) => {
          const detail = (e as CustomEvent).detail as any;
          const isRemote = detail._isRemote;

          if (isMultiplayer && !isRemote) {
              if (!['MOVE_CAMERA', 'TOGGLE_PAUSE'].includes(detail.action)) {
                  network.send({ type: 'GAME_COMMAND', payload: { action: detail.action, data: detail, owner: Owner.PLAYER } });
              }
          }

          if (detail.action === 'RESTART' && !isMultiplayer) {
                gameStateRef.current = initGame(detail.difficulty || Difficulty.MEDIUM);
                if (exploredCanvasRef.current) {
                    const ctx = exploredCanvasRef.current.getContext('2d');
                    if (ctx) {
                        ctx.globalCompositeOperation = 'source-over';
                        ctx.fillStyle = 'black';
                        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
                    }
                }
                onGameStateUpdate({ ...gameStateRef.current });
                return;
          }

          if (detail.action === 'TOGGLE_PAUSE') {
              gameStateRef.current.paused = !gameStateRef.current.paused;
              onGameStateUpdate({ ...gameStateRef.current }); 
              return;
          }

          if (detail.action === 'MOVE_CAMERA' && !isRemote) {
              const UI_BOTTOM_HEIGHT = 224;
              const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
              const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
              gameStateRef.current.camera = { x: Math.max(0, Math.min(detail.x, maxCamX)), y: Math.max(0, Math.min(detail.y, maxCamY)) };
              return;
          }

          const logicEvents = ['TRAIN', 'UNLOAD_ALL', 'SET_RALLY', 'MINIMAP_ACTION', 'UNIT_COMMAND'];
          if (logicEvents.includes(detail.action)) {
             const ents = gameStateRef.current.entities;
             if (detail.action === 'TRAIN') {
                 const ent = ents.get(detail.id);
                 const owner = isRemote ? Owner.OPPONENT : Owner.PLAYER;
                 if (ent && ent.owner === owner) {
                     const s = STATS[detail.type as EntityType];
                     if (gameStateRef.current.resources[owner] >= s.cost) {
                         if (!ent.trainQueue) ent.trainQueue = [];
                         if (ent.trainQueue.length < 5) {
                             ent.trainQueue.push(detail.type);
                             gameStateRef.current.resources[owner] -= s.cost;
                             if(!isRemote) playSound('train');
                         }
                     } else if (!isRemote) { playSound('error'); addNotification(gameStateRef.current, "Not Enough Minerals"); }
                 }
             }
             if (detail.action === 'MINIMAP_ACTION' && !isRemote) {
                 const selected = gameStateRef.current.selection;
                 const pos = {x: detail.x, y: detail.y};
                 gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: pos, type: 'MOVE', life: 20, maxLife: 20 });
                 selected.forEach(id => {
                     const u = ents.get(id);
                     if (u && u.owner === Owner.PLAYER) {
                         u.state = 'MOVING';
                         u.targetPosition = pos;
                         u.targetId = null;
                         if (u.type === EntityType.MARINE && detail.unitAction === 'ATTACK') u.state = 'ATTACKING';
                     }
                 });
                 playSound('click');
             }
             if (detail.action === 'SET_RALLY') {
                 const ent = ents.get(detail.id);
                 if (ent) { ent.rallyPoint = detail.pos; ent.rallyTargetId = detail.targetId; if(!isRemote) playSound('click'); }
             }
             if (detail.action === 'UNLOAD_ALL') {
                  const ent = ents.get(detail.id);
                  if (ent && ent.garrison) {
                      ent.garrison.forEach(uid => {
                          const u = ents.get(uid);
                          if (u) {
                              u.state = 'IDLE'; u.containerId = null;
                              u.position = { x: ent.position.x + (Math.random()*40-20), y: ent.position.y + 30 };
                          }
                      });
                      ent.garrison = [];
                      if(!isRemote) playSound('click');
                  }
             }
          }
      };
      window.addEventListener('GAME_COMMAND', handleCommand);
      return () => window.removeEventListener('GAME_COMMAND', handleCommand);
  }, [isMultiplayer, windowSize]);

  // Input Listeners
  useEffect(() => {
      const onKeyDown = (e: KeyboardEvent) => {
          keysPressed.current.add(e.code);
          if ((e.target as HTMLElement).tagName === 'INPUT') return;
          const key = e.key.toUpperCase();
          if (key === 'A') setCommandMode('ATTACK');
          if (key === 'P') { gameStateRef.current.paused = !gameStateRef.current.paused; onGameStateUpdate({...gameStateRef.current}); }

          // --- SHORTCUTS ---
          // 1: Select Worker (Idle > Gathering > Any)
          if (key === '1') {
              const ents = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
              const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

              let target = workers.find(w => w.state === 'IDLE');
              if (!target) target = workers.find(w => w.state === 'GATHERING');
              if (!target && workers.length > 0) target = workers[0];

              if (target) {
                  gameStateRef.current.selection = [target.id];
                  onSelectionChange([target]);
                  playSound('click');
              }
          }

          // 2: Select All Army (Marines + Medics)
          if (key === '2') {
              const ents = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
              const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
              if (army.length > 0) {
                  gameStateRef.current.selection = army.map(u => u.id);
                  onSelectionChange(army);
                  playSound('click');
              }
          }

          // Space: Center Camera on Selection or Base
          if (key === ' ') {
              e.preventDefault();
              if (gameStateRef.current.selection.length > 0) {
                  const id = gameStateRef.current.selection[0];
                  const ent = gameStateRef.current.entities.get(id);
                  if (ent && canvasRef.current) {
                      gameStateRef.current.camera.x = Math.max(0, ent.position.x - canvasRef.current.width / 2);
                      gameStateRef.current.camera.y = Math.max(0, ent.position.y - canvasRef.current.height / 2);
                  }
              } else {
                  const base = Array.from(gameStateRef.current.entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                  if (base && canvasRef.current) {
                      gameStateRef.current.camera.x = Math.max(0, base.position.x - canvasRef.current.width / 2);
                      gameStateRef.current.camera.y = Math.max(0, base.position.y - canvasRef.current.height / 2);
                  }
              }
          }
      };
      const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);
      window.addEventListener('keydown', onKeyDown);
      window.addEventListener('keyup', onKeyUp);
      return () => { window.removeEventListener('keydown', onKeyDown); window.removeEventListener('keyup', onKeyUp); };
  }, [setCommandMode]);

  const getWorldPos = (cx: number, cy: number) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: cx - rect.left + gameStateRef.current.camera.x, y: cy - rect.top + gameStateRef.current.camera.y };
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    const state = gameStateRef.current;
    const { width, height } = ctx.canvas;
    const mousePos = mousePosRef.current;

    const allEntities = Array.from(state.entities.values()) as GameEntity[];
    const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');
    const visibleEntities = new Set<string>();
    allEntities.forEach(e => {
        if (e.state === 'GARRISONED') return;
        if (isEntityVisible(e, playerUnits)) visibleEntities.add(e.id);
    });

    // --- FOG & TERRAIN ---
    // Draw Terrain Cache
    if (terrainCanvasRef.current) {
        // Draw terrain shifted by camera
        ctx.drawImage(terrainCanvasRef.current, -state.camera.x, -state.camera.y);
    } else {
        ctx.fillStyle = '#111'; ctx.fillRect(0,0,width,height);
    }

    // Fog Calculation
    if (exploredCanvasRef.current && visionCanvasRef.current) {
        const ctxExp = exploredCanvasRef.current.getContext('2d');
        const ctxVis = visionCanvasRef.current.getContext('2d');
        if (ctxExp && ctxVis) {
            ctxExp.globalCompositeOperation = 'destination-out';
            ctxExp.fillStyle = 'white';

            ctxVis.globalCompositeOperation = 'source-over';
            ctxVis.fillStyle = 'rgba(0, 0, 0, 0.7)'; // Darker fog
            ctxVis.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
            ctxVis.globalCompositeOperation = 'destination-out';
            ctxVis.fillStyle = 'white';

            playerUnits.forEach(u => {
                const range = STATS[u.type].vision;
                ctxExp.beginPath(); ctxExp.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxExp.fill();
                ctxVis.beginPath(); ctxVis.arc(u.position.x, u.position.y, range, 0, Math.PI * 2); ctxVis.fill();
            });
        }

        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
        // Draw Explored (Darkened Terrain)
        ctx.drawImage(exploredCanvasRef.current, 0, 0);
    } else {
        ctx.save();
        ctx.translate(-state.camera.x, -state.camera.y);
    }

    // Markers
    state.markers.forEach(mk => {
        const lifePct = mk.life / mk.maxLife;
        ctx.save();
        ctx.translate(mk.position.x, mk.position.y);
        ctx.globalAlpha = lifePct;
        if (mk.type === 'MOVE') {
             ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2;
             const r = 10 * (1 + (1-lifePct));
             ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.stroke();
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0, -r); ctx.stroke();
        } else if (mk.type === 'ATTACK') {
             ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
             const r = 10;
             ctx.beginPath(); ctx.moveTo(-r, -r); ctx.lineTo(r, r); ctx.moveTo(r, -r); ctx.lineTo(-r, r); ctx.stroke();
        }
        ctx.restore();
    });
    ctx.globalAlpha = 1.0;

    // Entities
    // Sort by Y for pseudo-depth
    const sorted = [...allEntities].sort((a,b) => a.position.y - b.position.y);
    sorted.forEach((entity: GameEntity) => {
      if (!visibleEntities.has(entity.id)) return;
      const isSelected = state.selection.includes(entity.id);
      drawUnit(ctx, entity, isSelected);

      // Rally Lines
      if (isSelected && entity.rallyPoint && (entity.type === EntityType.BASE || entity.type === EntityType.BARRACKS)) {
          ctx.strokeStyle = '#f59e0b'; ctx.setLineDash([5, 5]); ctx.beginPath();
          ctx.moveTo(entity.position.x, entity.position.y); ctx.lineTo(entity.rallyPoint.x, entity.rallyPoint.y);
          ctx.stroke(); ctx.setLineDash([]);
      }

      // Attack Beams
      if (entity.state === 'ATTACKING' && entity.targetId && entity.cooldown > STATS[entity.type].attackSpeed - 5) {
          const target = state.entities.get(entity.targetId);
          if (target && visibleEntities.has(target.id)) {
              ctx.strokeStyle = entity.type === EntityType.MARINE ? '#facc15' : 'white';
              ctx.lineWidth = 2;
              ctx.beginPath();
              ctx.moveTo(entity.position.x, entity.position.y - 5);
              ctx.lineTo(target.position.x, target.position.y - 5);
              ctx.stroke();

              // Hit flash
              ctx.fillStyle = '#fff';
              ctx.beginPath(); ctx.arc(target.position.x, target.position.y - 5, 5, 0, Math.PI*2); ctx.fill();
          }
      }
    });

    // Effects
    state.effects.forEach(fx => {
        let visible = false;
        for(const u of playerUnits) {
             const d = Math.sqrt(Math.pow(u.position.x - fx.position.x, 2) + Math.pow(u.position.y - fx.position.y, 2));
             if (d < STATS[u.type].vision) { visible = true; break; }
        }
        if (!visible) return;

        ctx.save();
        ctx.translate(fx.position.x, fx.position.y);
        const lifePct = fx.life / fx.maxLife; 

        if (fx.type === 'EXPLOSION' || fx.type === 'BUILDING_EXPLOSION') {
            const r = (1 - lifePct) * (fx.type === 'BUILDING_EXPLOSION' ? 100 : 40) * fx.scale;
            const alpha = lifePct;
            ctx.globalAlpha = alpha;
            const grad = ctx.createRadialGradient(0,0,0,0,0,r);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, '#f59e0b');
            grad.addColorStop(1, 'rgba(239, 68, 68, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0,0, r, 0, Math.PI*2); ctx.fill();
        } else if (fx.type === 'HEAL') {
            ctx.strokeStyle = '#10b981'; ctx.lineWidth = 2; ctx.globalAlpha = lifePct;
            ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(0,-15*lifePct); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-3,-15*lifePct); ctx.lineTo(3,-15*lifePct); ctx.stroke();
        }
        ctx.restore();
    });

    // Draw Fog Overlay on top
    if (visionCanvasRef.current) {
         ctx.drawImage(visionCanvasRef.current, 0, 0);
    }

    ctx.restore(); // Pop Camera

    // Screen Space UI (Selection Box)
    if (mouseDownStateRef.current) {
        const startScreen = mouseDownStateRef.current.screen;
        const curScreen = mousePos;

        // CORRECT COORDINATE TRANSFORMATION FOR CANVAS RENDER
        const rect = ctx.canvas.getBoundingClientRect();
        const startX = startScreen.x - rect.left;
        const startY = startScreen.y - rect.top;
        const curX = curScreen.x - rect.left;
        const curY = curScreen.y - rect.top;

        ctx.strokeStyle = '#10b981';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(startX, startY, curX - startX, curY - startY);
        ctx.setLineDash([]);
    }

    // Build Preview
    if (commandMode && commandMode.startsWith('BUILD_')) {
       const type = commandMode.replace('BUILD_', '') as EntityType;
       const worldMouse = getWorldPos(mousePos.x, mousePos.y);
       const stats = STATS[type];

       ctx.save();
       ctx.translate(worldMouse.x - gameStateRef.current.camera.x, worldMouse.y - gameStateRef.current.camera.y);

       const valid = gameStateRef.current.resources[Owner.PLAYER] >= stats.cost;
       ctx.fillStyle = valid ? 'rgba(16, 185, 129, 0.5)' : 'rgba(239, 68, 68, 0.5)';
       ctx.fillRect(-stats.width/2, -stats.height/2, stats.width, stats.height);
       ctx.strokeStyle = '#fff';
       ctx.strokeRect(-stats.width/2, -stats.height/2, stats.width, stats.height);

       ctx.restore();
    }

    // Notification & Pause UI
    if (state.paused) {
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, width, height);
        ctx.fillStyle = 'white'; ctx.font = 'bold 48px monospace'; ctx.textAlign = 'center';
        ctx.fillText('PAUSED', width / 2, height / 2);
    }
    if (state.notifications.length > 0) {
        ctx.font = 'bold 20px monospace'; ctx.textAlign = 'center'; ctx.fillStyle = '#f87171';
        state.notifications.forEach((n, i) => {
            const y = height - 300 - (i * 30);
            ctx.globalAlpha = n.life / 60;
            ctx.fillText(n.text, width / 2, y);
        });
        ctx.globalAlpha = 1;
    }
  };

  // Loop & Input Handlers (Same as previous)
  const loop = () => {
    if (!gameStateRef.current.victory && !gameStateRef.current.paused) {
        gameStateRef.current = updateGame(gameStateRef.current);
        if (gameStateRef.current.soundEvents.length > 0) {
            gameStateRef.current.soundEvents.forEach(evt => playSound(evt as any));
            gameStateRef.current.soundEvents = [];
        }
    }
    const mousePos = mousePosRef.current;

    const panSpeed = 15;
    const margin = 20;
    const keySpeed = 20;

    if (keysPressed.current.has('ArrowLeft')) gameStateRef.current.camera.x -= keySpeed;
    if (keysPressed.current.has('ArrowRight')) gameStateRef.current.camera.x += keySpeed;
    if (keysPressed.current.has('ArrowUp')) gameStateRef.current.camera.y -= keySpeed;
    if (keysPressed.current.has('ArrowDown')) gameStateRef.current.camera.y += keySpeed;

    if (!isDraggingCamera.current && !isRightDragging.current) {
        if (mousePos.x < margin && mousePos.x >= 0) gameStateRef.current.camera.x -= panSpeed;
        if (mousePos.x > window.innerWidth - margin && mousePos.x <= window.innerWidth) gameStateRef.current.camera.x += panSpeed;
        if (mousePos.y < margin && mousePos.y >= 0) gameStateRef.current.camera.y -= panSpeed;
        if (mousePos.y > windowSize.height - margin && mousePos.y <= windowSize.height) gameStateRef.current.camera.y += panSpeed;
    }

    const UI_BOTTOM_HEIGHT = 224; 
    const maxCamX = Math.max(0, GAME_WIDTH - window.innerWidth);
    const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_HEIGHT);
    gameStateRef.current.camera.x = Math.max(0, Math.min(gameStateRef.current.camera.x, maxCamX));
    gameStateRef.current.camera.y = Math.max(0, Math.min(gameStateRef.current.camera.y, maxCamY));

    if (canvasRef.current) draw(canvasRef.current.getContext('2d')!);
    if (gameStateRef.current.gameTime % 5 === 0 || gameStateRef.current.paused || gameStateRef.current.victory) {
        onGameStateUpdate({ ...gameStateRef.current });
    }
    requestRef.current = requestAnimationFrame(loop);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      if (gameStateRef.current.paused) return;
      if (e.button === 1) { e.preventDefault(); isDraggingCamera.current = true; lastDragPos.current = { x: e.clientX, y: e.clientY }; return; }
      if (e.button === 2) { e.preventDefault(); rightDragStart.current = { x: e.clientX, y: e.clientY }; lastDragPos.current = { x: e.clientX, y: e.clientY }; isRightDragging.current = false; return; }
      if (e.button === 0) {
          if (commandMode === 'ATTACK') {
              const pos = getWorldPos(e.clientX, e.clientY);
              const all = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
              const pUnits = all.filter(en => en.owner === Owner.PLAYER);
              const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

              gameStateRef.current.selection.forEach(id => {
                 const u = gameStateRef.current.entities.get(id) as GameEntity | undefined;
                 if (u && u.owner === Owner.PLAYER) {
                     u.state = 'ATTACKING'; u.targetPosition = pos; u.targetId = target ? target.id : null;
                     if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'UNIT_COMMAND', subAction: 'ATTACK', unitId: id, targetPos: pos, targetId: target?.id } }));
                 }
              });
              gameStateRef.current.markers.push({ id: `mk_${Math.random()}`, position: target ? target.position : pos, type: 'ATTACK', life: 20, maxLife: 20 });
              setCommandMode(null); playSound('click'); return;
          }
          if (commandMode && commandMode.startsWith('BUILD_')) {
              const type = commandMode.replace('BUILD_', '') as EntityType;
              const pos = getWorldPos(e.clientX, e.clientY);
              const s = STATS[type];
              if (gameStateRef.current.resources[Owner.PLAYER] >= s.cost) {
                  gameStateRef.current.resources[Owner.PLAYER] -= s.cost;
                  const b = createEntity(type, Owner.PLAYER, pos, `${network.id}_b_${Math.random()}`);
                  b.constructionProgress = 0; gameStateRef.current.entities.set(b.id, b);
                  setCommandMode(null); playSound('build');
                  if (isMultiplayer) window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'BUILD', type, pos } }));
              } else { addNotification(gameStateRef.current, "Not Enough Minerals"); playSound('error'); }
              return;
          }
          const wPos = getWorldPos(e.clientX, e.clientY);
          mouseDownStateRef.current = { screen: {x:e.clientX, y:e.clientY}, world: wPos };
      }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    mousePosRef.current = { x: e.clientX, y: e.clientY };
    if (gameStateRef.current.paused) return;
    if (isDraggingCamera.current) {
        const dx = e.clientX - lastDragPos.current.x;
        const dy = e.clientY - lastDragPos.current.y;
        gameStateRef.current.camera.x -= dx;
        gameStateRef.current.camera.y -= dy;
        lastDragPos.current = { x: e.clientX, y: e.clientY };
    }
    if (e.buttons === 2) {
        const dist = Math.sqrt(Math.pow(e.clientX - rightDragStart.current.x, 2) + Math.pow(e.clientY - rightDragStart.current.y, 2));
        if (dist > 5) isRightDragging.current = true;
        if (isRightDragging.current) {
            const dx = e.clientX - lastDragPos.current.x;
            const dy = e.clientY - lastDragPos.current.y;
            gameStateRef.current.camera.x -= dx;
            gameStateRef.current.camera.y -= dy;
            lastDragPos.current = { x: e.clientX, y: e.clientY };
        }
    }
  };

  const handleMouseUp = (e: React.MouseEvent) => {
     if (gameStateRef.current.paused) return;
     if (e.button === 1) { isDraggingCamera.current = false; return; }
     if (e.button === 2) {
         e.preventDefault();
         if (!isRightDragging.current) {
             const pos = getWorldPos(e.clientX, e.clientY);
             const all = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
             const pUnits = all.filter(en => en.owner === Owner.PLAYER);
             const target = all.find(en => Math.sqrt(Math.pow(en.position.x-pos.x,2)+Math.pow(en.position.y-pos.y,2)) < en.radius+15 && isEntityVisible(en, pUnits));

             const selection = gameStateRef.current.selection;
             if (selection.length > 0) {
                 const hasBuildings = selection.some(id => { const u=gameStateRef.current.entities.get(id) as GameEntity | undefined; return !!(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE || u.type===EntityType.BARRACKS))});
                 if (hasBuildings) {
                     selection.forEach(id => {
                         const u=gameStateRef.current.entities.get(id) as GameEntity | undefined;
                         if(u && u.owner===Owner.PLAYER && (u.type===EntityType.BASE||u.type===EntityType.BARRACKS)) {
                             window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action:'SET_RALLY', id:u.id, pos, targetId: target?target.id:null}}));
                         }
                     });
                 } else {
                     playSound('click');
                     let moveType = 'MOVE';
                     let tId = null;
                     if (target && target.owner !== Owner.PLAYER) { moveType = 'ATTACK'; tId = target.id; }
                     else if (target && target.type === EntityType.MINERAL) { moveType = 'GATHER'; tId = target.id; }

                     window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y, unitAction: moveType, targetId: tId }}));
                 }
             }
         }
         isRightDragging.current = false;
         return;
     }

     if (e.button === 0 && mouseDownStateRef.current) {
         // Selection Box Logic
         const start = mouseDownStateRef.current.world;
         const cur = getWorldPos(e.clientX, e.clientY);
         const dist = Math.sqrt(Math.pow(e.clientX - mouseDownStateRef.current.screen.x, 2) + Math.pow(e.clientY - mouseDownStateRef.current.screen.y, 2));
         const isClick = dist < 5;

         const minX = Math.min(start.x, cur.x); const maxX = Math.max(start.x, cur.x);
         const minY = Math.min(start.y, cur.y); const maxY = Math.max(start.y, cur.y);

         const newSel: string[] = [];
         const all = Array.from(gameStateRef.current.entities.values()) as GameEntity[];
         const pUnits = all.filter(en => en.owner === Owner.PLAYER);

         all.forEach(en => {
             if (en.type === EntityType.MOUNTAIN || en.type === EntityType.WATER || en.state==='GARRISONED') return;
             if (!isEntityVisible(en, pUnits)) return;
             if (!isClick && en.owner !== Owner.PLAYER) return;

             if (isClick) {
                 if (Math.sqrt(Math.pow(en.position.x-cur.x,2)+Math.pow(en.position.y-cur.y,2)) < en.radius+15) newSel.push(en.id);
             } else {
                 if (en.position.x > minX && en.position.x < maxX && en.position.y > minY && en.position.y < maxY && en.owner === Owner.PLAYER) newSel.push(en.id);
             }
         });

         if (isClick && newSel.length > 0) { 
             playSound('click'); 
             const clickedId = newSel[0]; 

             // Shift-Click Toggle
             if (e.shiftKey) {
                 const prev = gameStateRef.current.selection;
                 if (prev.includes(clickedId)) {
                     gameStateRef.current.selection = prev.filter(id => id !== clickedId);
                 } else {
                     gameStateRef.current.selection = [...prev, clickedId];
                 }
             } else {
                 gameStateRef.current.selection = [clickedId];
             }
         }
         else if (newSel.length > 0) {
              const nonBuildings = newSel.filter(id => { const t = (gameStateRef.current.entities.get(id) as GameEntity | undefined)?.type; return t!==EntityType.BASE && t!==EntityType.BARRACKS && t!==EntityType.SUPPLY_DEPOT && t!==EntityType.BUNKER });
              // Drag selection usually excludes buildings unless ONLY buildings are selected, OR shift is used.
              // For shift drag, we just add whatever is valid.
              const candidates = nonBuildings.length > 0 ? nonBuildings : newSel;

              if (e.shiftKey) {
                   const combined = new Set([...gameStateRef.current.selection, ...candidates]);
                   gameStateRef.current.selection = Array.from(combined);
              } else {
                   gameStateRef.current.selection = candidates;
              }
         } else if (!e.shiftKey) {
             gameStateRef.current.selection = [];
         }

         onSelectionChange(gameStateRef.current.selection.map(id => gameStateRef.current.entities.get(id)!).filter(Boolean) as GameEntity[]);
         mouseDownStateRef.current = null;
     }
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [commandMode]); 

  return (
    <canvas
      ref={canvasRef}
      width={windowSize.width}
      height={windowSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={() => { mouseDownStateRef.current=null; isDraggingCamera.current=false; isRightDragging.current=false; }}
      onContextMenu={(e) => e.preventDefault()}
      className={`block ${commandMode === 'ATTACK' ? 'cursor-crosshair' : 'cursor-default'}`}
    />
  );
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI', // Kept for backward compatibility with single player
  OPPONENT = 'OPPONENT', // For multiplayer
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  MEDIC = 'MEDIC',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  BUNKER = 'BUNKER',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export enum Difficulty {
    EASY = 'EASY',
    MEDIUM = 'MEDIUM',
    HARD = 'HARD'
}

export enum AIStrategy {
    RUSH = 'RUSH', // Early attack, low economy
    MACRO = 'MACRO', // High economy, late attack
    TURTLE = 'TURTLE' // Defensive, builds bunkers
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD' | 'BUILDING_EXPLOSION' | 'HEAL';
  position: Vector2;
  life: number;
  maxLife: number;
  scale: number;
}

export interface Marker {
  id: string;
  position: Vector2;
  type: 'MOVE' | 'ATTACK' | 'LOAD';
  life: number;
  maxLife: number;
}

export interface Notification {
    id: string;
    text: string;
    life: number;
}

export interface GameEntity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING' | 'ENTERING' | 'GARRISONED' | 'HEALING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
  lastAttackerId?: string | null; // For retaliation
  garrison?: string[]; // IDs of units inside (for Bunker)
  containerId?: string | null; // ID of entity this unit is inside
}

export interface GameState {
  entities: Map<string, GameEntity>;
  effects: Effect[];
  markers: Marker[];
  notifications: Notification[];
  soundEvents: string[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
    [Owner.OPPONENT]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
    [Owner.OPPONENT]: { used: number; max: number };
  };
  selection: string[];
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
  noRushFrames: number; // New field
  difficulty: Difficulty;
  aiStrategy: AIStrategy; 
  paused: boolean;
  isMultiplayer: boolean;
  localPlayerId?: string;
}

export interface UnitStats {
  cost: number;
  hp: number;
  damage: number;
  range: number;
  vision: number;
  speed: number;
  attackSpeed: number;
  buildTime: number;
  width: number;
  height: number;
  supplyCost: number;
  supplyProvided: number;
  healRate?: number; // For Medics
}

// Network Types
export type NetMessage = 
  | { type: 'JOIN', payload: { name: string, id: string } }
  | { type: 'WELCOME', payload: { seed: number, hostId: string } }
  | { type: 'READY', payload: { id: string, ready: boolean } }
  | { type: 'START_GAME', payload: { seed: number, noRushSeconds: number } }
  | { type: 'GAME_COMMAND', payload: { action: string, data: any, owner: Owner } }
  | { type: 'ERROR', payload: { message: string } };

export interface PlayerInfo {
    id: string;
    name: string;
    isReady: boolean;
    isHost: boolean;
}

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT, FPS } from '../constants';
import { GameEntity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, AIStrategy } from '../types';
import { SeededRandom } from './random';

let idCounter = 0;
// We need to synchronize IDs in multiplayer. 
// In a real app, we'd use GUIDs or owner-prefixed IDs. 
// For this simple version, Host generates odd IDs, Client generates even IDs, or we rely on the prefix.
export const generateId = (prefix: string = 'ent') => `${prefix}_${++idCounter}_${Math.floor(Math.random()*1000)}`;

export const addNotification = (state: GameState, text: string) => {
    state.notifications.push({
        id: `n_${Math.random()}`,
        text,
        life: 120
    });
};

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2, id?: string): GameEntity => {
  const stats = STATS[type];
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: id || generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null,
    garrison: [],
    containerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, GameEntity>, type?: EntityType, owner?: Owner) => {
  let nearest: GameEntity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (e.state === 'GARRISONED') return;
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, GameEntity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

const isBio = (type: EntityType) => type === EntityType.WORKER || type === EntityType.MARINE || type === EntityType.MEDIC;
const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT || type === EntityType.BUNKER;

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM, isMultiplayer = false, seed = Math.random() * 10000, isHost = true, noRushSeconds = 0): GameState => {
  const entities = new Map<string, GameEntity>();
  const effects: Effect[] = [];
  const add = (e: GameEntity) => entities.set(e.id, e);

  // Use seeded random
  const rng = new SeededRandom(seed);

  // --- RANDOMIZED BASE PLACEMENT ---
  // Define 4 corners with padding
  const corners = [
      { x: 150, y: 150 }, // TL
      { x: GAME_WIDTH - 150, y: 150 }, // TR
      { x: 150, y: GAME_HEIGHT - 150 }, // BL
      { x: GAME_WIDTH - 150, y: GAME_HEIGHT - 150 } // BR
  ];

  // Shuffle corners using seeded random
  // Fisher-Yates shuffle
  for (let i = corners.length - 1; i > 0; i--) {
        const j = Math.floor(rng.next() * (i + 1));
        [corners[i], corners[j]] = [corners[j], corners[i]];
  }

  // If Host (Player 1), we are at corners[0]. If Client (Player 2), we are at corners[0] but visually we might want to swap?
  // Actually, to keep it simple: Player is ALWAYS corners[0] in singleplayer.
  // In multiplayer: 
  //   Host -> Owner.PLAYER at corners[0], Opponent -> Owner.OPPONENT at corners[1].
  //   Client -> Owner.PLAYER at corners[1], Opponent -> Owner.OPPONENT at corners[0].

  let myBasePos = corners[0];
  let opBasePos = corners[1];

  if (isMultiplayer && !isHost) {
      // If I am the client, I spawn at the second position, and the opponent (Host) is at the first.
      // But from MY perspective, I am Owner.PLAYER.
      myBasePos = corners[1];
      opBasePos = corners[0];
  }

  // Add random offset to prevent exact static spots
  const jitter = (pt: Vector2) => ({
      x: pt.x + (rng.next() - 0.5) * 50,
      y: pt.y + (rng.next() - 0.5) * 50
  });

  myBasePos = jitter(myBasePos);
  opBasePos = jitter(opBasePos);

  // --- RANDOM STRATEGY ---
  const strategies = [AIStrategy.RUSH, AIStrategy.MACRO, AIStrategy.TURTLE];
  const aiStrategy = strategies[Math.floor(rng.next() * strategies.length)];

  // --- MAP GENERATION ---
  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = rng.next() * Math.PI * 2;
          const dist = rng.next() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, myBasePos) < 400) continue;
          if (getDistance({x,y}, opBasePos) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  // Terrain
  for(let i=0; i<15; i++) {
      generateCluster(EntityType.MOUNTAIN, 5, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 150);
  }
  for(let i=0; i<8; i++) {
      generateCluster(EntityType.WATER, 4, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 120);
  }

  // Expansion Minerals: 2, 4, 6, or 8 clusters
  const possibleExpansions = [2, 4, 6, 8];
  const numExpansions = possibleExpansions[Math.floor(rng.next() * possibleExpansions.length)];

  for(let i=0; i<numExpansions; i++) {
      let exX = rng.range(150, GAME_WIDTH - 300);
      let exY = rng.range(150, GAME_HEIGHT - 300);

      let safe = false;
      let attempts = 0;
      while (!safe && attempts < 10) {
          if (getDistance({x:exX, y:exY}, myBasePos) > 700 && getDistance({x:exX, y:exY}, opBasePos) > 700) {
              safe = true;
          } else {
              exX = rng.range(150, GAME_WIDTH - 300);
              exY = rng.range(150, GAME_HEIGHT - 300);
          }
          attempts++;
      }
      generateCluster(EntityType.MINERAL, 7, exX, exY, 70);
  }

  // --- PLAYER SETUP ---
  const spawnBase = (pos: Vector2, owner: Owner) => {
      const centerAngle = Math.atan2((GAME_HEIGHT/2) - pos.y, (GAME_WIDTH/2) - pos.x);
      for (let i = 0; i < 8; i++) {
        const angle = centerAngle - (Math.PI/2) + (i / 7) * Math.PI; 
        add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
          x: pos.x + 220 * Math.cos(angle), 
          y: pos.y + 220 * Math.sin(angle) 
        }));
      }
      const base = createEntity(EntityType.BASE, owner, pos);
      add(base);
      for (let i = 0; i < 4; i++) {
        const worker = createEntity(EntityType.WORKER, owner, { 
            x: pos.x + (rng.next()-0.5)*50, 
            y: pos.y + (rng.next()-0.5)*50 
        });
        add(worker);
        const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
        if (mineral) {
            worker.state = 'GATHERING';
            worker.targetId = mineral.id;
        }
      }
      const nearestMineral = findNearest(base.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
      if (nearestMineral) {
          base.rallyPoint = nearestMineral.position;
          base.rallyTargetId = nearestMineral.id;
      }
  };

  spawnBase(myBasePos, Owner.PLAYER);
  const opponentOwner = isMultiplayer ? Owner.OPPONENT : Owner.AI;
  spawnBase(opBasePos, opponentOwner);

  const startCameraY = Math.max(0, myBasePos.y - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));
  const startCameraX = Math.max(0, myBasePos.x - (typeof window !== 'undefined' ? window.innerWidth / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50, [Owner.OPPONENT]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 },
      [Owner.OPPONENT]: { used: 4, max: 10 }
    },
    selection: [],
    camera: { x: startCameraX, y: startCameraY },
    gameTime: 0,
    noRushFrames: noRushSeconds * FPS, // Convert seconds to frames
    difficulty,
    aiStrategy,
    victory: undefined,
    paused: false,
    isMultiplayer
  };
};

const resolveCollisions = (entity: GameEntity, entities: Map<string, GameEntity>) => {
  if (entity.state === 'BUILDING' || entity.state === 'GARRISONED') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;
    if (other.state === 'GARRISONED') return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; 

    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; 

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const acquireTarget = (entity: GameEntity, entities: Map<string, GameEntity>, gameTime: number, noRushFrames: number) => {
    const stats = STATS[entity.type];
    let bestTarget: GameEntity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.state === 'GARRISONED') return;

        // No Rush Logic: Don't auto-acquire enemy targets during rush time
        if (gameTime < noRushFrames) {
            if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL) return;
        }

        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;
                if (e.targetId === entity.id) score += 5000;
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; 
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };
  supply[Owner.OPPONENT] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    // Supply Logic Fix: Only fully constructed buildings provide supply
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);
  supply[Owner.OPPONENT].max = Math.min(supply[Owner.OPPONENT].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 
    if (entity.state === 'GARRISONED') return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) {
           entity.constructionProgress = 100;
           // Completed sound?
       }
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 
             // IMPORTANT: In multiplayer, ID generation must be consistent or handled by owner.
             // We use a random suffix in generateId, which is risky for exact sync.
             // For this clone, we assume "good enough" sync or command-based spawning.
             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Inherit rally point
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                         newUnit.state = unitType === EntityType.MEDIC ? 'MOVING' : 'ATTACKING'; 
                     }
                 }
             } else if ((entity.owner === Owner.AI || entity.owner === Owner.OPPONENT) && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                // AI Units just spawn
                newUnit.state = 'IDLE'; 
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    const stats = STATS[entity.type];

    // --- BUNKER LOGIC ---
    if (entity.type === EntityType.BUNKER) {
        if (entity.garrison && entity.garrison.length > 0) {
            let target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp <= 0 || getDistance(entity.position, target.position) > stats.range) {
                target = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
                entity.targetId = target ? target.id : null;
            }

            if (target) {
                const dist = getDistance(entity.position, target.position);
                if (dist <= stats.range) {
                    if (entity.cooldown <= 0) {
                        const marineStats = STATS[EntityType.MARINE];
                        target.hp -= marineStats.damage;
                        entity.cooldown = Math.max(5, 30 / entity.garrison.length);

                        if (target.hp <= 0) entity.targetId = null;
                        soundEvents.push('shoot');
                    }
                }
            }
        }
    }

    // --- MEDIC LOGIC ---
    if (entity.type === EntityType.MEDIC) {
        if (['IDLE', 'MOVING', 'ATTACKING'].includes(entity.state)) {
            let healTarget: GameEntity | null = null;
            let bestHealDist = stats.vision;

            entities.forEach(e => {
                if (e.owner === entity.owner && isBio(e.type) && e.hp < e.maxHp && e.state !== 'GARRISONED') {
                    const d = getDistance(entity.position, e.position);
                    if (d < bestHealDist) {
                        bestHealDist = d;
                        healTarget = e;
                    }
                }
            });

            if (healTarget) {
                const d = getDistance(entity.position, healTarget.position);
                if (d <= stats.range) {
                    entity.state = 'HEALING';
                    entity.targetId = healTarget.id;
                    entity.targetPosition = null; 
                } else {
                    const angle = Math.atan2(healTarget.position.y - entity.position.y, healTarget.position.x - entity.position.x);
                    entity.position.x += Math.cos(angle) * stats.speed;
                    entity.position.y += Math.sin(angle) * stats.speed;
                }
            }
        }

        if (entity.state === 'HEALING') {
            const target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp >= target.maxHp || getDistance(entity.position, target.position) > stats.range + 20) {
                 entity.state = 'IDLE';
                 entity.targetId = null;
            } else {
                 if (entity.cooldown <= 0) {
                     target.hp = Math.min(target.maxHp, target.hp + (stats.healRate || 5));
                     entity.cooldown = stats.attackSpeed;
                     newEffects.push({
                        id: `fx_${Math.random()}`,
                        type: 'HEAL',
                        position: { ...target.position },
                        life: 20, maxLife: 20, scale: 1
                     });
                 }
            }
        }
    }

    // --- ENTERING BUNKER LOGIC ---
    if (entity.state === 'ENTERING' && entity.targetId) {
        const bunker = entities.get(entity.targetId);
        // Bunker Fix: Must be built to enter
        if (bunker && bunker.type === EntityType.BUNKER && bunker.hp > 0 && bunker.owner === entity.owner && bunker.constructionProgress! >= 100) {
             const dist = getDistance(entity.position, bunker.position);
             if (dist < bunker.radius + entity.radius + 10) {
                 if (!bunker.garrison) bunker.garrison = [];
                 if (bunker.garrison.length < 4) {
                     bunker.garrison.push(entity.id);
                     entity.state = 'GARRISONED';
                     entity.containerId = bunker.id;
                     entity.targetId = null;
                     entity.targetPosition = null;
                     soundEvents.push('click'); 
                 } else {
                     entity.state = 'IDLE'; 
                 }
             } else {
                 const angle = Math.atan2(bunker.position.y - entity.position.y, bunker.position.x - entity.position.x);
                 entity.position.x += Math.cos(angle) * stats.speed;
                 entity.position.y += Math.sin(angle) * stats.speed;
             }
        } else {
            entity.state = 'IDLE';
        }
    }

    // --- STANDARD ACTION LOGIC ---
    if (entity.state === 'IDLE' && entity.type !== EntityType.MEDIC && entity.type !== EntityType.WORKER && stats.damage > 0) {
        const target = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
        if (target) {
            entity.targetId = target.id;
            entity.state = 'ATTACKING';
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // No Rush Enforcement: If manual attack is issued during rush time, cancel it if targeting enemy
        if (state.gameTime < state.noRushFrames && target && target.owner !== entity.owner && target.owner !== Owner.NEUTRAL) {
             entity.state = 'IDLE';
             entity.targetId = null;
             // Silent cancel for now, or could walk to target without shooting
             target = null;
        }

        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner && attacker.state !== 'GARRISONED') {
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        if (!target || target.hp <= 0 || target.state === 'GARRISONED') {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; 

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; 
                  entity.cooldown = stats.attackSpeed;
                  soundEvents.push('shoot');

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
         const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            let newRes: GameEntity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });
            if (newRes) entity.targetId = (newRes as GameEntity).id;
            else entity.state = 'IDLE';
        } else {
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }
            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; 
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) newEntities.delete(target.id);
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;
                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (isBio(entity.type)) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');

        if (entity.garrison && entity.garrison.length > 0) {
            entity.garrison.forEach(id => {
                const unit = newEntities.get(id);
                if (unit) {
                    unit.state = 'IDLE';
                    unit.containerId = null;
                    unit.position = { 
                        x: entity.position.x + (Math.random() * 40 - 20), 
                        y: entity.position.y + (Math.random() * 40 - 20) 
                    };
                }
            });
        }

        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  newEffects = newEffects.filter(fx => { fx.life--; return fx.life > 0; });
  newMarkers = newMarkers.filter(mk => { mk.life--; return mk.life > 0; });
  newNotifications = newNotifications.filter(n => { n.life--; return n.life > 0; });

  // ONLY RUN AI IF SINGLE PLAYER
  if (!state.isMultiplayer && state.gameTime % 30 === 0) {
      runAI(state, newEntities, resources, supply);
  }

  let playerBuildings = 0;
  let opponentBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if ((e.owner === Owner.AI || e.owner === Owner.OPPONENT) && isBuilding(e.type)) opponentBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = state.isMultiplayer ? Owner.OPPONENT : Owner.AI; 
  if (opponentBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, GameEntity>, resources: any, supply: any) => {
  const aiOwner = Owner.AI;
  const playerOwner = Owner.PLAYER;

  const myUnits = Array.from(entities.values()).filter(e => e.owner === aiOwner);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const bunkers = myUnits.filter(e => e.type === EntityType.BUNKER);
  const army = myUnits.filter(e => e.type === EntityType.MARINE || e.type === EntityType.MEDIC);
  const depots = myUnits.filter(e => e.type === EntityType.SUPPLY_DEPOT);

  const myMinerals = resources[aiOwner];
  const mySupply = supply[aiOwner];
  const strategy = state.aiStrategy;

  let maxWorkers = 12;
  let attackThreshold = 12;
  let expand = false;
  let buildBunkers = false;

  // Modify logic based on Strategy
  if (strategy === AIStrategy.RUSH) {
      maxWorkers = 10;
      attackThreshold = 8;
  } else if (strategy === AIStrategy.MACRO) {
      maxWorkers = 20;
      attackThreshold = 25;
      expand = true;
  } else if (strategy === AIStrategy.TURTLE) {
      maxWorkers = 14;
      attackThreshold = 30; // Wait for big army
      buildBunkers = true;
  }

  // Difficulty Override (Difficulty caps capability, Strategy directs it)
  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = Math.min(maxWorkers, 10);
      attackThreshold = Math.max(attackThreshold, 15);
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = Math.max(maxWorkers, 16);
  }

  // --- 0. DEFENSE CHECK ---
  let underAttack = false;
  let threatPos: Vector2 | null = null;

  if (bases.length > 0) {
      const mainBase = bases[0];
      const enemies = Array.from(entities.values()).filter(e => e.owner === playerOwner);
      const nearestEnemy = enemies.find(e => getDistance(e.position, mainBase.position) < 800);
      if (nearestEnemy) {
          underAttack = true;
          threatPos = nearestEnemy.position;
      }
  }

  if (underAttack && army.length === 0 && state.difficulty === Difficulty.HARD) {
       workers.slice(0, 5).forEach(w => {
           if (w.state !== 'ATTACKING') {
               w.state = 'ATTACKING';
               w.targetPosition = threatPos;
           }
       });
  }

  // --- 1. WORKERS ---
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.sort((a,b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
      if (base && (!base.trainQueue || base.trainQueue.length < 1)) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[aiOwner] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'ATTACKING' && !underAttack) w.state = 'IDLE';
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // --- 2. SUPPLY ---
  if (mySupply.max - mySupply.used <= 3 && myMinerals >= 100 && depots.length < 10) {
      const construction = myUnits.find(u => u.type === EntityType.SUPPLY_DEPOT && u.constructionProgress! < 100);
      if (!construction) {
          const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
          if (builder) {
              resources[aiOwner] -= 100;
              const basePos = bases[0]?.position || builder.position;
              const angle = Math.random() * Math.PI * 2;
              const dist = 100 + Math.random() * 100;
              const buildPos = { x: basePos.x + Math.cos(angle)*dist, y: basePos.y + Math.sin(angle)*dist };
              const depot = createEntity(EntityType.SUPPLY_DEPOT, aiOwner, buildPos);
              depot.constructionProgress = 0;
              entities.set(depot.id, depot);
          }
      }
  }

  // --- 3. BUILDINGS ---
  const desiredBarracks = (strategy === AIStrategy.RUSH) ? 4 : 3;
  if (barracks.length < desiredBarracks && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING');
      if (builder) {
           resources[aiOwner] -= 150;
           const basePos = bases[0]?.position || builder.position;
           const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };
           const b = createEntity(EntityType.BARRACKS, aiOwner, buildPos);
           b.constructionProgress = 0;
           entities.set(b.id, b);
      }
  }

  if (buildBunkers && bunkers.length < (bases.length * 2) && myMinerals >= 100 && barracks.length > 0) {
       const builder = workers.find(w => w.state === 'GATHERING');
       if (builder && bases.length > 0) {
           const base = bases[0];
           const center = { x: GAME_WIDTH/2, y: GAME_HEIGHT/2 };
           const angle = Math.atan2(center.y - base.position.y, center.x - base.position.x);
           const dist = 300;
           const buildPos = { x: base.position.x + Math.cos(angle)*dist + (Math.random()-0.5)*100, y: base.position.y + Math.sin(angle)*dist + (Math.random()-0.5)*100 };

           resources[aiOwner] -= 100;
           const bunk = createEntity(EntityType.BUNKER, aiOwner, buildPos);
           bunk.constructionProgress = 0;
           entities.set(bunk.id, bunk);
       }
  }

  // Garrison Bunkers (Turtle or defense)
  if (bunkers.length > 0 && army.length > 0) {
      bunkers.forEach(bunk => {
          if (bunk.hp > 0 && bunk.constructionProgress! >= 100 && (!bunk.garrison || bunk.garrison.length < 4)) {
              const marines = army.filter(u => u.type === EntityType.MARINE && u.state !== 'GARRISONED' && u.state !== 'ENTERING');
              let bestMarine: GameEntity | null = null;
              let bestDist = 500;
              marines.forEach(m => {
                  const d = getDistance(m.position, bunk.position);
                  if (d < bestDist) { bestDist = d; bestMarine = m; }
              });
              if (bestMarine) {
                  bestMarine.state = 'ENTERING';
                  bestMarine.targetId = bunk.id;
              }
          }
      });
  }

  // Expansion
  if (expand && bases.length < 3 && myMinerals >= 400) {
      let bestPatch: GameEntity | null = null;
      const minerals = Array.from(entities.values()).filter(e => e.type === EntityType.MINERAL);
      minerals.forEach(m => {
          let minDistToBase = Infinity;
          bases.forEach(b => {
             const d = getDistance(m.position, b.position);
             if (d < minDistToBase) minDistToBase = d;
          });
          if (minDistToBase > 800 && minDistToBase < 2000) {
              const nearbyBase = Array.from(entities.values()).find(e => e.type === EntityType.BASE && getDistance(e.position, m.position) < 300);
              if (!nearbyBase) bestPatch = m;
          }
      });

      if (bestPatch) {
          const builder = workers.find(w => w.state === 'GATHERING');
          if (builder) {
              resources[aiOwner] -= 400;
              const buildPos = { x: bestPatch.position.x + 100, y: bestPatch.position.y };
              const newBase = createEntity(EntityType.BASE, aiOwner, buildPos);
              newBase.constructionProgress = 0;
              entities.set(newBase.id, newBase);
              builder.position = { ...buildPos }; 
          }
      }
  }

  // --- 4. PRODUCTION ---
  if (barracks.length > 0 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if (b.constructionProgress! >= 100 && (!b.trainQueue || b.trainQueue.length < 5) && resources[aiOwner] >= 50) {
              let type = EntityType.MARINE;
              const medicCount = army.filter(u => u.type === EntityType.MEDIC).length;
              const marineCount = army.length - medicCount;
              const desiredMedicRatio = 0.25;

              if (marineCount > 2 && medicCount / (marineCount || 1) < desiredMedicRatio && resources[aiOwner] >= 75) {
                   type = EntityType.MEDIC;
              }
              if (resources[aiOwner] >= STATS[type].cost) {
                  if (!b.trainQueue) b.trainQueue = [];
                  b.trainQueue.push(type);
                  resources[aiOwner] -= STATS[type].cost;
              }
          }
      });
  }

  // --- 6. ARMY MOVEMENT ---
  if (underAttack && army.length > 0) {
      army.forEach(u => {
          if (u.state === 'GARRISONED') return;
          if (threatPos) {
              u.state = u.type === EntityType.MEDIC ? 'MOVING' : 'ATTACKING';
              u.targetPosition = threatPos;
          }
      });
      return;
  }

  if (army.length >= attackThreshold) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === playerOwner && e.type === EntityType.BASE);
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === playerOwner);
      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state === 'GARRISONED') return;
          if (unit.state === 'ATTACKING' && unit.targetId) return;

          if (unit.type === EntityType.MEDIC) {
               const buddy = army.find(a => a !== unit && a.type === EntityType.MARINE);
               if (buddy && getDistance(unit.position, buddy.position) > 100) {
                    unit.state = 'MOVING';
                    unit.targetPosition = buddy.position;
               } else {
                    unit.state = 'MOVING';
                    unit.targetPosition = targetPos;
               }
          } else {
               unit.state = 'ATTACKING';
               unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useState, useRef } from 'react';
import { network } from '../services/network';
import { PlayerInfo, Difficulty } from '../types';
import { NO_RUSH_OPTIONS } from '../constants';

interface Props {
    onGameStart: (seed: number, isHost: boolean, noRushSeconds: number) => void;
    onSinglePlayerStart: (difficulty: Difficulty, noRushSeconds: number) => void;
}

const PUBLIC_ROOMS = [
    { id: 'STAR_DRAFT_ROOM_ALPHA', name: 'Sector Alpha' },
    { id: 'STAR_DRAFT_ROOM_BETA', name: 'Sector Beta' },
    { id: 'STAR_DRAFT_ROOM_GAMMA', name: 'Sector Gamma' }
];

const StarBackground = () => {
    const containerRef = useRef<HTMLDivElement>(null);
    // Generate static stars
    const [stars] = useState(() => Array.from({ length: 150 }).map((_, i) => ({
        id: i,
        x: Math.random() * 100,
        y: Math.random() * 100,
        size: Math.random() * 2 + 1,
        opacity: Math.random() * 0.7 + 0.3,
        animDuration: Math.random() * 4 + 2,
        animDelay: Math.random() * 5
    })));

    useEffect(() => {
        const handleMove = (e: MouseEvent) => {
            if (!containerRef.current) return;
            // Normalize coordinates from -0.5 to 0.5
            const x = (e.clientX / window.innerWidth) - 0.5;
            const y = (e.clientY / window.innerHeight) - 0.5;

            // Move uniformly opposite to cursor direction (Locked Layer Effect)
            // Multiplier determines magnitude. -40 means max shift of 20px in opposite direction.
            const moveX = x * -40; 
            const moveY = y * -40;

            containerRef.current.style.transform = `translate3d(${moveX}px, ${moveY}px, 0)`;
        };

        window.addEventListener('mousemove', handleMove);
        return () => window.removeEventListener('mousemove', handleMove);
    }, []);

    return (
        // inset-[-40px] ensures the container is larger than the viewport so edges don't show when shifting
        <div className="absolute inset-[-40px] overflow-hidden pointer-events-none">
            <div 
                ref={containerRef} 
                className="w-full h-full transition-transform duration-100 ease-out will-change-transform"
            >
                {stars.map(s => (
                    <div 
                        key={s.id} 
                        className="absolute bg-white rounded-full shadow-[0_0_2px_rgba(255,255,255,0.8)]"
                        style={{
                            left: `${s.x}%`, 
                            top: `${s.y}%`, 
                            width: `${s.size}px`, 
                            height: `${s.size}px`, 
                            opacity: s.opacity,
                            animation: `twinkle ${s.animDuration}s infinite ${s.animDelay}s`
                        }}
                    />
                ))}
            </div>
             <style>{`
                @keyframes twinkle {
                    0%, 100% { opacity: 0.3; transform: scale(0.8); }
                    50% { opacity: 1; transform: scale(1.2); }
                }
            `}</style>
        </div>
    );
};

export const Lobby: React.FC<Props> = ({ onGameStart, onSinglePlayerStart }) => {
    // MODES: MENU -> NAME_INPUT -> LOBBY (Hosting Private + Viewing Public) -> JOINING (Transition)
    const [mode, setMode] = useState<'MENU' | 'SINGLEPLAYER' | 'NAME_INPUT' | 'LOBBY' | 'JOINING'>('MENU');
    const [name, setName] = useState('Player');
    const [opponent, setOpponent] = useState<PlayerInfo | null>(null);
    const [isReady, setIsReady] = useState(false);
    const [opponentReady, setOpponentReady] = useState(false);
    const [seed, setSeed] = useState<number>(0);
    const [isHost, setIsHost] = useState(false);
    const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
    const [selectedNoRush, setSelectedNoRush] = useState<number>(0); // 0 means disabled
    const [hostCode, setHostCode] = useState(''); // Private code
    const [joinCode, setJoinCode] = useState('');
    const [error, setError] = useState<string | null>(null);
    const [statusMsg, setStatusMsg] = useState('');

    useEffect(() => {
        const handleMsg = (msg: any) => {
            if (msg.type === 'JOIN' && !opponent) {
                // Received JOIN request (I am Host)
                setOpponent({ id: msg.payload.id, name: msg.payload.name, isReady: false, isHost: false });
                const newSeed = Math.random() * 10000;
                setSeed(newSeed);
                network.send({ type: 'WELCOME', payload: { seed: newSeed, hostId: network.id } });
            }
            if (msg.type === 'WELCOME' && !opponent) {
                // Received WELCOME (I am Client)
                setSeed(msg.payload.seed);
                setOpponent({ id: msg.payload.hostId, name: 'Opponent', isReady: false, isHost: true });
                setStatusMsg('');
                setMode('LOBBY'); // ensure we are in lobby view (but now with opponent)
            }
            if (msg.type === 'READY' && opponent) {
                setOpponentReady(msg.payload.ready);
            }
            if (msg.type === 'START_GAME' && opponent) {
                onGameStart(seed, isHost, msg.payload.noRushSeconds || 0);
            }
            if (msg.type === 'ERROR') {
                setError(msg.payload.message);
                network.close(); // Disconnect
                setOpponent(null);
                setMode('NAME_INPUT'); // Kick back
            }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [opponent, seed, onGameStart, isHost]);

    useEffect(() => {
        if (isReady && opponentReady && isHost) {
            network.send({ type: 'START_GAME', payload: { seed, noRushSeconds: selectedNoRush } });
            onGameStart(seed, true, selectedNoRush);
        }
    }, [isReady, opponentReady, isHost, seed, onGameStart, selectedNoRush]);

    const enterLobby = async () => {
        if (!name) return setError("Please enter a name");
        network.setName(name);
        setMode('LOBBY');
        setIsHost(true);
        // Automatically host a private room
        try {
            const id = await network.hostGame();
            setHostCode(id);
        } catch (e: any) {
            setError("Failed to generate private room.");
        }
    };

    const joinPrivate = async () => {
        if (!joinCode || joinCode.length !== 4) return setError("Invalid Code (Must be 4 chars)");
        setError(null);
        setStatusMsg("Joining Private Room...");
        try {
             await network.joinGame(joinCode);
             network.send({ type: 'JOIN', payload: { name, id: network.id } });
             setIsHost(false);
        } catch (e: any) {
             setError(e.message);
             setStatusMsg("");
             // Re-host private?
             const id = await network.hostGame();
             setHostCode(id);
             setIsHost(true);
        }
    };

    const handlePublicRoomClick = async (room: { id: string, name: string }) => {
        setError(null);
        setStatusMsg(`Connecting to ${room.name}...`);

        try {
            // 1. Try to Join
            await network.joinGame(room.id);
            // 2. If successful, send JOIN
            network.send({ type: 'JOIN', payload: { name, id: network.id } });
            setIsHost(false);
            setHostCode(room.id); // Just for display
        } catch (e: any) {
            // 3. If join failed, assume room is free and Try to Host
            // We must destroy current peer (private host) to claim the public ID
            console.log("Join failed, attempting to host...", e);
            setStatusMsg(`Creating ${room.name}...`);
            try {
                await network.hostGame(room.id);
                setHostCode(room.id); // "STAR_DRAFT_ROOM_ALPHA"
                setIsHost(true);
                setOpponent(null); 
                setStatusMsg("");
            } catch (hostErr: any) {
                setError("Room is busy or unavailable.");
                setStatusMsg("");
                // Revert to private host
                const id = await network.hostGame();
                setHostCode(id);
            }
        }
    };

    const toggleReady = () => {
        const newState = !isReady;
        setIsReady(newState);
        network.send({ type: 'READY', payload: { id: network.id, ready: newState } });
    };

    const copyCode = () => {
        navigator.clipboard.writeText(hostCode);
        alert("Code copied!");
    };

    const formatSeconds = (sec: number) => {
        if (sec === 0) return "No Rush: OFF";
        const m = Math.floor(sec / 60);
        const s = sec % 60;
        return `No Rush: ${m}m${s > 0 ? s + 's' : ''}`;
    }

    // Render helper to keep layout consistent
    const renderContent = () => {
        // --- MAIN MENU ---
        if (mode === 'MENU') {
            return (
                <div className="max-w-md w-full bg-slate-900/90 backdrop-blur border border-slate-700 p-8 rounded-lg shadow-2xl text-center">
                    <h1 className="text-4xl font-black mb-2 text-cyan-400 tracking-tighter drop-shadow-lg">STARDRAFT</h1>
                    <p className="text-slate-500 mb-8 text-sm uppercase tracking-widest">Minimalist RTS</p>

                    <div className="space-y-4">
                        <button 
                            onClick={() => setMode('SINGLEPLAYER')}
                            className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded uppercase tracking-widest transition-all hover:scale-105 shadow-lg border border-emerald-400/30"
                        >
                            Single Player
                        </button>
                        <button 
                            onClick={() => setMode('NAME_INPUT')}
                            className="w-full py-4 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded uppercase tracking-widest transition-all hover:scale-105 shadow-lg border border-blue-400/30"
                        >
                            Multiplayer
                        </button>
                    </div>
                </div>
            );
        }

        // --- SINGLE PLAYER ---
        if (mode === 'SINGLEPLAYER') {
            return (
                <div className="max-w-md w-full bg-slate-900/90 backdrop-blur border border-slate-700 p-8 rounded-lg shadow-2xl">
                    <button onClick={() => setMode('MENU')} className="text-slate-500 hover:text-white mb-4 text-xs uppercase tracking-widest">
                        &larr; Back
                    </button>
                    <h1 className="text-3xl font-bold mb-8 text-center text-emerald-400">VS COMPUTER</h1>

                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm text-slate-400 mb-3 text-center uppercase tracking-widest">Select Difficulty</label>
                            <div className="grid grid-cols-3 gap-2">
                                {[Difficulty.EASY, Difficulty.MEDIUM, Difficulty.HARD].map(diff => (
                                    <button
                                        key={diff}
                                        onClick={() => setSelectedDifficulty(diff)}
                                        className={`py-3 px-2 rounded font-bold text-sm uppercase transition-colors border ${
                                            selectedDifficulty === diff 
                                            ? 'bg-emerald-600 border-emerald-400 text-white' 
                                            : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                                        }`}
                                    >
                                        {diff}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm text-slate-400 mb-3 text-center uppercase tracking-widest">Peace Timer</label>
                            <div className="grid grid-cols-4 gap-2">
                                {NO_RUSH_OPTIONS.map(sec => (
                                    <button
                                        key={sec}
                                        onClick={() => setSelectedNoRush(sec)}
                                        className={`py-3 px-1 rounded font-bold text-xs uppercase transition-colors border ${
                                            selectedNoRush === sec 
                                            ? 'bg-blue-600 border-blue-400 text-white' 
                                            : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                                        }`}
                                    >
                                        {sec === 0 ? "Off" : `${sec}s`}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <button 
                            onClick={() => onSinglePlayerStart(selectedDifficulty, selectedNoRush)}
                            className="w-full py-4 bg-emerald-500 hover:bg-emerald-400 text-white font-bold rounded uppercase tracking-widest transition-colors shadow-lg mt-4 border border-emerald-400/30"
                        >
                            Start Game
                        </button>
                    </div>
                </div>
            );
        }

        // --- NAME INPUT ---
        if (mode === 'NAME_INPUT') {
            return (
                <div className="max-w-md w-full bg-slate-900/90 backdrop-blur border border-slate-700 p-8 rounded-lg shadow-2xl">
                    <button onClick={() => setMode('MENU')} className="text-slate-500 hover:text-white mb-4 text-xs uppercase tracking-widest">
                        &larr; Back
                    </button>
                    <h1 className="text-3xl font-bold mb-8 text-center text-cyan-400">MULTIPLAYER</h1>
                    {error && <div className="bg-red-900/50 text-red-200 p-3 mb-4 rounded text-sm border border-red-800">{error}</div>}
                    <div>
                        <label className="block text-sm text-slate-400 mb-2">Enter Username</label>
                        <input 
                            type="text" 
                            value={name} 
                            onChange={(e) => setName(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && enterLobby()}
                            className="w-full bg-slate-800 border border-slate-600 p-3 rounded text-white focus:outline-none focus:border-cyan-500 mb-4"
                        />
                        <button onClick={enterLobby} className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 rounded font-bold uppercase tracking-widest shadow-lg border border-indigo-400/30">
                            Enter Lobby
                        </button>
                    </div>
                </div>
            );
        }

        // --- MAIN LOBBY ---
        if (mode === 'LOBBY') {
            return (
                <div className="max-w-4xl w-full bg-slate-900/90 backdrop-blur border border-slate-700 rounded-lg shadow-2xl flex flex-col md:flex-row overflow-hidden min-h-[500px]">

                    {/* LEFT PANEL: Public Rooms */}
                    <div className="flex-1 p-6 border-b md:border-b-0 md:border-r border-slate-700 bg-slate-800/50">
                        <h2 className="text-xl font-bold mb-6 text-slate-300 uppercase tracking-widest flex items-center gap-2">
                            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                            Public Sectors
                        </h2>

                        <div className="space-y-3">
                            {PUBLIC_ROOMS.map(room => (
                                <button
                                    key={room.id}
                                    disabled={!!opponent || statusMsg !== ''}
                                    onClick={() => handlePublicRoomClick(room)}
                                    className="w-full p-4 bg-slate-800 hover:bg-slate-700 border border-slate-600 hover:border-cyan-500 rounded flex justify-between items-center group transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <div className="flex flex-col items-start">
                                        <span className="font-bold text-slate-200 group-hover:text-cyan-400 transition-colors">{room.name}</span>
                                        <span className="text-xs text-slate-500">Official Server</span>
                                    </div>
                                    <span className="text-xs bg-slate-900 text-slate-400 px-2 py-1 rounded group-hover:bg-cyan-900/30 group-hover:text-cyan-300">
                                        JOIN / CREATE
