                                        onClick={toggleReady}
                                        className={`w-full py-4 font-bold rounded uppercase tracking-widest transition-colors shadow-lg
                                            ${isReady ? 'bg-yellow-600 hover:bg-yellow-500 text-white' : 'bg-green-600 hover:bg-green-500 text-white'}
                                        `}
                                    >
                                        {isReady ? "Cancel Ready" : "READY UP"}
                                    </button>
                                </div>
                            ) : (
                                <div className="text-center">
                                    <div className="mb-6">
                                        <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-700 relative shadow-[0_0_15px_rgba(34,211,238,0.3)]">
                                            <div className="w-3 h-3 bg-cyan-500 rounded-full animate-ping absolute top-0 right-0"></div>
                                            <span className="text-2xl">📡</span>
                                        </div>
                                        <h3 className="text-white font-bold text-lg mb-1">Hosting Private Room</h3>
                                        <p className="text-slate-500 text-xs">Waiting for challenger...</p>
                                    </div>

                                    <div className="bg-black/40 p-4 rounded border border-slate-700/50 inline-block mb-4 shadow-inner">
                                        <div className="text-xs text-slate-500 uppercase mb-1">Your Room Code</div>
                                        <div onClick={copyCode} className="text-4xl font-mono font-black text-cyan-400 cursor-pointer hover:text-cyan-300 select-all tracking-widest">
                                            {hostCode || "...."}
                                        </div>
                                    </div>
                                    <p className="text-slate-600 text-xs">Share code or join a public sector on the left.</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            );
        }
        return null;
    };

    return (
        <div className="w-full h-full bg-slate-950 flex items-center justify-center font-mono text-white relative overflow-hidden">
            <StarBackground />
            <div className="relative z-10 w-full h-full flex items-center justify-center p-4">
                {renderContent()}
            </div>
        </div>
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

