const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            // Sort by Y for simple depth sorting
            const sortedEntities = Array.from(state.entities.values()).sort((a, b) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter(e => e.owner === Owner.PLAYER);

            sortedEntities.forEach(entity => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or ignore precise unit micro sync for this demo.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 state.camera.x = Math.max(0, Math.min(GAME_WIDTH - window.innerWidth, detail.x));
                 state.camera.y = Math.max(0, Math.min(GAME_HEIGHT - (window.innerHeight - UI_TOP_HEIGHT - 200), detail.y)); // Approx bottom panel height
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach(ent => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 stateRef.current.entities.forEach(ent => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight - UI_TOP_HEIGHT} // Subtract top UI height
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import React, { useState } from 'react';
import { GameCanvas } from './components/GameCanvas';
import { Interface } from './components/Interface';
import { Lobby } from './components/Lobby';
import { GameState, GameEntity, EntityType, Owner, Difficulty } from './types';
import { initGame } from './services/gameLogic';

const App: React.FC = () => {
  const [view, setView] = useState<'LOBBY' | 'GAME'>('LOBBY');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [selectedEntities, setSelectedEntities] = useState<GameEntity[]>([]);
  const [commandMode, setCommandMode] = useState<string | null>(null);

  // Multiplayer Props
  const [isMultiplayer, setIsMultiplayer] = useState(false);
  const [gameSeed, setGameSeed] = useState(0);
  const [isHost, setIsHost] = useState(false);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.MEDIUM);
  const [noRushSeconds, setNoRushSeconds] = useState(0);

  const handleGameStart = (seed: number, host: boolean, nrSeconds: number) => {
      setGameSeed(seed);
      setIsHost(host);
      setIsMultiplayer(true);
      setNoRushSeconds(nrSeconds);
      setDifficulty(Difficulty.MEDIUM); // Default MP difficulty to medium (or irrelevant)
      setView('GAME');
  };

  const handleSinglePlayer = (diff: Difficulty, nrSeconds: number) => {
      setDifficulty(diff);
      setNoRushSeconds(nrSeconds);
      setIsMultiplayer(false);
      setGameSeed(Math.random());
      setView('GAME');
  };

  const handleInterfaceTrain = (type: EntityType) => {
      // Find selected building
      selectedEntities.forEach(ent => {
          if (ent.owner === Owner.PLAYER) {
              window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'TRAIN', id: ent.id, type } }));
          }
      });
  };

  const handleInterfaceCommand = (cmd: string) => {
      if (cmd === 'QUIT') {
          setView('LOBBY');
          setGameState(null);
          // Optional: Reset other state
          setSelectedEntities([]);
          setCommandMode(null);
          return;
      }
      if (cmd === 'RESTART' && isMultiplayer) return; // Disable restart in MP for now
      if (cmd === 'RESTART') {
           window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'RESTART', difficulty } })); // Pass difficulty
           return;
      }
      setCommandMode(cmd); // e.g., 'BUILD_SUPPLY_DEPOT'
  };

  if (view === 'LOBBY') {
      return (
          <div className="relative w-full h-full bg-zinc-950">
              <Lobby onGameStart={handleGameStart} onSinglePlayerStart={handleSinglePlayer} />
          </div>
      )
  }

  return (
    <div className="relative w-full h-full bg-zinc-950 overflow-hidden select-none">
      {/* Game Layer */}
      <div className="absolute inset-0 z-0">
          <GameCanvas 
            onGameStateUpdate={setGameState} 
            onSelectionChange={setSelectedEntities}
            commandMode={commandMode}
            setCommandMode={setCommandMode}
            isMultiplayer={isMultiplayer}
            gameSeed={gameSeed}
            isHost={isHost}
            difficulty={difficulty}
            noRushSeconds={noRushSeconds}
          />
      </div>

      {/* UI Overlay Layer */}
      {gameState && (
          <div className="absolute inset-0 z-10 pointer-events-none">
             <Interface 
                gameState={gameState} 
                selectedEntities={selectedEntities}
                onCommand={handleInterfaceCommand}
                onTrain={handleInterfaceTrain}
             />
          </div>
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { GameEntity, EntityType, GameState, Owner, Difficulty } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT } from '../constants';
import { toggleMute, getMuteState } from '../services/audio';

interface Props {
  gameState: GameState;
  selectedEntities: GameEntity[];
  onCommand: (cmd: string) => void;
  onTrain: (type: EntityType) => void;
}

export const Interface: React.FC<Props> = ({ gameState, selectedEntities, onCommand, onTrain }) => {
  const resources = gameState.resources[Owner.PLAYER];
  const supply = gameState.supply[Owner.PLAYER];
  const [isMuted, setIsMuted] = useState(getMuteState());
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Selection Logic
  const singleSelection = selectedEntities.length === 1 ? selectedEntities[0] : null;
  const allWorkers = selectedEntities.length > 0 && selectedEntities.every(e => e.type === EntityType.WORKER);
  const canBuild = allWorkers && selectedEntities.length === 1; 

  const allBarracks = selectedEntities.filter(e => e.type === EntityType.BARRACKS && e.owner === Owner.PLAYER);
  const showBarracksMenu = singleSelection?.type === EntityType.BARRACKS || allBarracks.length > 0;

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const key = e.key.toUpperCase();
        if ((e.target as HTMLElement).tagName === 'INPUT') return;

        if (singleSelection?.type === EntityType.BASE) {
            if (key === 'W') onTrain(EntityType.WORKER);
        }

        if (showBarracksMenu) {
            if (key === 'M') handleMultiTrain(EntityType.MARINE);
            if (key === 'E') handleMultiTrain(EntityType.MEDIC);
        }

        if (singleSelection?.type === EntityType.WORKER) {
            if (key === 'B') onCommand(`BUILD_${EntityType.BARRACKS}`);
            if (key === 'S') onCommand(`BUILD_${EntityType.SUPPLY_DEPOT}`);
            if (key === 'U') onCommand(`BUILD_${EntityType.BUNKER}`);
        }

        if (singleSelection?.type === EntityType.BUNKER && singleSelection.owner === Owner.PLAYER) {
            if (key === 'D') handleUnload();
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [singleSelection, showBarracksMenu, onTrain, onCommand]);

  // Close menu on click outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setMenuOpen(false);
      }
    };
    if (menuOpen) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [menuOpen]);

  const handleMultiTrain = (type: EntityType) => {
      if (allBarracks.length > 0) {
          const bestBarracks = [...allBarracks].sort((a, b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'TRAIN', id: bestBarracks.id, type } 
          }));
      } else if (singleSelection) {
          onTrain(type);
      }
  };

  const handleUnload = () => {
      if (singleSelection && singleSelection.type === EntityType.BUNKER) {
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'UNLOAD_ALL', id: singleSelection.id } 
          }));
      }
  };

  const changeDifficulty = (diff: Difficulty) => {
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
          detail: { action: 'RESTART', difficulty: diff } 
      }));
  };

  const togglePause = () => {
      setMenuOpen(false);
      window.dispatchEvent(new CustomEvent('GAME_COMMAND', { detail: { action: 'TOGGLE_PAUSE' } }));
  };

  const handleToggleMute = () => setIsMuted(toggleMute());

  // --- Minimap Logic ---
  const [isDraggingMinimap, setIsDraggingMinimap] = useState(false);
  const minimapRef = useRef<HTMLDivElement>(null);

  const getMinimapPos = (clientX: number, clientY: number) => {
      if (!minimapRef.current) return null;
      const rect = minimapRef.current.getBoundingClientRect();
      const xPct = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const yPct = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
      return { x: xPct * GAME_WIDTH, y: yPct * GAME_HEIGHT };
  };

  const handleMinimapInteraction = (e: React.MouseEvent) => {
      const pos = getMinimapPos(e.clientX, e.clientY);
      if (!pos) return;

      if (e.button === 0) {
          // Left Click: Move Camera
          setIsDraggingMinimap(true);
          const centerX = pos.x - (window.innerWidth / 2);
          const centerY = pos.y - (window.innerHeight / 2);
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
          }));
      } else if (e.button === 2) {
          // Right Click: Move Unit / Attack Move
          e.preventDefault();
          window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
              detail: { action: 'MINIMAP_ACTION', x: pos.x, y: pos.y } 
          }));
      }
  };

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (isDraggingMinimap) {
              const pos = getMinimapPos(e.clientX, e.clientY);
              if (pos) {
                  const centerX = pos.x - (window.innerWidth / 2);
                  const centerY = pos.y - (window.innerHeight / 2);
                  window.dispatchEvent(new CustomEvent('GAME_COMMAND', { 
                      detail: { action: 'MOVE_CAMERA', x: centerX, y: centerY } 
                  }));
              }
          }
      };
      const handleMouseUp = () => setIsDraggingMinimap(false);

      if (isDraggingMinimap) {
          window.addEventListener('mousemove', handleMouseMove);
          window.addEventListener('mouseup', handleMouseUp);
      }
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
      };
  }, [isDraggingMinimap]);


  const isVisibleOnMinimap = (entity: GameEntity, playerUnits: GameEntity[]) => {
      if (entity.owner === Owner.PLAYER) return true;
      if (entity.type === EntityType.MINERAL && entity.resourceAmount! <= 0) return false;
      for(const pu of playerUnits) {
          const dx = entity.position.x - pu.position.x;
          const dy = entity.position.y - pu.position.y;
          if (dx*dx + dy*dy < 250000) return true;
      }
      return false;
  };

  const allEntities: GameEntity[] = Array.from(gameState.entities.values());
  const playerUnits = allEntities.filter(e => e.owner === Owner.PLAYER && e.state !== 'GARRISONED');

  const formatTime = (frames: number) => {
      const sec = Math.floor(frames / 60);
      const m = Math.floor(sec / 60);
      const s = sec % 60;
      return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const noRushTimeLeft = Math.max(0, gameState.noRushFrames - gameState.gameTime);

  return (
    <div className="absolute inset-0 flex flex-col justify-between pointer-events-none font-sans text-white">
      {/* Top HUD */}
      <div className="h-16 w-full bg-gradient-to-b from-zinc-950/90 to-zinc-950/0 px-6 pt-3 flex items-start justify-between pointer-events-auto backdrop-blur-[2px]">
         {/* Resources */}
         <div className="flex gap-8 items-center pt-1">
             <div className="flex flex-col">
                 <span className="text-[10px] uppercase tracking-widest text-zinc-400 font-bold">Minerals</span>
                 <span className="text-2xl font-mono font-bold text-cyan-400 drop-shadow-lg flex items-center gap-2">
                     <div className="w-3 h-3 bg-cyan-400 rounded-sm rotate-45 shadow-[0_0_10px_rgba(34,211,238,0.5)]" />
                     {Math.floor(resources)}
                 </span>
             </div>
             <div className="flex flex-col">
                 <span className="text-[10px] uppercase tracking-widest text-zinc-400 font-bold">Supply</span>
                 <span className={`text-2xl font-mono font-bold flex items-center gap-2 drop-shadow-lg ${supply.used > supply.max ? "text-rose-500" : "text-white"}`}>
                    <div className={`w-3 h-3 rounded-full shadow-[0_0_10px_rgba(255,255,255,0.3)] ${supply.used > supply.max ? "bg-rose-500" : "bg-emerald-500"}`} />
                    {supply.used}<span className="text-zinc-600 text-lg">/</span>{supply.max}
                 </span>
             </div>
         </div>

         {/* Center Widget */}
         <div className="flex flex-col items-center transform -translate-y-1">
             <div className="bg-zinc-900/90 backdrop-blur-md border border-white/10 px-6 py-1.5 rounded-full shadow-2xl flex items-center gap-2">
                 <div className={`w-2 h-2 rounded-full animate-pulse ${gameState.paused ? 'bg-yellow-500' : 'bg-green-500'}`} />
                 <span className="text-xl font-mono font-bold tracking-widest text-zinc-100">{formatTime(gameState.gameTime)}</span>
             </div>
             {noRushTimeLeft > 0 && (
                 <div className="mt-2 text-[10px] font-bold uppercase tracking-[0.2em] text-emerald-400 bg-emerald-950/80 px-3 py-1 rounded-full border border-emerald-500/30 animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.2)]">
                     No Rush: {Math.ceil(noRushTimeLeft / 60)}s
                 </div>
             )}
         </div>

         {/* Menu Button */}
         <div className="relative pt-1" ref={menuRef}>
            <button 
                onClick={() => setMenuOpen(!menuOpen)}
                className="w-10 h-10 flex flex-col items-center justify-center gap-1.5 bg-zinc-800/40 hover:bg-zinc-700/60 rounded-lg border border-white/10 hover:border-white/30 transition-all group backdrop-blur-sm"
            >
                <div className="w-5 h-0.5 bg-zinc-400 group-hover:bg-white transition-colors" />
                <div className="w-5 h-0.5 bg-zinc-400 group-hover:bg-white transition-colors" />
                <div className="w-5 h-0.5 bg-zinc-400 group-hover:bg-white transition-colors" />
            </button>

            {menuOpen && (
                <div className="absolute right-0 top-full mt-3 w-64 bg-zinc-950/95 border border-white/10 rounded-xl shadow-2xl flex flex-col p-1.5 z-50 text-sm backdrop-blur-xl">
                    <button onClick={togglePause} className="text-left px-4 py-3 hover:bg-white/5 rounded-lg font-semibold text-white transition-colors flex justify-between items-center group">
                        {gameState.paused ? 'Resume Mission' : 'Pause Mission'} 
                        <span className="text-zinc-600 text-xs font-mono border border-zinc-700 px-1.5 rounded group-hover:border-zinc-500 transition-colors">P</span>
                    </button>
                    <button onClick={handleToggleMute} className="text-left px-4 py-3 hover:bg-white/5 rounded-lg text-zinc-300 transition-colors">
                        Audio Systems: <span className={isMuted ? 'text-red-400' : 'text-green-400'}>{isMuted ? 'Offline' : 'Online'}</span>
                    </button>
                    <div className="h-px bg-white/10 my-1.5 mx-2"></div>
                    <button onClick={() => changeDifficulty(gameState.difficulty)} className="text-left px-4 py-3 text-rose-400 hover:bg-rose-500/10 rounded-lg font-bold transition-colors">
                        Restart Operation
                    </button>
                    <button onClick={() => onCommand('QUIT')} className="text-left px-4 py-3 text-amber-400 hover:bg-amber-500/10 rounded-lg font-bold transition-colors">
                        Abort to Menu
                    </button>
                </div>
            )}
         </div>
      </div>

      {/* Victory/Defeat Overlay */}
      {gameState.victory && (
         <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-50 pointer-events-auto backdrop-blur-md">
             <div className="bg-zinc-950 p-12 rounded-2xl border border-white/10 text-center shadow-[0_0_50px_rgba(0,0,0,0.5)] max-w-lg w-full relative overflow-hidden">
