const CommandButton = ({ label, sub, hotkey, cost, res, onClick, progress, max, queue }: any) => {
    const disabled = res < cost;
    return (
        <button 
            disabled={disabled}
            onClick={onClick}
            className={`
                relative rounded-lg flex flex-col items-center justify-center p-1 transition-all duration-100 group
                ${disabled 
                    ? 'bg-zinc-900/50 border border-white/5 opacity-40 cursor-not-allowed' 
                    : 'bg-white/5 hover:bg-white/10 border border-white/10 hover:border-cyan-400/50 hover:shadow-[0_0_15px_rgba(34,211,238,0.1)] active:scale-95 active:bg-cyan-950/30'}
            `}
        >
            <span className="absolute top-1 right-1.5 text-[10px] font-bold text-zinc-500 group-hover:text-cyan-400 font-mono transition-colors">{hotkey}</span>
            <span className="text-[10px] text-zinc-300 font-bold leading-tight text-center mt-1 group-hover:text-white tracking-wide">{label}</span>
            <span className="text-[9px] text-cyan-700 group-hover:text-cyan-500 leading-none mt-0.5 font-mono">{sub}</span>

            {queue > 0 && (
                <span className="absolute top-1 left-1 bg-cyan-600 text-white text-[9px] w-4 h-4 rounded flex items-center justify-center shadow-lg font-bold">
                    {queue}
                </span>
            )}

            {progress !== undefined && progress > 0 && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-zinc-950 rounded-b overflow-hidden">
                    <div className="h-full bg-cyan-400 opacity-80" style={{ width: `${(progress / max) * 100}%` }} />
                </div>
            )}
        </button>
    );
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();

    // UI Layout Constants - Matches new Interface.tsx styling
    // Bottom panel height is approx 256px (h-64 in Tailwind)
    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        // Ensure we can scroll enough to see bottom of map despite UI overlay
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = Array.from(state.entities.values()).sort((a, b) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter(e => e.owner === Owner.PLAYER);

            sortedEntities.forEach(entity => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or ignore precise unit micro sync for this demo.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 // Camera handling with bounds check against map size + visual allowance
                 // This ensures the camera doesn't pan infinitely into void, but allows reaching edges
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); // Allow scrolling past for bottom UI

                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach(ent => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 stateRef.current.entities.forEach(ent => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();

    // UI Layout Constants - Matches new Interface.tsx styling
    // Bottom panel height is approx 256px (h-64 in Tailwind)
    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        // Ensure we can scroll enough to see bottom of map despite UI overlay
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = Array.from(state.entities.values()).sort((a: GameEntity, b: GameEntity) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or command-based spawning.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 // Camera handling with bounds check against map size + visual allowance
                 // This ensures the camera doesn't pan infinitely into void, but allows reaching edges
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); // Allow scrolling past for bottom UI

                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach(ent => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 stateRef.current.entities.forEach((ent: GameEntity) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();
    const keysPressed = useRef<Set<string>>(new Set());

    // UI Layout Constants - Matches new Interface.tsx styling
    // Bottom panel height is approx 256px (h-64 in Tailwind)
    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Keyboard Listeners
    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            keysPressed.current.add(e.code);
            if ((e.target as HTMLElement).tagName === 'INPUT') return;
            const key = e.key.toUpperCase();

            if (key === 'A') setCommandMode('ATTACK');
            if (key === 'P') { 
                if (stateRef.current) {
                    stateRef.current.paused = !stateRef.current.paused; 
                    onGameStateUpdate({...stateRef.current}); 
                }
            }

            if (stateRef.current) {
                // 1: Select Worker
                if (key === '1') {
                    const ents = Array.from(stateRef.current.entities.values());
                    const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

                    let target = workers.find(w => w.state === 'IDLE');
                    if (!target) target = workers.find(w => w.state === 'GATHERING');
                    if (!target && workers.length > 0) target = workers[0];

                    if (target) {
                        stateRef.current.selection = [target.id];
                        onSelectionChange([target]);
                        playSound('click');
                    }
                }

                // 2: Select Army
                if (key === '2') {
                    const ents = Array.from(stateRef.current.entities.values());
                    const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
                    if (army.length > 0) {
                        const ids = army.map(u => u.id);
                        stateRef.current.selection = ids;
                        onSelectionChange(army);
                        playSound('click');
                    }
                }

                // Space: Center Camera
                if (key === ' ') {
                    e.preventDefault();
                    if (stateRef.current.selection.length > 0) {
                        const id = stateRef.current.selection[0];
                        const ent = stateRef.current.entities.get(id);
                        if (ent && canvasRef.current) {
                            stateRef.current.camera.x = ent.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = ent.position.y - window.innerHeight / 2;
                        }
                    } else {
                        const base = Array.from(stateRef.current.entities.values()).find(e => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                        if (base && canvasRef.current) {
                            stateRef.current.camera.x = base.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = base.position.y - window.innerHeight / 2;
                        }
                    }
                }
            }
        };

        const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);
        return () => { 
            window.removeEventListener('keydown', onKeyDown); 
            window.removeEventListener('keyup', onKeyUp); 
        };
    }, [setCommandMode, onSelectionChange, onGameStateUpdate]);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Logic
        const panSpeed = 15;
        if (keysPressed.current.has('ArrowLeft')) stateRef.current.camera.x -= panSpeed;
        if (keysPressed.current.has('ArrowRight')) stateRef.current.camera.x += panSpeed;
        if (keysPressed.current.has('ArrowUp')) stateRef.current.camera.y -= panSpeed;
        if (keysPressed.current.has('ArrowDown')) stateRef.current.camera.y += panSpeed;

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        // Ensure we can scroll enough to see bottom of map despite UI overlay
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = Array.from(state.entities.values()).sort((a: GameEntity, b: GameEntity) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or command-based spawning.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 // Camera handling with bounds check against map size + visual allowance
                 // This ensures the camera doesn't pan infinitely into void, but allows reaching edges
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); // Allow scrolling past for bottom UI

                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach(ent => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 stateRef.current.entities.forEach((ent: GameEntity) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();
    const keysPressed = useRef<Set<string>>(new Set());

    // UI Layout Constants - Matches new Interface.tsx styling
    // Bottom panel height is approx 256px (h-64 in Tailwind)
    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Keyboard Listeners
    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            keysPressed.current.add(e.code);
            if ((e.target as HTMLElement).tagName === 'INPUT') return;
            const key = e.key.toUpperCase();

            if (key === 'A') setCommandMode('ATTACK');
            if (key === 'P') { 
                if (stateRef.current) {
                    stateRef.current.paused = !stateRef.current.paused; 
                    onGameStateUpdate({...stateRef.current}); 
                }
            }

            if (stateRef.current) {
                // 1: Select Worker
                if (key === '1') {
                    const ents: GameEntity[] = Array.from(stateRef.current.entities.values());
                    const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

                    let target = workers.find(w => w.state === 'IDLE');
                    if (!target) target = workers.find(w => w.state === 'GATHERING');
                    if (!target && workers.length > 0) target = workers[0];

                    if (target) {
                        stateRef.current.selection = [target.id];
                        onSelectionChange([target]);
                        playSound('click');
                    }
                }

                // 2: Select Army
                if (key === '2') {
                    const ents: GameEntity[] = Array.from(stateRef.current.entities.values());
                    const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
                    if (army.length > 0) {
                        const ids = army.map(u => u.id);
                        stateRef.current.selection = ids;
                        onSelectionChange(army);
                        playSound('click');
                    }
                }

                // Space: Center Camera
                if (key === ' ') {
                    e.preventDefault();
                    if (stateRef.current.selection.length > 0) {
                        const id = stateRef.current.selection[0];
                        const ent = stateRef.current.entities.get(id);
                        if (ent && canvasRef.current) {
                            stateRef.current.camera.x = ent.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = ent.position.y - window.innerHeight / 2;
                        }
                    } else {
                        const base = Array.from(stateRef.current.entities.values()).find((e: GameEntity) => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                        if (base && canvasRef.current) {
                            stateRef.current.camera.x = base.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = base.position.y - window.innerHeight / 2;
                        }
                    }
                }
            }
        };

        const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);
        return () => { 
            window.removeEventListener('keydown', onKeyDown); 
            window.removeEventListener('keyup', onKeyUp); 
        };
    }, [setCommandMode, onSelectionChange, onGameStateUpdate]);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Logic
        const panSpeed = 15;
        if (keysPressed.current.has('ArrowLeft')) stateRef.current.camera.x -= panSpeed;
        if (keysPressed.current.has('ArrowRight')) stateRef.current.camera.x += panSpeed;
        if (keysPressed.current.has('ArrowUp')) stateRef.current.camera.y -= panSpeed;
        if (keysPressed.current.has('ArrowDown')) stateRef.current.camera.y += panSpeed;

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        // Ensure we can scroll enough to see bottom of map despite UI overlay
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = Array.from(state.entities.values()).sort((a: GameEntity, b: GameEntity) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or command-based spawning.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 // Camera handling with bounds check against map size + visual allowance
                 // This ensures the camera doesn't pan infinitely into void, but allows reaching edges
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); // Allow scrolling past for bottom UI

                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([] as GameEntity[]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach((ent: GameEntity) => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 stateRef.current.entities.forEach((ent: GameEntity) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();
    const keysPressed = useRef<Set<string>>(new Set());

    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Keyboard Listeners
    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            keysPressed.current.add(e.code);
            if ((e.target as HTMLElement).tagName === 'INPUT') return;
            const key = e.key.toUpperCase();

            if (key === 'A') setCommandMode('ATTACK');
            if (key === 'P') { 
                if (stateRef.current) {
                    stateRef.current.paused = !stateRef.current.paused; 
                    onGameStateUpdate({...stateRef.current}); 
                }
            }

            if (stateRef.current) {
                // 1: Select Worker
                if (key === '1') {
                    const ents = Array.from(stateRef.current.entities.values());
                    const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

                    let target = workers.find(w => w.state === 'IDLE');
                    if (!target) target = workers.find(w => w.state === 'GATHERING');
                    if (!target && workers.length > 0) target = workers[0];

                    if (target) {
                        stateRef.current.selection = [target.id];
                        onSelectionChange([target]);
                        playSound('click');
                    }
                }

                // 2: Select Army
                if (key === '2') {
                    const ents = Array.from(stateRef.current.entities.values());
                    const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
                    if (army.length > 0) {
                        const ids = army.map(u => u.id);
                        stateRef.current.selection = ids;
                        onSelectionChange(army);
                        playSound('click');
                    }
                }

                // Space: Center Camera
                if (key === ' ') {
                    e.preventDefault();
                    if (stateRef.current.selection.length > 0) {
                        const id = stateRef.current.selection[0];
                        const ent = stateRef.current.entities.get(id);
                        if (ent && canvasRef.current) {
                            stateRef.current.camera.x = ent.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = ent.position.y - window.innerHeight / 2;
                        }
                    } else {
                        const base = Array.from(stateRef.current.entities.values()).find((e: GameEntity) => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                        if (base && canvasRef.current) {
                            stateRef.current.camera.x = base.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = base.position.y - window.innerHeight / 2;
                        }
                    }
                }
            }
        };

        const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);
        return () => { 
            window.removeEventListener('keydown', onKeyDown); 
            window.removeEventListener('keyup', onKeyUp); 
        };
    }, [setCommandMode, onSelectionChange, onGameStateUpdate]);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Logic
        const panSpeed = 15;
        if (keysPressed.current.has('ArrowLeft')) stateRef.current.camera.x -= panSpeed;
        if (keysPressed.current.has('ArrowRight')) stateRef.current.camera.x += panSpeed;
        if (keysPressed.current.has('ArrowUp')) stateRef.current.camera.y -= panSpeed;
        if (keysPressed.current.has('ArrowDown')) stateRef.current.camera.y += panSpeed;

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = Array.from(state.entities.values()).sort((a: GameEntity, b: GameEntity) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 }
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); 
                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([] as GameEntity[]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; 
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; 
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach((ent: GameEntity) => {
                 if (ent.owner !== Owner.PLAYER) return; 
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 stateRef.current.entities.forEach((ent: GameEntity) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT, FPS } from '../constants';
import { GameEntity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, AIStrategy } from '../types';
import { SeededRandom } from './random';

let idCounter = 0;
// We need to synchronize IDs in multiplayer. 
// In a real app, we'd use GUIDs or owner-prefixed IDs. 
// For this simple version, Host generates odd IDs, Client generates even IDs, or we rely on the prefix.
export const generateId = (prefix: string = 'ent') => `${prefix}_${++idCounter}_${Math.floor(Math.random()*1000)}`;

export const addNotification = (state: GameState, text: string) => {
    state.notifications.push({
        id: `n_${Math.random()}`,
        text,
        life: 120
    });
};

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2, id?: string): GameEntity => {
  const stats = STATS[type];
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: id || generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null,
    garrison: [],
    containerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, GameEntity>, type?: EntityType, owner?: Owner) => {
  let nearest: GameEntity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (e.state === 'GARRISONED') return;
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

// Count how many workers are targeting a specific mineral patch
const getWorkerCountForMineral = (mineralId: string, entities: Map<string, GameEntity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

const isBio = (type: EntityType) => type === EntityType.WORKER || type === EntityType.MARINE || type === EntityType.MEDIC;
const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT || type === EntityType.BUNKER;

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM, isMultiplayer = false, seed = Math.random() * 10000, isHost = true, noRushSeconds = 0): GameState => {
  const entities = new Map<string, GameEntity>();
  const effects: Effect[] = [];
  const add = (e: GameEntity) => entities.set(e.id, e);

  // Use seeded random
  const rng = new SeededRandom(seed);

  // --- RANDOMIZED BASE PLACEMENT ---
  // Define 4 corners with padding
  const corners = [
      { x: 150, y: 150 }, // TL
      { x: GAME_WIDTH - 150, y: 150 }, // TR
      { x: 150, y: GAME_HEIGHT - 150 }, // BL
      { x: GAME_WIDTH - 150, y: GAME_HEIGHT - 150 } // BR
  ];

  // Shuffle corners using seeded random
  // Fisher-Yates shuffle
  for (let i = corners.length - 1; i > 0; i--) {
        const j = Math.floor(rng.next() * (i + 1));
        [corners[i], corners[j]] = [corners[j], corners[i]];
  }

  // If Host (Player 1), we are at corners[0]. If Client (Player 2), we are at corners[0] but visually we might want to swap?
  // Actually, to keep it simple: Player is ALWAYS corners[0] in singleplayer.
  // In multiplayer: 
  //   Host -> Owner.PLAYER at corners[0], Opponent -> Owner.OPPONENT at corners[1].
  //   Client -> Owner.PLAYER at corners[1], Opponent -> Owner.OPPONENT at corners[0].

  let myBasePos = corners[0];
  let opBasePos = corners[1];

  if (isMultiplayer && !isHost) {
      // If I am the client, I spawn at the second position, and the opponent (Host) is at the first.
      // But from MY perspective, I am Owner.PLAYER.
      myBasePos = corners[1];
      opBasePos = corners[0];
  }

  // Add random offset to prevent exact static spots
  const jitter = (pt: Vector2) => ({
      x: pt.x + (rng.next() - 0.5) * 50,
      y: pt.y + (rng.next() - 0.5) * 50
  });

  myBasePos = jitter(myBasePos);
  opBasePos = jitter(opBasePos);

  // --- RANDOM STRATEGY ---
  const strategies = [AIStrategy.RUSH, AIStrategy.MACRO, AIStrategy.TURTLE];
  const aiStrategy = strategies[Math.floor(rng.next() * strategies.length)];

  // --- MAP GENERATION ---
  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = rng.next() * Math.PI * 2;
          const dist = rng.next() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;

          if (getDistance({x,y}, myBasePos) < 400) continue;
          if (getDistance({x,y}, opBasePos) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;

          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  // Terrain
  for(let i=0; i<15; i++) {
      generateCluster(EntityType.MOUNTAIN, 5, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 150);
  }
  for(let i=0; i<8; i++) {
      generateCluster(EntityType.WATER, 4, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 120);
  }

  // Expansion Minerals: 2, 4, 6, or 8 clusters
  const possibleExpansions = [2, 4, 6, 8];
  const numExpansions = possibleExpansions[Math.floor(rng.next() * possibleExpansions.length)];

  for(let i=0; i<numExpansions; i++) {
      let exX = rng.range(150, GAME_WIDTH - 300);
      let exY = rng.range(150, GAME_HEIGHT - 300);

      let safe = false;
      let attempts = 0;
      while (!safe && attempts < 10) {
          if (getDistance({x:exX, y:exY}, myBasePos) > 700 && getDistance({x:exX, y:exY}, opBasePos) > 700) {
              safe = true;
          } else {
              exX = rng.range(150, GAME_WIDTH - 300);
              exY = rng.range(150, GAME_HEIGHT - 300);
          }
          attempts++;
      }
      generateCluster(EntityType.MINERAL, 7, exX, exY, 70);
  }

  // --- PLAYER SETUP ---
  const spawnBase = (pos: Vector2, owner: Owner) => {
      const centerAngle = Math.atan2((GAME_HEIGHT/2) - pos.y, (GAME_WIDTH/2) - pos.x);
      for (let i = 0; i < 8; i++) {
        const angle = centerAngle - (Math.PI/2) + (i / 7) * Math.PI; 
        add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { 
          x: pos.x + 220 * Math.cos(angle), 
          y: pos.y + 220 * Math.sin(angle) 
        }));
      }
      const base = createEntity(EntityType.BASE, owner, pos);
      add(base);
      for (let i = 0; i < 4; i++) {
        const worker = createEntity(EntityType.WORKER, owner, { 
            x: pos.x + (rng.next()-0.5)*50, 
            y: pos.y + (rng.next()-0.5)*50 
        });
        add(worker);
        const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
        if (mineral) {
            worker.state = 'GATHERING';
            worker.targetId = mineral.id;
        }
      }
      const nearestMineral = findNearest(base.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
      if (nearestMineral) {
          base.rallyPoint = nearestMineral.position;
          base.rallyTargetId = nearestMineral.id;
      }
  };

  spawnBase(myBasePos, Owner.PLAYER);
  const opponentOwner = isMultiplayer ? Owner.OPPONENT : Owner.AI;
  spawnBase(opBasePos, opponentOwner);

  const startCameraY = Math.max(0, myBasePos.y - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));
  const startCameraX = Math.max(0, myBasePos.x - (typeof window !== 'undefined' ? window.innerWidth / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50, [Owner.OPPONENT]: 50 },
    supply: { 
      [Owner.PLAYER]: { used: 4, max: 10 }, 
      [Owner.AI]: { used: 4, max: 10 },
      [Owner.OPPONENT]: { used: 4, max: 10 }
    },
    selection: [],
    camera: { x: startCameraX, y: startCameraY },
    gameTime: 0,
    noRushFrames: noRushSeconds * FPS, // Convert seconds to frames
    difficulty,
    aiStrategy,
    victory: undefined,
    paused: false,
    isMultiplayer
  };
};

const resolveCollisions = (entity: GameEntity, entities: Map<string, GameEntity>) => {
  if (entity.state === 'BUILDING' || entity.state === 'GARRISONED') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;
    if (other.state === 'GARRISONED') return;

    const isStatic = STATS[other.type].speed === 0;

    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; 

    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);

      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; 

      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const acquireTarget = (entity: GameEntity, entities: Map<string, GameEntity>, gameTime: number, noRushFrames: number) => {
    const stats = STATS[entity.type];
    let bestTarget: GameEntity | null = null;
    let bestScore = -Infinity;
    const searchRange = stats.range + 250; 

    entities.forEach(e => {
        if (e.state === 'GARRISONED') return;

        // No Rush Logic: Don't auto-acquire enemy targets during rush time
        if (gameTime < noRushFrames) {
            if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL) return;
        }

        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;
                if (e.targetId === entity.id) score += 5000;
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; 
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };
  supply[Owner.OPPONENT] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    // Supply Logic Fix: Only fully constructed buildings provide supply
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);
  supply[Owner.OPPONENT].max = Math.min(supply[Owner.OPPONENT].max, 200);

  // --- ENTITY UPDATE LOOP ---
  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 
    if (entity.state === 'GARRISONED') return; 

    // 1. Building Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) {
           entity.constructionProgress = 100;
           // Completed sound?
       }
       return; 
    }

    // 2. Unit Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 
             // IMPORTANT: In multiplayer, ID generation must be consistent or handled by owner.
             // We use a random suffix in generateId, which is risky for exact sync.
             // For this clone, we assume "good enough" sync or command-based spawning.
             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             // Inherit rally point
             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     }
                     if (!entity.rallyTargetId && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                         newUnit.state = unitType === EntityType.MEDIC ? 'MOVING' : 'ATTACKING'; 
                     }
                 }
             } else if ((entity.owner === Owner.AI || entity.owner === Owner.OPPONENT) && (unitType === EntityType.MARINE || unitType === EntityType.MEDIC)) {
                // AI Units just spawn
                newUnit.state = 'IDLE'; 
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    const stats = STATS[entity.type];

    // --- BUNKER LOGIC ---
    if (entity.type === EntityType.BUNKER) {
        if (entity.garrison && entity.garrison.length > 0) {
            let target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp <= 0 || getDistance(entity.position, target.position) > stats.range) {
                target = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
                entity.targetId = target ? target.id : null;
            }

            if (target) {
                const dist = getDistance(entity.position, target.position);
                if (dist <= stats.range) {
                    if (entity.cooldown <= 0) {
                        const marineStats = STATS[EntityType.MARINE];
                        target.hp -= marineStats.damage;
                        entity.cooldown = Math.max(5, 30 / entity.garrison.length);

                        if (target.hp <= 0) entity.targetId = null;
                        soundEvents.push('shoot');
                    }
                }
            }
        }
    }

    // --- MEDIC LOGIC ---
    if (entity.type === EntityType.MEDIC) {
        if (['IDLE', 'MOVING', 'ATTACKING'].includes(entity.state)) {
            let healTarget: GameEntity | null = null;
            let bestHealDist = stats.vision;

            entities.forEach(e => {
                if (e.owner === entity.owner && isBio(e.type) && e.hp < e.maxHp && e.state !== 'GARRISONED') {
                    const d = getDistance(entity.position, e.position);
                    if (d < bestHealDist) {
                        bestHealDist = d;
                        healTarget = e;
                    }
                }
            });

            if (healTarget) {
                const d = getDistance(entity.position, healTarget.position);
                if (d <= stats.range) {
                    entity.state = 'HEALING';
                    entity.targetId = healTarget.id;
                    entity.targetPosition = null; 
                } else {
                    const angle = Math.atan2(healTarget.position.y - entity.position.y, healTarget.position.x - entity.position.x);
                    entity.position.x += Math.cos(angle) * stats.speed;
                    entity.position.y += Math.sin(angle) * stats.speed;
                }
            }
        }

        if (entity.state === 'HEALING') {
            const target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp >= target.maxHp || getDistance(entity.position, target.position) > stats.range + 20) {
                 entity.state = 'IDLE';
                 entity.targetId = null;
            } else {
                 if (entity.cooldown <= 0) {
                     target.hp = Math.min(target.maxHp, target.hp + (stats.healRate || 5));
                     entity.cooldown = stats.attackSpeed;
                     newEffects.push({
                        id: `fx_${Math.random()}`,
                        type: 'HEAL',
                        position: { ...target.position },
                        life: 20, maxLife: 20, scale: 1
                     });
                 }
            }
        }
    }

    // --- ENTERING BUNKER LOGIC ---
    if (entity.state === 'ENTERING' && entity.targetId) {
        const bunker = entities.get(entity.targetId);
        // Bunker Fix: Must be built to enter
        if (bunker && bunker.type === EntityType.BUNKER && bunker.hp > 0 && bunker.owner === entity.owner && bunker.constructionProgress! >= 100) {
             const dist = getDistance(entity.position, bunker.position);
             if (dist < bunker.radius + entity.radius + 10) {
                 if (!bunker.garrison) bunker.garrison = [];
                 if (bunker.garrison.length < 4) {
                     bunker.garrison.push(entity.id);
                     entity.state = 'GARRISONED';
                     entity.containerId = bunker.id;
                     entity.targetId = null;
                     entity.targetPosition = null;
                     soundEvents.push('click'); 
                 } else {
                     entity.state = 'IDLE'; 
                 }
             } else {
                 const angle = Math.atan2(bunker.position.y - entity.position.y, bunker.position.x - entity.position.x);
                 entity.position.x += Math.cos(angle) * stats.speed;
                 entity.position.y += Math.sin(angle) * stats.speed;
             }
        } else {
            entity.state = 'IDLE';
        }
    }

    // --- STANDARD ACTION LOGIC ---
    if (entity.state === 'IDLE' && entity.type !== EntityType.MEDIC && entity.type !== EntityType.WORKER && stats.damage > 0) {
        const target = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
        if (target) {
            entity.targetId = target.id;
            entity.state = 'ATTACKING';
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // No Rush Enforcement: If manual attack is issued during rush time, cancel it if targeting enemy
        if (state.gameTime < state.noRushFrames && target && target.owner !== entity.owner && target.owner !== Owner.NEUTRAL) {
             entity.state = 'IDLE';
             entity.targetId = null;
             // Silent cancel for now, or could walk to target without shooting
             target = null;
        }

        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner && attacker.state !== 'GARRISONED') {
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null;
                }
            }
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        if (!target || target.hp <= 0 || target.state === 'GARRISONED') {
           entity.targetId = null;
           target = null;

           if (entity.targetPosition) {
                if (stats.damage > 0) {
                    const newTarget = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
                    if (newTarget) {
                        entity.targetId = newTarget.id;
                    } else {
                        const dist = getDistance(entity.position, entity.targetPosition);
                        if (dist < 10) {
                            entity.state = 'IDLE';
                            entity.targetPosition = null;
                        } else {
                            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                            entity.position.x += Math.cos(angle) * stats.speed;
                            entity.position.y += Math.sin(angle) * stats.speed;
                        }
                    }
                } else {
                    entity.state = 'MOVING';
                }
           } else {
             entity.state = 'IDLE';
           }
        } 

        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; 

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; 
                  entity.cooldown = stats.attackSpeed;
                  soundEvents.push('shoot');

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
         const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            let newRes: GameEntity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });
            if (newRes) entity.targetId = (newRes as GameEntity).id;
            else entity.state = 'IDLE';
        } else {
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }
            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; 
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) newEntities.delete(target.id);
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;
                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    // Check death
    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;

        if (isBio(entity.type)) {
            effectType = 'BLOOD';
        } else if (isBuilding(entity.type)) {
            effectType = 'BUILDING_EXPLOSION';
            effectScale = 2.0;
        }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');

        if (entity.garrison && entity.garrison.length > 0) {
            entity.garrison.forEach(id => {
                const unit = newEntities.get(id);
                if (unit) {
                    unit.state = 'IDLE';
                    unit.containerId = null;
                    unit.position = { 
                        x: entity.position.x + (Math.random() * 40 - 20), 
                        y: entity.position.y + (Math.random() * 40 - 20) 
                    };
                }
            });
        }

        newEntities.delete(entity.id);
    }

    resolveCollisions(entity, entities);
  });

  newEffects = newEffects.filter(fx => { fx.life--; return fx.life > 0; });
  newMarkers = newMarkers.filter(mk => { mk.life--; return mk.life > 0; });
  newNotifications = newNotifications.filter(n => { n.life--; return n.life > 0; });

  // ONLY RUN AI IF SINGLE PLAYER
  if (!state.isMultiplayer && state.gameTime % 30 === 0) {
      runAI(state, newEntities, resources, supply);
  }

  let playerBuildings = 0;
  let opponentBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if ((e.owner === Owner.AI || e.owner === Owner.OPPONENT) && isBuilding(e.type)) opponentBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = state.isMultiplayer ? Owner.OPPONENT : Owner.AI; 
  if (opponentBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, GameEntity>, resources: any, supply: any) => {
  const aiOwner = Owner.AI;
  const playerOwner = Owner.PLAYER;

  const myUnits = Array.from(entities.values()).filter(e => e.owner === aiOwner);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const bunkers = myUnits.filter(e => e.type === EntityType.BUNKER);
  const army = myUnits.filter(e => e.type === EntityType.MARINE || e.type === EntityType.MEDIC);
  const depots = myUnits.filter(e => e.type === EntityType.SUPPLY_DEPOT);

  const myMinerals = resources[aiOwner];
  const mySupply = supply[aiOwner];
  const strategy = state.aiStrategy;

  let maxWorkers = 12;
  let attackThreshold = 12;
  let expand = false;
  let buildBunkers = false;

  // Modify logic based on Strategy
  if (strategy === AIStrategy.RUSH) {
      maxWorkers = 10;
      attackThreshold = 8;
  } else if (strategy === AIStrategy.MACRO) {
      maxWorkers = 20;
      attackThreshold = 25;
      expand = true;
  } else if (strategy === AIStrategy.TURTLE) {
      maxWorkers = 14;
      attackThreshold = 30; // Wait for big army
      buildBunkers = true;
  }

  // Difficulty Override (Difficulty caps capability, Strategy directs it)
  if (state.difficulty === Difficulty.EASY) {
      maxWorkers = Math.min(maxWorkers, 10);
      attackThreshold = Math.max(attackThreshold, 15);
  } else if (state.difficulty === Difficulty.HARD) {
      maxWorkers = Math.max(maxWorkers, 16);
  }

  // --- 0. DEFENSE CHECK ---
  let underAttack = false;
  let threatPos: Vector2 | null = null;

  if (bases.length > 0) {
      const mainBase = bases[0];
      const enemies = Array.from(entities.values()).filter(e => e.owner === playerOwner);
      const nearestEnemy = enemies.find(e => getDistance(e.position, mainBase.position) < 800);
      if (nearestEnemy) {
          underAttack = true;
          threatPos = nearestEnemy.position;
      }
  }

  if (underAttack && army.length === 0 && state.difficulty === Difficulty.HARD) {
       workers.slice(0, 5).forEach(w => {
           if (w.state !== 'ATTACKING') {
               w.state = 'ATTACKING';
               w.targetPosition = threatPos;
           }
       });
  }

  // --- 1. WORKERS ---
  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.sort((a,b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
      if (base && (!base.trainQueue || base.trainQueue.length < 1)) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[aiOwner] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'ATTACKING' && !underAttack) w.state = 'IDLE';
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) {
              w.targetId = m.id;
              w.state = 'GATHERING';
          }
      }
  });

  // --- 2. SUPPLY ---
  if (mySupply.max - mySupply.used <= 3 && myMinerals >= 100 && depots.length < 10) {
      const construction = myUnits.find(u => u.type === EntityType.SUPPLY_DEPOT && u.constructionProgress! < 100);
      if (!construction) {
          const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
          if (builder) {
              resources[aiOwner] -= 100;
              const basePos = bases[0]?.position || builder.position;
              const angle = Math.random() * Math.PI * 2;
              const dist = 100 + Math.random() * 100;
              const buildPos = { x: basePos.x + Math.cos(angle)*dist, y: basePos.y + Math.sin(angle)*dist };
              const depot = createEntity(EntityType.SUPPLY_DEPOT, aiOwner, buildPos);
              depot.constructionProgress = 0;
              entities.set(depot.id, depot);
          }
      }
  }

  // --- 3. BUILDINGS ---
  const desiredBarracks = (strategy === AIStrategy.RUSH) ? 4 : 3;
  if (barracks.length < desiredBarracks && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING');
      if (builder) {
           resources[aiOwner] -= 150;
           const basePos = bases[0]?.position || builder.position;
           const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };
           const b = createEntity(EntityType.BARRACKS, aiOwner, buildPos);
           b.constructionProgress = 0;
           entities.set(b.id, b);
      }
  }

  if (buildBunkers && bunkers.length < (bases.length * 2) && myMinerals >= 100 && barracks.length > 0) {
       const builder = workers.find(w => w.state === 'GATHERING');
       if (builder && bases.length > 0) {
           const base = bases[0];
           const center = { x: GAME_WIDTH/2, y: GAME_HEIGHT/2 };
           const angle = Math.atan2(center.y - base.position.y, center.x - base.position.x);
           const dist = 300;
           const buildPos = { x: base.position.x + Math.cos(angle)*dist + (Math.random()-0.5)*100, y: base.position.y + Math.sin(angle)*dist + (Math.random()-0.5)*100 };

           resources[aiOwner] -= 100;
           const bunk = createEntity(EntityType.BUNKER, aiOwner, buildPos);
           bunk.constructionProgress = 0;
           entities.set(bunk.id, bunk);
       }
  }

  // Garrison Bunkers (Turtle or defense)
  if (bunkers.length > 0 && army.length > 0) {
      bunkers.forEach(bunk => {
          if (bunk.hp > 0 && bunk.constructionProgress! >= 100 && (!bunk.garrison || bunk.garrison.length < 4)) {
              const marines = army.filter(u => u.type === EntityType.MARINE && u.state !== 'GARRISONED' && u.state !== 'ENTERING');
              let bestMarine: GameEntity | null = null;
              let bestDist = 500;
              marines.forEach(m => {
                  const d = getDistance(m.position, bunk.position);
                  if (d < bestDist) { bestDist = d; bestMarine = m; }
              });
              if (bestMarine) {
                  bestMarine.state = 'ENTERING';
                  bestMarine.targetId = bunk.id;
              }
          }
      });
  }

  // Expansion
  if (expand && bases.length < 3 && myMinerals >= 400) {
      let bestPatch: GameEntity | null = null;
      const minerals = Array.from(entities.values()).filter(e => e.type === EntityType.MINERAL);
      minerals.forEach(m => {
          let minDistToBase = Infinity;
          bases.forEach(b => {
             const d = getDistance(m.position, b.position);
             if (d < minDistToBase) minDistToBase = d;
          });
          if (minDistToBase > 800 && minDistToBase < 2000) {
              const nearbyBase = Array.from(entities.values()).find(e => e.type === EntityType.BASE && getDistance(e.position, m.position) < 300);
              if (!nearbyBase) bestPatch = m;
          }
      });

      if (bestPatch) {
          const builder = workers.find(w => w.state === 'GATHERING');
          if (builder) {
              resources[aiOwner] -= 400;
              const buildPos = { x: bestPatch.position.x + 100, y: bestPatch.position.y };
              const newBase = createEntity(EntityType.BASE, aiOwner, buildPos);
              newBase.constructionProgress = 0;
              entities.set(newBase.id, newBase);
              builder.position = { ...buildPos }; 
          }
      }
  }

  // --- 4. PRODUCTION ---
  if (barracks.length > 0 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if (b.constructionProgress! >= 100 && (!b.trainQueue || b.trainQueue.length < 5) && resources[aiOwner] >= 50) {
              let type = EntityType.MARINE;
              const medicCount = army.filter(u => u.type === EntityType.MEDIC).length;
              const marineCount = army.length - medicCount;
              const desiredMedicRatio = 0.25;

              if (marineCount > 2 && medicCount / (marineCount || 1) < desiredMedicRatio && resources[aiOwner] >= 75) {
                   type = EntityType.MEDIC;
              }
              if (resources[aiOwner] >= STATS[type].cost) {
                  if (!b.trainQueue) b.trainQueue = [];
                  b.trainQueue.push(type);
                  resources[aiOwner] -= STATS[type].cost;
              }
          }
      });
  }

  // --- 6. ARMY MOVEMENT ---
  if (underAttack && army.length > 0) {
      army.forEach(u => {
          if (u.state === 'GARRISONED') return;
          if (threatPos) {
              u.state = u.type === EntityType.MEDIC ? 'MOVING' : 'ATTACKING';
              u.targetPosition = threatPos;
          }
      });
      return;
  }

  if (army.length >= attackThreshold && state.gameTime > state.noRushFrames) {
      const enemyBase = Array.from(entities.values()).find(e => e.owner === playerOwner && e.type === EntityType.BASE);
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === playerOwner);
      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state === 'GARRISONED') return;
          if (unit.state === 'ATTACKING' && unit.targetId) return;

          if (unit.type === EntityType.MEDIC) {
               const buddy = army.find(a => a !== unit && a.type === EntityType.MARINE);
               if (buddy && getDistance(unit.position, buddy.position) > 100) {
                    unit.state = 'MOVING';
                    unit.targetPosition = buddy.position;
               } else {
                    unit.state = 'MOVING';
                    unit.targetPosition = targetPos;
               }
          } else {
               unit.state = 'ATTACKING';
               unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();
    const keysPressed = useRef<Set<string>>(new Set());

    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Keyboard Listeners
    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            keysPressed.current.add(e.code);
            if ((e.target as HTMLElement).tagName === 'INPUT') return;
            const key = e.key.toUpperCase();

            if (key === 'A') setCommandMode('ATTACK');
            if (key === 'P') { 
                if (stateRef.current) {
                    stateRef.current.paused = !stateRef.current.paused; 
                    onGameStateUpdate({...stateRef.current}); 
                }
            }

            if (stateRef.current) {
                // 1: Select Worker
                if (key === '1') {
                    const ents = Array.from(stateRef.current.entities.values()) as GameEntity[];
                    const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

                    let target = workers.find(w => w.state === 'IDLE');
                    if (!target) target = workers.find(w => w.state === 'GATHERING');
                    if (!target && workers.length > 0) target = workers[0];

                    if (target) {
                        stateRef.current.selection = [target.id];
                        onSelectionChange([target]);
                        playSound('click');
                    }
                }

                // 2: Select Army
                if (key === '2') {
                    const ents = Array.from(stateRef.current.entities.values()) as GameEntity[];
                    const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
                    if (army.length > 0) {
                        const ids = army.map(u => u.id);
                        stateRef.current.selection = ids;
                        onSelectionChange(army);
                        playSound('click');
                    }
                }

                // Space: Center Camera
                if (key === ' ') {
                    e.preventDefault();
                    if (stateRef.current.selection.length > 0) {
                        const id = stateRef.current.selection[0];
                        const ent = stateRef.current.entities.get(id);
                        if (ent && canvasRef.current) {
                            stateRef.current.camera.x = ent.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = ent.position.y - window.innerHeight / 2;
                        }
                    } else {
                        const base = Array.from(stateRef.current.entities.values()).find((e: GameEntity) => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                        if (base && canvasRef.current) {
                            stateRef.current.camera.x = base.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = base.position.y - window.innerHeight / 2;
                        }
                    }
                }
            }
        };

        const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);
        return () => { 
            window.removeEventListener('keydown', onKeyDown); 
            window.removeEventListener('keyup', onKeyUp); 
        };
    }, [setCommandMode, onSelectionChange, onGameStateUpdate]);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([] as GameEntity[]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Logic
        const panSpeed = 15;
        if (keysPressed.current.has('ArrowLeft')) stateRef.current.camera.x -= panSpeed;
        if (keysPressed.current.has('ArrowRight')) stateRef.current.camera.x += panSpeed;
        if (keysPressed.current.has('ArrowUp')) stateRef.current.camera.y -= panSpeed;
        if (keysPressed.current.has('ArrowDown')) stateRef.current.camera.y += panSpeed;

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = (Array.from(state.entities.values()) as GameEntity[]).sort((a: GameEntity, b: GameEntity) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 }
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); 
                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([] as GameEntity[]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; 
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; 
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach((ent: GameEntity) => {
                 if (ent.owner !== Owner.PLAYER) return; 
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 const allEnts = Array.from(stateRef.current.entities.values()) as GameEntity[];
                 allEnts.forEach((ent: GameEntity) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();
    const keysPressed = useRef<Set<string>>(new Set());

    // UI Layout Constants - Matches new Interface.tsx styling
    // Bottom panel height is approx 256px (h-64 in Tailwind)
    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Keyboard Listeners
    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            keysPressed.current.add(e.code);
            if ((e.target as HTMLElement).tagName === 'INPUT') return;
            const key = e.key.toUpperCase();

            if (key === 'A') setCommandMode('ATTACK');
            if (key === 'P') { 
                if (stateRef.current) {
                    stateRef.current.paused = !stateRef.current.paused; 
                    onGameStateUpdate({...stateRef.current}); 
                }
            }

            if (stateRef.current) {
                // 1: Select Worker
                if (key === '1') {
                    const ents = Array.from(stateRef.current.entities.values()) as GameEntity[];
                    const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

                    let target = workers.find(w => w.state === 'IDLE');
                    if (!target) target = workers.find(w => w.state === 'GATHERING');
                    if (!target && workers.length > 0) target = workers[0];

                    if (target) {
                        stateRef.current.selection = [target.id];
                        onSelectionChange([target]);
                        playSound('click');
                    }
                }

                // 2: Select Army
                if (key === '2') {
                    const ents = Array.from(stateRef.current.entities.values()) as GameEntity[];
                    const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
                    if (army.length > 0) {
                        const ids = army.map(u => u.id);
                        stateRef.current.selection = ids;
                        onSelectionChange(army);
                        playSound('click');
                    }
                }

                // Space: Center Camera
                if (key === ' ') {
                    e.preventDefault();
                    if (stateRef.current.selection.length > 0) {
                        const id = stateRef.current.selection[0];
                        const ent = stateRef.current.entities.get(id);
                        if (ent && canvasRef.current) {
                            stateRef.current.camera.x = ent.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = ent.position.y - window.innerHeight / 2;
                        }
                    } else {
                        const base = Array.from(stateRef.current.entities.values()).find((e: GameEntity) => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                        if (base && canvasRef.current) {
                            stateRef.current.camera.x = base.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = base.position.y - window.innerHeight / 2;
                        }
                    }
                }
            }
        };

        const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);
        return () => { 
            window.removeEventListener('keydown', onKeyDown); 
            window.removeEventListener('keyup', onKeyUp); 
        };
    }, [setCommandMode, onSelectionChange, onGameStateUpdate]);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([] as GameEntity[]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Logic
        const panSpeed = 15;
        if (keysPressed.current.has('ArrowLeft')) stateRef.current.camera.x -= panSpeed;
        if (keysPressed.current.has('ArrowRight')) stateRef.current.camera.x += panSpeed;
        if (keysPressed.current.has('ArrowUp')) stateRef.current.camera.y -= panSpeed;
        if (keysPressed.current.has('ArrowDown')) stateRef.current.camera.y += panSpeed;

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        // Ensure we can scroll enough to see bottom of map despite UI overlay
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = (Array.from(state.entities.values()) as GameEntity[]).sort((a: GameEntity, b: GameEntity) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or command-based spawning.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 // Camera handling with bounds check against map size + visual allowance
                 // This ensures the camera doesn't pan infinitely into void, but allows reaching edges
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); // Allow scrolling past for bottom UI

                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([] as GameEntity[]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach((ent: GameEntity) => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 const allEnts = Array.from(stateRef.current.entities.values()) as GameEntity[];
                 allEnts.forEach((ent: GameEntity) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push((found as GameEntity).id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

import { STATS, GAME_WIDTH, GAME_HEIGHT, GATHER_TIME, RESOURCE_GATHER_AMOUNT, FPS } from '../constants';
import { GameEntity, EntityType, GameState, Owner, Vector2, Effect, Difficulty, AIStrategy } from '../types';
import { SeededRandom } from './random';

let idCounter = 0;
export const generateId = (prefix: string = 'ent') => `${prefix}_${++idCounter}_${Math.floor(Math.random()*1000)}`;

export const addNotification = (state: GameState, text: string) => {
    state.notifications.push({
        id: `n_${Math.random()}`,
        text,
        life: 120
    });
};

export const createEntity = (type: EntityType, owner: Owner, pos: Vector2, id?: string): GameEntity => {
  const stats = STATS[type];
  const startRes = type === EntityType.MINERAL ? 1250 : 0; 

  return {
    id: id || generateId(),
    type,
    owner,
    position: { ...pos },
    radius: Math.max(stats.width, stats.height) / 2,
    hp: stats.hp,
    maxHp: stats.hp,
    targetId: null,
    targetPosition: null,
    state: 'IDLE',
    cooldown: 0,
    resourceAmount: startRes,
    trainQueue: [],
    trainProgress: 0,
    constructionProgress: (type === EntityType.MOUNTAIN || type === EntityType.WATER) ? 100 : 100,
    rallyPoint: null,
    rallyTargetId: null,
    lastAttackerId: null,
    garrison: [],
    containerId: null
  };
};

const getDistance = (p1: Vector2, p2: Vector2) => {
  return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
};

const findNearest = (pos: Vector2, entities: Map<string, GameEntity>, type?: EntityType, owner?: Owner) => {
  let nearest: GameEntity | null = null;
  let minDist = Infinity;
  entities.forEach(e => {
    if (e.state === 'GARRISONED') return;
    if (type && e.type !== type) return;
    if (owner && e.owner !== owner) return;
    const dist = getDistance(pos, e.position);
    if (dist < minDist) {
      minDist = dist;
      nearest = e;
    }
  });
  return nearest;
};

const getWorkerCountForMineral = (mineralId: string, entities: Map<string, GameEntity>) => {
    let count = 0;
    entities.forEach(e => {
        if (e.type === EntityType.WORKER && (e.state === 'GATHERING' || e.state === 'RETURNING') && e.targetId === mineralId) {
            count++;
        }
    });
    return count;
};

const isBio = (type: EntityType) => type === EntityType.WORKER || type === EntityType.MARINE || type === EntityType.MEDIC;
const isBuilding = (type: EntityType) => type === EntityType.BASE || type === EntityType.BARRACKS || type === EntityType.SUPPLY_DEPOT || type === EntityType.BUNKER;

export const initGame = (difficulty: Difficulty = Difficulty.MEDIUM, isMultiplayer = false, seed = Math.random() * 10000, isHost = true, noRushSeconds = 0): GameState => {
  const entities = new Map<string, GameEntity>();
  const effects: Effect[] = [];
  const add = (e: GameEntity) => entities.set(e.id, e);
  const rng = new SeededRandom(seed);

  const corners = [
      { x: 150, y: 150 }, 
      { x: GAME_WIDTH - 150, y: 150 }, 
      { x: 150, y: GAME_HEIGHT - 150 }, 
      { x: GAME_WIDTH - 150, y: GAME_HEIGHT - 150 } 
  ];

  for (let i = corners.length - 1; i > 0; i--) {
        const j = Math.floor(rng.next() * (i + 1));
        [corners[i], corners[j]] = [corners[j], corners[i]];
  }

  let myBasePos = corners[0];
  let opBasePos = corners[1];

  if (isMultiplayer && !isHost) {
      myBasePos = corners[1];
      opBasePos = corners[0];
  }

  const jitter = (pt: Vector2) => ({
      x: pt.x + (rng.next() - 0.5) * 50,
      y: pt.y + (rng.next() - 0.5) * 50
  });

  myBasePos = jitter(myBasePos);
  opBasePos = jitter(opBasePos);

  const strategies = [AIStrategy.RUSH, AIStrategy.MACRO, AIStrategy.TURTLE];
  const aiStrategy = strategies[Math.floor(rng.next() * strategies.length)];

  const generateCluster = (type: EntityType, count: number, centerX: number, centerY: number, spread: number) => {
      for(let i=0; i<count; i++) {
          const angle = rng.next() * Math.PI * 2;
          const dist = rng.next() * spread;
          const x = centerX + Math.cos(angle) * dist;
          const y = centerY + Math.sin(angle) * dist;
          if (getDistance({x,y}, myBasePos) < 400) continue;
          if (getDistance({x,y}, opBasePos) < 400) continue;
          if (x < 50 || x > GAME_WIDTH-50 || y < 50 || y > GAME_HEIGHT-50) continue;
          add(createEntity(type, Owner.NEUTRAL, {x, y}));
      }
  };

  for(let i=0; i<15; i++) {
      generateCluster(EntityType.MOUNTAIN, 5, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 150);
  }
  for(let i=0; i<8; i++) {
      generateCluster(EntityType.WATER, 4, rng.range(0, GAME_WIDTH), rng.range(0, GAME_HEIGHT), 120);
  }

  const possibleExpansions = [2, 4, 6, 8];
  const numExpansions = possibleExpansions[Math.floor(rng.next() * possibleExpansions.length)];
  for(let i=0; i<numExpansions; i++) {
      let exX = rng.range(150, GAME_WIDTH - 300);
      let exY = rng.range(150, GAME_HEIGHT - 300);
      let safe = false;
      let attempts = 0;
      while (!safe && attempts < 10) {
          if (getDistance({x:exX, y:exY}, myBasePos) > 700 && getDistance({x:exX, y:exY}, opBasePos) > 700) safe = true;
          else { exX = rng.range(150, GAME_WIDTH - 300); exY = rng.range(150, GAME_HEIGHT - 300); }
          attempts++;
      }
      generateCluster(EntityType.MINERAL, 7, exX, exY, 70);
  }

  const spawnBase = (pos: Vector2, owner: Owner) => {
      const centerAngle = Math.atan2((GAME_HEIGHT/2) - pos.y, (GAME_WIDTH/2) - pos.x);
      for (let i = 0; i < 8; i++) {
        const angle = centerAngle - (Math.PI/2) + (i / 7) * Math.PI; 
        add(createEntity(EntityType.MINERAL, Owner.NEUTRAL, { x: pos.x + 220 * Math.cos(angle), y: pos.y + 220 * Math.sin(angle) }));
      }
      const base = createEntity(EntityType.BASE, owner, pos);
      add(base);
      for (let i = 0; i < 4; i++) {
        const worker = createEntity(EntityType.WORKER, owner, { x: pos.x + (rng.next()-0.5)*50, y: pos.y + (rng.next()-0.5)*50 });
        add(worker);
        const mineral = findNearest(worker.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
        if (mineral) { worker.state = 'GATHERING'; worker.targetId = mineral.id; }
      }
      const nearestMineral = findNearest(base.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
      if (nearestMineral) { base.rallyPoint = nearestMineral.position; base.rallyTargetId = nearestMineral.id; }
  };

  spawnBase(myBasePos, Owner.PLAYER);
  const opponentOwner = isMultiplayer ? Owner.OPPONENT : Owner.AI;
  spawnBase(opBasePos, opponentOwner);

  const startCameraY = Math.max(0, myBasePos.y - (typeof window !== 'undefined' ? window.innerHeight / 2 : 400));
  const startCameraX = Math.max(0, myBasePos.x - (typeof window !== 'undefined' ? window.innerWidth / 2 : 400));

  return {
    entities,
    effects,
    markers: [],
    notifications: [],
    soundEvents: [],
    resources: { [Owner.PLAYER]: 50, [Owner.AI]: 50, [Owner.OPPONENT]: 50 },
    supply: { [Owner.PLAYER]: { used: 4, max: 10 }, [Owner.AI]: { used: 4, max: 10 }, [Owner.OPPONENT]: { used: 4, max: 10 } },
    selection: [],
    camera: { x: startCameraX, y: startCameraY },
    gameTime: 0,
    noRushFrames: noRushSeconds * FPS,
    difficulty,
    aiStrategy,
    victory: undefined,
    paused: false,
    isMultiplayer
  };
};

const resolveCollisions = (entity: GameEntity, entities: Map<string, GameEntity>) => {
  if (entity.state === 'BUILDING' || entity.state === 'GARRISONED') return; 
  if (STATS[entity.type].speed === 0) return; 

  entities.forEach(other => {
    if (entity.id === other.id) return;
    if (other.state === 'GARRISONED') return;

    const isStatic = STATS[other.type].speed === 0;
    const dist = getDistance(entity.position, other.position);
    const combinedRadius = entity.radius + other.radius;
    const separationRadius = combinedRadius + 5; 

    if (dist < separationRadius && dist > 0) {
      const pushStrength = (separationRadius - dist) / separationRadius;
      const angle = Math.atan2(entity.position.y - other.position.y, entity.position.x - other.position.x);
      const force = dist < combinedRadius ? 2.0 : 0.5;
      const staticMult = isStatic ? 2.0 : 1.0; 
      entity.position.x += Math.cos(angle) * pushStrength * force * staticMult; 
      entity.position.y += Math.sin(angle) * pushStrength * force * staticMult;
    }
  });
};

const acquireTarget = (entity: GameEntity, entities: Map<string, GameEntity>, gameTime: number, noRushFrames: number) => {
    const stats = STATS[entity.type];
    let bestTarget: GameEntity | null = null;
    let bestScore = -Infinity;
    const searchRange = Math.max(stats.vision, stats.range + 300); // Increased acquisition range

    entities.forEach(e => {
        if (e.state === 'GARRISONED') return;

        // No Rush Check
        if (noRushFrames > 0 && gameTime < noRushFrames) {
            if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL) return;
        }

        if (e.owner !== entity.owner && e.owner !== Owner.NEUTRAL && e.hp > 0 && e.type !== EntityType.MOUNTAIN && e.type !== EntityType.WATER) {
            const d = getDistance(entity.position, e.position);
            if (d < searchRange) {
                let score = 0;
                if (e.targetId === entity.id) score += 5000;
                if (!isBuilding(e.type)) score += 1000;
                else score += 100; 
                score -= d;

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = e;
                }
            }
        }
    });
    return bestTarget;
};

export const updateGame = (state: GameState): GameState => {
  const { entities, resources, supply } = state;
  let newEntities = new Map(entities);
  let newEffects = [...state.effects];
  let newMarkers = [...state.markers];
  let newNotifications = [...state.notifications];
  const soundEvents: string[] = [];

  supply[Owner.PLAYER] = { used: 0, max: 0 };
  supply[Owner.AI] = { used: 0, max: 0 };
  supply[Owner.OPPONENT] = { used: 0, max: 0 };

  entities.forEach(ent => {
    if (ent.owner === Owner.NEUTRAL) return;
    if (ent.constructionProgress! >= 100) {
        supply[ent.owner].max += STATS[ent.type].supplyProvided;
    }
    supply[ent.owner].used += STATS[ent.type].supplyCost;
  });

  supply[Owner.PLAYER].max = Math.min(supply[Owner.PLAYER].max, 200);
  supply[Owner.AI].max = Math.min(supply[Owner.AI].max, 200);
  supply[Owner.OPPONENT].max = Math.min(supply[Owner.OPPONENT].max, 200);

  entities.forEach(entity => {
    if (entity.type === EntityType.MOUNTAIN || entity.type === EntityType.WATER) return; 
    if (entity.state === 'GARRISONED') return; 

    // Construction
    if (entity.constructionProgress! < 100) {
       entity.constructionProgress! += (100 / STATS[entity.type].buildTime);
       if (entity.constructionProgress! >= 100) entity.constructionProgress = 100;
       return; 
    }

    // Production
    if (entity.trainQueue && entity.trainQueue.length > 0) {
       entity.trainProgress!++;
       const unitType = entity.trainQueue[0];
       if (entity.trainProgress! >= STATS[unitType].buildTime) {
          const stats = STATS[unitType];
          if (supply[entity.owner].used + stats.supplyCost <= supply[entity.owner].max) {
             const spawnDir = entity.owner === Owner.PLAYER ? -1 : 1;
             const offset = 80; 
             const newUnit = createEntity(unitType, entity.owner, { 
                x: entity.position.x + (Math.random() * 40 - 20), 
                y: entity.position.y + (offset * spawnDir) + (Math.random() * 10) 
             });

             if (entity.rallyPoint) {
                 if (newUnit.type === EntityType.WORKER && entity.rallyTargetId) {
                     const target = entities.get(entity.rallyTargetId);
                     if (target && target.type === EntityType.MINERAL) {
                         newUnit.state = 'GATHERING';
                         newUnit.targetId = target.id;
                         newUnit.targetPosition = null;
                     } else {
                         newUnit.state = 'MOVING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 } else {
                     newUnit.state = 'MOVING'; 
                     newUnit.targetPosition = { ...entity.rallyPoint };
                     if (entity.rallyTargetId) {
                         const target = entities.get(entity.rallyTargetId);
                         if (target && target.owner !== entity.owner) {
                             newUnit.state = 'ATTACKING';
                             newUnit.targetId = target.id;
                         }
                     } else if (unitType === EntityType.MARINE) {
                         // Attack move towards rally
                         newUnit.state = 'ATTACKING';
                         newUnit.targetPosition = { ...entity.rallyPoint };
                     }
                 }
             }

             newEntities.set(newUnit.id, newUnit);
             entity.trainQueue.shift();
             entity.trainProgress = 0;
          } else {
             entity.trainProgress = STATS[unitType].buildTime - 1; 
          }
       }
    }

    const stats = STATS[entity.type];

    // Bunker Logic
    if (entity.type === EntityType.BUNKER) {
        if (entity.garrison && entity.garrison.length > 0) {
            let target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp <= 0 || getDistance(entity.position, target.position) > stats.range) {
                target = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
                entity.targetId = target ? target.id : null;
            }
            if (target) {
                const dist = getDistance(entity.position, target.position);
                if (dist <= stats.range) {
                    if (entity.cooldown <= 0) {
                        const marineStats = STATS[EntityType.MARINE];
                        target.hp -= marineStats.damage;
                        entity.cooldown = Math.max(5, 30 / entity.garrison.length);
                        if (target.hp <= 0) entity.targetId = null;
                        soundEvents.push('shoot');
                    }
                }
            }
        }
    }

    // Medic Logic
    if (entity.type === EntityType.MEDIC) {
        if (['IDLE', 'MOVING', 'ATTACKING'].includes(entity.state)) {
            let healTarget: GameEntity | null = null;
            let bestHealDist = stats.vision;
            entities.forEach(e => {
                if (e.owner === entity.owner && isBio(e.type) && e.hp < e.maxHp && e.state !== 'GARRISONED') {
                    const d = getDistance(entity.position, e.position);
                    if (d < bestHealDist) { bestHealDist = d; healTarget = e; }
                }
            });
            if (healTarget) {
                const d = getDistance(entity.position, healTarget.position);
                if (d <= stats.range) {
                    entity.state = 'HEALING';
                    entity.targetId = healTarget.id;
                    entity.targetPosition = null; 
                } else {
                    const angle = Math.atan2(healTarget.position.y - entity.position.y, healTarget.position.x - entity.position.x);
                    entity.position.x += Math.cos(angle) * stats.speed;
                    entity.position.y += Math.sin(angle) * stats.speed;
                }
            }
        }
        if (entity.state === 'HEALING') {
            const target = entity.targetId ? entities.get(entity.targetId) : null;
            if (!target || target.hp >= target.maxHp || getDistance(entity.position, target.position) > stats.range + 20) {
                 entity.state = 'IDLE';
                 entity.targetId = null;
            } else {
                 if (entity.cooldown <= 0) {
                     target.hp = Math.min(target.maxHp, target.hp + (stats.healRate || 5));
                     entity.cooldown = stats.attackSpeed;
                     newEffects.push({ id: `fx_${Math.random()}`, type: 'HEAL', position: { ...target.position }, life: 20, maxLife: 20, scale: 1 });
                 }
            }
        }
    }

    if (entity.state === 'ENTERING' && entity.targetId) {
        const bunker = entities.get(entity.targetId);
        if (bunker && bunker.type === EntityType.BUNKER && bunker.hp > 0 && bunker.owner === entity.owner && bunker.constructionProgress! >= 100) {
             const dist = getDistance(entity.position, bunker.position);
             if (dist < bunker.radius + entity.radius + 10) {
                 if (!bunker.garrison) bunker.garrison = [];
                 if (bunker.garrison.length < 4) {
                     bunker.garrison.push(entity.id);
                     entity.state = 'GARRISONED';
                     entity.containerId = bunker.id;
                     entity.targetId = null;
                     entity.targetPosition = null;
                     soundEvents.push('click'); 
                 } else { entity.state = 'IDLE'; }
             } else {
                 const angle = Math.atan2(bunker.position.y - entity.position.y, bunker.position.x - entity.position.x);
                 entity.position.x += Math.cos(angle) * stats.speed;
                 entity.position.y += Math.sin(angle) * stats.speed;
             }
        } else { entity.state = 'IDLE'; }
    }

    // Auto-Acquire Targets when IDLE
    if (entity.state === 'IDLE' && entity.type !== EntityType.MEDIC && entity.type !== EntityType.WORKER && stats.damage > 0) {
        const target = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
        if (target) {
            entity.targetId = target.id;
            entity.state = 'ATTACKING';
        }
    }

    if (entity.state === 'MOVING' && entity.targetPosition) {
        const dist = getDistance(entity.position, entity.targetPosition);
        if (dist < 10) {
            entity.state = 'IDLE';
            entity.targetPosition = null;
        } else {
            const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
            entity.position.x += Math.cos(angle) * stats.speed;
            entity.position.y += Math.sin(angle) * stats.speed;
        }
    }

    // ATTACK Logic
    if (entity.state === 'ATTACKING') {
        let target = entity.targetId ? entities.get(entity.targetId) : null;

        // Retaliation Logic
        if (entity.lastAttackerId) {
            const attacker = entities.get(entity.lastAttackerId);
            if (attacker && attacker.hp > 0 && attacker.owner !== entity.owner && attacker.state !== 'GARRISONED') {
                if (!target || isBuilding(target.type) || target.owner === Owner.NEUTRAL) {
                    entity.targetId = attacker.id;
                    target = attacker;
                    entity.targetPosition = null; // Switch to direct attack
                }
            }
            if (state.gameTime % 20 === 0) entity.lastAttackerId = null;
        }

        // If no target, try to find one
        if (!target || target.hp <= 0 || target.state === 'GARRISONED') {
           entity.targetId = null;
           target = null;

           if (stats.damage > 0) {
                const newTarget = acquireTarget(entity, entities, state.gameTime, state.noRushFrames);
                if (newTarget) {
                    entity.targetId = newTarget.id;
                    entity.targetPosition = null; // Important: Stop "Attack Move" to ground, focus on target
                    target = newTarget; // Process immediately below
                }
           }

           if (!target && entity.targetPosition) {
                // Continue moving to Attack Move destination
                const dist = getDistance(entity.position, entity.targetPosition);
                if (dist < 10) {
                    entity.state = 'IDLE';
                    entity.targetPosition = null;
                } else {
                    const angle = Math.atan2(entity.targetPosition.y - entity.position.y, entity.targetPosition.x - entity.position.x);
                    entity.position.x += Math.cos(angle) * stats.speed;
                    entity.position.y += Math.sin(angle) * stats.speed;
                }
           } else if (!target) {
             entity.state = 'IDLE';
           }
        } 

        // Attack Target
        if (target) {
           const dist = getDistance(entity.position, target.position);
           const rangeBuffer = target.radius; 

           if (dist <= stats.range + rangeBuffer) {
              if (entity.cooldown <= 0) {
                  target.hp -= stats.damage;
                  target.lastAttackerId = entity.id; 
                  entity.cooldown = stats.attackSpeed;
                  soundEvents.push('shoot');

                  if (target.state === 'IDLE' && STATS[target.type].damage > 0 && target.owner !== Owner.NEUTRAL) {
                      target.targetId = entity.id;
                      target.state = 'ATTACKING';
                  }
              }
           } else {
              const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
              entity.position.x += Math.cos(angle) * stats.speed;
              entity.position.y += Math.sin(angle) * stats.speed;
           }
        }
    }

    if (entity.state === 'GATHERING') {
         const target = entity.targetId ? entities.get(entity.targetId) : null;
        if (!target || target.resourceAmount! <= 0) {
            let newRes: GameEntity | null = null;
            let minDist = Infinity;
            entities.forEach(e => {
                if (e.type === EntityType.MINERAL && e.resourceAmount! > 0) {
                     const dist = getDistance(entity.position, e.position);
                     if (dist < minDist && getWorkerCountForMineral(e.id, entities) < 3) {
                         minDist = dist;
                         newRes = e;
                     }
                }
            });
            if (newRes) entity.targetId = (newRes as GameEntity).id;
            else entity.state = 'IDLE';
        } else {
            if (state.gameTime % 60 === 0 && getWorkerCountForMineral(target.id, entities) > 3) {
                 const better = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                 if (better && better.id !== target.id && getWorkerCountForMineral(better.id, entities) < 3) {
                     entity.targetId = better.id;
                     return;
                 }
            }
            const dist = getDistance(entity.position, target.position);
            const reach = entity.radius + target.radius + 15; 
            if (dist <= reach) {
                entity.cooldown++; 
                if (entity.cooldown >= GATHER_TIME) {
                    entity.resourceAmount = (entity.resourceAmount || 0) + RESOURCE_GATHER_AMOUNT;
                    target.resourceAmount! -= RESOURCE_GATHER_AMOUNT;
                    if (target.resourceAmount! <= 0) newEntities.delete(target.id);
                    entity.state = 'RETURNING';
                    entity.cooldown = 0;
                    const base = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
                    if (base) entity.targetId = base.id;
                }
            } else {
                const angle = Math.atan2(target.position.y - entity.position.y, target.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.state === 'RETURNING') {
        const base = entity.targetId ? entities.get(entity.targetId) : null;
        if (!base || base.hp <= 0) {
             const newBase = findNearest(entity.position, entities, EntityType.BASE, entity.owner);
             if (newBase) entity.targetId = newBase.id;
             else entity.state = 'IDLE'; 
        } else {
            const dist = getDistance(entity.position, base.position);
            const reach = base.radius + entity.radius + 15;
            if (dist <= reach) {
                resources[entity.owner] += entity.resourceAmount || 0;
                entity.resourceAmount = 0;
                entity.state = 'GATHERING';
                const mineral = findNearest(entity.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
                entity.targetId = mineral ? mineral.id : null;
            } else {
                const angle = Math.atan2(base.position.y - entity.position.y, base.position.x - entity.position.x);
                entity.position.x += Math.cos(angle) * stats.speed;
                entity.position.y += Math.sin(angle) * stats.speed;
            }
        }
    }

    if (entity.cooldown > 0 && entity.state !== 'GATHERING') entity.cooldown--;

    if (entity.hp <= 0) {
        let effectType: Effect['type'] = 'EXPLOSION';
        let effectScale = entity.radius / 10;
        if (isBio(entity.type)) effectType = 'BLOOD';
        else if (isBuilding(entity.type)) { effectType = 'BUILDING_EXPLOSION'; effectScale = 2.0; }

        newEffects.push({
            id: `fx_${Math.random()}`,
            type: effectType,
            position: { ...entity.position },
            life: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            maxLife: effectType === 'BUILDING_EXPLOSION' ? 60 : 30,
            scale: effectScale
        });
        soundEvents.push('explosion');
        if (entity.garrison) {
            entity.garrison.forEach(id => {
                const unit = newEntities.get(id);
                if (unit) {
                    unit.state = 'IDLE';
                    unit.containerId = null;
                    unit.position = { x: entity.position.x + (Math.random() * 40 - 20), y: entity.position.y + (Math.random() * 40 - 20) };
                }
            });
        }
        newEntities.delete(entity.id);
    }
    resolveCollisions(entity, entities);
  });

  newEffects = newEffects.filter(fx => { fx.life--; return fx.life > 0; });
  newMarkers = newMarkers.filter(mk => { mk.life--; return mk.life > 0; });
  newNotifications = newNotifications.filter(n => { n.life--; return n.life > 0; });

  if (!state.isMultiplayer && state.gameTime % 30 === 0) runAI(state, newEntities, resources, supply);

  let playerBuildings = 0;
  let opponentBuildings = 0;
  newEntities.forEach(e => {
      if (e.owner === Owner.PLAYER && isBuilding(e.type)) playerBuildings++;
      if ((e.owner === Owner.AI || e.owner === Owner.OPPONENT) && isBuilding(e.type)) opponentBuildings++;
  });

  let victory = undefined;
  if (playerBuildings === 0 && newEntities.size > 0) victory = state.isMultiplayer ? Owner.OPPONENT : Owner.AI; 
  if (opponentBuildings === 0 && newEntities.size > 0) victory = Owner.PLAYER;

  return {
    ...state,
    entities: newEntities,
    effects: newEffects,
    markers: newMarkers,
    notifications: newNotifications,
    soundEvents,
    gameTime: state.gameTime + 1,
    victory,
    difficulty: state.difficulty,
    paused: state.paused
  };
};

const runAI = (state: GameState, entities: Map<string, GameEntity>, resources: any, supply: any) => {
  const aiOwner = Owner.AI;
  const playerOwner = Owner.PLAYER;

  const myUnits = Array.from(entities.values()).filter(e => e.owner === aiOwner);
  const workers = myUnits.filter(e => e.type === EntityType.WORKER);
  const bases = myUnits.filter(e => e.type === EntityType.BASE);
  const barracks = myUnits.filter(e => e.type === EntityType.BARRACKS);
  const bunkers = myUnits.filter(e => e.type === EntityType.BUNKER);
  const army = myUnits.filter(e => e.type === EntityType.MARINE || e.type === EntityType.MEDIC);
  const depots = myUnits.filter(e => e.type === EntityType.SUPPLY_DEPOT);

  const myMinerals = resources[aiOwner];
  const mySupply = supply[aiOwner];
  const strategy = state.aiStrategy;

  let maxWorkers = 12;
  let attackThreshold = 12;
  let expand = false;
  let buildBunkers = false;

  if (strategy === AIStrategy.RUSH) { maxWorkers = 10; attackThreshold = 8; } 
  else if (strategy === AIStrategy.MACRO) { maxWorkers = 20; attackThreshold = 25; expand = true; } 
  else if (strategy === AIStrategy.TURTLE) { maxWorkers = 14; attackThreshold = 30; buildBunkers = true; }

  if (state.difficulty === Difficulty.EASY) { maxWorkers = Math.min(maxWorkers, 10); attackThreshold = Math.max(attackThreshold, 15); } 
  else if (state.difficulty === Difficulty.HARD) { maxWorkers = Math.max(maxWorkers, 16); }

  let underAttack = false;
  let threatPos: Vector2 | null = null;

  if (bases.length > 0) {
      const mainBase = bases[0];
      const enemies = Array.from(entities.values()).filter(e => e.owner === playerOwner);
      const nearestEnemy = enemies.find(e => getDistance(e.position, mainBase.position) < 800);
      if (nearestEnemy) { underAttack = true; threatPos = nearestEnemy.position; }
  }

  if (underAttack && army.length === 0 && state.difficulty === Difficulty.HARD) {
       workers.slice(0, 5).forEach(w => { if (w.state !== 'ATTACKING') { w.state = 'ATTACKING'; w.targetPosition = threatPos; } });
  }

  if (workers.length < maxWorkers && bases.length > 0 && myMinerals >= 50 && mySupply.used < mySupply.max) {
      const base = bases.sort((a,b) => (a.trainQueue?.length || 0) - (b.trainQueue?.length || 0))[0];
      if (base && (!base.trainQueue || base.trainQueue.length < 1)) {
          if (!base.trainQueue) base.trainQueue = [];
          base.trainQueue.push(EntityType.WORKER);
          resources[aiOwner] -= 50;
      }
  }

  workers.forEach(w => {
      if (w.state === 'ATTACKING' && !underAttack) w.state = 'IDLE';
      if (w.state === 'IDLE') {
          const m = findNearest(w.position, entities, EntityType.MINERAL, Owner.NEUTRAL);
          if (m) { w.targetId = m.id; w.state = 'GATHERING'; }
      }
  });

  if (mySupply.max - mySupply.used <= 3 && myMinerals >= 100 && depots.length < 10) {
      const construction = myUnits.find(u => u.type === EntityType.SUPPLY_DEPOT && u.constructionProgress! < 100);
      if (!construction) {
          const builder = workers.find(w => w.state === 'GATHERING' || w.state === 'IDLE');
          if (builder) {
              resources[aiOwner] -= 100;
              const basePos = bases[0]?.position || builder.position;
              const angle = Math.random() * Math.PI * 2;
              const dist = 100 + Math.random() * 100;
              const buildPos = { x: basePos.x + Math.cos(angle)*dist, y: basePos.y + Math.sin(angle)*dist };
              const depot = createEntity(EntityType.SUPPLY_DEPOT, aiOwner, buildPos);
              depot.constructionProgress = 0;
              entities.set(depot.id, depot);
          }
      }
  }

  const desiredBarracks = (strategy === AIStrategy.RUSH) ? 4 : 3;
  if (barracks.length < desiredBarracks && myMinerals >= 150) {
      const builder = workers.find(w => w.state === 'GATHERING');
      if (builder) {
           resources[aiOwner] -= 150;
           const basePos = bases[0]?.position || builder.position;
           const buildPos = { x: basePos.x + (Math.random() - 0.5) * 300, y: basePos.y + (Math.random() - 0.5) * 300 };
           const b = createEntity(EntityType.BARRACKS, aiOwner, buildPos);
           b.constructionProgress = 0;
           entities.set(b.id, b);
      }
  }

  if (buildBunkers && bunkers.length < (bases.length * 2) && myMinerals >= 100 && barracks.length > 0) {
       const builder = workers.find(w => w.state === 'GATHERING');
       if (builder && bases.length > 0) {
           const base = bases[0];
           const center = { x: GAME_WIDTH/2, y: GAME_HEIGHT/2 };
           const angle = Math.atan2(center.y - base.position.y, center.x - base.position.x);
           const dist = 300;
           const buildPos = { x: base.position.x + Math.cos(angle)*dist + (Math.random()-0.5)*100, y: base.position.y + Math.sin(angle)*dist + (Math.random()-0.5)*100 };
           resources[aiOwner] -= 100;
           const bunk = createEntity(EntityType.BUNKER, aiOwner, buildPos);
           bunk.constructionProgress = 0;
           entities.set(bunk.id, bunk);
       }
  }

  if (bunkers.length > 0 && army.length > 0) {
      bunkers.forEach(bunk => {
          if (bunk.hp > 0 && bunk.constructionProgress! >= 100 && (!bunk.garrison || bunk.garrison.length < 4)) {
              const marines = army.filter(u => u.type === EntityType.MARINE && u.state !== 'GARRISONED' && u.state !== 'ENTERING');
              let bestMarine: GameEntity | null = null;
              let bestDist = 500;
              marines.forEach(m => {
                  const d = getDistance(m.position, bunk.position);
                  if (d < bestDist) { bestDist = d; bestMarine = m; }
              });
              if (bestMarine) { bestMarine.state = 'ENTERING'; bestMarine.targetId = bunk.id; }
          }
      });
  }

  if (expand && bases.length < 3 && myMinerals >= 400) {
      let bestPatch: GameEntity | null = null;
      const minerals = Array.from(entities.values()).filter(e => e.type === EntityType.MINERAL);
      minerals.forEach(m => {
          let minDistToBase = Infinity;
          bases.forEach(b => {
             const d = getDistance(m.position, b.position);
             if (d < minDistToBase) minDistToBase = d;
          });
          if (minDistToBase > 800 && minDistToBase < 2000) {
              const nearbyBase = Array.from(entities.values()).find(e => e.type === EntityType.BASE && getDistance(e.position, m.position) < 300);
              if (!nearbyBase) bestPatch = m;
          }
      });

      if (bestPatch) {
          const builder = workers.find(w => w.state === 'GATHERING');
          if (builder) {
              resources[aiOwner] -= 400;
              const buildPos = { x: bestPatch.position.x + 100, y: bestPatch.position.y };
              const newBase = createEntity(EntityType.BASE, aiOwner, buildPos);
              newBase.constructionProgress = 0;
              entities.set(newBase.id, newBase);
              builder.position = { ...buildPos }; 
          }
      }
  }

  if (barracks.length > 0 && mySupply.used < mySupply.max) {
      barracks.forEach(b => {
          if (b.constructionProgress! >= 100 && (!b.trainQueue || b.trainQueue.length < 5) && resources[aiOwner] >= 50) {
              let type = EntityType.MARINE;
              const medicCount = army.filter(u => u.type === EntityType.MEDIC).length;
              const marineCount = army.length - medicCount;
              const desiredMedicRatio = 0.25;
              if (marineCount > 2 && medicCount / (marineCount || 1) < desiredMedicRatio && resources[aiOwner] >= 75) type = EntityType.MEDIC;
              if (resources[aiOwner] >= STATS[type].cost) {
                  if (!b.trainQueue) b.trainQueue = [];
                  b.trainQueue.push(type);
                  resources[aiOwner] -= STATS[type].cost;
              }
          }
      });
  }

  if (underAttack && army.length > 0) {
      army.forEach(u => {
          if (u.state === 'GARRISONED') return;
          if (threatPos) { u.state = u.type === EntityType.MEDIC ? 'MOVING' : 'ATTACKING'; u.targetPosition = threatPos; }
      });
      return;
  }

  if (army.length >= attackThreshold) {
      // Rush Check in AI logic as well (mostly defensive during rush)
      if (state.noRushFrames > 0 && state.gameTime < state.noRushFrames) return;

      const enemyBase = Array.from(entities.values()).find(e => e.owner === playerOwner && e.type === EntityType.BASE);
      const anyEnemy = Array.from(entities.values()).find(e => e.owner === playerOwner);
      const targetPos = enemyBase ? enemyBase.position : (anyEnemy ? anyEnemy.position : { x: 200, y: 1800 });

      army.forEach(unit => {
          if (unit.state === 'GARRISONED') return;
          if (unit.state === 'ATTACKING' && unit.targetId) return;

          if (unit.type === EntityType.MEDIC) {
               const buddy = army.find(a => a !== unit && a.type === EntityType.MARINE);
               if (buddy && getDistance(unit.position, buddy.position) > 100) {
                    unit.state = 'MOVING';
                    unit.targetPosition = buddy.position;
               } else {
                    unit.state = 'MOVING';
                    unit.targetPosition = targetPos;
               }
          } else {
               unit.state = 'ATTACKING';
               unit.targetPosition = targetPos;
          }
      });
  }
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameState, GameEntity, EntityType, Owner, Vector2, Marker, Difficulty, NetMessage } from '../types';
import { STATS, GAME_WIDTH, GAME_HEIGHT, UI_TOP_HEIGHT } from '../constants';
import { updateGame, initGame, createEntity, addNotification } from '../services/gameLogic';
import { playSound } from '../services/audio';
import { network } from '../services/network';

interface Props {
  onGameStateUpdate: (state: GameState) => void;
  onSelectionChange: (selected: GameEntity[]) => void;
  commandMode: string | null;
  setCommandMode: (mode: string | null) => void;
  isMultiplayer?: boolean;
  gameSeed?: number;
  isHost?: boolean;
  difficulty?: Difficulty;
  noRushSeconds?: number;
}

// Generate terrain texture once
const renderTerrain = () => {
    const canvas = document.createElement('canvas');
    canvas.width = GAME_WIDTH;
    canvas.height = GAME_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    // 1. Base Ground
    ctx.fillStyle = '#1c1917'; // Dark stone/dirt
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    // 2. Noise/Dust
    for (let i = 0; i < 40000; i++) {
        const x = Math.random() * GAME_WIDTH;
        const y = Math.random() * GAME_HEIGHT;
        const s = Math.random() * 3 + 1;
        ctx.fillStyle = Math.random() > 0.5 ? '#292524' : '#0c0a09';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x, y, s, s);
    }

    // 3. Subtle Grid Overlay
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.1;
    for (let x = 0; x <= GAME_WIDTH; x += 100) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, GAME_HEIGHT); ctx.stroke();
    }
    for (let y = 0; y <= GAME_HEIGHT; y += 100) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(GAME_WIDTH, y); ctx.stroke();
    }

    // 4. Craters / Details
    ctx.globalAlpha = 0.2;
    for (let i = 0; i < 50; i++) {
        const cx = Math.random() * GAME_WIDTH;
        const cy = Math.random() * GAME_HEIGHT;
        const r = Math.random() * 50 + 20;
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#444'; // Highlight edge
        ctx.beginPath();
        ctx.arc(cx + 2, cy + 2, r * 0.9, 0, Math.PI * 2);
        ctx.fill();
    }

    return canvas;
};

const isEntityVisible = (entity: GameEntity, playerUnits: GameEntity[]) => {
    if (entity.owner === Owner.PLAYER) return true;
    return true; 
};

const drawUnit = (ctx: CanvasRenderingContext2D, entity: GameEntity, isSelected: boolean) => {
    ctx.save();
    ctx.translate(entity.position.x, entity.position.y);

    const isPlayer = entity.owner === Owner.PLAYER;
    const isEnemy = entity.owner === Owner.AI || entity.owner === Owner.OPPONENT;
    const primaryColor = isPlayer ? '#3b82f6' : (isEnemy ? '#ef4444' : '#9ca3af'); // Blue : Red : Gray

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    ctx.beginPath();
    ctx.ellipse(3, 3, entity.radius, entity.radius * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Construction Scaffold
    if (entity.constructionProgress !== undefined && entity.constructionProgress < 100) {
        ctx.globalAlpha = 0.6;
        ctx.strokeStyle = '#fbbf24';
        ctx.setLineDash([4, 2]);
        ctx.strokeRect(-entity.radius, -entity.radius, entity.radius*2, entity.radius*2);
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Progress bar for construction
        ctx.fillStyle = '#000';
        ctx.fillRect(-15, -10, 30, 4);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(-15, -10, 30 * (entity.constructionProgress / 100), 4);
    } else {
        // Normal Rendering
        if (entity.type === EntityType.WORKER) {
            // Body
            const grad = ctx.createRadialGradient(-2, -2, 1, 0, 0, 8);
            grad.addColorStop(0, '#e5e7eb');
            grad.addColorStop(1, '#9ca3af');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
            // Team indicator
            ctx.fillStyle = primaryColor;
            ctx.beginPath(); ctx.arc(0, -3, 3, 0, Math.PI*2); ctx.fill();
            // Resource bag
            if (entity.resourceAmount && entity.resourceAmount > 0) {
                ctx.fillStyle = '#06b6d4'; // Cyan crystal
                ctx.fillRect(-3, 2, 6, 4);
            }
        } else if (entity.type === EntityType.MARINE) {
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Gun
             ctx.strokeStyle = '#1f2937';
             ctx.lineWidth = 3;
             ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(8, 2); ctx.stroke();
        } else if (entity.type === EntityType.MEDIC) {
             ctx.fillStyle = '#fff';
             ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI*2); ctx.fill();
             // Cross
             ctx.fillStyle = '#ef4444';
             ctx.fillRect(-2, -5, 4, 10);
             ctx.fillRect(-5, -2, 10, 4);
        } else if (entity.type === EntityType.BASE) {
             ctx.fillStyle = isPlayer ? '#1e3a8a' : '#7f1d1d';
             ctx.fillRect(-25, -25, 50, 50);
             ctx.fillStyle = primaryColor;
             ctx.fillRect(-20, -20, 40, 40);
             // Roof detail
             ctx.fillStyle = 'rgba(255,255,255,0.1)';
             ctx.beginPath(); ctx.moveTo(-20, -20); ctx.lineTo(20, 20); ctx.lineTo(-20, 20); ctx.fill();
        } else if (entity.type === EntityType.BARRACKS) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-20, -20, 40, 40);
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 2;
             ctx.strokeRect(-20, -20, 40, 40);
             // Hatch
             ctx.fillStyle = '#111';
             ctx.fillRect(-10, -10, 20, 20);
        } else if (entity.type === EntityType.BUNKER) {
             ctx.fillStyle = '#4b5563';
             // Hexagon
             ctx.beginPath();
             for (let i = 0; i < 6; i++) {
                 const angle = (i * Math.PI) / 3;
                 ctx.lineTo(Math.cos(angle) * 20, Math.sin(angle) * 20);
             }
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = primaryColor;
             ctx.lineWidth = 3;
             ctx.stroke();
             if (entity.garrison && entity.garrison.length > 0) {
                 ctx.fillStyle = '#10b981'; // Green slots
                 entity.garrison.forEach((_, i) => {
                     ctx.beginPath(); ctx.arc(-10 + i*6, 0, 2, 0, Math.PI*2); ctx.fill();
                 });
             }
        } else if (entity.type === EntityType.SUPPLY_DEPOT) {
             ctx.fillStyle = '#374151';
             ctx.fillRect(-15, -15, 30, 30);
             ctx.fillStyle = primaryColor;
             ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        } else if (entity.type === EntityType.MINERAL) {
             ctx.fillStyle = '#06b6d4';
             ctx.beginPath();
             ctx.moveTo(0, -10); ctx.lineTo(8, -2); ctx.lineTo(5, 8); ctx.lineTo(-5, 8); ctx.lineTo(-8, -2);
             ctx.closePath();
             ctx.fill();
             ctx.strokeStyle = '#cffafe';
             ctx.lineWidth = 1;
             ctx.stroke();
             // Glow
             if (Math.random() > 0.95) {
                 ctx.globalAlpha = 0.5;
                 ctx.fillStyle = '#fff';
                 ctx.beginPath(); ctx.arc(Math.random()*10-5, Math.random()*10-5, 2, 0, Math.PI*2); ctx.fill();
                 ctx.globalAlpha = 1.0;
             }
        } else if (entity.type === EntityType.MOUNTAIN) {
            ctx.fillStyle = '#44403c';
            ctx.beginPath();
            ctx.moveTo(-30, 30); ctx.lineTo(-10, -20); ctx.lineTo(10, 0); ctx.lineTo(30, -30); ctx.lineTo(40, 30);
            ctx.closePath();
            ctx.fill();
        } else if (entity.type === EntityType.WATER) {
            ctx.fillStyle = '#1e3a8a';
            ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI*2); ctx.fill();
        }
    }

    // Selection & Health
    if (isSelected) {
        ctx.strokeStyle = '#10b981'; // Green selection
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(0, 0, entity.radius + 6, 0, Math.PI * 2);
        ctx.stroke();

        // HP Bar
        const hpPct = entity.hp / entity.maxHp;
        ctx.fillStyle = '#000';
        ctx.fillRect(-12, -entity.radius - 12, 24, 4);
        ctx.fillStyle = hpPct > 0.5 ? '#10b981' : (hpPct > 0.25 ? '#fbbf24' : '#ef4444');
        ctx.fillRect(-12, -entity.radius - 12, 24 * hpPct, 4);
    }

    ctx.restore();
};

export const GameCanvas: React.FC<Props> = ({
  onGameStateUpdate,
  onSelectionChange,
  commandMode,
  setCommandMode,
  isMultiplayer = false,
  gameSeed = 123,
  isHost = true,
  difficulty = Difficulty.MEDIUM,
  noRushSeconds = 0
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const terrainCanvasRef = useRef<HTMLCanvasElement | null>(null);
    const stateRef = useRef<GameState | null>(null);
    const requestRef = useRef<number>();
    const keysPressed = useRef<Set<string>>(new Set());

    // UI Layout Constants - Matches new Interface.tsx styling
    // Bottom panel height is approx 256px (h-64 in Tailwind)
    const UI_BOTTOM_OVERLAY_HEIGHT = 256; 

    const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });

    // Mouse Interaction
    const [dragStart, setDragStart] = useState<Vector2 | null>(null);
    const [mousePos, setMousePos] = useState<Vector2 | null>(null);

    useEffect(() => {
        const handleResize = () => setWindowSize({ width: window.innerWidth, height: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Keyboard Listeners
    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            keysPressed.current.add(e.code);
            if ((e.target as HTMLElement).tagName === 'INPUT') return;
            const key = e.key.toUpperCase();

            if (key === 'A') setCommandMode('ATTACK');
            if (key === 'P') { 
                if (stateRef.current) {
                    stateRef.current.paused = !stateRef.current.paused; 
                    onGameStateUpdate({...stateRef.current}); 
                }
            }

            if (stateRef.current) {
                // 1: Select Worker
                if (key === '1') {
                    const ents = Array.from(stateRef.current.entities.values()) as GameEntity[];
                    const workers = ents.filter(e => e.owner === Owner.PLAYER && e.type === EntityType.WORKER);

                    let target = workers.find(w => w.state === 'IDLE');
                    if (!target) target = workers.find(w => w.state === 'GATHERING');
                    if (!target && workers.length > 0) target = workers[0];

                    if (target) {
                        stateRef.current.selection = [target.id];
                        onSelectionChange([target]);
                        playSound('click');
                    }
                }

                // 2: Select Army
                if (key === '2') {
                    const ents = Array.from(stateRef.current.entities.values()) as GameEntity[];
                    const army = ents.filter(e => e.owner === Owner.PLAYER && (e.type === EntityType.MARINE || e.type === EntityType.MEDIC));
                    if (army.length > 0) {
                        const ids = army.map(u => u.id);
                        stateRef.current.selection = ids;
                        onSelectionChange(army);
                        playSound('click');
                    }
                }

                // Space: Center Camera
                if (key === ' ') {
                    e.preventDefault();
                    if (stateRef.current.selection.length > 0) {
                        const id = stateRef.current.selection[0];
                        const ent = stateRef.current.entities.get(id);
                        if (ent && canvasRef.current) {
                            stateRef.current.camera.x = ent.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = ent.position.y - window.innerHeight / 2;
                        }
                    } else {
                        const base = Array.from(stateRef.current.entities.values()).find((e: GameEntity) => e.owner === Owner.PLAYER && e.type === EntityType.BASE);
                        if (base && canvasRef.current) {
                            stateRef.current.camera.x = base.position.x - window.innerWidth / 2;
                            stateRef.current.camera.y = base.position.y - window.innerHeight / 2;
                        }
                    }
                }
            }
        };

        const onKeyUp = (e: KeyboardEvent) => keysPressed.current.delete(e.code);

        window.addEventListener('keydown', onKeyDown);
        window.addEventListener('keyup', onKeyUp);
        return () => { 
            window.removeEventListener('keydown', onKeyDown); 
            window.removeEventListener('keyup', onKeyUp); 
        };
    }, [setCommandMode, onSelectionChange, onGameStateUpdate]);

    // Initialize Game
    useEffect(() => {
        const initialState = initGame(difficulty, isMultiplayer, gameSeed, isHost, noRushSeconds);
        stateRef.current = initialState;
        onGameStateUpdate(initialState);

        // Render terrain once
        terrainCanvasRef.current = renderTerrain();

        // Reset
        setCommandMode(null);
        onSelectionChange([] as GameEntity[]);

        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [gameSeed, isMultiplayer, isHost, difficulty, noRushSeconds]);

    // Game Loop
    const loop = useCallback(() => {
        if (!stateRef.current) return;

        // 1. Update Game Logic
        if (!stateRef.current.paused && !stateRef.current.victory) {
            stateRef.current = updateGame(stateRef.current);
            onGameStateUpdate(stateRef.current); // Sync to React state for UI

            // Play Sounds
            stateRef.current.soundEvents.forEach(evt => {
                if (['shoot', 'explosion', 'train', 'build', 'error', 'click'].includes(evt)) {
                    playSound(evt as any);
                }
            });
            // Clear sound events after playing
            stateRef.current.soundEvents = [];
        }

        // Camera Logic
        const panSpeed = 15;
        if (keysPressed.current.has('ArrowLeft')) stateRef.current.camera.x -= panSpeed;
        if (keysPressed.current.has('ArrowRight')) stateRef.current.camera.x += panSpeed;
        if (keysPressed.current.has('ArrowUp')) stateRef.current.camera.y -= panSpeed;
        if (keysPressed.current.has('ArrowDown')) stateRef.current.camera.y += panSpeed;

        // Camera Clamping Logic
        const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
        // Ensure we can scroll enough to see bottom of map despite UI overlay
        const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + UI_BOTTOM_OVERLAY_HEIGHT);
        stateRef.current.camera.x = Math.max(0, Math.min(stateRef.current.camera.x, maxCamX));
        stateRef.current.camera.y = Math.max(0, Math.min(stateRef.current.camera.y, maxCamY));

        // 2. Render
        const canvas = canvasRef.current;
        const ctx = canvas?.getContext('2d');
        if (canvas && ctx && stateRef.current) {
            const state = stateRef.current;

            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Camera Transform
            ctx.save();
            ctx.translate(-state.camera.x, -state.camera.y);

            // Draw Terrain
            if (terrainCanvasRef.current) {
                ctx.drawImage(terrainCanvasRef.current, 0, 0);
            }

            // Draw Entities
            const sortedEntities = Array.from(state.entities.values()).sort((a, b) => a.position.y - b.position.y);
            const playerUnits = sortedEntities.filter((e: GameEntity) => e.owner === Owner.PLAYER);

            sortedEntities.forEach((entity: GameEntity) => {
                if (entity.state === 'GARRISONED') return;
                if (!isEntityVisible(entity, playerUnits)) return;

                const isSelected = state.selection.includes(entity.id);
                drawUnit(ctx, entity, isSelected);
            });

            // Draw Effects
            state.effects.forEach(effect => {
                 ctx.save();
                 ctx.translate(effect.position.x, effect.position.y);
                 const lifePct = effect.life / effect.maxLife;
                 const scale = effect.scale * (2 - lifePct); 

                 if (effect.type === 'EXPLOSION' || effect.type === 'BUILDING_EXPLOSION') {
                     ctx.fillStyle = `rgba(255, 100, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 15 * scale, 0, Math.PI*2); ctx.fill();
                     ctx.fillStyle = `rgba(255, 255, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 8 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'BLOOD') {
                     ctx.fillStyle = `rgba(180, 0, 0, ${lifePct})`;
                     ctx.beginPath(); ctx.arc(0, 0, 5 * scale, 0, Math.PI*2); ctx.fill();
                 } else if (effect.type === 'HEAL') {
                     ctx.strokeStyle = `rgba(0, 255, 100, ${lifePct})`;
                     ctx.lineWidth = 2;
                     ctx.beginPath(); ctx.arc(0, 0, 10 + (1-lifePct)*10, 0, Math.PI*2); ctx.stroke();
                 }
                 ctx.restore();
            });

            // Draw Selection Box
            if (dragStart && mousePos) {
                 const wx = mousePos.x + state.camera.x;
                 const wy = mousePos.y + state.camera.y;
                 const dx = dragStart.x + state.camera.x;
                 const dy = dragStart.y + state.camera.y;

                 ctx.strokeStyle = '#00ff00';
                 ctx.lineWidth = 1;
                 ctx.strokeRect(dx, dy, wx - dx, wy - dy);
                 ctx.fillStyle = 'rgba(0, 255, 0, 0.1)';
                 ctx.fillRect(dx, dy, wx - dx, wy - dy);
            }

            // Draw Rally Points for selected buildings
            state.selection.forEach(id => {
                const ent = state.entities.get(id);
                if (ent && ent.rallyPoint) {
                    ctx.beginPath();
                    ctx.moveTo(ent.position.x, ent.position.y);
                    ctx.lineTo(ent.rallyPoint.x, ent.rallyPoint.y);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.setLineDash([5, 5]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    ctx.fillStyle = '#fbbf24';
                    ctx.beginPath(); ctx.arc(ent.rallyPoint.x, ent.rallyPoint.y, 3, 0, Math.PI*2); ctx.fill();
                }
            });

            ctx.restore();
        }

        requestRef.current = requestAnimationFrame(loop);
    }, [dragStart, mousePos, onGameStateUpdate, isMultiplayer, gameSeed, windowSize]);

    useEffect(() => {
        requestRef.current = requestAnimationFrame(loop);
        return () => {
            if (requestRef.current) cancelAnimationFrame(requestRef.current);
        };
    }, [loop]);

    // Handle Network Messages
    useEffect(() => {
        if (!isMultiplayer) return;

        const handleMsg = (msg: NetMessage) => {
             if (msg.type === 'GAME_COMMAND' && stateRef.current) {
                 const { action, data, owner } = msg.payload;
                 const state = stateRef.current;

                 // Apply remote commands locally to sync simulation
                 // In a real lockstep, we'd queue these for a specific tick. 
                 // Here we just apply immediately.
                 if (action === 'TRAIN') {
                     const building = state.entities.get(data.id);
                     if (building && building.owner === owner) {
                          if (state.resources[owner] >= STATS[data.type as EntityType].cost) {
                              if (!building.trainQueue) building.trainQueue = [];
                              building.trainQueue.push(data.type);
                              state.resources[owner] -= STATS[data.type as EntityType].cost;
                              playSound('train');
                          }
                     }
                 } else if (action === 'BUILD') {
                     // Remote build command... simplified for now (instant deduction, worker logic local?)
                     // Actually, for BUILD, we typically send a "worker move to build" command. 
                 }
                 // Movement / Attack sync is harder without lockstep. 
                 // We rely on "good enough" sync or command-based spawning.
             }
        };

        const cleanup = network.subscribe(handleMsg);
        return cleanup;
    }, [isMultiplayer]);

    // Handle Global Events (UI Commands)
    useEffect(() => {
        const handleCommand = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            const state = stateRef.current;
            if (!state) return;

            // Helper to broadcast if multiplayer
            const broadcast = (action: string, data: any) => {
                if (isMultiplayer) {
                    network.send({ type: 'GAME_COMMAND', payload: { action, data, owner: Owner.PLAYER } });
                }
            };

            if (detail.action === 'TRAIN') {
                const building = state.entities.get(detail.id);
                if (building && building.owner === Owner.PLAYER) {
                    const cost = STATS[detail.type as EntityType].cost;
                    if (state.resources[Owner.PLAYER] >= cost) {
                        state.resources[Owner.PLAYER] -= cost;
                        if (!building.trainQueue) building.trainQueue = [];
                        building.trainQueue.push(detail.type);
                        playSound('train');
                        broadcast('TRAIN', { id: detail.id, type: detail.type });
                    } else {
                        playSound('error');
                    }
                }
            }
            else if (detail.action === 'BUILD_AT') {
                 // From Worker Logic below
            }
            else if (detail.action === 'MOVE_CAMERA') {
                 // Camera handling with bounds check against map size + visual allowance
                 // This ensures the camera doesn't pan infinitely into void, but allows reaching edges
                 const maxCamX = Math.max(0, GAME_WIDTH - windowSize.width);
                 const maxCamY = Math.max(0, GAME_HEIGHT - windowSize.height + 256); // Allow scrolling past for bottom UI

                 state.camera.x = Math.max(0, Math.min(maxCamX, detail.x));
                 state.camera.y = Math.max(0, Math.min(maxCamY, detail.y)); 
            }
            else if (detail.action === 'UNLOAD_ALL') {
                 const bunker = state.entities.get(detail.id);
                 if (bunker && bunker.garrison && bunker.garrison.length > 0) {
                     // Empty garrison
                     bunker.garrison.forEach((uid, i) => {
                         // We need to 'respawn' them or find them in map if they were just hidden? 
                         // In updateGame, they are hidden. We need to reset their state.
                         const unit = state.entities.get(uid);
                         if (unit) {
                             unit.state = 'IDLE';
                             unit.containerId = null;
                             const angle = (i * Math.PI) / 2;
                             unit.position = {
                                 x: bunker.position.x + Math.cos(angle) * 50,
                                 y: bunker.position.y + Math.sin(angle) * 50
                             };
                         }
                     });
                     bunker.garrison = [];
                     playSound('click');
                 }
            }
            else if (detail.action === 'TOGGLE_PAUSE') {
                state.paused = !state.paused;
            }
            else if (detail.action === 'RESTART') {
                // Handled in App mostly, but we can reset here too
                stateRef.current = initGame(detail.difficulty || difficulty, isMultiplayer, Math.random(), isHost, noRushSeconds);
                if (terrainCanvasRef.current) terrainCanvasRef.current = renderTerrain();
                onSelectionChange([] as GameEntity[]);
            }
            else if (detail.action === 'MINIMAP_ACTION') {
                // Attack move to location
                const targetPos = { x: detail.x, y: detail.y };
                state.selection.forEach(id => {
                    const ent = state.entities.get(id);
                    if (ent && ent.owner === Owner.PLAYER) {
                         if (STATS[ent.type].damage > 0) {
                             ent.state = 'ATTACKING';
                             ent.targetPosition = targetPos;
                             ent.targetId = null;
                             ent.rallyPoint = targetPos; // Set rally for buildings
                             playSound('click');
                         } else {
                             ent.state = 'MOVING';
                             ent.targetPosition = targetPos;
                             ent.rallyPoint = targetPos;
                             playSound('click');
                         }
                    }
                });
            }
        };

        window.addEventListener('GAME_COMMAND', handleCommand);
        return () => window.removeEventListener('GAME_COMMAND', handleCommand);
    }, [isMultiplayer, difficulty, isHost, noRushSeconds, windowSize]);

    // Canvas Inputs
    const handleMouseDown = (e: React.MouseEvent) => {
        if (!stateRef.current) return;
        const rect = canvasRef.current!.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const worldX = x + stateRef.current.camera.x;
        const worldY = y + stateRef.current.camera.y;

        if (e.button === 0) {
            // Left Click
            if (commandMode) {
                // Place Building
                const typeStr = commandMode.replace('BUILD_', '');
                const type = typeStr as EntityType;

                // Find a worker
                const workerId = stateRef.current.selection.find(id => {
                     const ent = stateRef.current!.entities.get(id);
                     return ent && ent.type === EntityType.WORKER && ent.owner === Owner.PLAYER;
                });

                if (workerId) {
                    const worker = stateRef.current.entities.get(workerId);
                    if (worker) {
                         const cost = STATS[type].cost;
                         if (stateRef.current.resources[Owner.PLAYER] >= cost) {
                             // Check placement validity (simplified)
                             let valid = true;
                             // Just check bounds
                             if (worldX < 50 || worldX > GAME_WIDTH-50 || worldY < 50 || worldY > GAME_HEIGHT-50) valid = false;

                             if (valid) {
                                 stateRef.current.resources[Owner.PLAYER] -= cost;

                                 // Create Placeholder
                                 const b = createEntity(type, Owner.PLAYER, { x: worldX, y: worldY });
                                 b.constructionProgress = 0;
                                 stateRef.current.entities.set(b.id, b);

                                 // Order worker
                                 worker.state = 'BUILDING';
                                 worker.targetId = b.id;
                                 // Actually, worker just builds instantly in this simplified version? 
                                 // No, let's make worker walk there? 
                                 // For now, simple: instant place, worker continues idle. 
                                 // Real RTS: Worker walks, then builds.
                                 // Let's just deduct cost and spawn building "under construction".
                                 playSound('build');
                                 setCommandMode(null);
                             } else {
                                 playSound('error');
                             }
                         } else {
                             playSound('error');
                         }
                    }
                }
            } else {
                setDragStart({ x, y });
            }
        } else if (e.button === 2) {
            // Right Click
            setCommandMode(null);
            e.preventDefault();

            let targetId: string | null = null;
            // Check if clicked on entity
            // Reverse iteration to click top-most
            const entities = Array.from(stateRef.current.entities.values());
            for (let i = entities.length - 1; i >= 0; i--) {
                const ent = entities[i];
                if (ent.state === 'GARRISONED') continue;
                const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                if (dist < ent.radius + 5) {
                    targetId = ent.id;
                    break;
                }
            }

            // Issue Orders
            stateRef.current.selection.forEach(id => {
                const ent = stateRef.current!.entities.get(id);
                if (ent && ent.owner === Owner.PLAYER) {
                    // Set Rally Point for Buildings
                    if (STATS[ent.type].speed === 0) {
                        ent.rallyPoint = { x: worldX, y: worldY };
                        ent.rallyTargetId = targetId;
                        playSound('click');
                        return;
                    }

                    // Unit Logic
                    if (targetId) {
                        const target = stateRef.current!.entities.get(targetId);
                        if (target) {
                            if (target.owner === Owner.NEUTRAL && target.type === EntityType.MINERAL && ent.type === EntityType.WORKER) {
                                ent.state = 'GATHERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.owner !== Owner.PLAYER && target.owner !== Owner.NEUTRAL) {
                                ent.state = 'ATTACKING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.BUNKER && target.owner === Owner.PLAYER && ent.type !== EntityType.WORKER) {
                                ent.state = 'ENTERING';
                                ent.targetId = target.id;
                                playSound('click');
                            } else if (target.type === EntityType.MEDIC && target.owner === Owner.PLAYER) {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                playSound('click');
                            } else {
                                ent.state = 'MOVING';
                                ent.targetPosition = { x: worldX, y: worldY };
                                ent.targetId = null; // Clear target if just moving to friendly
                                playSound('click');
                            }
                        }
                    } else {
                        ent.state = 'MOVING';
                        ent.targetPosition = { x: worldX, y: worldY };
                        ent.targetId = null;
                        playSound('click');
                    }
                }
            });
        }
    };

    const handleMouseUp = (e: React.MouseEvent) => {
        if (!stateRef.current || !dragStart) {
            setDragStart(null);
            return;
        }

        if (e.button === 0 && !commandMode) {
            const rect = canvasRef.current!.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const dx = Math.abs(x - dragStart.x);
            const dy = Math.abs(y - dragStart.y);

            // Box Select or Click Select
            const newSelection: string[] = [];
            const isBox = dx > 5 || dy > 5;

            const wx1 = Math.min(x, dragStart.x) + stateRef.current.camera.x;
            const wy1 = Math.min(y, dragStart.y) + stateRef.current.camera.y;
            const wx2 = Math.max(x, dragStart.x) + stateRef.current.camera.x;
            const wy2 = Math.max(y, dragStart.y) + stateRef.current.camera.y;

            stateRef.current.entities.forEach((ent: GameEntity) => {
                 if (ent.owner !== Owner.PLAYER) return; // Only select own units
                 if (ent.state === 'GARRISONED') return;

                 if (isBox) {
                     if (ent.position.x >= wx1 && ent.position.x <= wx2 && ent.position.y >= wy1 && ent.position.y <= wy2) {
                         newSelection.push(ent.id);
                     }
                 } else {
                     const dist = Math.sqrt(Math.pow(ent.position.x - (x + stateRef.current.camera.x), 2) + Math.pow(ent.position.y - (y + stateRef.current.camera.y), 2));
                     if (dist < ent.radius + 10) {
                         newSelection.push(ent.id);
                     }
                 }
            });

            // If single click and no own units, try selecting enemy/neutral to see HP
            if (!isBox && newSelection.length === 0) {
                 const worldX = x + stateRef.current.camera.x;
                 const worldY = y + stateRef.current.camera.y;
                 let found: GameEntity | null = null;
                 const allEnts = Array.from(stateRef.current.entities.values());
                 allEnts.forEach((ent) => {
                     if (ent.state === 'GARRISONED') return;
                     const dist = Math.sqrt(Math.pow(ent.position.x - worldX, 2) + Math.pow(ent.position.y - worldY, 2));
                     if (dist < ent.radius + 10) found = ent;
                 });
                 if (found) newSelection.push(found.id);
            }

            stateRef.current.selection = newSelection;
            onSelectionChange(newSelection.map(id => stateRef.current!.entities.get(id)!).filter(Boolean));
        }
        setDragStart(null);
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    };

    return (
        <canvas
            ref={canvasRef}
            width={window.innerWidth}
            height={window.innerHeight}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseMove={handleMouseMove}
            onContextMenu={(e) => e.preventDefault()}
            className={`block cursor-${commandMode ? 'crosshair' : 'default'}`}
        />
    );
};

export enum Owner {
  PLAYER = 'PLAYER',
  AI = 'AI', // Kept for backward compatibility with single player
  OPPONENT = 'OPPONENT', // For multiplayer
  NEUTRAL = 'NEUTRAL',
}

export enum EntityType {
  WORKER = 'WORKER',
  MARINE = 'MARINE',
  MEDIC = 'MEDIC',
  BASE = 'BASE',
  BARRACKS = 'BARRACKS',
  BUNKER = 'BUNKER',
  SUPPLY_DEPOT = 'SUPPLY_DEPOT',
  MINERAL = 'MINERAL',
  MOUNTAIN = 'MOUNTAIN',
  WATER = 'WATER',
}

export enum Difficulty {
    EASY = 'EASY',
    MEDIUM = 'MEDIUM',
    HARD = 'HARD'
}

export enum AIStrategy {
    RUSH = 'RUSH', // Early attack, low economy
    MACRO = 'MACRO', // High economy, late attack
    TURTLE = 'TURTLE' // Defensive, builds bunkers
}

export interface Vector2 {
  x: number;
  y: number;
}

export interface Effect {
  id: string;
  type: 'EXPLOSION' | 'BLOOD' | 'BUILDING_EXPLOSION' | 'HEAL' | 'BULLET' | 'HEAL_BEAM' | 'SPARK';
  position: Vector2;
  targetPosition?: Vector2; // Added for lines like bullets and beams
  life: number;
  maxLife: number;
  scale: number;
}

export interface Marker {
  id: string;
  position: Vector2;
  type: 'MOVE' | 'ATTACK' | 'LOAD';
  life: number;
  maxLife: number;
}

export interface Notification {
    id: string;
    text: string;
    life: number;
}

export interface GameEntity {
  id: string;
  type: EntityType;
  owner: Owner;
  position: Vector2;
  radius: number;
  hp: number;
  maxHp: number;
  targetId: string | null;
  targetPosition: Vector2 | null;
  state: 'IDLE' | 'MOVING' | 'ATTACKING' | 'GATHERING' | 'RETURNING' | 'BUILDING' | 'ENTERING' | 'GARRISONED' | 'HEALING';
  cooldown: number;
  resourceAmount?: number; // For minerals or carrying
  constructionProgress?: number; // 0-100
  trainQueue?: EntityType[];
  trainProgress?: number;
  rallyPoint?: Vector2 | null;
  rallyTargetId?: string | null;
  lastAttackerId?: string | null; // For retaliation
  garrison?: string[]; // IDs of units inside (for Bunker)
  containerId?: string | null; // ID of entity this unit is inside
}

export interface GameState {
  entities: Map<string, GameEntity>;
  effects: Effect[];
  markers: Marker[];
  notifications: Notification[];
  soundEvents: string[];
  resources: {
    [Owner.PLAYER]: number;
    [Owner.AI]: number;
    [Owner.OPPONENT]: number;
  };
  supply: {
    [Owner.PLAYER]: { used: number; max: number };
    [Owner.AI]: { used: number; max: number };
    [Owner.OPPONENT]: { used: number; max: number };
  };
  selection: string[];
  camera: Vector2;
  victory?: Owner;
  gameTime: number;
  noRushFrames: number; // New field
  difficulty: Difficulty;
  aiStrategy: AIStrategy; 
  paused: boolean;
  isMultiplayer: boolean;
  localPlayerId?: string;
